#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ADS1115_ADDR   0x48
#define ADS1115_CONV   0x00
#define ADS1115_CONFIG 0x01

#define CONFIG_REG     0x01
#define CONVERSION_REG 0x00

#define REF_VOLTAGE    4.096
#define ADC_MAX        32767.0
#define SENSITIVITY    0.001
#define SAMPLE_US      500000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t swap16(int16_t v) {
    return (int16_t)(((v >> 8) & 0xFF) | ((v & 0xFF) << 8));
}

static int16_t read_conversion(int handle) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, CONVERSION_REG, buf, 2) != 2) {
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    return swap16(raw);
}

static int16_t read_current(int handle) {
    char cfg[3];
    cfg[0] = CONFIG_REG;
    cfg[1] = 0xC1; /* OS=1, MUX=100 (AIN0 single-ended), PGA=001 (±4.096V) */
    cfg[2] = 0x83; /* MODE=1 (single-shot), DR=100 (128 SPS), COMP_DISABLE */

    if (i2cWriteDevice(handle, cfg, 3) != 0) {
        return -1;
    }

    gpioDelay(10000);

    int16_t raw = read_conversion(handle);
    if (raw < 0) {
        return -1;
    }

    return raw;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int16_t raw = read_current(handle);
        if (raw < 0) {
            fprintf(stderr, "Error reading current (I2C failure or sensor absent)\n");
        } else {
            double voltage = (raw / ADC_MAX) * REF_VOLTAGE;
            double current = voltage / SENSITIVITY;
            printf("Current: %.3f A\n", current);
        }
        gpioDelay(SAMPLE_US);
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

