#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8483  /* MUX=AIN0, PGA=4.096V, MODE=single, DR=128SPS */
#define DEBOUNCE_DELAY_US 50000
#define BUZZER_DURATION_US 2000000
#define POLL_DELAY_US 100000
#define FIRE_LOG_FILE "fire_log.txt"
#define TEMP_THRESHOLD 60.0f
#define ADC_MAX 32767.0f
#define ADC_VREF 4.096f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set flame sensor pin mode.\n");
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode.\n");
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize buzzer state.\n");
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (err=%d).\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_ads1115(void) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_BASE >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_BASE & 0xFF;
    if (i2cWriteDevice(i2c_handle, config, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register.\n");
        return -1;
    }
    return 0;
}

static int read_flame_sensor(void) {
    int state = gpioRead(FLAME_SENSOR_PIN);
    if (state < 0) {
        fprintf(stderr, "Error: failed to read flame sensor pin.\n");
        return -1;
    }
    gpioDelay(DEBOUNCE_DELAY_US);
    int confirmed = gpioRead(FLAME_SENSOR_PIN);
    if (confirmed < 0) {
