#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP_NAME  "gpiochip4"   /* Pi 5 default; fall back to gpiochip0 */
#define FAN_GPIO_LINE   18            /* BCM 18 */
#define CURRENT_THRESHOLD  500
#define LOG_FILE        "current_log.txt"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_DELAY_US    0
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_fan_line = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    g_spi_fd = fd;
    return 0;
}

static int gpio_init(void)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    g_fan_line = gpiod_chip_get_line(chip, FAN_GPIO_LINE);
    if (!g_fan_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", FAN_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(g_fan_line, "fan_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", FAN_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    g_chip = chip;
    return 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_current(int current)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s, Current: %d\n", timestamp, current);
    fclose(fp);
    return 0;
}

static void control_fan(int current)
{
    int val = (current > CURRENT_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(g_fan_line, val) < 0) {
        fprintf(stderr, "Error setting fan GPIO value: %s\n", strerror(errno));
    }
}

static void cleanup(void)
{
    if (g_fan_line) {
        gpiod_line_set_value(g_fan_line, 0);
        gpiod_line_release(g_fan_line);
        g_fan_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int current = read_mcp3008(0);
        if (current < 0) {
            fprintf(stderr, "Error reading current sensor\n");
        } else if (current == 0 || current == 1023) {
            fprintf(stderr, "Warning: ADC reading at rail (%d) - sensor absent or wiring fault\n", current);
        } else {
            if (log_current(current) < 0) {
                fprintf(stderr, "Error logging current\n");
            }
            control_fan(current);
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

