    (void)sig;
    running = 0;
}

static int read_flame_sensor(int gpio_pin) {
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error reading flame sensor on GPIO %d\n", gpio_pin);
        return -1;
    }
    return level;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer error on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_temperature(int adc_value) {
    return (float)adc_value * 0.1f;
}

