#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MICS4514_ADDR 0x48
#define CO_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mics4514(int handle, uint16_t *ox, uint16_t *red) {
    char buf[4];
    int bytes_read = i2cReadDevice(handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C device: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    *ox = ((uint16_t)(buf[0] & 0x0F) << 8) | (uint8_t)buf[1];
    *red = ((uint16_t)(buf[2] & 0x0F) << 8) | (uint8_t)buf[3];
    return 0;
}

float calculate_co_ppm(uint16_t ox) {
    return (float)ox * 0.1;
}

int log_data(const char *filename, float co_ppm) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f ppm\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

int log_alert(const char *filename, float co_ppm) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening alert file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO level exceeded threshold! CO: %.2f ppm\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t ox, red;
    float co_ppm;

    while (running) {
        if (read_mics4514(i2c_handle, &ox, &red) == 0) {
            co_ppm = calculate_co_ppm(ox);
            printf("CO: %.2f ppm\n", co_ppm);

            if (log_data(LOG_FILE, co_ppm) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            if (co_ppm > CO_THRESHOLD) {
                if (log_alert(ALERT_FILE, co_ppm) != 0) {
                    fprintf(stderr, "Error logging alert\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

