#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8) for mic1, CE1 (GPIO9) for mic2 */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL_MIC1 0          /* MCP3008 channel 0 */
#define ADC_CHANNEL_MIC2 1          /* MCP3008 channel 1 */
#define LED_PIN          27         /* BCM 27 */
#define SAMPLE_RATE_HZ   1000       /* 1 kHz */
#define WINDOW_MS        100        /* 100 ms window */
#define NUM_SAMPLES      (SAMPLE_RATE_HZ * WINDOW_MS / 1000) /* 100 */
#define HIGH_LEVEL_THRESHOLD 100.0f
#define LED_ON_MS        500
#define LOG_FILE         "audio_events.csv"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize(void);
static void cleanup(void);
static int  read_adc(int channel, int *out_value);
static float calculate_rms(const int *data, int num_samples);
static void log_event(float rms1, float rms2);
static void signal_handler(int sig);

/* ----------------------------- Implementation ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    /* Open SPI0 CE0 (GPIO8) for mic1 and CE1 (GPIO9) for mic2 in a single handle.
     * pigpio drives CE0/CE1 automatically when the channel is 0/1. */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d).\n", g_spi_handle);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set LED pin %d as output.\n", LED_PIN);
        spiClose(g_spi_handle);
        gpioTerminate();
        return -1;
    }
    gpioWrite(LED_PIN, 0);

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s'.\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,mic1_rms,mic2_rms\n");
        fflush(g_log_file);
    }

    return 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Read a single-ended sample from the MCP3008.
 * Returns 0 on success (value stored in *out_value), -1 on error. */
static int read_adc(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d.\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer.
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4  -> SGL/DIFF=1, D2 D1 D0 = channel
     * Byte 2: 0x00 (don't care, clocked out to read low byte) */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (ret=%d).\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    *out_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

static float calculate_rms(const int *data, int num_samples)
{
    if (data == NULL || num_samples <= 0) {
        return 0.0f;
    }

    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)data[i];
        sum_sq += v * v;
    }
    return (float)sqrt(sum_sq / (double)num_samples);
}

static void log_event(float rms1, float rms2)
{
    if (g_log_file == NULL) {
        return;
    }

    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%.2f,%.2f\n", timestamp, rms1, rms2) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
    } else {
        fflush(g_log_file);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    int *mic1_data = malloc(NUM_SAMPLES * sizeof(int));
    int *mic2_data = malloc(NUM_SAMPLES * sizeof(int));
    if (mic1_data == NULL || mic2_data == NULL) {
        fprintf(stderr, "Error: memory allocation failed.\n");
        cleanup();
        free(mic1_data);
        free(mic2_data);
        return EXIT_FAILURE;
    }

    const uint32_t sample_period_us = 1000000 / SAMPLE_RATE_HZ; /* 1000 us */

    while (g_running) {
        int samples_collected = 0;

        while (samples_collected < NUM_SAMPLES && g_running) {
            int v1 = 0, v2 = 0;

            if (read_adc(ADC_CHANNEL_MIC1, &v1) != 0) {
                fprintf(stderr, "Warning: ADC read failed for mic1 (ch%d).\n",
                        ADC_CHANNEL_MIC1);
                gpioDelay(sample_period_us);
                continue;
            }
            if (read_adc(ADC_CHANNEL_MIC2, &v2) != 0) {
                fprintf(stderr, "Warning: ADC read failed for mic2 (ch%d).\n",
                        ADC_CHANNEL_MIC2);
                gpioDelay(sample_period_us);
                continue;
            }

            mic1_data[samples_collected] = v1;
            mic2_data[samples_collected] = v2;
            samples_collected++;

            gpioDelay(sample_period_us);
        }

        if (!g_running) {
            break;
        }

        float rms1 = calculate_rms(mic1_data, samples_collected);
        float rms2 = calculate_rms(mic2_data, samples_collected);

        log_event(rms1, rms2);

        if (rms1 > HIGH_LEVEL_THRESHOLD || rms2 > HIGH_LEVEL_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_MS * 1000); /* 500 ms */
            gpioWrite(LED_PIN, 0);
        }
    }

    free(mic1_data);
    free(mic2_data);
    cleanup();
    return EXIT_SUCCESS;
}

