#define ADS1115_ADDR         0x48
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/* Config: single-shot, AIN0 single-ended, PGA ±4.096 V, 128 SPS, no comp */
#define ADS1115_CFG_BASE     0x8000  /* OS bit */
#define ADS1115_CFG_MUX_A0  0x4000  /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4V  0x0200  /* ±4.096 V */
#define ADS1115_CFG_DR_128  0x0080  /* 128 SPS */
#define ADS1115_CFG_MODE    0x0100  /* single-shot */
#define ADS1115_CFG_DEFAULT (ADS1115_CFG_BASE | ADS1115_CFG_MUX_A0 | \
                            ADS1115_CFG_PGA_4V | ADS1115_CFG_DR_128 | \
                            ADS1115_CFG_MODE)

#define LED_GPIO             17
#define BUFFER_SIZE          100
#define SAMPLE_RATE_HZ       10
#define SAMPLE_PERIOD_US     (1000000 / SAMPLE_RATE_HZ)
#define CURRENT_THRESHOLD    50.0f   /* Amperes */
#define ADC_VREF             4.096f  /* Volts */
#define ADC_MAX              32767.0f /* 16-bit signed positive max */
#define ADC_RESOLUTION       32768.0f /* 2^15 */
#define SENSOR_SENSITIVITY   0.01f   /* V/A (example placeholder) */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Circular Buffer ----------------------------- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* --------------------------- ADS1115 Helpers ----------------------------- */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);
    if (i2cWriteDevice(handle, buf, 3) < 0) return -1;
    return 0;
}

static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) < 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int ads1115_read_adc(int handle, int16_t *raw) {
    uint16_t cfg = ADS1115_CFG_DEFAULT;
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, cfg) < 0) return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    uint16_t conv;
    if (ads1115_read_reg(handle, ADS1115_REG_CONV, &conv) < 0) return -1;

    *raw = (int16_t)conv;
    return 0;
}

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X (handle=%d).\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading the config register */
    uint16_t cfg_check;
    if (ads1115_read_reg(g_i2c_handle, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "Error: ADS1115 not responding on I2C bus %d.\n", I2C_BUS);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Initialize circular buffer */
    CircularBuffer current_buffer;
    cb_init(&current_buffer);

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring current sensor on ADS1115 channel A0. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_adc(g_i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: I2C read error from ADS1115.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Convert raw ADC to voltage, then to current */
        float voltage = ((float)raw / ADC_RESOLUTION) * ADC_VREF;
        float current = voltage / SENSOR_SENSITIVITY;

        cb_add(&current_buffer, current);

        float avg_current = cb_average(&current_buffer);

        /* Threshold check and LED control */
        if (avg_current > CURRENT_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            printf("WARNING: Average current %.2f A exceeds threshold %.2f A\n",
                   avg_current, CURRENT_THRESHOLD);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --------------------------- Cleanup --------------------------- */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

