#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#include "tcs34725.h"

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define LOG_FILE       "color_log.csv"
#define SAMPLE_PERIOD  1.0
#define MAX_CONSEC_ERR 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int file_exists(const char *path)
{
    FILE *f = fopen(path, "r");
    if (f) { fclose(f); return 1; }
    return 0;
}

static int write_header_if_needed(void)
{
    if (file_exists(LOG_FILE)) return 0;
    FILE *f = fopen(LOG_FILE, "w");
    if (!f) { perror("fopen header"); return -1; }
    fprintf(f, "timestamp,clear,red,green,blue\n");
    fclose(f);
    return 0;
}

static int log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (!g_log_fp) {
        g_log_fp = fopen(LOG_FILE, "a");
        if (!g_log_fp) { perror("fopen log"); return -1; }
    }
    fprintf(g_log_fp, "%s,%u,%u,%u,%u\n", ts, clear, red, green, blue);
    fflush(g_log_fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (addr 0x%02X): %s\n", I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(g_i2c_handle) != 0) {
        fprintf(stderr, "TCS34725 init failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_header_if_needed() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int consec_err = 0;

    while (g_running) {
        uint16_t clear, red, green, blue;

        if (tcs34725_read(g_i2c_handle, &clear, &red, &green, &blue) != 0) {
            consec_err++;
            fprintf(stderr, "I2C read error (%d/%d)\n", consec_err, MAX_CONSEC_ERR);
            if (consec_err >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Too many consecutive I2C errors, exiting\n");
                break;
            }
            time_sleep(SAMPLE_PERIOD);
            continue;
        }
        consec_err = 0;

        if (log_data(clear, red, green, blue) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    if (g_i2c_handle >= 0) { i2cClose(g_i2c_handle); g_i2c_handle = -1; }
    gpioTerminate();
    return EXIT_SUCCESS;
}

