#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0
#define ADC_CHANNEL      0
#define MOTOR_GPIO       17
#define OVER_CURRENT_A   10.0f
#define SAMPLE_PERIOD_S  1
#define MAX_RETRIES      3
#define LOG_FILE         "current_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_adc(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret >= 0) {
            int raw = ((rx[1] & 0x03) << 8) | rx[2];
            return raw;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES) {
            usleep(10000);
        }
    }
    return -1;
}

static float adc_to_amperes(int adc_value)
{
    float vref = 3.3f;
    float v_out = (float)adc_value / 1023.0f * vref;
    float current = (v_out - 1.65f) / 0.01f;
    return current;
}

static int log_current(float current)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, current) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", MOTOR_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(MOTOR_GPIO, 1) != 0) {
        fprintf(stderr, "gpioWrite(%d, 1) failed\n", MOTOR_GPIO);
        gpioTerminate();
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(g_spi_fd);
        gpioTerminate();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long fsize = ftell(g_log_fp);
    if (fsize == 0) {
        if (fprintf(g_log_fp, "Timestamp,Current_A\n") < 0) {
            fprintf(stderr, "fprintf header: %s\n", strerror(errno));
        }
        if (fflush(g_log_fp) != 0) {
            fprintf(stderr, "fflush header: %s\n", strerror(errno));
        }
    }

    printf("Monitoring current on MCP3008 ch%d. Ctrl+C to exit.\n", ADC_CHANNEL);

    while (g_running) {
        int adc = read_adc(g_spi_fd, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
        } else {
            float current = adc_to_amperes(adc);
            printf("Current: %.2f A\n", current);

            if (log_current(current) != 0) {
                fprintf(stderr, "Logging failed\n");
            }

            if (current > OVER_CURRENT_A) {
                printf("Over-current detected (%.2f A > %.2f A)! Disabling motor.\n",
                       current, OVER_CURRENT_A);
                if (gpioWrite(MOTOR_GPIO, 0) != 0) {
                    fprintf(stderr, "gpioWrite(%d, 0) failed\n", MOTOR_GPIO);
                }
                log_current(current);
                sleep(1);
                if (gpioWrite(MOTOR_GPIO, 1) != 0) {
                    fprintf(stderr, "gpioWrite(%d, 1) failed\n", MOTOR_GPIO);
                }
                printf("Motor re-enabled.\n");
            }
        }
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

