#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90817_ADDR  0x4A
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0
#define MAX_READ_ERRORS 10

/* MLX90817 register addresses (16-bit, big-endian on the bus) */
#define MLX90817_REG_PRESSURE_MSB  0x00
#define MLX90817_REG_PRESSURE_LSB  0x01
#define MLX90817_REG_TEMP_MSB      0x02
#define MLX90817_REG_TEMP_LSB      0x03
#define MLX90817_REG_CONFIG        0x0F

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs.     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register address.                 */
/* ------------------------------------------------------------------ */
static int mlx_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (i2cWriteDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (big-endian on the bus).                    */
/* ------------------------------------------------------------------ */
static int mlx_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure in kPa.  Returns 0 on success, -1 on error.          */
/* ------------------------------------------------------------------ */
static int read_pressure(int handle, float *pressure_kPa)
{
    uint16_t msb, lsb;
    uint32_t raw;

