#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

#define LED_GPIO       17
#define PRESSURE_CHANNEL 0
#define TEMPERATURE_CHANNEL 1

#define PRESSURE_THRESHOLD 105.0f
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = { ms / 1000, (ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t cfg = 0x8000 | (0x4000) | (0x0000) | (0x0400) | (0x0080);
    return i2c_write16(fd, ADS1115_REG_CONFIG, cfg);
}

static int ads1115_read_channel(int fd, int channel, float *value) {
    uint16_t cfg = 0x8000 | (0x4000) | ((uint16_t)channel << 12) | (0x0400) | (0x0080);
    if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) < 0) return -1;
    sleep_ms(10);
    uint16_t raw;
    if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw) < 0) return -1;
    int16_t signed_raw = (int16_t)raw;
    *value = (float)signed_raw / 32768.0f * 4.096f;
    return 0;
}

static float read_pressure(int fd) {
    float p = 0.0f;
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (ads1115_read_channel(fd, PRESSURE_CHANNEL, &p) == 0) return p;
        sleep_ms(RETRY_DELAY_MS);
    }
    return -1.0f;
}

static float read_temperature(int fd) {
    float t = 0.0f;
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (ads1115_read_channel(fd, TEMPERATURE_CHANNEL, &t) == 0) return t;
        sleep_ms(RETRY_DELAY_MS);
    }
    return -1.0f;
}

static void control_led(int state) {
    FILE *fp = fopen("/sys/class/gpio/gpio17/value", "w");
    if (fp) { fprintf(fp, "%d", state); fclose(fp); }
}

int main(void) {
    struct sigaction sa = { .sa_handler = sigint_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    FILE *fp = fopen("/sys/class/gpio/export", "w");
    if (!fp) { perror("export"); return 1; }
    fprintf(fp, "17");
    fclose(fp);
    sleep_ms(100);

    fp = fopen("/sys/class/gpio/gpio17/direction", "w");
    if (!fp) { perror("direction"); return 1; }
    fprintf(fp, "out");
    fclose(fp);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) { perror("ioctl"); close(fd); return 1; }
    if (ads1115_init(fd) < 0) { fprintf(stderr, "ADS1115 init failed\n"); close(fd); return 1; }

    while (running) {
        float pressure = read_pressure(fd);
        float temperature = read_temperature(fd);
        if (pressure < 0.0f || temperature < 0.0f) {
            fprintf(stderr, "Sensor read error\n");
        } else {
            printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
            control_led(pressure > PRESSURE_THRESHOLD ? 1 : 0);
        }
        sleep_ms(1000);
    }

    control_led(0);
    close(fd);
    return 0;
}

