#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define ALERT_EMAIL "recipient@example.com"
#define ALERT_EMAIL_SUBJECT "Humidity Alert"
#define ALERT_EMAIL_BODY "Humidity exceeded threshold!"

#define ADC_CHANNEL_HUMIDITY 0
#define ADC_CHANNEL_TEMPERATURE 1

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return ((rx[1] & 0x0F) << 8) | rx[2];
}

static float convert_humidity(int adc_value) {
    float voltage = (float)adc_value * 3.3 / 4095.0;
    float humidity = (voltage - 0.4) / 0.8 * 100.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

static float convert_temperature(int adc_value) {
    float voltage = (float)adc_value * 3.3 / 4095.0;
    float temperature = (voltage - 0.5) / 0.01 * 100.0;
    return temperature;
}

static int log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int send_email_alert(float humidity) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo '%s' | ssmtp -s '%s' %s",
             ALERT_EMAIL_BODY, ALERT_EMAIL_SUBJECT, ALERT_EMAIL);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        perror("Error executing ssmtp");
        return -1;
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "ssmtp exited with status %d\n", status);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error setting SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error setting SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int humidity_adc = read_adc(ADC_CHANNEL_HUMIDITY);
        int temperature_adc = read_adc(ADC_CHANNEL_TEMPERATURE);

        if (humidity_adc < 0 || temperature_adc < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            sleep(1);
            continue;
        }

        float humidity = convert_humidity(humidity_adc);
        float temperature = convert_temperature(temperature_adc);

        if (log_data(humidity, temperature) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        if (humidity > HUMIDITY_THRESHOLD) {
            printf("Humidity threshold exceeded! Sending email alert.\n");
            if (send_email_alert(humidity) < 0) {
                fprintf(stderr, "Error sending email alert\n");
            }
        }

        sleep(5);
    }

    printf("\nCleaning up and exiting...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpioTerminate();
    return 0;
}

