#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define GPIO_CHIP       "gpiochip4"
#define CE0_LINE        8

#define VREF            3.3
#define ADC_MAX         4095.0
#define TMP36_OFFSET    0.5
#define TMP36_SCALE     100.0

#define LOG_FILE        "temperature_log.csv"
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_ce0 = NULL;
static FILE *g_log = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

static int gpio_init(void) {
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_ce0 = gpiod_chip_get_line(g_chip, CE0_LINE);
    if (!g_ce0) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", CE0_LINE, strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL; return -1;
    }

    if (gpiod_line_request_output(g_ce0, "mcp3208-ce0", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL; g_ce0 = NULL; return -1;
    }

    return 0;
}

static int read_adc(uint16_t *adc_out) {
    if (gpiod_line_set_value(g_ce0, 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value(0): %s\n", strerror(errno));
        return -1;
    }

    uint8_t tx[3] = { 0x01, 0x80, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        gpiod_line_set_value(g_ce0, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_ce0, 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value(1): %s\n", strerror(errno));
        return -1;
    }

    int raw = ((rx[1] & 0x0F) << 8) | rx[2];
    *adc_out = (uint16_t)raw;
    return 0;
}

static float adc_to_celsius(uint16_t adc) {
    float v = (adc / ADC_MAX) * VREF;
    return (v - TMP36_OFFSET) * TMP36_SCALE;
}

static int log_open(void) {
    int flags = (g_log = fopen(LOG_FILE, "a")) ? 0 : -1;
    if (flags == 0) {
        fseek(g_log, 0, SEEK_END);
        if (ftell(g_log) == 0) {
            fprintf(g_log, "timestamp,temperature_celsius\n");
            fflush(g_log);
        }
    } else {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
    }
    return flags;
}

static void log_sample(float temp) {
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    localtime_r(&now, &tmv);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    fprintf(g_log, "%s,%.2f\n", ts, temp);
    fflush(g_log);
}

static void cleanup(void) {
    if (g_log) { fclose(g_log); g_log = NULL; }
    if (g_ce0) { gpiod_line_release(g_ce0); g_ce0 = NULL; }
    if (g_chip) { gpiod_chip_close(g_chip); g_chip = NULL; }
    if (g_spi_fd >= 0) { close(g_spi_fd); g_spi_fd = -1; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) { cleanup(); return 1; }
    if (gpio_init() < 0) { cleanup(); return 1; }
    if (log_open() < 0) { cleanup(); return 1; }

    printf("TMP36 via MCP3208 logging to %s at 1 Hz. Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        uint16_t adc = 0;
        if (read_adc(&adc) < 0) {
            fprintf(stderr, "ADC read failed; retrying next cycle.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float temp = adc_to_celsius(adc);
        if (temp < -40.0f || temp > 125.0f) {
            fprintf(stderr, "Out-of-range reading (%.2f C) — sensor absent or fault.\n", temp);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        log_sample(temp);
        printf("ADC=%u  T=%.2f C\n", adc, temp);
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

