/*
 * Raspberry Pi Zero W – Si1172‑A30‑GMR Optical Heart Rate / SpO₂ Logger
 *
 * Reads raw PPG IR and RED ADC samples from the Si1172 on I2C bus 1
 * (default address 0x53) once per second and logs them to
 * biometric_log.csv with a Unix-timestamp header row.
 *
 * NOTE: The Si1172 requires a proprietary algorithm to convert raw
 * PPG samples to true HR (bpm) and SpO₂ (%).  This program logs the
 * raw 16‑bit IR and RED ADC values as proxy values and documents
 * this limitation.  A production deployment must replace the
 * read_si1172_sample() function with the vendor‑provided HR / SpO₂
 * algorithm.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1172_logger si1172_logger.c \
 *       -lsi117x -lpigpio -lrt
 *
 * Run:
 *   sudo ./si1172_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#include <si117x.h>

#define I2C_BUS        1
#define SI1172_ADDR    0x53
#define LOG_FILE       "biometric_log.csv"
#define SAMPLE_PERIOD  1.0   /* seconds */

/* ------------------------------------------------------------------ */
/* Globals for signal‑safe cleanup                                     */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    si117x_terminate();
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Open the log file and write the header row                           */
/* ------------------------------------------------------------------ */
static int open_log_file(void)
{
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    /* Write header only if the file is empty */
    long pos = ftell(g_log_file);
    if (pos == 0) {
        fprintf(g_log_file,
                "timestamp,hr_bpm,spo2_pct,error_flag\n");
        fflush(g_log_file);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the Si1172.
 *
 * Returns 0 on success and fills *ir and *red with raw 16‑bit ADC
 * values; returns -1 on I2C error (transient) or -2 if the sensor
 * appears absent or the driver reports an uninitialized device.
 *
 * NOTE: Replace this with the vendor‑provided HR / SpO₂ algorithm
 * for production use.
 * ------------------------------------------------------------------ */
static int read_si1172_sample(int handle, uint16_t *ir, uint16_t *red)
{
    int rc;

    /*
     * Probe the device by reading the PART_ID register.
     * A valid Si117x returns 0x1177 or 0x1178; a zero or negative
     * value indicates the sensor is absent or the driver cannot
     * communicate with it.
     */
    rc = i2cReadWordData(handle, SI117X_REG_PART_ID);
    if (rc < 0) {
        return -2;                 /* I2C bus error – sensor absent or bus fault */
    }
    if (rc != 0x1177 && rc != 0x1178) {
        return -2;                 /* Wrong PART_ID – wrong device or not initialised */
    }

    /*
     * Read the raw PPG IR and RED ADC samples.
     * The Si117x driver exposes 16‑bit ADC data registers; the
     * exact register names depend on the driver version but are
     * typically SI117X_REG_ALS_IR_DATA and SI117X_REG_ALS_RED_DATA.
     */
    rc = i2cReadWordData(handle, SI117X_REG_ALS_IR_DATA);
    if (rc < 0) {
        return -1;                 /* Transient I2C read error */
    }
    *ir = (uint16_t)rc;

    rc = i2cReadWordData(handle, SI117X_REG_ALS_RED_DATA);
    if (rc < 0) {
        return -1;                 /* Transient I2C read error */
    }
    *red = (uint16_t)rc;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one row to the CSV file                                         */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, time_t ts, uint16_t ir, uint16_t red, int err)
{
    fprintf(fp, "%ld,%u,%u,%d\n", (long)ts, ir, red, err);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t ir = 0, red = 0;
    int      err;
    time_t   now;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Si117x library init ---- */
    if (si117x_init() != 0) {
        fprintf(stderr, "Si117x library initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SI1172_ADDR, g_i2c_handle);
        si117x_terminate();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    if (open_log_file() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1172 logger started.  Logging to %s  (Ctrl-C to stop)\n",
           LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        now = time(NULL);

        err = read_si1172_sample(g_i2c_handle, &ir, &red);

        if (err == 0) {
            log_data(g_log_file, now, ir, red, 0);
        } else if (err == -2) {
            /*
             * Sensor absent or wrong device – log with error flag 2
             * so the row is identifiable in the CSV.
             */
            log_data(g_log_file, now, 0, 0, 2);
            fprintf(stderr, "Sensor absent or wrong device at %ld\n",
                    (long)now);
        } else {
            /*
             * Transient I2C error – log with error flag 1 and
             * continue so a brief bus glitch does not kill the
             * application.
             */
            log_data(g_log_file, now, 0, 0, 1);
            fprintf(stderr, "I2C read error at %ld\n", (long)now);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

