#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x25
#define MEASURE_CMD 0x36
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    int32_t raw_pressure, raw_temperature;

    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) {
        return -1;
    }

    usleep(20000);

    if (i2c_read_data(fd, data, 6) < 0) {
        return -1;
    }

    raw_pressure = ((int32_t)data[0] << 16) | ((int32_t)data[1] << 8) | data[2];
    raw_temperature = ((int32_t)data[3] << 16) | ((int32_t)data[4] << 8) | data[5];

    *pressure = (float)raw_pressure / 256.0;
    *temperature = (float)raw_temperature / 256.0;

    return 0;
}

static void log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, pressure);
    fflush(fp);
}

static void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Pressure(Pa)\n");
        fflush(log_file);
    }

    float temperature, pressure;

    while (running) {
        if (read_sensor_data(i2c_fd, &temperature, &pressure) == 0) {
            log_data(log_file, temperature, pressure);
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            fprintf(log_file, "Error reading sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

