#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define BUZZER_PIN 18
#define ADC_CHANNEL 0
#define VREF 3.3
#define ADC_MAX 1023.0
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3
#define TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ambient_temperature(float *temp) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n", TEMP_FILE, strerror(errno));
        *temp = 25.0f;
        return -1;
    }
    if (fscanf(fp, "%f", temp) != 1) {
        fprintf(stderr, "Warning: cannot parse %s\n", TEMP_FILE);
        *temp = 25.0f;
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float compensate_voltage(int adc_value, float temperature) {
    float v = (float)adc_value * VREF / ADC_MAX;
    float c = 0.01f * temperature;
    return v + c;
}

static int log_data(int adc_value, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n",
                timestamp, adc_value, voltage, compensated_voltage, temperature, flame_detected) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: cannot set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned char bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: cannot set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: cannot set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && !read_ok) {
            if (read_mcp3008(ADC_CHANNEL, &adc_value) == 0) {
                if (adc_value >= 0 && adc_value <= 1023) {
                    read_ok = 1;
                } else {
                    fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
                    adc_value = -1;
                }
            } else {
                fprintf(stderr, "Error: SPI read failed, retry %d/%d\n", retries + 1, MAX_RETRIES);
            }
            retries++;
            if (retries < MAX_RETRIES) usleep(10000);
        }

        if (!read_ok) {
            fprintf(stderr, "Error: failed to read ADC after %d retries, skipping iteration\n", MAX_RETRIES);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float temperature = 0.0f;
        read_ambient_temperature(&temperature);

        float voltage = (float)adc_value * VREF / ADC_MAX;
        float compensated_voltage = compensate_voltage(adc_value, temperature);
        int flame_detected = (compensated_voltage > 1.5f) ? 1 : 0;

        if (log_data(adc_value, voltage, compensated_voltage, temperature, flame_detected) != 0) {
            fprintf(stderr, "Error: logging failed\n");
        }

        if (flame_detected) {
            printf("Flame detected! (ADC=%d, V=%.3f, Vc=%.3f, T=%.2f)\n",
                   adc_value, voltage, compensated_voltage, temperature);
        } else {
            printf("No flame. (ADC=%d, V=%.3f, Vc=%.3f, T=%.2f)\n",
                   adc_value, voltage, compensated_voltage, temperature);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

