#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, CE0 active low */
#define LED_PIN     17       /* BCM 17 */
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW  70
#define JSON_FILE  "water_levels.json"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define SLEEP_INCREMENT_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_json_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs.     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 on channel 0 (single-ended).       */
/* Returns 0–1023 on success, -1 on SPI transfer error.                */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC count to percentage (0–100).                           */
/* ------------------------------------------------------------------ */
static float adc_to_percentage(int adc_value)
{
    return ((float)adc_value / 1023.0f) * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Append one JSON entry to the file.                                 */
/* ------------------------------------------------------------------ */
static void log_water_level(FILE *fp, float percentage)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(fp, "  {\"timestamp\": \"%s.%03ld\", \"water_level\": %.2f},\n",
            timestamp, ts.tv_nsec / 1000000L, percentage);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Hysteresis LED control.                                            */
/* ------------------------------------------------------------------ */
static void control_led(float percentage)
{
    static int led_state = 0;

    if (percentage > WATER_LEVEL_THRESHOLD_HIGH && led_state == 0) {
        gpioWrite(LED_PIN, 1);
        led_state = 1;
        printf("Water level above threshold (%.2f%%). LED ON.\n", percentage);
    } else if (percentage < WATER_LEVEL_THRESHOLD_LOW && led_state == 1) {
        gpioWrite(LED_PIN, 0);
        led_state = 0;
        printf("Water level below threshold (%.2f%%). LED OFF.\n", percentage);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — close SPI, turn off LED, terminate pigpio, close JSON.   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    if (g_json_file != NULL) {
        fflush(g_json_file);
        fclose(g_json_file);
        g_json_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED pin --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* --- Open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open JSON file --- */
    g_json_file = fopen(JSON_FILE, "w");
    if (g_json_file == NULL) {
        perror("Error opening JSON file");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_json_file, "[\n");
    fflush(g_json_file);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Skipping.\n");
        } else {
            float percentage = adc_to_percentage(adc_value);
            printf("Water level: %.2f%%\n", percentage);
            log_water_level(g_json_file, percentage);
            control_led(percentage);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_US / SLEEP_INCREMENT_US && g_running; i++) {
            gpioDelay(SLEEP_INCREMENT_US);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    fprintf(g_json_file, "]\n");
    cleanup();
    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

