        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "Timestamp,Airflow (LPM)\n") < 0) {
            fprintf(stderr, "Error: Failed to write CSV header\n");
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(log_file);
    }

