#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_VALUE 300
#define DEFAULT_MAX_VALUE 700
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_INTERVAL 60
#define DEFAULT_EMAIL_RECIPIENT "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "/etc/msmtprc"
#define LOG_FILE "plant_data.txt"
#define SPI_SPEED 500000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture(int adc_value, int min_value, int max_value) {
    if (max_value <= min_value) {
        fprintf(stderr, "Error: Invalid calibration range (max=%d, min=%d)\n", max_value, min_value);
        return -1.0;
    }
    float moisture = 100.0 - ((float)(adc_value - min_value) / (float)(max_value - min_value) * 100.0);
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

static int log_data(float moisture) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture);
    fclose(fp);
    return 0;
}

static int send_email_alert(float moisture, const char *recipient, const char *config) {
    char command[512];
    snprintf(command, sizeof(command),
             "msmtp -C %s -t %s", config, recipient);

    FILE *fp = popen(command, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not execute msmtp: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "Subject: Plant Moisture Alert\n");
    fprintf(fp, "\n");
    fprintf(fp, "Plant moisture level is below threshold!\n");
    fprintf(fp, "Timestamp: %s\n", timestamp);
    fprintf(fp, "Moisture: %.2f%%\n", moisture);

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed: %s\n", strerror(errno));
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    } else if (WIFSIGNALED(status)) {
        fprintf(stderr, "Error: msmtp killed by signal %d\n", WTERMSIG(status));
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int spi_channel = DEFAULT_SPI_CHANNEL;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    int min_value = DEFAULT_MIN_VALUE;
    int max_value = DEFAULT_MAX_VALUE;
    float threshold = DEFAULT_THRESHOLD;
    int interval = DEFAULT_INTERVAL;
    char *email_recipient = strdup(DEFAULT_EMAIL_RECIPIENT);
    char *msmtp_config = strdup(DEFAULT_MSMTP_CONFIG);

    if (email_recipient == NULL || msmtp_config == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(email_recipient);
        free(msmtp_config);
        return 1;
    }

    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:M:t:i:e:")) != -1) {
        switch (opt) {
            case 'c': spi_channel = atoi(optarg); break;
            case 'a': adc_channel = atoi(optarg); break;
            case 'm': min_value = atoi(optarg); break;
            case 'M': max_value = atoi(optarg); break;
            case 't': threshold = atof(optarg); break;
            case 'i': interval = atoi(optarg); break;
            case 'e': email_recipient = strdup(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_value] [-M max_value] [-t threshold] [-i interval] [-e email_recipient]\n", argv[0]);
                free(email_recipient);
                free(msmtp_config);
                return 1;
        }
    }

    if (email_recipient == NULL) {
        email_recipient = strdup(DEFAULT_EMAIL_RECIPIENT);
    }
    if (msmtp_config == NULL) {
        msmtp_config = strdup(DEFAULT_MSMTP_CONFIG);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        free(email_recipient);
        free(msmtp_config);
        return 1;
    }

    spi_handle = spiOpen(spi_channel, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed on channel %d\n", spi_channel);
        gpioTerminate();
        free(email_recipient);
        free(msmtp_config);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Plant monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            float moisture = calculate_moisture(adc_value, min_value, max_value);
            if (moisture < 0.0) {
                fprintf(stderr, "Error: Failed to calculate moisture\n");
            } else {
                if (log_data(moisture) != 0) {
                    fprintf(stderr, "Error: Failed to log data\n");
                }
                if (moisture < threshold) {
                    if (send_email_alert(moisture, email_recipient, msmtp_config) != 0) {
                        fprintf(stderr, "Error: Failed to send email alert\n");
                    }
                }
            }
        }

        for (int i = 0; i < interval && running; i++) {
            sleep(1);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    free(email_recipient);
    free(msmtp_config);

    printf("Plant monitoring stopped.\n");
    return 0;
}

