        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Logging to %s every %d second(s).\n",
           LOG_FILE, interval);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
