#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (BCM GPIO8)                  */
#define SPI_SPEED      1000000    /* 1 MHz                                 */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                 */
#define ADC_CHANNEL    0          /* MCP3008 channel 0                     */
#define VREF           3.3f       /* Reference voltage                     */
#define ADC_MAX        1023       /* 10-bit ADC full-scale code            */
#define SAMPLE_PERIOD  1          /* Seconds between readings              */
#define MAX_CONSEC_ERR 10         /* Abort after this many consecutive errs */

/* Sensor-absent heuristic: a rail-stuck reading is likely no sensor present */
#define RAIL_LOW       0.0f
#define RAIL_HIGH      (VREF - 0.05f)  /* 3.25 V — within tolerance of 3.3 V  */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  read_mcp3008(int channel, int *out_value);
static float adc_to_voltage(int adc_value);
static bool is_sensor_absent(float voltage);
static void log_reading(float voltage, int adc_value);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MCP3008 read ------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 * Result: bits 9..0 in rx[1] (low 2) and rx[2] (8).
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    *out_value = adc_value;
    return 0;
}

/* ----------------------------- Conversions ------------------------------- */
static float adc_to_voltage(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX) * VREF;
}

/* ----------------------------- Sensor-absent ----------------------------- */
static bool is_sensor_absent(float voltage)
{
    return (voltage <= RAIL_LOW + 0.01f) || (voltage >= RAIL_HIGH - 0.01f);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_reading(float voltage, int adc_value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s - Voltage: %.3f V, ADC: %d\n", timestamp, voltage, adc_value);
    fflush(stdout);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90823 pressure sensor monitoring started.\n");
    printf("SPI0 CE0 @ %d Hz, ADC channel %d, Vref %.1f V\n",
           SPI_SPEED, ADC_CHANNEL, VREF);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int consecutive_errors = 0;

    while (g_running) {
        int adc_value = 0;

        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            consecutive_errors++;
            fprintf(stderr, "ADC read error (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Too many consecutive errors; aborting.\n");
                break;
            }
            sleep(SAMPLE_PERIOD);
            continue;
        }

        consecutive_errors = 0;
        float voltage = adc_to_voltage(adc_value);

        if (is_sensor_absent(voltage)) {
            fprintf(stderr,
                    "Warning: sensor-absent heuristic triggered "
                    "(voltage %.3f V). Check wiring/power.\n",
                    voltage);
        }

        log_reading(voltage, adc_value);

        sleep(SAMPLE_PERIOD);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

