    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   tx[2] = 0x00  (don't care, clocks out low 2 bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void log_data(int adc_value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    printf("[%s] ADC Value: %d\n", timestamp, adc_value);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Data Logger\n");
    printf("SPI device: %s | Mode: %d | Speed: %d Hz | Channel: %d\n",
           SPI_DEVICE, SPI_MODE, SPI_SPEED_HZ, MCP3008_CHANNEL);
    printf("Sampling every %d seconds. Press Ctrl+C to exit.\n\n", SAMPLE_INTERVAL);

    int consecutive_errors = 0;

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_fd, MCP3008_CHANNEL);

        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "Error reading ADC value (consecutive: %d/%d)\n",
                    consecutive_errors, MAX_CONSECUTIVE_ERRORS);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive SPI errors. Aborting.\n");
                break;
            }
        } else {
            consecutive_errors = 0;

            if (adc_value == 0 || adc_value == 1023) {
                fprintf(stderr, "Warning: ADC value at extreme (%d). Sensor absent or wiring fault?\n", adc_value);
            }

            log_data(adc_value);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

