#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define PUMP_GPIO 17
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_MS 5000

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01;
    spi_tx_buf[1] = (0x08 | channel) << 4;
    spi_tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, (char *)spi_tx_buf, (char *)spi_rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to pump GPIO %d\n", PUMP_GPIO);
        return -1;
    }
    return 0;
}

static void add_log_entry(int moisture_level, int pump_state) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer ---\n");
    int start_index = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int index = (start_index + i) % BUFFER_SIZE;
        char time_str[30];
        struct tm *tm_info = localtime(&log_buffer[index].timestamp);
        if (tm_info != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "Invalid Time", sizeof(time_str));
            time_str[sizeof(time_str) - 1] = '\0';
        }
        printf("[%s] Moisture: %d, Pump: %d\n", time_str, log_buffer[index].moisture_level, log_buffer[index].pump_state);
    }
    printf("--- End of Log Buffer ---\n\n");
    fflush(stdout);
}

static void timer_callback(void *user_data) {
    (void)user_data;

    int moisture_level = read_mcp3008(0);
    if (moisture_level < 0) {
        fprintf(stderr, "Error: Failed to read moisture level\n");
        return;
    }

    int pump_state = gpioRead(PUMP_GPIO);
    if (pump_state < 0) {
        fprintf(stderr, "Error: Failed to read pump state\n");
        return;
    }

    if (moisture_level < MOISTURE_LOW_THRESHOLD && pump_state == 0) {
        if (control_pump(1) == 0) {
            pump_state = 1;
            printf("Pump turned ON\n");
        }
    } else if (moisture_level > MOISTURE_HIGH_THRESHOLD && pump_state == 1) {
        if (control_pump(0) == 0) {
            pump_state = 0;
            printf("Pump turned OFF\n");
        }
    }

    add_log_entry(moisture_level, pump_state);
    print_log_buffer();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set pump GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize pump GPIO %d to LOW\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetTimerFunc(0, SAMPLE_INTERVAL_MS, timer_callback) != 0) {
        fprintf(stderr, "Error: Failed to set timer function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        sleep(1);
    }

    printf("\nShutting down...\n");

    gpioSetTimerFunc(0, 0, NULL);
    control_pump(0);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil Moisture Monitoring System stopped.\n");
    return 0;
}

