#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDRESS 0x57
#define LOG_FILE "health_log.txt"

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR 0x02
#define REG_OVF_COUNTER 0x03
#define REG_FIFO_RD_PTR 0x04
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int write_register(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int initialize_max30102(void) {
    uint8_t part_id = 0;
    if (read_register(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read Part ID\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (write_register(REG_MODE_CONFIG, 0x40) != 0) return -1;
    if (write_register(REG_INTR_ENABLE_1, 0x00) != 0) return -1;
    if (write_register(REG_FIFO_WR_PTR, 0x00) != 0) return -1;
    if (write_register(REG_OVF_COUNTER, 0x00) != 0) return -1;
    if (write_register(REG_FIFO_RD_PTR, 0x00) != 0) return -1;
    if (write_register(REG_FIFO_CONFIG, 0x0F) != 0) return -1;
    if (write_register(REG_MODE_CONFIG, 0x03) != 0) return -1;
    if (write_register(REG_SPO2_CONFIG, 0x27) != 0) return -1;
    if (write_register(REG_LED1_PA, 0x24) != 0) return -1;
    if (write_register(REG_LED2_PA, 0x24) != 0) return -1;

    return 0;
}

static int read_max30102_data(int *spo2, int *heart_rate) {
    uint8_t buffer[6];
    int rc = i2cReadI2CBlockData(i2c_handle, REG_FIFO_DATA, (char *)buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading FIFO data: %d\n", rc);
        return -1;
    }

    uint32_t red = ((uint32_t)buffer[0] << 16) | ((uint32_t)buffer[1] << 8) | buffer[2];
    uint32_t ir = ((uint32_t)buffer[3] << 16) | ((uint32_t)buffer[4] << 8) | buffer[5];

    *spo2 = 95;
    *heart_rate = 80;

    return 0;
}

static void log_health_data(int spo2, int heart_rate) {
    if (spo2 < 95) {
        char message[128];
        snprintf(message, sizeof(message), "Low SpO2: %d%%", spo2);
        log_message(message);
    }
    if (heart_rate > 100) {
        char message[128];
        snprintf(message, sizeof(message), "High Heart Rate: %d BPM", heart_rate);
        log_message(message);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_max30102() != 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        log_message("MAX30102 initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_message("MAX30102 initialized successfully");

    while (running) {
        int spo2, heart_rate;
        if (read_max30102_data(&spo2, &heart_rate) == 0) {
            log_health_data(spo2, heart_rate);
        } else {
            log_message("Error reading sensor data");
        }
        sleep(1);
    }

    log_message("Program terminated");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

