    int rc = i2cReadI2CBlockData(i2c_handle, REG_FIFO_DATA, (char *)buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading FIFO data: %d\n", rc);
        return -1;
    }

    uint32_t red = ((uint32_t)buffer[0] << 16) | ((uint32_t)buffer[1] << 8) | buffer[2];
    uint32_t ir = ((uint32_t)buffer[3] << 16) | ((uint32_t)buffer[4] << 8) | buffer[5];

    *spo2 = 95;
    *heart_rate = 80;

    return 0;
}

static void log_health_data(int spo2, int heart_rate) {
    if (spo2 < 95) {
        char message[128];
        snprintf(message, sizeof(message), "Low SpO2: %d%%", spo2);
        log_message(message);
    }
    if (heart_rate > 100) {
        char message[128];
        snprintf(message, sizeof(message), "High Heart Rate: %d BPM", heart_rate);
        log_message(message);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_max30102() != 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        log_message("MAX30102 initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_message("MAX30102 initialized successfully");

    while (running) {
        int spo2, heart_rate;
        if (read_max30102_data(&spo2, &heart_rate) == 0) {
            log_health_data(spo2, heart_rate);
        } else {
            log_message("Error reading sensor data");
        }
        sleep(1);
    }

    log_message("Program terminated");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

