#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE0 */
#define VREF        3.3
#define NUM_CHANNELS 3
#define LOG_FILE    "analog_log.csv"
#define SAMPLE_US   500000   /* 500 ms */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0..1023 on success, or -1 on SPI error.
 */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out low 2 bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc;
}

static float adc_to_voltage(int adc) {
    return (adc / 1023.0f) * VREF;
}

static void log_data(FILE *fp, int channel, float voltage) {
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%d,%.3f\n", ts, channel, voltage);
    fflush(fp);
}

int main(void) {
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append) --- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,Channel,Voltage\n");
        fflush(log_fp);
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(log_fp);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging MCP3008 channels 0-2 to %s every 500 ms. Press Ctrl+C to stop.\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (running) {
        for (int ch = 0; ch < NUM_CHANNELS; ch++) {
            int adc = read_mcp3008(ch);
            if (adc < 0) {
                fprintf(stderr, "Read failed on channel %d; skipping.\n", ch);
                continue;
            }
            float v = adc_to_voltage(adc);
            log_data(log_fp, ch, v);
            printf("Ch %d: %.3f V\n", ch, v);
        }
        gpioDelay(SAMPLE_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (log_fp) {
        fclose(log_fp);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

