#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

#define BUZZER_GPIO 24
#define THRESHOLD   500
#define SAMPLE_US   500000   /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, or -1 on error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel select)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + 8 bits of rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int set_buzzer(int on)
{
    int ret = gpioWrite(BUZZER_GPIO, on ? 1 : 0);
    if (ret < 0) {
        fprintf(stderr, "gpioWrite(%d) failed: %s\n", BUZZER_GPIO, pigpio_error(ret));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(g_spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure buzzer GPIO as output, ensure it starts OFF --- */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", BUZZER_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_buzzer(0) < 0) {
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MQ-2 gas sensor monitoring started. Press Ctrl-C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
        } else {
            printf("ADC Value: %d\n", adc_value);
            if (adc_value >= THRESHOLD) {
                if (set_buzzer(1) < 0) {
                    break;
                }
            } else {
                if (set_buzzer(0) < 0) {
                    break;
                }
            }
        }
        gpioDelay(SAMPLE_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    set_buzzer(0);  /* ensure buzzer is off */
    spiClose(g_spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

