#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CFG  0x01

#define RELAY_GPIO       17
#define DOOR_SENSOR_GPIO 27

#define LOG_FILE         "/var/log/door_events.log"
#define CALIBRATION_SAMPLES 10
#define SAMPLE_DELAY_US  50000
#define LOOP_DELAY_US    200000
#define RELAY_PULSE_US   3000000

#define ADS1115_CFG_OS   0x8000
#define ADS1115_CFG_MUX_A0 0x4000
#define ADS1115_CFG_PGA_4V 0x0200
#define ADS1115_CFG_MODE_SS 0x0100
#define ADS1115_CFG_DR_128 0x0080

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    struct i2c_msg msg = { .addr = ADS1115_ADDR, .flags = 0, .len = 3, .buf = buf };
    struct i2c_rdwr_ioctl_data data = { .msgs = &msg, .nmsgs = 1 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t wbuf[1] = { reg };
    struct i2c_msg wmsg = { .addr = ADS1115_ADDR, .flags = 0, .len = 1, .buf = wbuf };
    struct i2c_msg rmsg = { .addr = ADS1115_ADDR, .flags = I2C_M_RD, .len = 2, .buf = (uint8_t *)val };
    struct i2c_msg msgs[2] = { wmsg, rmsg };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) return -1;
    *val = ((uint16_t)msgs[1].buf[0] << 8) | msgs[1].buf[1];
    return 0;
}

static int read_ads1115(int fd, int16_t *out) {
    uint16_t cfg = ADS1115_CFG_OS | ADS1115_CFG_MUX_A0 | ADS1115_CFG_PGA_4V | ADS1115_CFG_MODE_SS | ADS1115_CFG_DR_128;
    if (i2c_write_reg16(fd, ADS1115_REG_CFG, cfg) < 0) return -1;
    usleep(10000);
    uint16_t raw;
    if (i2c_read_reg16(fd, ADS1115_REG_CONV, &raw) < 0) return -1;
    *out = (int16_t)raw;
    return 0;
}

static int calibrate_threshold(int fd, int *threshold) {
    int sum = 0, valid = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int16_t v;
        if (read_ads1115(fd, &v) < 0) {
            fprintf(stderr, "Calibration read failed: %s\n", strerror(errno));
            return -1;
        }
        sum += v;
        valid++;
        usleep(SAMPLE_DELAY_US);
    }
    if (valid == 0) return -1;
    *threshold = sum / valid;
    printf("Calibration complete. Threshold: %d\n", *threshold);
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

