        int16_t v;
        if (read_ads1115(i2c_fd, &v) < 0) {
            fprintf(stderr, "Read failed: %s\n", strerror(errno));
            log_event("Sensor read error");
            usleep(LOOP_DELAY_US);
            continue;
        }

        if (v < threshold) {
            printf("Threshold breached! Activating relay.\n");
            gpioWrite(RELAY_GPIO, 1);
            usleep(RELAY_PULSE_US);
