#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define ADC_CHANNEL    0
#define PUMP_GPIO      18
#define LOG_FILE       "irrigation.log"
#define MAX_RETRIES    3
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Error: Invalid ADC channel");
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (result == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        char msg[128];
        snprintf(msg, sizeof(msg), "SPI transfer failed (attempt %d/%d, result=%d)",
                 attempt + 1, MAX_RETRIES, result);
        log_message(msg);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000);
        }
    }
    log_message("Error: SPI communication failed after retries");
    return -1;
}

static float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        log_message("Error: Invalid ADC value");
        return -1.0;
    }
    return ((float)adc_value / 1023.0) * 100.0;
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        log_message("Error: Failed to write to pump GPIO");
    } else {
        char msg[64];
        snprintf(msg, sizeof(msg), "Pump %s", state ? "activated" : "deactivated");
        log_message(msg);
    }
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    int pump_duration = DEFAULT_PUMP_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atof(argv[++i]);
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            pump_duration = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            sleep_interval = atoi(argv[++i]);
        } else {
            fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    control_pump(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            log_message("Error: Failed to read ADC value, skipping irrigation cycle");
            for (int i = 0; i < sleep_interval && running; i++) {
                sleep(1);
            }
            continue;
        }

        float moisture = calculate_moisture(adc_value);
        if (moisture < 0) {
            log_message("Error: Failed to calculate moisture, skipping irrigation cycle");
            for (int i = 0; i < sleep_interval && running; i++) {
                sleep(1);
            }
            continue;
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture level: %.2f%% (ADC: %d)", moisture, adc_value);
        log_message(msg);

        if (moisture < threshold) {
            log_message("Moisture below threshold, activating pump");
            control_pump(1);

            for (int i = 0; i < pump_duration && running; i++) {
                sleep(1);
            }

            control_pump(0);
            log_message("Pump deactivated");
        }

        for (int i = 0; i < sleep_interval && running; i++) {
            sleep(1);
        }
    }

    log_message("Irrigation system shutting down");
    cleanup();
    return 0;
}

