#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "/var/log/sound_events.log"
#define INITIAL_THRESHOLD 100
#define THRESHOLD_INCREMENT 10
#define THRESHOLD_DECREMENT 5
#define THRESHOLD_MAX 255
#define THRESHOLD_MIN 50

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_event(int adc_value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s - Peak detected: %d\n", timestamp, adc_value) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
    }
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int threshold = INITIAL_THRESHOLD;
    int peak_detected = 0;

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (adc_value > threshold) {
            log_event(adc_value);
            peak_detected = 1;
            threshold = (threshold + THRESHOLD_INCREMENT > THRESHOLD_MAX) ? THRESHOLD_MAX : threshold + THRESHOLD_INCREMENT;
        } else {
            if (peak_detected) {
                threshold = (threshold - THRESHOLD_DECREMENT < THRESHOLD_MIN) ? THRESHOLD_MIN : threshold - THRESHOLD_DECREMENT;
                peak_detected = 0;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Shutting down...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

