#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define PCF8591_CTRL   0x40   /* single-ended, channel 0, auto-increment off */
#define SAMPLE_US      100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_sigint_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_sigint_handler() != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Dummy write to select AIN0 single-ended; the PCF8591 returns the
       result of the *previous* conversion on the next read, so we discard
       one byte before entering the main loop. */
    uint8_t ctrl = PCF8591_CTRL;
    if (write(fd, &ctrl, 1) != 1) {
        fprintf(stderr, "Failed to configure PCF8591: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Dummy read to clear the stale conversion result. */
    uint8_t dummy;
    ssize_t n = read(fd, &dummy, 1);
    if (n != 1) {
        fprintf(stderr, "Failed to read dummy byte: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        uint8_t value;
        n = read(fd, &value, 1);
        if (n != 1) {
            fprintf(stderr, "Failed to read ADC value: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("AIN0: %u\n", (unsigned int)value);
        fflush(stdout);
        usleep(SAMPLE_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

