        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Dummy write to select AIN0 single-ended; the PCF8591 returns the
       result of the *previous* conversion on the next read, so we discard
       one byte before entering the main loop. */
    uint8_t ctrl = PCF8591_CTRL;
    if (write(fd, &ctrl, 1) != 1) {
        fprintf(stderr, "Failed to configure PCF8591: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Dummy read to clear the stale conversion result. */
    uint8_t dummy;
    ssize_t n = read(fd, &dummy, 1);
    if (n != 1) {
        fprintf(stderr, "Failed to read dummy byte: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        uint8_t value;
        n = read(fd, &value, 1);
        if (n != 1) {
            fprintf(stderr, "Failed to read ADC value: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("AIN0: %u\n", (unsigned int)value);
        fflush(stdout);
        usleep(SAMPLE_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

