#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/* Single-ended AIN0, PGA gain +/-4.096 V, single-shot, 128 SPS */
#define ADS1115_CFG_BASE     0x8000  /* OS bit */
#define ADS1115_CFG_MUX_AIN0 0x4000  /* MUX[14:12] = 100 */
#define ADS1115_CFG_PGA_4V   0x0200  /* PGA[11:9] = 001 */
#define ADS1115_CFG_MODE_SS  0x0100  /* MODE = 1 */
#define ADS1115_CFG_DR_128   0x0080  /* DR[7:5] = 100 */
#define ADS1115_CFG_CQUE_1   0x0001  /* CQUE[2:0] = 000 */

#define GPIO_MOTOR_SHUTDOWN  27
#define BUFFER_SIZE          10
#define SAMPLE_PERIOD_US     1000000  /* 1 Hz */
#define THRESHOLD_GAUSS      500.0f
#define VREF                 3.3f
#define ADC_MAX              32767.0f  /* 16-bit signed, single-ended positive */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Circular buffer -------------------------- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ----------------------------- ADS1115 helpers -------------------------- */
static int ads1115_write_config(int handle, uint16_t cfg)
{
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)((cfg >> 8) & 0xFF);
    buf[2] = (char)(cfg & 0xFF);
    if (i2cWriteDevice(handle, buf, 3) < 0) {
        syslog(LOG_ERR, "ads1115_write_config: i2cWriteDevice failed");
        return -1;
    }
    return 0;
}

static int ads1115_read_conversion(int handle, int16_t *raw)
{
    char reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "ads1115_read_conversion: i2cWriteDevice (reg select) failed");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        syslog(LOG_ERR, "ads1115_read_conversion: i2cReadDevice failed");
        return -1;
    }
    *raw = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

/* ----------------------------- Conversion -------------------------------- */
static float voltage_to_gauss(float voltage)
{
    /*
     * SS49E transfer function (approximate):
     *   B (Gauss) = 1200 * (V - 0.5)  for V in [0.4, 0.8]
     *   B = 0 for V < 0.4 or V > 0.8
     * This is a simplified model; a real deployment would calibrate
     * the offset and slope for the specific magnet and environment.
     */
    if (voltage < 0.4f || voltage > 0.8f)
        return 0.0f;
    return 1200.0f * (voltage - 0.5f);
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed (bus %d, addr 0x%02X): %d",
               I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ads1115_write_config(g_i2c_handle,
                             ADS1115_CFG_BASE | ADS1115_CFG_MUX_AIN0 |
                             ADS1115_CFG_PGA_4V | ADS1115_CFG_MODE_SS |
                             ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_1) < 0) {
        syslog(LOG_ERR, "Failed to configure ADS1115");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_MOTOR_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_MOTOR_SHUTDOWN, 0);

    CircularBuffer gauss_buffer;
    cb_init(&gauss_buffer);

    syslog(LOG_INFO, "Monitoring started (threshold %.1f Gauss)", THRESHOLD_GAUSS);

    while (g_running) {
        int16_t raw;
        if (ads1115_read_conversion(g_i2c_handle, &raw) < 0) {
            syslog(LOG_WARNING, "ADC read failed; skipping sample");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = ((float)raw / ADC_MAX) * VREF;
        if (voltage < 0.0f || voltage > VREF) {
            syslog(LOG_WARNING, "Voltage out of range: %.3f V", voltage);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        cb_add(&gauss_buffer, gauss);
        float avg = cb_average(&gauss_buffer);

        syslog(LOG_INFO, "Raw=%d  V=%.3f  Gauss=%.2f  Avg=%.2f",
               raw, voltage, gauss, avg);

        if (avg > THRESHOLD_GAUSS) {
            syslog(LOG_ALERT, "Threshold exceeded: %.2f Gauss > %.1f Gauss",
                   avg, THRESHOLD_GAUSS);
            gpioWrite(GPIO_MOTOR_SHUTDOWN, 1);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ----------------------------- Cleanup ------------------------------- */
    syslog(LOG_INFO, "Shutting down");
    gpioWrite(GPIO_MOTOR_SHUTDOWN, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

