#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000  /* 1 MHz */
#define SPI_FLAGS        0        /* Mode 0, active-low CE */
#define ADC_CHANNEL      0
#define PUMP_GPIO        18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10      /* seconds */
#define SAMPLE_INTERVAL  60       /* seconds */
#define LOG_FILE         "watering_events.txt"
#define MAX_CONSECUTIVE_ERRORS 10

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI transfer failure,
 * -2 on invalid channel, -3 on invalid data (stuck or out-of-range).
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -2;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9–8 in rx[1] & 0x03, bits 7–0 in rx[2].
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    /* Sanity-check: 10-bit ADC should never read 0 or 1023 repeatedly */
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Warning: ADC reading at extreme (%d) — possible sensor fault\n", adc_value);
        return -3;
    }

    return adc_value;
}

static int control_pump(int state)
{
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: failed to %s pump (GPIO %d)\n",
                state ? "activate" : "deactivate", PUMP_GPIO);
        return -1;
    }
    return 0;
}

static void log_event(int moisture_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Moisture: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_level);
    } else {
        fprintf(fp, "[timestamp error] - Moisture: %d\n", moisture_level);
    }

    fclose(fp);
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (control_pump(0) != 0) {
        fprintf(stderr, "Error: failed to initialise pump to OFF state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open SPI bus --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", g_spi_handle);
        gpioWrite(PUMP_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction failed");
        spiClose(g_spi_handle);
        gpioWrite(PUMP_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitor started. Threshold=%d, pump GPIO=%d, interval=%ds\n",
           MOISTURE_THRESHOLD, PUMP_GPIO, SAMPLE_INTERVAL);

    int consecutive_errors = 0;

    while (g_running) {
        int moisture = read_mcp3008(ADC_CHANNEL);

        if (moisture < 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: ADC read failed (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Fatal: %d consecutive ADC errors — aborting\n",
                        consecutive_errors);
                break;
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        consecutive_errors = 0;

        printf("Moisture level: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold — watering for %d seconds\n",
                   WATERING_DURATION);
            if (control_pump(1) == 0) {
                log_event(moisture);
                /* Sleep in 1-second increments so signals are caught promptly */
                for (int i = 0; i < WATERING_DURATION && g_running; i++) {
                    sleep(1);
                }
                control_pump(0);
            }
        }

        /* Sleep in 1-second increments for responsive shutdown */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    control_pump(0);
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

