#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8483  /* MUX=AIN0(GND), PGA=4.096V, single-shot, 128 SPS */
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define SAMPLE_INTERVAL_US 100000
#define BLINK_TOTAL_US 1000000
#define BLINK_HALF_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int pigpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115_raw(void) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing conversion register pointer: %s\n", strerror(errno));
        return -1;
    }
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading conversion data: %s\n", strerror(errno));
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

static double read_magnetic_field(void) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_BASE >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_BASE & 0xFF;
    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing config: %s\n", strerror(errno));
