#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_ON 30.0
#define MOISTURE_THRESHOLD_OFF 35.0
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_moisture_monitor"
#define MQTT_TOPIC "soil_moisture"
#define MQTT_COMMAND_TOPIC "pump_control"
#define SAMPLE_INTERVAL 60
#define SENSOR_READ_ERROR -1
#define SENSOR_OUT_OF_RANGE -2

static int spi_handle = -1;
static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return SENSOR_READ_ERROR;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed on channel %d", channel);
        return SENSOR_READ_ERROR;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0;
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

static int control_pump(float moisture_level) {
    static int pump_state = 0;

    if (moisture_level < MOISTURE_THRESHOLD_ON && pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            syslog(LOG_INFO, "Pump turned ON (moisture: %.2f%%)", moisture_level);
            pump_state = 1;
        } else {
            syslog(LOG_ERR, "Failed to turn pump ON");
            return -1;
        }
    } else if (moisture_level > MOISTURE_THRESHOLD_OFF && pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            syslog(LOG_INFO, "Pump turned OFF (moisture: %.2f%%)", moisture_level);
            pump_state = 0;
        } else {
            syslog(LOG_ERR, "Failed to turn pump OFF");
            return -1;
        }
    }
    return 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        if (mosquitto_subscribe(m, NULL, MQTT_COMMAND_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to command topic");
        }
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_strerror(result));
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0) {
        char payload[32];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';

        if (strcmp(payload, "pump_on") == 0) {
            if (gpioWrite(PUMP_GPIO, 1) == 0) {
                syslog(LOG_INFO, "Pump turned ON via MQTT");
            } else {
                syslog(LOG_ERR, "Failed to turn pump ON via MQTT");
            }
        } else if (strcmp(payload, "pump_off") == 0) {
            if (gpioWrite(PUMP_GPIO, 0) == 0) {
                syslog(LOG_INFO, "Pump turned OFF via MQTT");
            } else {
                syslog(LOG_ERR, "Failed to turn pump OFF via MQTT");
            }
        } else {
            syslog(LOG_WARNING, "Unknown command received: %s", payload);
        }
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != 0) {
        syslog(LOG_WARNING, "Unexpected MQTT disconnect: %s", mosquitto_strerror(rc));
    }
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        mosq = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog(MQTT_CLIENT_ID, LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set pump GPIO mode");
        cleanup();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %d", spi_handle);
        cleanup();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    rc = mosquitto_subscribe(mosq, NULL, MQTT_COMMAND_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT subscribe failed: %s", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Soil moisture monitor started");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value == SENSOR_READ_ERROR) {
            syslog(LOG_ERR, "Failed to read ADC value");
        } else if (adc_value == SENSOR_OUT_OF_RANGE) {
            syslog(LOG_ERR, "Sensor out of range or absent");
        } else {
            float moisture_level = adc_to_moisture(adc_value);
            if (moisture_level >= 0.0) {
                control_pump(moisture_level);
                char payload[32];
                snprintf(payload, sizeof(payload), "%.2f", moisture_level);
                rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, (int)strlen(payload), payload, 0, false);
                if (rc != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
                }
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

