#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define VREF        3.3f
#define CSV_FILE    "sensor_data.csv"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns 0-1023 on success, or -1 on error.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (SGL/DIFF=1, D2-D0=channel, padded)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: bits 9-8 in rx[1] & 0x03, bits 7-0 in rx[2].
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

static float adc_to_voltage(int adc_value)
{
    return (adc_value / 1023.0f) * VREF;
}

static int log_data(const char *filename, float v0, float v1, float v2)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, v0, v1, v2) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 at 1 MHz, mode 0 (CPOL=0, CPHA=0) --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MCP3008 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc0 = read_mcp3008(spi_handle, 0);
        int adc1 = read_mcp3008(spi_handle, 1);
        int adc2 = read_mcp3008(spi_handle, 2);

        if (adc0 < 0 || adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "Error reading ADC values. Skipping sample.\n");
        } else {
            float v0 = adc_to_voltage(adc0);
            float v1 = adc_to_voltage(adc1);
            float v2 = adc_to_voltage(adc2);

            if (log_data(CSV_FILE, v0, v1, v2) != 0) {
                fprintf(stderr, "Error logging data.\n");
            } else {
                printf("Logged: %.3f, %.3f, %.3f\n", v0, v1, v2);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

