#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define PWM_FREQUENCY 100
#define PWM_RANGE 1000

#define NOISE_THRESHOLD 500
#define SAMPLE_DELAY_US 10000
#define VIBRATION_LOG_FILE "vibration_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void set_motor_speed(int pin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    gpioPWM(pin, speed);
}

static void log_vibration_event(int motor_pin, int noise_level) {
    FILE *fp = fopen(VIBRATION_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", VIBRATION_LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Motor %d: Vibration detected (Noise Level: %d)\n", timestamp, motor_pin, noise_level);
    fclose(fp);
}

static void cleanup(void) {
    set_motor_speed(MOTOR1_PIN, 0);
    set_motor_speed(MOTOR2_PIN, 0);
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Vibration detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int noise_level = read_mcp3008(0);
        if (noise_level < 0) {
            fprintf(stderr, "Error reading ADC, skipping iteration\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (noise_level > NOISE_THRESHOLD) {
            set_motor_speed(MOTOR1_PIN, 500);
            set_motor_speed(MOTOR2_PIN, 500);
            log_vibration_event(MOTOR1_PIN, noise_level);
            log_vibration_event(MOTOR2_PIN, noise_level);
        } else {
            set_motor_speed(MOTOR1_PIN, 0);
            set_motor_speed(MOTOR2_PIN, 0);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

