#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <stdint.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_CONT_HIGH_RES 0x10
#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL 5
#define ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    uint32_t speed = SPI_SPEED;
    uint8_t mode = 0;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    return 0;
}

int read_bh1750(float *lux) {
    if (i2c_fd < 0) return -1;
    if (write(i2c_fd, &BH1750_CMD_CONT_HIGH_RES, 1) != 1) {
        perror("Failed to write to BH1750");
        return -1;
    }
    usleep(180000);
    uint8_t buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }
    uint16_t raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

int read_mcp3008(int channel, int *value) {
    if (spi_fd < 0) return -1;
    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

float adc_to_db(int adc_value) {
    if (adc_value <= 0) return -120.0f;
    float voltage = (float)adc_value / 1023.0f * 3.3f;
    float db = 20.0f * log10f(voltage / 0.00002f);
    return db;
}

void log_data(float sound_level, float light_level, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(log_file);
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    while (running) {
        float sound_level = 0.0f;
        float light_level = 0.0f;
        int error_code = 0;

        int adc_value = 0;
        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            error_code = 1;
        } else {
            sound_level = adc_to_db(adc_value);
        }

        if (read_bh1750(&light_level) != 0) {
            error_code = 2;
        }

        log_data(sound_level, light_level, error_code);
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

