#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000  /* 1 MHz */
#define SPI_FLAGS        0        /* Mode 0, active-low CE */

#define PUMP_GPIO        17
#define MOISTURE_THRESHOLD 30.0f
#define ADC_MAX          1023     /* MCP3008 is 10-bit */
#define ADC_VREF         3.3f     /* Pi 3.3 V rail */
#define VH400_DRY        0.0f     /* 0 V = dry air */
#define VH400_WET        3.0f     /* 3 V = saturated soil */
#define SAMPLE_INTERVAL  60       /* seconds */
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0..1023 on success, -1 on error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc;
}

static float adc_to_moisture(int adc)
{
    float voltage = (float)adc * ADC_VREF / (float)ADC_MAX;
    float moisture = (voltage - VH400_DRY) / (VH400_WET - VH400_DRY) * 100.0f;
    if (moisture < 0.0f)   moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;
    return moisture;
}

static void log_reading(float moisture)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Moisture: %.2f%%\n", ts, moisture);
}

static void control_pump(float moisture)
{
    int level = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(PUMP_GPIO, level) < 0) {
        fprintf(stderr, "Failed to write pump GPIO %d\n", PUMP_GPIO);
        return;
    }
    printf("Pump %s\n", level ? "ON" : "OFF");
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI init --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Pump GPIO setup --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump GPIO %d as output\n", PUMP_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);  /* ensure pump is off at start */

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Monitoring System started.\n");
    printf("SPI channel %d, %d Hz | Pump on GPIO %d | Threshold %.1f%%\n",
           SPI_CHANNEL, SPI_SPEED, PUMP_GPIO, MOISTURE_THRESHOLD);

    while (g_running) {
        int adc = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
            adc = read_mcp3008(0);
            if (adc >= 0) break;
            if (attempt < MAX_RETRIES - 1) {
                fprintf(stderr, "Read attempt %d failed; retrying...\n", attempt + 1);
                time_sleep(1.0);
            }
        }

        if (adc < 0) {
            fprintf(stderr, "Sensor read failed after %d attempts; skipping cycle.\n",
                    MAX_RETRIES);
        } else {
            float moisture = adc_to_moisture(adc);
            log_reading(moisture);
            control_pump(moisture);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL && g_running; ++s) {
            time_sleep(1.0);
        }
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpioWrite(PUMP_GPIO, 0);
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

