#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define MAX_RETRIES 5
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int result = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n", result, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0f;
    }
    return 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
}

static int log_data(float moisture_percentage, int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, ADC: %d, Moisture: %.2f%%\n", timestamp, adc_value, moisture_percentage);
    fclose(fp);
    return 0;
}

static int log_error(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, ERROR: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

static int read_adc_with_retry(int channel) {
    int adc_value = -1;
    int delay_ms = 10;

    for (int i = 0; i < MAX_RETRIES; i++) {
        adc_value = read_mcp3008(channel);
        if (adc_value >= 0) {
            return adc_value;
        }
        fprintf(stderr, "Read attempt %d failed, retrying in %d ms...\n", i + 1, delay_ms);
        gpioDelay(delay_ms * 1000);
        delay_ms *= 2;
    }

    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc_with_retry(ADC_CHANNEL);

        if (adc_value >= 0) {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            if (moisture_percentage >= 0.0f) {
                if (log_data(moisture_percentage, adc_value) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
                printf("ADC: %d, Moisture: %.2f%%\n", adc_value, moisture_percentage);
            } else {
                fprintf(stderr, "Failed to calculate moisture percentage\n");
                log_error("Failed to calculate moisture percentage");
            }
        } else {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", MAX_RETRIES);
            log_error("Failed to read ADC value after retries");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

