    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && !terminate) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Error: SPI read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                sleep(RETRY_DELAY);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: SPI read failed after %d retries, re-initializing SPI...\n", MAX_RETRIES);
            if (init_spi() != 0) {
                fprintf(stderr, "Error: SPI re-initialization failed, exiting.\n");
                break;
            }
            continue;
        }

        float aqi = calculate_aqi(adc_value);
        if (aqi < 0.0f) {
            fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
            continue;
        }

        log_data(aqi);
        control_fan(aqi);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

