            gpioDelay(SAMPLE_PERIOD * 1000000);
            continue;
        }

        if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr, "Warning: Sensor absent or wiring fault (ADC raw = %d)\n", adc_value);
        }

