#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0        /* Mode 0, active-low CE */

#define PUMP_GPIO      18       /* BCM 18 */
#define MOISTURE_THRESHOLD 300
#define SAMPLE_INTERVAL 60      /* seconds */
#define LOG_FILE       "irrigation.log"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs.     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 single-ended channel (0–7).         */
/* Returns 0–1023 on success, -1 on error.                            */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped line to the log file.                          */
/* ------------------------------------------------------------------ */
static void log_data(int moisture, int pump_on)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_file, "%s, Moisture: %d, Pump: %s\n",
            ts, moisture, pump_on ? "ON" : "OFF");
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup — turn pump off, close SPI, close log, terminate pigpio.   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure pump GPIO ---- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);  /* pump off at startup */

    /* ---- Open SPI0 CE0 at 1 MHz, mode 0 ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Irrigation controller started.  Sampling every %d s, threshold %d.\n",
           SAMPLE_INTERVAL, MOISTURE_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            fprintf(stderr, "Sensor read error — skipping cycle\n");
            log_data(-1, gpioRead(PUMP_GPIO));
        } else {
            int pump_on = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;
            gpioWrite(PUMP_GPIO, pump_on);
            log_data(moisture, pump_on);
            printf("Moisture: %d  Pump: %s\n", moisture, pump_on ? "ON" : "OFF");
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    gpioWrite(PUMP_GPIO, 0);
    cleanup();
    return EXIT_SUCCESS;
}

