#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define SPI_CHANNEL    0
#define SPI_SPEED      1000000          /* 1 MHz */
#define SPI_FLAGS      0                /* mode 0, active-low CE */

#define MOTOR1_ENABLE  18               /* PWM0 */
#define MOTOR1_DIR     23               /* direction */
#define MOTOR2_ENABLE  24               /* PWM1 */
#define MOTOR2_DIR     25               /* direction */

#define PWM_RANGE      255
#define PWM_FREQ       1000             /* Hz */

/* ---- Timing constants ---- */
#define ACCEL_TIME_US  500000           /* 0.5 s acceleration */
#define HOLD_TIME_US   2000000          /* 2 s hold */
#define DEC_TIME_US    500000           /* 0.5 s deceleration */
#define PAUSE_TIME_US  5000000          /* 5 s pause */
#define REV_DELAY_US   100000           /* 100 ms between direction swaps */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- MCP3008 single-ended read ---- */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI frame: start bit, SGL/DIFF=1, D2 D1 D0, then 10 don't-care bits */
    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ---- Map 10-bit ADC to PWM range ---- */
static int map_adc_to_pwm(int adc)
{
    if (adc < 0) return 0;
    if (adc > 1023) adc = 1023;
    return (int)(((float)adc / 1023.0f) * PWM_RANGE);
}

/* ---- Accelerate a motor from 0 to target speed ---- */
static void accelerate(int enable, int dir, int target)
{
    for (int i = 0; i <= target && g_running; i++) {
        gpioPWM(enable, i);
        gpioDelay(ACCEL_TIME_US / target);
    }
}

/* ---- Decelerate a motor from current to 0 ---- */
static void decelerate(int enable, int current)
{
    for (int i = current; i >= 0; i--) {
        gpioPWM(enable, i);
        gpioDelay(DEC_TIME_US / current);
    }
}

/* ---- Set motor direction and drive at speed ---- */
static void set_motor(int enable, int dir_pin, int speed, int forward)
{
    gpioWrite(dir_pin, forward ? 1 : 0);
    gpioPWM(enable, speed);
}

/* ---- Reverse both motors with a short delay between direction changes ---- */
static void reverse_motors(void)
{
    /* Swap directions: Motor1 forward, Motor2 backward */
    gpioWrite(MOTOR1_DIR, 1);
    gpioWrite(MOTOR2_DIR, 0);
    gpioDelay(REV_DELAY_US);
}

/* ---- Cleanup all resources ---- */
static void cleanup(void)
{
    /* Stop motors */
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);

    /* Close SPI */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor control pins */
    if (gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_DIR, PI_OUTPUT)  < 0 ||
        gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_DIR, PI_OUTPUT)  < 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR1_ENABLE, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR2_ENABLE, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Motor control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc1 = read_mcp3008(0);
        int adc2 = read_mcp3008(1);

        if (adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "ADC read error; stopping motors and retrying.\n");
            gpioPWM(MOTOR1_ENABLE, 0);
            gpioPWM(MOTOR2_ENABLE, 0);
            gpioDelay(1000000);
            continue;
        }

        int speed1 = map_adc_to_pwm(adc1);
        int speed2 = map_adc_to_pwm(adc2);

        printf("ADC1=%4d  ADC2=%4d  Speed1=%3d  Speed2=%3d\n",
               adc1, adc2, speed1, speed2);

        /* Accelerate both motors */
        accelerate(MOTOR1_ENABLE, MOTOR1_DIR, speed1);
        accelerate(MOTOR2_ENABLE, MOTOR2_DIR, speed2);

        /* Hold at constant speed */
        uint32_t hold_start = gpioTick();
        while (g_running && (gpioTick() - hold_start) < HOLD_TIME_US) {
            gpioDelay(10000);
        }

        /* Decelerate both motors */
        decelerate(MOTOR1_ENABLE, speed1);
        decelerate(MOTOR2_ENABLE, speed2);

        /* Pause */
        uint32_t pause_start = gpioTick();
        while (g_running && (gpioTick() - pause_start) < PAUSE_TIME_US) {
            gpioDelay(10000);
        }

        /* Reverse directions */
        reverse_motors();

        /* Accelerate in reverse */
        accelerate(MOTOR1_ENABLE, MOTOR1_DIR, speed1);
        accelerate(MOTOR2_ENABLE, MOTOR2_DIR, speed2);

        /* Hold at reverse speed */
        hold_start = gpioTick();
        while (g_running && (gpioTick() - hold_start) < HOLD_TIME_US) {
            gpioDelay(10000);
        }

        /* Decelerate in reverse */
        decelerate(MOTOR1_ENABLE, speed1);
        decelerate(MOTOR2_ENABLE, speed2);

        /* Pause */
        pause_start = gpioTick();
        while (g_running && (gpioTick() - pause_start) < PAUSE_TIME_US) {
            gpioDelay(10000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

