#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_PIN 17
#define DEBOUNCE_DELAY_US 10000
#define CALIBRATION_TIME_S 5
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_noise_level(int duration_s) {
    int sum = 0;
    int count = 0;
    time_t start = time(NULL);

    printf("Calibrating ambient noise for %d seconds...\n", duration_s);
    while (running && (time(NULL) - start) < duration_s) {
        int val = read_mcp3008(0);
        if (val >= 0) {
            sum += val;
            count++;
        }
        usleep(SAMPLE_DELAY_US);
    }

    if (count == 0) {
        fprintf(stderr, "Calibration failed: no valid samples\n");
        return -1;
    }

    return sum / count;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int threshold = calibrate_noise_level(CALIBRATION_TIME_S);
    if (threshold < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Calibration complete. Threshold: %d\n", threshold);
    printf("Monitoring sound levels... (Ctrl+C to exit)\n");

    int led_state = 0;
    uint32_t last_toggle = 0;

    while (running) {
        int sound_level = read_mcp3008(0);
        if (sound_level < 0) {
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        uint32_t now = gpioTick();
        if (sound_level > threshold) {
            if (led_state == 0 && (now - last_toggle) > DEBOUNCE_DELAY_US) {
                gpioWrite(LED_PIN, 1);
                led_state = 1;
                last_toggle = now;
            }
        } else {
            if (led_state == 1 && (now - last_toggle) > DEBOUNCE_DELAY_US) {
                gpioWrite(LED_PIN, 0);
                led_state = 0;
                last_toggle = now;
            }
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

