#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_PIN          8
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_line *g_cs_line = NULL;
static struct gpiod_chip *g_chip = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_spi(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio_cs(void)
{
    g_chip = gpiod_chip_open(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, CS_PIN);
    if (!g_cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", CS_PIN, strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        g_cs_line = NULL;
        gpiod_chip_close(g_chip); g_chip = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3008(uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (g_cs_line) {
        if (gpiod_line_set_value(g_cs_line, 0) < 0) {
            fprintf(stderr, "gpiod_line_set_value(0): %s\n", strerror(errno));
            return -1;
        }
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        if (g_cs_line) gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    if (g_cs_line) {
        if (gpiod_line_set_value(g_cs_line, 1) < 0) {
            fprintf(stderr, "gpiod_line_set_value(1): %s\n", strerror(errno));
            return -1;
        }
    }

    *out = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_sample(long long ts_ns, uint16_t adc)
{
    if (!g_log_fp) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }
    if (fprintf(g_log_fp, "%lld|%u\n", ts_ns, adc) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) == EOF) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_cs_line) {
        gpiod_line_set_value(g_cs_line, 1);
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() < 0) {
        cleanup();
        return 1;
    }

    if (init_gpio_cs() < 0) {
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next);

    while (g_running) {
        uint16_t adc = 0;
        if (read_mcp3008(0, &adc) < 0) {
            fprintf(stderr, "ADC read failed; continuing\n");
            struct timespec rem = {0, SAMPLE_PERIOD_NS};
            nanosleep(&rem, NULL);
            clock_gettime(CLOCK_MONOTONIC_RAW, &next);
            continue;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);
        long long ts_ns = (long long)now.tv_sec * 1000000000LL + now.tv_nsec;

        if (log_sample(ts_ns, adc) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        next.tv_nsec += SAMPLE_PERIOD_NS;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_sec  += 1;
            next.tv_nsec -= 1000000000L;
        }

        struct timespec rem;
        rem.tv_sec  = next.tv_sec  - now.tv_sec;
        rem.tv_nsec = next.tv_nsec - now.tv_nsec;
        if (rem.tv_nsec < 0) {
            rem.tv_sec  -= 1;
            rem.tv_nsec += 1000000000L;
        }

        if (rem.tv_sec < 0 || (rem.tv_sec == 0 && rem.tv_nsec <= 0)) {
            continue;
        }

        if (nanosleep(&rem, NULL) < 0 && errno != EINTR) {
            fprintf(stderr, "nanosleep: %s\n", strerror(errno));
        }
    }

    cleanup();
    return 0;
}

