#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* MCP3008 CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_VREF       3.3f       /* Reference voltage */
#define ADC_MAX        1023       /* 10-bit ADC full-scale code */
#define ADC_CHANNELS   3          /* X, Y, Z channels */

#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

/* Kalman filter parameters */
#define Q 0.01f
#define R 0.1f

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* Kalman state per axis */
typedef struct {
    float x;          /* state estimate */
    float p;          /* estimate covariance */
} kalman_state_t;

static kalman_state_t g_kalman[ADC_CHANNELS];

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  initialize_spi(void);
static int  read_adc_channel(int channel, int *out_value);
static float adc_to_voltage(int adc_value);
static float kalman_filter(int channel, float measurement);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI / ADC --------------------------------- */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (value stored in *out_value), -1 on error.
 */
static int read_adc_channel(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d.\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed on channel %d (returned %d).\n",
                channel, ret);
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    *out_value = value;
    return 0;
}

static float adc_to_voltage(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX) * ADC_VREF;
}

/* ----------------------------- Kalman filter ----------------------------- */
static float kalman_filter(int channel, float measurement)
{
    kalman_state_t *s = &g_kalman[channel];

    /* Prediction step */
    s->p = s->p + Q;

    /* Update step */
    float k = s->p / (s->p + R);
    s->x = s->x + k * (measurement - s->x);
    s->p = (1.0f - k) * s->p;

    return s->x;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize Kalman filters */
    for (int i = 0; i < ADC_CHANNELS; i++) {
        g_kalman[i].x = 0.0f;
        g_kalman[i].p = 1.0f;
    }

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 via MCP3008 — sampling at %d Hz. Press Ctrl+C to stop.\n",
           SAMPLE_RATE_HZ);

    /* Main loop */
    while (g_running) {
        int adc[ADC_CHANNELS];
        bool read_ok = true;

        for (int i = 0; i < ADC_CHANNELS; i++) {
            if (read_adc_channel(i, &adc[i]) != 0) {
                read_ok = false;
                break;
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Warning: ADC read failed — skipping sample.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float x_g = kalman_filter(0, adc_to_voltage(adc[0]));
        float y_g = kalman_filter(1, adc_to_voltage(adc[1]));
        float z_g = kalman_filter(2, adc_to_voltage(adc[2]));

        printf("X: %7.3f g  Y: %7.3f g  Z: %7.3f g\n", x_g, y_g, z_g);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

