#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <stdbool.h>
#include <stdint.h>
#include <errno.h>
#include <mosquitto.h>

#include "gpio_driver.h"
#include "json_parser.h"

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            char buf[128];
            snprintf(buf, sizeof(buf), "Subscribe failed: %s", mosquitto_strerror(rc));
            log_message(buf);
        }
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf), "Connect failed: %s", mosquitto_strerror(result));
        log_message(buf);
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;

    if (message->payloadlen <= 0) {
        log_message("Empty message received");
        return;
    }

    char *payload = malloc(message->payloadlen + 1);
    if (!payload) {
        log_message("Memory allocation failed for payload");
        return;
    }
    memcpy(payload, message->payload, message->payloadlen);
    payload[message->payloadlen] = '\0';

    bool led_state = false;
    int rc = parse_json(payload, &led_state);

    if (rc == 0) {
        if (set_gpio_output(GPIO_PIN, led_state) != 0) {
            log_message("Failed to set GPIO output");
        }
    } else {
        char buf[256];
        snprintf(buf, sizeof(buf), "JSON parse error: %s", payload);
        log_message(buf);
    }

    free(payload);
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Unexpected disconnect: %s", mosquitto_strerror(rc));
        log_message(buf);
    }
}

static void on_subscribe(struct mosquitto *m, void *userdata, int mid, int qos_count, const int *granted_qos) {
    (void)m;
    (void)userdata;
    (void)mid;
    (void)qos_count;
    (void)granted_qos;
    log_message("Subscribed to topic");
}

int main(void) {
    int rc = 0;
    int reconnect_delay = 1;

    if (gpio_init() != 0) {
        log_message("GPIO initialization failed");
        return 1;
    }

    if (set_gpio_mode(GPIO_PIN, GPIO_MODE_OUTPUT) != 0) {
        log_message("Failed to set GPIO mode");
        gpio_cleanup();
        return 1;
    }

    if (set_gpio_output(GPIO_PIN, false) != 0) {
        log_message("Failed to initialize GPIO output state");
        gpio_cleanup();
        return 1;
    }

    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message("mosquitto_new failed");
        gpio_cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_subscribe_callback_set(mosq, on_subscribe);

    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Initial connect failed: %s", mosquitto_strerror(rc));
        log_message(buf);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (!mosquitto_is_connected(mosq)) {
            rc = mosquitto_reconnect(mosq);
            if (rc != MOSQ_ERR_SUCCESS) {
                char buf[128];
                snprintf(buf, sizeof(buf), "Reconnect failed: %s", mosquitto_strerror(rc));
                log_message(buf);
                sleep(reconnect_delay);
                reconnect_delay = (reconnect_delay * 2 > MAX_RECONNECT_DELAY) ? MAX_RECONNECT_DELAY : reconnect_delay * 2;
            } else {
                reconnect_delay = 1;
            }
        } else {
            rc = mosquitto_loop(mosq, 100, 1);
            if (rc != MOSQ_ERR_SUCCESS) {
                char buf[128];
                snprintf(buf, sizeof(buf), "Loop error: %s", mosquitto_strerror(rc));
                log_message(buf);
            }
        }
    }

    log_message("Shutting down...");

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();

    set_gpio_output(GPIO_PIN, false);
    gpio_cleanup();

    log_message("Shutdown complete.");
    return 0;
}

