#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_RESET_REG 0xE0
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_CALIB_00_REG 0x88
#define BMP280_CALIB_26_REG 0xE1

#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;
static int32_t t_fine;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int bmp280_init() {
    int id = i2cReadByteData(i2c_handle, BMP280_CHIP_ID_REG);
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: BMP280 chip ID mismatch (got 0x%02X, expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_RESET_REG, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset BMP280\n");
        return -1;
    }
    gpioDelay(2000);

    if (i2cWriteByteData(i2c_handle, BMP280_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_CTRL_MEAS_REG, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas register\n");
        return -1;
    }

    return 0;
}

int bmp280_read_calibration_data() {
    uint8_t data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_CALIB_00_REG, (char *)data, 26) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data (0x88-0xA1)\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)(data[0] | (data[1] << 8));
    calib.dig_T2 = (int16_t)(data[2] | (data[3] << 8));
    calib.dig_T3 = (int16_t)(data[4] | (data[5] << 8));
    calib.dig_P1 = (uint16_t)(data[6] | (data[7] << 8));
    calib.dig_P2 = (int16_t)(data[8] | (data[9] << 8));
    calib.dig_P3 = (int16_t)(data[10] | (data[11] << 8));
    calib.dig_P4 = (int16_t)(data[12] | (data[13] << 8));
    calib.dig_P5 = (int16_t)(data[14] | (data[15] << 8));
    calib.dig_P6 = (int16_t)(data[16] | (data[17] << 8));
    calib.dig_P7 = (int16_t)(data[18] | (data[19] << 8));
    calib.dig_P8 = (int16_t)(data[20] | (data[21] << 8));
    calib.dig_P9 = (int16_t)(data[22] | (data[23] << 8));

    uint8_t data_e1[7];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_CALIB_26_REG, (char *)data_e1, 7) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data (0xE1-0xEC)\n");
        return -1;
    }

    return 0;
}

int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_PRESS_MSB_REG, (char *)data, 6) < 0) {
        fprintf(stderr, "Error: Failed to read raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

double bmp280_compensate_temperature(int32_t raw_temperature) {
    double var1 = ((double)raw_temperature / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    double var2 = ((double)raw_temperature / 131072.0 - (double)calib.dig_T1 / 8192.0) * ((double)raw_temperature / 131072.0 - (double)calib.dig_T1 / 8192.0) * (double)calib.dig_T3;
    t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

double bmp280_compensate_pressure(int32_t raw_pressure) {
    double var1 = ((double)t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * (double)calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)calib.dig_P4 * 65536.0);
    var1 = ((double)calib.dig_P3 * var1 * var1 / 524288.0 + (double)calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)calib.dig_P1;

    if (var1 == 0.0) return 0.0;

    double p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)calib.dig_P7) / 16.0;

    return p;
}

double calculate_altitude(double pressure) {
    return 44330.0 * (1.0 - pow(pressure / 101325.0, 0.1903));
}

int log_data(double altitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %.2f\n", timestamp, altitude) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (bmp280_init() < 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed\n");
        cleanup();
        return 1;
    }

    if (bmp280_read_calibration_data() < 0) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        cleanup();
        return 1;
    }

    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    while (running) {
        int32_t raw_temperature, raw_pressure;
        if (bmp280_read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            double temperature = bmp280_compensate_temperature(raw_temperature);
            double pressure = bmp280_compensate_pressure(raw_pressure);
            double altitude = calculate_altitude(pressure);

            if (log_data(altitude) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

