    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_celsius(int adc_value) {
    return (float)adc_value * 0.48828125f;
}

static void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static int write_buffer_to_file(const char *filename) {
    FILE *fp = fopen(filename, "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file %s for writing\n", filename);
        return -1;
    }

    size_t elements_written = fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);
    if (elements_written != BUFFER_SIZE) {
        fprintf(stderr, "Error: Could not write all elements to file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Could not close file properly\n");
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Could not set signal handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    memset(temperature_buffer, 0, sizeof(temperature_buffer));

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            float temperature = adc_to_celsius(adc_value);
            add_to_buffer(temperature);
            printf("Temperature: %.2f °C\n", temperature);

            if (write_buffer_to_file(LOG_FILE) != 0) {
                fprintf(stderr, "Warning: Failed to write buffer to file\n");
            }
        }

        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

