    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed\n");
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI bus");
        close(i2c_fd);
        return 1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI config");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float lux = 0.0f;
        int sound_level = 0;
        int lux_ok = bh1750_read_lux(i2c_fd, &lux);
        int sound_ok = mcp3008_read(spi_fd, 0, &sound_level);

        if (lux_ok < 0) {
            fprintf(stderr, "BH1750 read error: %s\n", strerror(errno));
        }
        if (sound_ok < 0) {
            fprintf(stderr, "MCP3008 read error: %s\n", strerror(errno));
        }

        if (log_data(lux, sound_level) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    close(spi_fd);
    close(i2c_fd);
    return 0;
}

