#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SENSORS 3
#define SLEEP_DURATION 60
#define LOG_FILE "soil_data.txt"

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_data(FILE *fp, int sensor_id, int moisture_level) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: Failed to get current time\n");
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: Failed to convert time\n");
        return -1;
    }

    char timestamp[20];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s, Sensor %d, Moisture: %d\n", timestamp, sensor_id, moisture_level) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler\n");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int moisture_level = read_mcp3008(i);
            if (moisture_level < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i);
                continue;
            }
            if (log_data(log_file, i, moisture_level) != 0) {
                fprintf(stderr, "Error: Failed to log data for sensor %d\n", i);
            }
        }

        if (!terminate) {
            sleep(SLEEP_DURATION);
        }
    }

    printf("\nCaught SIGINT, cleaning up...\n");
    cleanup();
    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

