#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

#define NUM_RELAYS 4
#define RELAY_PINS {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN}

static const int relay_pins[NUM_RELAYS] = RELAY_PINS;

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_relay(int pin, int state) {
    int rc = gpioWrite(pin, state);
    if (rc < 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, state=%d) failed: %s\n",
                pin, state, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int deactivate_all_relays(void) {
    int rc = 0;
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (set_relay(relay_pins[i], 0) < 0) {
            rc = -1;
        }
    }
    return rc;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        int pin = relay_pins[i];
        if (gpioSetMode(pin, PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode(pin=%d, PI_OUTPUT) failed\n", pin);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pin, 0) < 0) {
            fprintf(stderr, "Error: gpioWrite(pin=%d, 0) failed\n", pin);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (g_running) {
        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (set_relay(relay_pins[i], 1) < 0) {
                deactivate_all_relays();
                gpioTerminate();
                return EXIT_FAILURE;
            }
            sleep(1);
            if (!g_running) break;
            if (set_relay(relay_pins[i], 0) < 0) {
                deactivate_all_relays();
                gpioTerminate();
                return EXIT_FAILURE;
            }
            sleep(1);
        }
    }

    if (deactivate_all_relays() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

