            fprintf(stderr, "Error: gpioWrite(pin=%d, 0) failed\n", pin);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (g_running) {
        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (set_relay(relay_pins[i], 1) < 0) {
                deactivate_all_relays();
                gpioTerminate();
                return EXIT_FAILURE;
            }
            sleep(1);
            if (!g_running) break;
            if (set_relay(relay_pins[i], 0) < 0) {
                deactivate_all_relays();
                gpioTerminate();
                return EXIT_FAILURE;
            }
            sleep(1);
        }
    }

    if (deactivate_all_relays() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

