#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin / SPI / Motor Configuration ---- */
#define SPI_CHANNEL    0
#define SPI_SPEED      1000000          /* 1 MHz */
#define SPI_FLAGS      0                /* Mode 0, active-low CE */

#define MOTOR_IN1      17               /* BCM 17 */
#define MOTOR_IN2      18               /* BCM 18 */
#define MOTOR_ENA      27               /* BCM 27, PWM-capable */

#define PWM_RANGE      255
#define PWM_DUTY       150              /* ~59% duty cycle */

#define RAIN_THRESHOLD 5
#define MOTOR_RUN_US   3000000          /* 3 seconds in microseconds */
#define POLL_INTERVAL  1                /* seconds between readings */

/* ---- Globals for cleanup ---- */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ---- Prototypes ---- */
static int  read_mcp3008(int channel);
static void log_rain_level(int rain_level);
static void control_window(int rain_level);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------------------------------------------ */
/*  Read a single-ended channel (0-7) from the MCP3008.               */
/*  Returns 0-1023 on success, -1 on error.                           */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel)
     *   Byte 2: 0x00                       (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the two LSBs
     *   rx[2] = b7..b0
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/*  Append a timestamped rain reading to the log file.                 */
/*  Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static void log_rain_level(int rain_level)
{
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open\n");
        return;
    }

    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
    }
}

/* ------------------------------------------------------------------ */
/*  Drive the motor forward or reverse for MOTOR_RUN_US microseconds. */
/* ------------------------------------------------------------------ */
static void control_window(int rain_level)
{
    int direction = (rain_level > RAIN_THRESHOLD) ? 1 : 0;  /* 1 = close, 0 = open */

    if (gpioPWM(MOTOR_ENA, PWM_DUTY) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on ENA\n");
        return;
    }

    if (gpioWrite(MOTOR_IN1, direction) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on IN1\n");
        gpioPWM(MOTOR_ENA, 0);
        return;
    }
    if (gpioWrite(MOTOR_IN2, !direction) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on IN2\n");
        gpioPWM(MOTOR_ENA, 0);
        return;
    }

    gpioDelay(MOTOR_RUN_US);

    gpioPWM(MOTOR_ENA, 0);
}

/* ------------------------------------------------------------------ */
/*  Release all resources.                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop motor first for safety */
    if (gpioInitialise() >= 0) {
        gpioPWM(MOTOR_ENA, 0);
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 0);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*  Signal handler — set flag so main loop can exit cleanly.          */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/*  Main                                                              */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor control pins */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed on IN1\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed on IN2\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_ENA, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed on ENA\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM range */
    if (gpioSetPWMrange(MOTOR_ENA, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open rain_log.txt\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        int rain_level = read_mcp3008(0);
        if (rain_level < 0) {
            fprintf(stderr, "Error: failed to read rain sensor\n");
        } else {
            log_rain_level(rain_level);
            control_window(rain_level);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

