#define ADC_PIN      26
#define LED_PIN      16
#define THRESHOLD    500
#define DEBOUNCE_MS  50
#define LED_ON_MS    500
#define SAMPLE_US    1000
#define POLL_US      10000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(pin, 0) < 0) return -1;
    gpioDelay(1);
    if (gpioSetMode(pin, PI_INPUT) < 0) return -1;
    gpioDelay(10);
    int val = gpioRead(pin);
    if (val < 0) return -1;
    return val;
}

static bool detect_clap(int adc_value) {
    return (adc_value > THRESHOLD);
}

static void log_timestamp(void) {
    time_t rawtime;
    struct tm timeinfo;
    char buffer[80];
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);
    printf("[%s] Clap detected!\n", buffer);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");

    uint32_t last_detection_ms = 0;

    while (running) {
        int adc_value = read_adc(ADC_PIN);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error on pin %d\n", ADC_PIN);
            gpioDelay(POLL_US);
            continue;
        }

        if (detect_clap(adc_value)) {
            uint32_t now_ms = gpioTick() / 1000;
            if (now_ms - last_detection_ms >= DEBOUNCE_MS) {
                last_detection_ms = now_ms;
                log_timestamp();
                if (gpioWrite(LED_PIN, 1) < 0) {
                    fprintf(stderr, "Failed to turn on LED\n");
                }
                gpioDelay(LED_ON_MS * 1000);
                if (gpioWrite(LED_PIN, 0) < 0) {
                    fprintf(stderr, "Failed to turn off LED\n");
                }
            }
        }
        gpioDelay(POLL_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

