#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"
#define GPIO_PATH "/sys/class/gpio"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_export(int pin) {
    int fd = open(GPIO_PATH "/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_PATH "/export", strerror(errno));
        return -1;
    }
    char buf[4];
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error exporting GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    int fd = open(GPIO_PATH "/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_PATH "/unexport", strerror(errno));
        return -1;
    }
    char buf[4];
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error unexporting GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error setting direction on %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_read_value(int pin) {
    char path[64];
    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/value", pin);
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    char value[2];
    ssize_t bytes = read(fd, value, 1);
    close(fd);
    if (bytes < 0) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        return -1;
    }
    return (value[0] == '1') ? 1 : 0;
}

static int log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Distance: %d mm\n", timestamp, distance);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpio_export(GPIO_PIN) < 0) {
        return 1;
    }
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Feeder control system started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = gpio_read_value(GPIO_PIN);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        if (log_distance(distance) < 0) {
            fprintf(stderr, "Error logging distance.\n");
        }

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    gpio_unexport(GPIO_PIN);
    printf("Feeder control system stopped.\n");
    return 0;
}

