#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "gpiochip0"
#define GPIO_LINE       17
#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023
#define VREF            5.0
#define SENSOR_V_PER_A  0.1
#define LOG_FILE        "current_log.txt"
#define SAMPLE_PERIOD   1

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_line *g_line = NULL;
static struct gpiod_chip *g_chip = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_spi(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = 1000000;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio(void) {
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_line, "mlx91209", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_line = NULL;
        return -1;
    }

    return 0;
}

static int read_adc(uint8_t channel, uint16_t *value) {
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static double adc_to_current(uint16_t adc_value) {
    double voltage = (double)adc_value * VREF / (double)ADC_MAX_VALUE;
    return voltage / SENSOR_V_PER_A;
}

static int log_current(double current) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s,%.3f\n", timestamp, current) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

static void cleanup(void) {
    if (g_line) {
        gpiod_line_set_value(g_line, 0);
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    printf("Starting current monitoring. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t adc_value = 0;
        if (read_adc(ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; retrying in %d s...\n", SAMPLE_PERIOD);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        double current = adc_to_current(adc_value);

        if (log_current(current) < 0) {
            fprintf(stderr, "Logging failed; continuing...\n");
        }

        printf("Current: %.3f A\n", current);
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

