#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* MCP3008 CE0 (GPIO8)                  */
#define SPI_SPEED      1000000    /* 1 MHz                                */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0       */
#define VREF           5.0        /* MCP3008 VDD / VREF tied to 5 V       */
#define ADC_MAX        1023       /* 10-bit ADC full-scale code           */
#define SAMPLE_US      100000     /* 100 ms between samples               */
#define LOG_FILE       "current_log.txt"

/* ----------------------------- Globals ---------------------------------- */
static int  spi_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize(void);
static void cleanup(void);
static int  read_adc(int channel);
static float voltage_to_current(float voltage);
static int  log_current(float current);
static void signal_handler(int sig);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- Initialization ----------------------------- */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (pigpio error %d).\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- MCP3008 read ------------------------------ */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d.\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d).\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ----------------------------- Conversion -------------------------------- */
static float voltage_to_current(float voltage)
{
    /*
     * MLX91211: linear approximation of the analog output.
     * Real deployments should calibrate against a known current.
     */
    return (voltage - 0.5f) * 2.0f;
}

/* ----------------------------- Logging ----------------------------------- */
static int log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
        return -1;
    }
    return 0;
}

/* ----------------------------- Main loop --------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: ADC read failed, skipping sample.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float voltage = (float)adc_value * (VREF / (float)ADC_MAX);

        if (voltage < 0.0f || voltage > VREF) {
            fprintf(stderr, "Warning: voltage %.3f V out of range, skipping sample.\n", voltage);
            gpioDelay(SAMPLE_US);
            continue;
        }

