#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR_1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR_2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(int pin) {
    int readings[DEBOUNCE_READINGS];
    int i;

    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(pin);
        if (readings[i] < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", pin);
            return -1;
        }
        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }

    int sum = 0;
    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        sum += readings[i];
    }

    return (sum >= (DEBOUNCE_READINGS + 1) / 2) ? 1 : 0;
}

static void log_sensor_data(int s1, int s2) {
    printf("Sensor 1: %d, Sensor 2: %d\n", s1, s2);
    fflush(stdout);
}

static void check_alert(int s1, int s2) {
    if (s1 == 0 && s2 == 0) {
        printf("ALERT: Both sensors detect object\n");
        fflush(stdout);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: sensor read failure, exiting.\n");
            break;
        }

        log_sensor_data(s1, s2);
        check_alert(s1, s2);

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nGPIO terminated. Exiting.\n");
    return EXIT_SUCCESS;
}

