#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN          17
#define DEBOUNCE_MS      200
#define POLL_INTERVAL_MS 50
#define CAPTURE_DIR      "/home/pi/security_cam"
#define FILENAME_MAX     256
#define PATH_MAX         512

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "Path %s exists but is not a directory", path);
        return -1;
    }
    if (errno != ENOENT) {
        syslog(LOG_ERR, "stat(%s) failed: %s", path, strerror(errno));
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "mkdir(%s) failed: %s", path, strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "Created directory %s", path);
    return 0;
}

static int capture_image(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        /* Child process */
        char *const argv[] = {
            "libcamera-still",
            "-o", (char *)filename,
            "--nopreview",
            "--timeout", "1",
            NULL
        };
        execvp("libcamera-still", argv);
        /* If execvp returns, it failed */
        syslog(LOG_ERR, "execvp(libcamera-still) failed: %s", strerror(errno));
        _exit(127);
    }

    /* Parent process: wait for child */
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) {
            if (!g_running)
                return -1;
            continue;
        }
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;

    if (WIFEXITED(status))
        syslog(LOG_ERR, "libcamera-still exited with status %d", WEXITSTATUS(status));
    else if (WIFSIGNALED(status))
        syslog(LOG_ERR, "libcamera-still killed by signal %d", WTERMSIG(status));

    return -1;
}

static void generate_filename(char *buf, size_t buflen, const char *sensor_id)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
