#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define MAX_UDP_PAYLOAD 65507
#define MAX_FRAGMENTS 10
#define NUM_BUFFERS 4
#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 5000

typedef struct {
    unsigned int frame_index;
    unsigned int fragment_index;
    unsigned int total_fragments;
    unsigned int payload_size;
} __attribute__((packed)) frame_header_t;

static volatile sig_atomic_t running = 1;
static int fd = -1;
static int sock = -1;
static struct sockaddr_in server_addr;
static void *buffers[NUM_BUFFERS];
static size_t buffer_sizes[NUM_BUFFERS];
static unsigned char *frame_data = NULL;
static size_t frame_size = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fh, int request, void *arg) {
    int r;
    do {
        r = ioctl(fh, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(void) {
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        fd = -1;
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV format\n");
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        fd = -1;
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        fd = -1;
        return -1;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            fd = -1;
            return -1;
        }

        buffer_sizes[i] = buf.length;
        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            buffers[i] = NULL;
            close(fd);
            fd = -1;
            return -1;
        }
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            close(fd);
            fd = -1;
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        close(fd);
        fd = -1;
        return -1;
    }

    return 0;
}

static void cleanup_camera(void) {
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i] != NULL && buffers[i] != MAP_FAILED) {
                munmap(buffers[i], buffer_sizes[i]);
                buffers[i] = NULL;
            }
        }
        close(fd);
        fd = -1;
    }
}

static int init_socket(void) {
    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sock);
        sock = -1;
        return -1;
    }

    return 0;
}

static void cleanup_socket(void) {
    if (sock >= 0) {
        close(sock);
        sock = -1;
    }
}

static int capture_frame(unsigned char **out_data, size_t *out_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *out_data = (unsigned char *)buffers[buf.index];
    *out_size = buf.bytesused;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    return 0;
}

static int send_frame(unsigned char *data, size_t data_size, unsigned int frame_index) {
    size_t frag_size = MAX_UDP_PAYLOAD;
    size_t total_fragments = (data_size + frag_size - 1) / frag_size;

    if (total_fragments > MAX_FRAGMENTS) {
        fprintf(stderr, "Frame too large: %zu bytes\n", data_size);
        return -1;
    }

    for (unsigned int i = 0; i < total_fragments; i++) {
        size_t payload_size = (i == total_fragments - 1) ? (data_size - i * frag_size) : frag_size;
        size_t packet_size = sizeof(frame_header_t) + payload_size;

        unsigned char *packet = malloc(packet_size);
        if (!packet) {
            perror("malloc");
            return -1;
        }

        frame_header_t *header = (frame_header_t *)packet;
        header->frame_index = frame_index;
        header->fragment_index = i;
        header->total_fragments = total_fragments;
        header->payload_size = payload_size;

        memcpy(packet + sizeof(frame_header_t), data + i * frag_size, payload_size);

        ssize_t sent = sendto(sock, packet, packet_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
        free(packet);

        if (sent < 0) {
            perror("sendto");
            return -1;
        }
    }

    return 0;
}

int main(int argc, char **argv) {
    (void)argc;
    (void)argv;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_camera() < 0) {
        return 1;
    }

    if (init_socket() < 0) {
        cleanup_camera();
        return 1;
    }

    unsigned int frame_index = 0;

    while (running) {
        unsigned char *data = NULL;
        size_t data_size = 0;

        if (capture_frame(&data, &data_size) < 0) {
            if (errno == EINTR) {
                continue;
            }
            break;
        }

        if (data_size > 0) {
            if (send_frame(data, data_size, frame_index) < 0) {
                break;
            }
            frame_index++;
        }
    }

    cleanup_socket();
    cleanup_camera();

    return 0;
}

