#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  4
#define TILT_SERVO_PIN 5

#define TILT_UP_PIN    6
#define TILT_DOWN_PIN  7
#define PAN_LEFT_PIN   8
#define PAN_RIGHT_PIN  9

#define PWM_RANGE      1000
#define PWM_MID        750
#define PWM_MIN        500
#define PWM_MAX        1000

#define STEP           5
#define MIN_POS        25
#define MAX_POS        125

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo(int pin, int position)
{
    if (position < MIN_POS) position = MIN_POS;
