#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void   *start;
    size_t  length;
};

static int               fd = -1;
static struct buffer    *buffers = NULL;
static unsigned int      n_buffers = 0;
static volatile sig_atomic_t stop = 0;

static void signal_handler(int signum) {
    (void)signum;
    stop = 1;
}

static void errno_exit(const char *s) {
    fprintf(stderr, "%s error %d, %s\n", s, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

static int xioctl(int fh, int request, void *arg) {
    int r;
    do {
        r = ioctl(fh, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void process_image(unsigned char *rgb_data, int width, int height) {
    for (int y = 1; y < height - 1; y++) {
        for (int x = 1; x < width - 1; x++) {
            int idx = (y * width + x) * 3;
            int r_sum = 0, g_sum = 0, b_sum = 0;
            for (int dy = -1; dy <= 1; dy++) {
                for (int dx = -1; dx <= 1; dx++) {
                    int n_idx = ((y + dy) * width + (x + dx)) * 3;
                    r_sum += rgb_data[n_idx];
                    g_sum += rgb_data[n_idx + 1];
                    b_sum += rgb_data[n_idx + 2];
                }
            }
            rgb_data[idx]     = r_sum / 9;
            rgb_data[idx + 1] = g_sum / 9;
            rgb_data[idx + 2] = b_sum / 9;
        }
    }
}

static int yuyv_to_rgb(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0; i < width * height * 2; i += 4) {
        int y1 = yuyv[i];
        int u  = yuyv[i + 1];
        int y2 = yuyv[i + 2];
        int v  = yuyv[i + 3];

        int c0 = y1 - 16;
        int c1 = u - 128;
        int c2 = v - 128;

        int r = (298 * c0 + 409 * c2 + 128) >> 8;
        int g = (298 * c0 - 100 * c1 - 208 * c2 + 128) >> 8;
        int b = (298 * c0 + 516 * c1 + 128) >> 8;

        if (r < 0) r = 0; if (r > 255) r = 255;
        if (g < 0) g = 0; if (g > 255) g = 255;
        if (b < 0) b = 0; if (b > 255) b = 255;

        rgb[i / 2 * 3]     = (unsigned char)r;
        rgb[i / 2 * 3 + 1] = (unsigned char)g;
        rgb[i / 2 * 3 + 2] = (unsigned char)b;
    }
    return 0;
}

static int write_jpeg(unsigned char *rgb_data, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile = NULL;
    unsigned char *row_pointer[1];

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "can't open %s\n", filename);
        jpeg_destroy_compress(&cinfo);
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, 75, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb_data[cinfo.next_scanline * width * 3];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    fd = open("/dev/video0", O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    CLEAR(cap);
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    CLEAR(req);
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("calloc");
        close(fd);
        return EXIT_FAILURE;
    }

    for (n_buffers = 0; n_buffers < req.count; n_buffers++) {
        struct v4l2_buffer buf;
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            break;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("mmap");
            break;
        }
    }

    if (n_buffers == 0) {
        fprintf(stderr, "Out of memory\n");
        for (unsigned int i = 0; i < n_buffers; i++) {
            if (buffers && buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    for (unsigned int i = 0; i < n_buffers; i++) {
        struct v4l2_buffer buf;
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        for (unsigned int i = 0; i < n_buffers; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    while (!stop) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            if (errno == EINTR) continue;
            perror("select");
            break;
        }
        if (r == 0) {
            fprintf(stderr, "select timeout\n");
            break;
        }

        struct v4l2_buffer buf;
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("VIDIOC_DQBUF");
            break;
        }

        if (buf.index >= n_buffers) {
            fprintf(stderr, "Buffer index out of range\n");
            break;
        }

        int width = fmt.fmt.pix.width;
        int height = fmt.fmt.pix.height;
        int size = width * height * 2;
        int rgb_size = width * height * 3;

        unsigned char *yuyv = malloc(size);
        unsigned char *rgb = malloc(rgb_size);
        if (!yuyv || !rgb) {
            perror("malloc");
            free(yuyv);
            free(rgb);
            break;
        }

        memcpy(yuyv, buffers[buf.index].start, size);
        yuyv_to_rgb(yuyv, rgb, width, height);
        process_image(rgb, width, height);

        time_t rawtime;
        struct tm *timeinfo;
        char filename[80];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

        if (write_jpeg(rgb, width, height, filename) != 0) {
            fprintf(stderr, "Failed to write JPEG\n");
        }

        free(yuyv);
        free(rgb);

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }
        break;
    }

    enum v4l2_buf_type type_stop = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type_stop) < 0) {
        perror("VIDIOC_STREAMOFF");
    }

    for (unsigned int i = 0; i < n_buffers; i++) {
        if (buffers && buffers[i].start && buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
        }
    }

    free(buffers);
    close(fd);
    return EXIT_SUCCESS;
}

