#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void)
{
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_ENUMERATE_FRAMESIZES)) {
        fprintf(stderr, "%s does not support frame size enumeration\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_frmsizeenum frmsize;
    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.index = 0;

    printf("Supported resolutions and frame rates:\n");
    while (xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        struct v4l2_frmivalenum frmi;
        memset(&frmi, 0, sizeof(frmi));
        frmi.index = 0;
        frmi.pixel_format = frmsize.pixel_format;

        printf("  %ux%u:\n", frmsize.discrete.width, frmsize.discrete.height);

        while (xioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmi) == 0) {
            if (frmi.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
                printf("    %u/%u fps\n",
                       frmi.discrete.numerator,
                       frmi.discrete.denominator);
            }
            frmi.index++;
        }

        if (errno != EINVAL) {
            fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n",
                    strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        frmsize.index++;
        memset(&frmi, 0, sizeof(frmi));
    }

    if (errno != EINVAL) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n",
                strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_queryctrl ctrl;
    memset(&ctrl, 0, sizeof(ctrl));
    ctrl.id = V4L2_CID_FOCUS_AUTO;

    if (xioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCTRL (focus auto) failed: %s\n",
                strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (ctrl.flags & V4L2_CTRL_FLAG_DISABLED) {
        printf("Autofocus is not supported.\n");
    } else {
        printf("Autofocus is supported.\n");
    }

    close(fd);
    return EXIT_SUCCESS;
}

