#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5

#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define MIN_PULSE_WIDTH  1000
#define MAX_PULSE_WIDTH  2000
#define CENTER_PULSE_WIDTH 1500
#define STEP_SIZE        10
#define LOOP_DELAY_US    50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pin, int pulse_width)
{
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }

    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pulse %d)\n", pin, pulse_width);
        return -1;
    }
    return 0;
}

static int read_button(int pin)
{
    return (gpioRead(pin) == 0) ? 1 : 0;
}

int main(void)
{
    int pan_position = CENTER_PULSE_WIDTH;
    int tilt_position = CENTER_PULSE_WIDTH;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set pan servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set tilt servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set button pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Camera Control\n");
    printf("Pan servo: GPIO%d, Tilt servo: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Buttons (active-low, pull-up): UP=GPIO%d, DOWN=GPIO%d, LEFT=GPIO%d, RIGHT=GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Center position: %d us, Range: %d-%d us, Step: %d us\n",
           CENTER_PULSE_WIDTH, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH, STEP_SIZE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_button(UP_BUTTON_PIN)) {
            tilt_position -= STEP_SIZE;
            if (set_servo_pulse(TILT_SERVO_PIN, tilt_position) < 0) {
                break;
            }
        }
        if (read_button(DOWN_BUTTON_PIN)) {
            tilt_position += STEP_SIZE;
            if (set_servo_pulse(TILT_SERVO_PIN, tilt_position) < 0) {
                break;
            }
        }
        if (read_button(LEFT_BUTTON_PIN)) {
            pan_position -= STEP_SIZE;
            if (set_servo_pulse(PAN_SERVO_PIN, pan_position) < 0) {
                break;
            }
        }
        if (read_button(RIGHT_BUTTON_PIN)) {
            pan_position += STEP_SIZE;
            if (set_servo_pulse(PAN_SERVO_PIN, pan_position) < 0) {
                break;
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

