        fprintf(stderr, "Error: %s exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Error creating directory %s: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command),
             "raspistill -o %s -q %d -n -e jpg", filename, IMAGE_QUALITY);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error executing raspistill: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(result) || WEXITSTATUS(result) != 0) {
        fprintf(stderr, "raspistill failed (exit code: %d)\n", WIFEXITED(result) ? WEXITSTATUS(result) : -1);
        return -1;
    }
    return 0;
}

static int create_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin, char *json_string, size_t max_len) {
    json_t *root = json_object();
    if (!root) return -1;

    json_object_set_new(root, "filename", json_string(filename));
    json_object_set_new(root, "timestamp", json_string(timestamp));
    json_object_set_new(root, "motion_status", json_integer(motion_status));
    json_object_set_new(root, "gpio_pin", json_integer(gpio_pin));

    char *json_str = json_dumps(root, JSON_COMPACT);
    json_decref(root);

    if (!json_str) return -1;
    strncpy(json_string, json_str, max_len - 1);
    json_string[max_len - 1] = '\0';
    free(json_str);
    return 0;
}

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    (void)contents; (void)userp;
    return size * nmemb;
}

static int post_data(const char *url, const char *json_payload, const char *filename) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error initializing libcurl\n");
        return -1;
    }

    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        curl_easy_cleanup(curl);
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    struct curl_httppost *formpost = NULL;
    struct curl_httppost *lastptr = NULL;
    struct curl_slist *headerlist = NULL;

    curl_formadd(&formpost, &lastptr, CURLFORM_COPYNAME, "json_payload", CURLFORM_COPYCONTENTS, json_payload, CURLFORM_END);
    curl_formadd(&formpost, &lastptr, CURLFORM_COPYNAME, "image", CURLFORM_FILE, filename, CURLFORM_END);
    curl_formadd(&formpost, &lastptr, CURLFORM_END);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_HTTPPOST, formpost);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 30L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        fclose(file);
        curl_easy_cleanup(curl);
        curl_formfree(formpost);
        curl_slist_free_all(headerlist);
        return -1;
    }

    long response_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
    if (response_code != 200) {
        fprintf(stderr, "HTTP request failed with response code: %ld\n", response_code);
        fclose(file);
        curl_easy_cleanup(curl);
        curl_formfree(formpost);
        curl_slist_free_all(headerlist);
