#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>

#define PIR_PIN        17
#define GPIO_CHIP_NAME "gpiochip0"
#define IMAGE_DIR      "/home/pi/images"
#define LOG_FILE       "/home/pi/motion_capture.log"
#define DEBOUNCE_MS    50
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int capture_image(void) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        log_message("localtime_r failed");
        return -1;
    }
    char filename[256];
    char command[512];
    snprintf(filename, sizeof(filename), "%s/%04d%02d%02d_%02d%02d%02d_%03d.jpg",
             IMAGE_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
             tm.tm_hour, tm.tm_min, tm.tm_sec, (int)(t % 1000));
    snprintf(command, sizeof(command),
             "raspistill -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview",
             filename);
    int status = system(command);
    if (status == -1) {
        log_message("system() failed to launch raspistill");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        char logmsg[512];
        snprintf(logmsg, sizeof(logmsg), "Image captured: %s", filename);
        log_message(logmsg);
        return 0;
    }
    char logmsg[512];
    snprintf(logmsg, sizeof(logmsg), "raspistill failed (status=0x%04x)", status);
    log_message(logmsg);
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "pir_monitor") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        gpiod_chip_close(chip);
        return 1;
    }

    log_message("PIR sensor monitoring started on GPIO17 (falling-edge).");

    while (program_running) {
        struct timespec ts = { POLL_TIMEOUT_MS / 1000, (POLL_TIMEOUT_MS % 1000) * 1000000L };
        int ret = gpiod_line_event_wait(pir_line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(pir_line, &event) < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_read");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
            continue;
        }

        log_message("Motion detected (falling edge on GPIO17).");

        if (capture_image() != 0) {
            log_message("Image capture failed.");
        }

        struct timespec debounce = { 0, DEBOUNCE_MS * 1000000L };
        nanosleep(&debounce, NULL);
    }

    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    log_message("PIR sensor monitoring stopped.");
    return 0;
}

