    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "pir_monitor") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        gpiod_chip_close(chip);
        return 1;
    }

    log_message("PIR sensor monitoring started on GPIO17 (falling-edge).");

    while (program_running) {
        struct timespec ts = { POLL_TIMEOUT_MS / 1000, (POLL_TIMEOUT_MS % 1000) * 1000000L };
        int ret = gpiod_line_event_wait(pir_line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(pir_line, &event) < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_read");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
            continue;
        }

        log_message("Motion detected (falling edge on GPIO17).");

        if (capture_image() != 0) {
            log_message("Image capture failed.");
        }

        struct timespec debounce = { 0, DEBOUNCE_MS * 1000000L };
        nanosleep(&debounce, NULL);
    }

    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    log_message("PIR sensor monitoring stopped.");
    return 0;
}

