#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define OUTPUT_FILE "cropped.yuv"
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo) {
    (void)signo;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    void *buffer = NULL;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = CAPTURE_WIDTH;
    fmt.fmt.pix.height = CAPTURE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }
    if (fmt.fmt.pix.width != CAPTURE_WIDTH || fmt.fmt.pix.height != CAPTURE_HEIGHT) {
        fprintf(stderr, "Warning: driver adjusted size to %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Error: driver did not accept YUYV format\n");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }
    if (req.count < 1) {
        fprintf(stderr, "Error: insufficient buffer memory\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        buffer = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    while (!g_stop) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = CAPTURE_TIMEOUT_SEC;
        tv.tv_usec = 0;
        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) continue;
            perror("select");
            goto cleanup;
        }
        if (r == 0) {
            fprintf(stderr, "select timeout\n");
            goto cleanup;
        }
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) continue;
            perror("VIDIOC_DQBUF");
            goto cleanup;
        }
        if (buf.bytesused < (size_t)(CROP_WIDTH * CROP_HEIGHT * 2)) {
            fprintf(stderr, "Incomplete frame (%u bytes)\n", buf.bytesused);
            if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
                perror("VIDIOC_QBUF");
            }
            continue;
        }
        break;
    }

    if (g_stop) {
        fprintf(stderr, "Interrupted by signal\n");
        goto cleanup;
    }

    fp = fopen(OUTPUT_FILE, "wb");
    if (!fp) {
        perror("fopen(" OUTPUT_FILE ")");
        goto cleanup;
    }

    size_t crop_size = (size_t)CROP_WIDTH * CROP_HEIGHT * 2;
    size_t src_row = (size_t)CAPTURE_WIDTH * 2;
    size_t dst_row = (size_t)CROP_WIDTH * 2;
    size_t crop_bytes = crop_size;
    unsigned char *dst = malloc(crop_size);
    if (!dst) {
        perror("malloc");
        goto cleanup;
    }

    for (size_t row = 0; row < CROP_HEIGHT && crop_bytes > 0; row++) {
        size_t src_row_start = (size_t)CAPTURE_WIDTH * 2 * row;
        size_t dst_row_start = (size_t)CROP_WIDTH * 2 * row;
        size_t copy_len = (src_row - dst_row < crop_bytes) ? src_row : dst_row;
        memcpy(dst + dst_row_start, buffer + src_row_start, copy_len);
        crop_bytes -= copy_len;
    }

    if (fwrite(dst, 1, crop_size, fp) != crop_size) {
        perror("fwrite");
        goto cleanup;
    }

    if (fflush(fp) == EOF) {
        perror("fflush");
        goto cleanup;
    }

    printf("Cropped YUYV frame saved to %s (%dx%d)\n", OUTPUT_FILE, CROP_WIDTH, CROP_HEIGHT);
    ret = EXIT_SUCCESS;

cleanup:
    if (buffer && buffer != MAP_FAILED) {
        munmap(buffer, buf.length);
    }
    if (fp) {
        fclose(fp);
    }
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }
    free(dst);
    return ret;
}

