#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define SERVO_FREQ 50
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_NEUTRAL_PULSE 1500
#define ANGLE_MIN 0
#define ANGLE_MAX 180
#define STEP_SIZE 5
#define DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int angle_to_pulse(int angle) {
    if (angle < ANGLE_MIN || angle > ANGLE_MAX) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, ANGLE_MIN, ANGLE_MAX);
        return -1;
    }
    return SERVO_MIN_PULSE + (int)((float)angle / 180.0f * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
}

static int set_servo_angle(int pin, int angle) {
    int pulse = angle_to_pulse(angle);
    if (pulse < 0) {
        return -1;
    }
    if (gpioServo(pin, pulse) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d (pulse %d)\n", pin, pulse);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, SERVO_NEUTRAL_PULSE);
    gpioServo(TILT_SERVO_PIN, SERVO_NEUTRAL_PULSE);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PAN_SERVO_PIN, SERVO_FREQ) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, SERVO_FREQ) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    int pan_angle = 90;
    int tilt_angle = 90;

    if (set_servo_angle(PAN_SERVO_PIN, pan_angle) < 0 ||
        set_servo_angle(TILT_SERVO_PIN, tilt_angle) < 0) {
        fprintf(stderr, "Error: Failed to initialize servos to neutral position\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler\n");
        cleanup();
        return 1;
    }

    printf("Servo control started. Press arrow keys to move pan (left/right) or tilt (up/down), 'q' to quit.\n");

    while (running) {
        char c = getchar();
        if (c == EOF) {
            break;
        }
        if (c == 'q' || c == 'Q') {
            break;
        }
        switch (c) {
            case 27: {
                int next = getchar();
                if (next == '[') {
                    int dir = getchar();
                    if (dir == 'A') {
                        tilt_angle -= STEP_SIZE;
                        if (tilt_angle < ANGLE_MIN) tilt_angle = ANGLE_MIN;
                    } else if (dir == 'B') {
                        tilt_angle += STEP_SIZE;
                        if (tilt_angle > ANGLE_MAX) tilt_angle = ANGLE_MAX;
                    }
                }
                break;
            }
            case 68:
                pan_angle += STEP_SIZE;
                if (pan_angle > ANGLE_MAX) pan_angle = ANGLE_MAX;
                break;
            case 65:
                pan_angle -= STEP_SIZE;
                if (pan_angle < ANGLE_MIN) pan_angle = ANGLE_MIN;
                break;
            case 67:
                tilt_angle += STEP_SIZE;
                if (tilt_angle > ANGLE_MAX) tilt_angle = ANGLE_MAX;
                break;
            case 66:
                tilt_angle -= STEP_SIZE;
                if (tilt_angle < ANGLE_MIN) tilt_angle = ANGLE_MIN;
                break;
            default:
                break;
        }

        if (set_servo_angle(PAN_SERVO_PIN, pan_angle) < 0 ||
            set_servo_angle(TILT_SERVO_PIN, tilt_angle) < 0) {
            fprintf(stderr, "Error: Failed to set servo angles\n");
            break;
        }

        gpioDelay(DELAY_MS * 1000);
    }

    cleanup();
    printf("Servo control stopped.\n");
    return 0;
}

