    int tilt_angle = 90;

    if (set_servo_angle(PAN_SERVO_PIN, pan_angle) < 0 ||
        set_servo_angle(TILT_SERVO_PIN, tilt_angle) < 0) {
        fprintf(stderr, "Error: Failed to initialize servos to neutral position\n");
        cleanup();
        return 1;
    }

