        if (c == EOF) {
            break;
        }
        if (c == 'q' || c == 'Q') {
            break;
        }
        switch (c) {
            case 27: {
                int next = getchar();
                if (next == '[') {
                    int dir = getchar();
                    if (dir == 'A') {
                        tilt_angle -= STEP_SIZE;
                        if (tilt_angle < ANGLE_MIN) tilt_angle = ANGLE_MIN;
