        fprintf(stderr, "OLED initialization failed\n");
        close(fd);
        return 1;
    }
    if (oled_clear(fd) < 0) { close(fd); return 1; }
    if (oled_display(fd) < 0) { close(fd); return 1; }

    while (running) {
        char temp_str[16], cpu_str[16];
        if (read_cpu_temp("/sys/class/thermal/thermal_zone0/temp", temp_str, sizeof(temp_str)) < 0) {
            snprintf(temp_str, sizeof(temp_str), "Temp Read Error");
        } else {
            int temp_milli = atoi(temp_str);
            snprintf(temp_str, sizeof(temp_str), "Temp: %d.%dC", temp_milli / 1000, (temp_milli % 1000) / 100);
        }
        if (read_cpu_usage("/proc/stat", cpu_str, sizeof(cpu_str)) < 0) {
            snprintf(cpu_str, sizeof(cpu_str), "CPU Read Error");
        }
        oled_clear(fd);
        oled_draw_string(fd, temp_str, 0, 0);
        oled_draw_string(fd, cpu_str, 0, 10);
        sleep(1);
    }

    oled_clear(fd);
    oled_display(fd);
    close(fd);
    return 0;
}

