#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_BACKLIGHT 0x08
#define LCD_ENABLE 0x04

#define PULSES_PER_LITER 4500.0
#define SAMPLE_INTERVAL_SEC 1.0
#define LCD_UPDATE_INTERVAL_SEC 10.0

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static double total_volume = 0.0;
static int i2c_handle = -1;

static void pulse_callback(int gpio, int level, uint32_t tick, void *user);
static void signal_handler(int sig);
static int lcd_init(int handle);
static void lcd_send(int handle, uint8_t bits, uint8_t mode);
static void lcd_string(int handle, const char *s);
static void lcd_clear(int handle);
static void lcd_set_cursor(int handle, int col, int row);
static void lcd_print_data(int handle, double flow_rate, double volume);

static void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pulse_count++;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int lcd_init(int handle) {
    char init_seq[] = {0x33, 0x32, 0x28, 0x0C, 0x06, 0x01};
    for (size_t i = 0; i < sizeof(init_seq); i++) {
        if (i2cWriteByte(handle, init_seq[i]) < 0) {
            fprintf(stderr, "Error writing LCD init byte 0x%02X: %s\n", init_seq[i], strerror(errno));
            return -1;
        }
        gpioDelay(5000);
    }
    return 0;
}

static void lcd_send(int handle, uint8_t bits, uint8_t mode) {
    uint8_t high = (bits & 0xF0) | mode | LCD_BACKLIGHT;
    uint8_t low = ((bits << 4) & 0xF0) | mode | LCD_BACKLIGHT;

    if (i2cWriteByte(handle, high) < 0) {
        fprintf(stderr, "Error writing LCD high nibble: %s\n", strerror(errno));
        return;
    }
    gpioDelay(1000);
    if (i2cWriteByte(handle, high | LCD_ENABLE) < 0) {
        fprintf(stderr, "Error writing LCD high enable: %s\n", strerror(errno));
        return;
    }
    gpioDelay(1000);
    if (i2cWriteByte(handle, high) < 0) {
        fprintf(stderr, "Error writing LCD high disable: %s\n", strerror(errno));
        return;
    }
    gpioDelay(1000);

    if (i2cWriteByte(handle, low) < 0) {
        fprintf(stderr, "Error writing LCD low nibble: %s\n", strerror(errno));
        return;
    }
    gpioDelay(1000);
    if (i2cWriteByte(handle, low | LCD_ENABLE) < 0) {
        fprintf(stderr, "Error writing LCD low enable: %s\n", strerror(errno));
        return;
    }
    gpioDelay(1000);
    if (i2cWriteByte(handle, low) < 0) {
        fprintf(stderr, "Error writing LCD low disable: %s\n", strerror(errno));
        return;
    }
    gpioDelay(1000);
}

static void lcd_string(int handle, const char *s) {
    while (*s) {
        lcd_send(handle, (uint8_t)*s++, LCD_CHR);
    }
}

static void lcd_clear(int handle) {
    lcd_send(handle, 0x01, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_set_cursor(int handle, int col, int row) {
    int offsets[] = {0x00, 0x40, 0x14, 0x54};
    if (row > 3) row = 3;
    lcd_send(handle, 0x80 | (col + offsets[row]), LCD_CMD);
}

static void lcd_print_data(int handle, double flow_rate, double volume) {
    char line1[17];
    char line2[17];

    snprintf(line1, sizeof(line1), "Flow: %.2f L/h", flow_rate);
    snprintf(line2, sizeof(line2), "Vol: %.2f L", volume);

    lcd_clear(handle);
    lcd_set_cursor(handle, 0, 0);
    lcd_string(handle, line1);
    lcd_set_cursor(handle, 0, 1);
    lcd_string(handle, line2);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, LCD_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init(i2c_handle) < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    time_t last_lcd_update = time(NULL);

    while (running) {
        time_t now = time(NULL);
        uint32_t pulses = pulse_count;
        pulse_count = 0;

        double flow_rate = (double)pulses / PULSES_PER_LITER / SAMPLE_INTERVAL_SEC * 3600.0;
        total_volume += (double)pulses / PULSES_PER_LITER;

        printf("Flow Rate: %.2f L/h, Total Volume: %.2f L\n", flow_rate, total_volume);

        if (difftime(now, last_lcd_update) >= LCD_UPDATE_INTERVAL_SEC) {
            lcd_print_data(i2c_handle, flow_rate, total_volume);
            last_lcd_update = now;
        }

        gpioDelay((uint32_t)(SAMPLE_INTERVAL_SEC * 1000000.0));
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        lcd_clear(i2c_handle);
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

