#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define ANEMOMETER_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SAMPLE_WINDOW_MS 500
#define MAX_PULSES 1000
#define MAX_SPI_RETRIES 3
#define MAX_I2C_RETRIES 3

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static int spi_fd = -1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    if (level == 1) {
        int count = __sync_fetch_and_add(&pulse_count, 1);
        if (count >= MAX_PULSES) {
            fprintf(stderr, "Warning: pulse count saturated\n");
        }
    }
}

static int init_gpio(void) {
    /* Use Linux GPIO character device /sys/class/gpio */
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY) {
            fprintf(stderr, "Failed to export GPIO %d: %s\n", ANEMOMETER_GPIO, strerror(errno));
            return -1;
        }
    } else {
        char buf[16];
        int len = snprintf(buf, sizeof(buf), "%d", ANEMOMETER_GPIO);
        if (write(fd, buf, len) < 0) {
            fprintf(stderr, "Failed to write GPIO export: %s\n", strerror(errno));
            close(fd);
            return -1;
        }
        close(fd);
    }

    fd = open("/sys/class/gpio/gpio" ANEMOMETER_GPIO "/direction", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "in", 2) < 0) {
        fprintf(stderr, "Failed to set GPIO input: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    fd = open("/sys/class/gpio/gpio" ANEMOMETER_GPIO "/edge", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to set GPIO edge: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "rising", 6) < 0) {
        fprintf(stderr, "Failed to set rising edge: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

static int init_i2c(void) {
    char dev[32];
    snprintf(dev, sizeof(dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(dev, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LCD_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_SPI_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static int read_wind_direction(void) {
    int adc_value = read_mcp3008(0);
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read wind direction from MCP3008\n");
        return -1;
    }
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Warning: ADC reading at extreme (%d) - sensor absent or fault\n", adc_value);
        return -1;
    }
    return adc_value;
}

static float calculate_wind_speed(int pulses) {
    float circumference = 1.0;
    float distance = (float)pulses * circumference;
    float time_sec = SAMPLE_WINDOW_MS / 1000.0;
    return distance / time_sec;
}

static void display_on_lcd(float wind_speed, int wind_direction) {
    char line1[17];
    char line2[17];

    snprintf(line1, sizeof(line1), "Speed: %.2f m/s", wind_speed);
    snprintf(line2, sizeof(line2), "Dir: %d", wind_direction);

    /* Send to PCF8574 LCD via I2C */
    for (int i = 0; i < 2; i++) {
        char *line = (i == 0) ? line1 : line2;
        int addr = (i == 0) ? 0x00 : 0x40; /* DDRAM address */

        uint8_t buf[18];
        buf[0] = 0x80 | addr;
        for (int j = 0; j < 16; j++) {
            buf[j + 1] = (uint8_t)line[j];
        }
        buf[17] = 0x00;

        for (int attempt = 0; attempt < MAX_I2C_RETRIES; attempt++) {
            if (write(i2c_fd, buf, sizeof(buf)) == (ssize_t)sizeof(buf)) {
                break;
            }
            fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n",
                    attempt + 1, MAX_I2C_RETRIES, strerror(errno));
            usleep(10000);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("Anemometer and Wind Vane Monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        struct timespec start, now;
        clock_gettime(CLOCK_MONOTONIC, &start);

        pulse_count = 0;

        /* Wait for sample window */
        do {
            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed_ms = (now.tv_sec - start.tv_sec) * 1000 +
                              (now.tv_nsec - start.tv_nsec) / 1000000;
            if (!running) break;
        } while (elapsed_ms < SAMPLE_WINDOW_MS);

        int pulses = pulse_count;
        float wind_speed = calculate_wind_speed(pulses);
        int wind_direction = read_wind_direction();

