#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_BACKLIGHT 0x08
#define LCD_ENABLE 0x04
#define LCD_READBACK 0x08

#define PULSES_PER_LITER 7.5
#define SAMPLE_INTERVAL_SEC 1
#define SENSOR_TIMEOUT_SEC 5

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        g_pulse_count++;
    }
}

static int lcd_write_nibble(int handle, uint8_t nibble, uint8_t mode) {
    uint8_t data = (nibble & 0xF0) | mode | LCD_BACKLIGHT;
    if (i2cWriteByte(handle, data) < 0) return -1;
    if (i2cWriteByte(handle, data | LCD_ENABLE) < 0) return -1;
    gpioDelay(1000);
    if (i2cWriteByte(handle, data & ~LCD_ENABLE) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int lcd_send_byte(int handle, uint8_t val, uint8_t mode) {
    if (lcd_write_nibble(handle, (val & 0xF0), mode) < 0) return -1;
    if (lcd_write_nibble(handle, ((val << 4) & 0xF0), mode) < 0) return -1;
    return 0;
}

static int lcd_send_command(int handle, uint8_t cmd) {
    return lcd_send_byte(handle, cmd, LCD_CMD);
}

static int lcd_send_data(int handle, uint8_t data) {
    return lcd_send_byte(handle, data, LCD_CHR);
}

static int lcd_init(int handle) {
    gpioDelay(50000);
    if (lcd_send_command(handle, 0x33) < 0) return -1;
    gpioDelay(50000);
    if (lcd_send_command(handle, 0x32) < 0) return -1;
    gpioDelay(50000);
    if (lcd_send_command(handle, 0x28) < 0) return -1;
    gpioDelay(50000);
    if (lcd_send_command(handle, 0x0C) < 0) return -1;
    gpioDelay(50000);
    if (lcd_send_command(handle, 0x06) < 0) return -1;
    gpioDelay(50000);
    if (lcd_send_command(handle, 0x01) < 0) return -1;
    gpioDelay(200000);
    return 0;
}

static int lcd_clear(int handle) {
    if (lcd_send_command(handle, 0x01) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_set_cursor(int handle, int col, int row) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    return lcd_send_command(handle, addr);
}

static int lcd_write_string(int handle, const char *str) {
    while (*str) {
        if (lcd_send_data(handle, (uint8_t)*str) < 0) return -1;
        str++;
    }
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        lcd_clear(g_i2c_handle);
        lcd_write_string(g_i2c_handle, "Shutting down...");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback) < 0) {
        fprintf(stderr, "Error: failed to set alert function on GPIO%d.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, LCD_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: LCD initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    time_t last_pulse_time = time(NULL);
    int consecutive_zero_samples = 0;

    while (g_running) {
        int pulses = g_pulse_count;
        g_pulse_count = 0;

        time_t now = time(NULL);
        if (pulses > 0) {
            last_pulse_time = now;
            consecutive_zero_samples = 0;
        } else {
            if (difftime(now, last_pulse_time) >= SENSOR_TIMEOUT_SEC) {
                fprintf(stderr, "Warning: no pulses detected for %d seconds. Sensor may be absent.\n", SENSOR_TIMEOUT_SEC);
            }
            consecutive_zero_samples++;
            if (consecutive_zero_samples >= (SENSOR_TIMEOUT_SEC * 2)) {
                fprintf(stderr, "Error: sensor absent for extended period. Aborting.\n");
                break;
            }
        }

        float flow_rate = (pulses / PULSES_PER_LITER) / (SAMPLE_INTERVAL_SEC / 60.0);
        char buffer[LCD_WIDTH + 1];
        snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);

        lcd_clear(g_i2c_handle);
        lcd_set_cursor(g_i2c_handle, 0, 0);
        lcd_write_string(g_i2c_handle, buffer);

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

