#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DELAY_US 800

static const int row_pins[8] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[8] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int check(int rc, const char *msg) {
    if (rc < 0) {
        fprintf(stderr, "Error: %s (pigpio code %d)\n", msg, rc);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (check(gpioInitialise(), "gpioInitialise")) return -1;

    for (int i = 0; i < 8; i++) {
        if (check(gpioSetMode(row_pins[i], PI_OUTPUT), "gpioSetMode row")) return -1;
