}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (safe_set_mode(row_pins[i], PI_OUTPUT) != 0) return -1;
        if (safe_write(row_pins[i], 0) != 0) return -1;
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (safe_set_mode(col_pins[i], PI_OUTPUT) != 0) return -1;
        if (safe_write(col_pins[i], 1) != 0) return -1;
    }
    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        safe_write(row_pins[i], 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        safe_write(col_pins[i], 1);
    }
}

static void display_column(int col) {
    clear_matrix();
    if (safe_write(col_pins[col], 0) != 0) return;
    for (int row = 0; row < NUM_ROWS; row++) {
        if (safe_write(row_pins[row], 1) != 0) return;
        gpioDelay(DELAY_MS * 1000);
    }
    if (safe_write(col_pins[col], 1) != 0) return;
}

static void cleanup(void) {
    clear_matrix();
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: signal handler installation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int col = 0; col < NUM_COLS && running; col++) {
            display_column(col);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

