#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX75031_ADDR 0x50
#define LOG_FILE "depth_log.csv"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                MLX75031_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance) {
    char cmd[2] = {0x01, 0x00};
    char buf[2];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    *distance = ((uint16_t)(buf[0] & 0x0F) << 8) | (uint8_t)buf[1];
    return 0;
}

static int log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%u\n", timestamp, distance) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_sensor() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
        fflush(log_file);
    }

    while (running) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            if (log_data(distance) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
            log_data((uint16_t)-1);
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000);
            if (init_sensor() != 0) {
                fprintf(stderr, "Sensor re-initialization failed, exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

