#define I2C_BUS 1
#define SI1145_ADDR 0x45
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_si1145(int handle) {
    if (i2cWriteByteData(handle, 0x17, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x18, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x0A, 0x07) < 0) return -1;
    if (i2cWriteByteData(handle, 0x0F, 0x07) < 0) return -1;
    if (i2cWriteByteData(handle, 0x10, 0x07) < 0) return -1;
