static int read_si1145_data(int handle, uint16_t *prox, uint16_t *als) {
    char buf[4];
    if (i2cReadI2CBlockData(handle, 0x22, buf, 4) != 4) return -1;
    *prox = (uint16_t)((buf[1] << 8) | buf[0]);
    *als = (uint16_t)((buf[3] << 8) | buf[2]);
    return 0;
}

static void log_data(FILE *fp, uint16_t prox, uint16_t als) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n", ts, prox, als);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145(i2c_handle) != 0) {
        fprintf(stderr, "Error initializing Si1145 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Si1145 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t prox, als;
        if (read_si1145_data(i2c_handle, &prox, &als) == 0) {
            log_data(log_file, prox, als);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

