        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = gpioRead(SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error reading initial sensor state: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
