#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x45
#define LOG_FILE "biometric_data.log"
#define SAMPLE_INTERVAL_US 1000000

/* Si1145 register addresses */
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_REV_ID 0x01
#define SI1145_REG_SEQ_ID 0x02
#define SI1145_REG_INT_CFG 0x03
#define SI1145_REG_IRQ_ENABLE 0x04
#define SI1145_REG_IRQ_MODE1 0x05
#define SI1145_REG_IRQ_MODE2 0x06
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_RATE 0x0A
#define SI1145_REG_PS_RATE 0x0B
#define SI1145_REG_PS_LED21 0x0C
#define SI1145_REG_PS_LED3 0x0D
#define SI1145_REG_PARAM_WR 0x17
#define SI1145_REG_COMMAND 0x18
#define SI1145_REG_RESPONSE 0x20
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_IR_DATA0 0x24
#define SI1145_REG_ALS_IR_DATA1 0x25
#define SI1145_REG_PS1_DATA0 0x26
#define SI1145_REG_PS1_DATA1 0x27
#define SI1145_REG_PS2_DATA0 0x28
#define SI1145_REG_PS2_DATA1 0x29
#define SI1145_REG_PS3_DATA0 0x2A
#define SI1145_REG_PS3_DATA1 0x2B

/* Si1145 command codes */
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_ALS_PS_FORCE 0x07
#define SI1145_CMD_PARAM_QUERY 0x80
#define SI1145_CMD_PARAM_SET 0xA0

/* Si1145 parameter offsets */
#define SI1145_PARAM_CHLIST 0x01
#define SI1145_PARAM_PSLED12_SELECT 0x02
#define SI1145_PARAM_PS_ADC_GAIN 0x03
#define SI1145_PARAM_PS_ADC_COUNTER 0x04
#define SI1145_PARAM_ALS_VIS_ADC_GAIN 0x05
#define SI1145_PARAM_ALS_VIS_ADC_COUNTER 0x06
#define SI1145_PARAM_ALS_IR_ADC_GAIN 0x07
#define SI1145_PARAM_ALS_IR_ADC_COUNTER 0x08

/* Si1145 channel list bits */
#define SI1145_CHLIST_EN_ALS_VIS 0x10
#define SI1145_CHLIST_EN_ALS_IR 0x20
#define SI1145_CHLIST_EN_PS1 0x01
#define SI1145_CHLIST_EN_PS2 0x02
#define SI1145_CHLIST_EN_PS3 0x04

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int si1145_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int si1145_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int si1145_read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading block from reg 0x%02X: %s\n", reg, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int si1145_wait_response(void) {
    uint8_t resp = 0xFF;
    for (int i = 0; i < 10; i++) {
        if (si1145_read_reg(SI1145_REG_RESPONSE, &resp) < 0) return -1;
        if (resp != 0xFF) return 0;
        gpioDelay(1000);
    }
    fprintf(stderr, "Si1145 response timeout\n");
    return -1;
}

static int si1145_param_set(uint8_t param, uint8_t value) {
    if (si1145_write_reg(SI1145_REG_PARAM_WR, value) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_PARAM_SET | param) < 0) return -1;
    return si1145_wait_response();
}

static int si1145_init(void) {
    uint8_t part_id = 0;
    if (si1145_read_reg(SI1145_REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    if (si1145_write_reg(SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_ALS_RATE, 0x00) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_PS_RATE, 0x00) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_PS_LED21, 0x0F) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_PS_LED3, 0x0F) < 0) return -1;

    if (si1145_param_set(SI1145_PARAM_CHLIST, SI1145_CHLIST_EN_ALS_VIS | SI1145_CHLIST_EN_ALS_IR | SI1145_CHLIST_EN_PS1) < 0) return -1;
    if (si1145_param_set(SI1145_PARAM_PSLED12_SELECT, 0x03) < 0) return -1;
    if (si1145_param_set(SI1145_PARAM_PS_ADC_GAIN, 0x00) < 0) return -1;
    if (si1145_param_set(SI1145_PARAM_PS_ADC_COUNTER, 0x40) < 0) return -1;
    if (si1145_param_set(SI1145_PARAM_ALS_VIS_ADC_GAIN, 0x00) < 0) return -1;
    if (si1145_param_set(SI1145_PARAM_ALS_VIS_ADC_COUNTER, 0x40) < 0) return -1;
    if (si1145_param_set(SI1145_PARAM_ALS_IR_ADC_GAIN, 0x00) < 0) return -1;
    if (si1145_param_set(SI1145_PARAM_ALS_IR_ADC_COUNTER, 0x40) < 0) return -1;

    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int si1145_read_data(uint16_t *proximity, uint16_t *ambient_light) {
    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_ALS_PS_FORCE) < 0) return -1;

    uint8_t buf[8];
    if (si1145_read_block(SI1145_REG_ALS_VIS_DATA0, buf, 8) < 0) return -1;

    *ambient_light = ((uint16_t)buf[1] << 8) | buf[0];
    *proximity = ((uint16_t)buf[5] << 8) | buf[4];

    return 0;
}

static void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n", I2C_BUS, SI1145_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t proximity = 0, ambient_light = 0;
        if (si1145_read_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

