#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27

#define TRIGGER_PULSE_US  10
#define ECHO_RISE_TIMEOUT_US  30000   /* 30 ms */
#define ECHO_PULSE_TIMEOUT_US 30000   /* 30 ms */
#define SAMPLE_PERIOD_US     60000000 /* 60 s */
#define MIN_DISTANCE_CM      2.0f
#define MAX_DISTANCE_CM      400.0f
#define WATER_THRESHOLD_CM   15.0f
#define LOG_FILE_NAME        "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static long long elapsed_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static float measure_distance(void)
{
    long long t0, t_rise, t_fall;

    trigger_sensor();

    t0 = elapsed_us();

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if (!g_running) {
            return -1.0f;
        }
        if (elapsed_us() - t0 > ECHO_RISE_TIMEOUT_US) {
            return -2.0f; /* sensor absent / no echo */
        }
    }
    t_rise = elapsed_us();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if (!g_running) {
            return -1.0f;
        }
        if (elapsed_us() - t_rise > ECHO_PULSE_TIMEOUT_US) {
            return -3.0f; /* echo stuck high / timeout */
        }
    }
    t_fall = elapsed_us();

    long long pulse_us = t_fall - t_rise;
    if (pulse_us <= 0) {
        return -4.0f;
    }

    /* speed of sound 343 m/s => 34300 cm/s = 0.0343 cm/us */
    float distance = (float)pulse_us * 0.0343f / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -5.0f; /* out of range */
    }

    return distance;
}

static void log_distance(float distance, int status)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (g_log_fp == NULL) {
        g_log_fp = fopen(LOG_FILE_NAME, "a");
        if (g_log_fp == NULL) {
            fprintf(stderr, "Error opening log file '%s': %s\n",
                    LOG_FILE_NAME, strerror(errno));
            return;
        }
    }

    switch (status) {
    case 0:
        fprintf(g_log_fp, "%s, Distance: %.2f cm\n", timestamp, distance);
        if (distance < WATER_THRESHOLD_CM) {
            fprintf(g_log_fp, "%s, Time to water the plant!\n", timestamp);
        }
        break;
    case -1:
        fprintf(g_log_fp, "%s, Error: measurement interrupted\n", timestamp);
        break;
    case -2:
        fprintf(g_log_fp, "%s, Error: sensor absent (no echo rise)\n", timestamp);
        break;
    case -3:
        fprintf(g_log_fp, "%s, Error: echo timeout (stuck high)\n", timestamp);
        break;
    case -4:
        fprintf(g_log_fp, "%s, Error: invalid pulse width\n", timestamp);
        break;
    case -5:
        fprintf(g_log_fp, "%s, Error: distance out of range\n", timestamp);
        break;
    default:
        fprintf(g_log_fp, "%s, Error: unknown status %d\n", timestamp, status);
        break;
    }

    fflush(g_log_fp);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(500000); /* 500 ms settle */

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            int status = (int)distance;
            log_distance(0.0f, status);
        } else {
            log_distance(distance, 0);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 60 && g_running; i++) {
            gpioDelay(1000000); /* 1 s */
        }
    }

    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

