#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define APDS9960_I2C_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define POLL_DELAY_MS 100

#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_CONFIG1 0x8D
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF5
#define APDS9960_CONFIG2 0x8B
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_RDATAL 0x96
#define APDS9960_GDATAL 0x98
#define APDS9960_BDATAL 0x9A
#define APDS9960_PDATA 0x9C

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[1] << 8 | buf[0];
    return 0;
}

static int apds9960_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, APDS9960_ID, &id) < 0) return -1;
    if (id != 0xAB) {
        fprintf(stderr, "APDS9960 ID mismatch: got 0x%02X, expected 0xAB\n", id);
        return -1;
    }

    if (i2c_write_reg8(fd, APDS9960_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, APDS9960_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, APDS9960_WTIME, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, APDS9960_CONFIG1, 0x60) < 0) return -1;
    if (i2c_write_reg8(fd, APDS9960_PPULSE, 0x40) < 0) return -1;
    if (i2c_write_reg8(fd, APDS9960_CONTROL, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, APDS9960_CONFIG2, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, APDS9960_ENABLE, 0x4F) < 0) return -1;
    return 0;
}

static int apds9960_read_proximity(int fd, uint16_t *prox) {
    uint8_t status;
    if (i2c_read_reg8(fd, APDS9960_STATUS, &status) < 0) return -1;
    if (!(status & 0x01)) return 1;
    if (i2c_read_reg16(fd, APDS9960_PDATA, prox) < 0) return -1;
    return 0;
}

static int apds9960_read_color(int fd, uint16_t *r, uint16_t *g, uint16_t *b) {
    if (i2c_read_reg16(fd, APDS9960_CDATAL, r) < 0) return -1;
    if (i2c_read_reg16(fd, APDS9960_RDATAL, g) < 0) return -1;
    if (i2c_read_reg16(fd, APDS9960_GDATAL, b) < 0) return -1;
    return 0;
}

static int open_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, APDS9960_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", APDS9960_I2C_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static void log_data(uint16_t r, uint16_t g, uint16_t b, uint16_t prox) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u,%u,%u,%u\n", ts, r, g, b, prox);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open_i2c();
    if (i2c_fd < 0) return 1;

    if (apds9960_init(i2c_fd) < 0) {
        fprintf(stderr, "APDS9960 init failed\n");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        uint16_t prox;
        int pr = apds9960_read_proximity(i2c_fd, &prox);
        if (pr == 0 && prox > PROXIMITY_THRESHOLD) {
            uint16_t r, g, b;
            if (apds9960_read_color(i2c_fd, &r, &g, &b) == 0) {
                log_data(r, g, b, prox);
            }
        } else if (pr < 0) {
            fprintf(stderr, "Proximity read error, re-initializing...\n");
            close(i2c_fd);
            i2c_fd = -1;
            usleep(100000);
            i2c_fd = open_i2c();
            if (i2c_fd >= 0 && apds9960_init(i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed\n");
                close(i2c_fd);
                i2c_fd = -1;
            }
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    printf("Shutdown complete.\n");
    return 0;
}

