#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60
#define PROX_DATA_REG  0x0A
#define SAMPLE_PERIOD  100000  /* microseconds (100 ms) */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val)
{
    if (i2c_smbus_read_byte_data(fd, reg) < 0) {
        return -1;
    }
    *val = (uint8_t)i2c_smbus_read_byte_data(fd, reg);
    return 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        return -1;
    }
    return 0;
}

static int read_proximity(int fd, uint8_t *prox)
{
    return i2c_read_byte(fd, PROX_DATA_REG, prox);
}

static float calculate_heart_rate(uint8_t prox)
{
    return (float)prox * 0.5f;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", timeinfo);
}

static int log_data(FILE *fp, const char *timestamp, float heart_rate)
{
    if (fprintf(fp, "%s,%.2f\n", timestamp, heart_rate) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        goto cleanup;
    }

    fp = fopen("heartrate.csv", "a");
    if (fp == NULL) {
        perror("fopen(heartrate.csv)");
        goto cleanup;
    }

    while (running) {
        uint8_t prox = 0;

        if (read_proximity(fd, &prox) < 0) {
            fprintf(stderr, "Warning: failed to read proximity data: %s\n",
                    strerror(errno));
            usleep(SAMPLE_PERIOD);
            continue;
        }

        float heart_rate = calculate_heart_rate(prox);

        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));

        if (log_data(fp, timestamp, heart_rate) < 0) {
            fprintf(stderr, "Warning: failed to log data: %s\n",
                    strerror(errno));
        }

        usleep(SAMPLE_PERIOD);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

