#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define CH101_ADDR 0x50
#define TRIGGER_REG 0x00
#define DISTANCE_REG 0x01
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_US 200000
#define TRIGGER_WAIT_US 50000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ch101_init(void) {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, CH101_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int ch101_trigger(void) {
    if (i2cWriteByteData(i2c_handle, TRIGGER_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing trigger to CH101\n");
        return -1;
    }
    return 0;
}

static int ch101_read_distance(uint16_t *distance) {
    int raw = i2cReadWordData(i2c_handle, DISTANCE_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading distance from CH101: %d\n", raw);
        return -1;
    }
    *distance = (uint16_t)raw;
    return 0;
}

static void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, %u\n", timestamp, distance);
        fflush(log_file);
    }
    printf("%s, %u\n", timestamp, distance);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (ch101_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Starting distance measurements. Press Ctrl-C to stop.\n");

    while (running) {
        if (ch101_trigger() != 0) {
            gpioDelay(TRIGGER_WAIT_US);
            continue;
        }

        gpioDelay(TRIGGER_WAIT_US);

        uint16_t distance = 0;
        if (ch101_read_distance(&distance) != 0) {
            continue;
        }

        log_distance(distance);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

