#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICU20201_ADDR 0x60
#define ICU20201_REG_DISTANCE 0x00
#define ICU20201_REG_CONFIG 0x01
#define ICU20201_REG_STATUS 0x02
#define ICU20201_REG_CHIP_ID 0x0F
#define ICU20201_CHIP_ID_VAL 0x2020

#define LED_PIN 17
#define DISTANCE_THRESHOLD 20.0f
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, ICU20201_ADDR, i2c_handle);
        return -1;
    }

    int chip_id = i2cReadWordData(i2c_handle, ICU20201_REG_CHIP_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading chip ID register: %d\n", chip_id);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if ((chip_id & 0xFFFF) != ICU20201_CHIP_ID_VAL) {
        fprintf(stderr, "Unexpected chip ID: 0x%04X (expected 0x%04X)\n", chip_id & 0xFFFF, ICU20201_CHIP_ID_VAL);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    printf("ICU-20201 detected (chip ID 0x%04X)\n", chip_id & 0xFFFF);

    /* Configure continuous ranging mode (example configuration) */
    if (i2cWriteWordData(i2c_handle, ICU20201_REG_CONFIG, 0x0001) < 0) {
        fprintf(stderr, "Error writing config register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_distance(float *distance) {
    int raw = i2cReadWordData(i2c_handle, ICU20201_REG_DISTANCE);
    if (raw < 0) {
        fprintf(stderr, "Error reading distance register: %d\n", raw);
        return -1;
    }

    /* Convert raw 16-bit value to centimeters (example scaling) */
    *distance = (float)raw * 0.1f;
    return 0;
}

static void control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

static void log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Starting distance monitoring (threshold: %.1f cm)...\n", DISTANCE_THRESHOLD);

    while (running) {
        float distance;
        if (read_distance(&distance) == 0) {
            control_led(distance);
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

