#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

/* Si1182 register addresses */
#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_HW_REV 0x01
#define SI1182_REG_SEQ_ID 0x02
#define SI1182_REG_INT_CFG 0x03
#define SI1182_REG_IRQ_ENABLE 0x04
#define SI1182_REG_IRQ_MODE1 0x05
#define SI1182_REG_IRQ_MODE2 0x06
#define SI1182_REG_HW_KEY 0x07
#define SI1182_REG_MEAS_RATE0 0x08
#define SI1182_REG_MEAS_RATE1 0x09
#define SI1182_REG_PS_LED21_SELECT 0x0A
#define SI1182_REG_PS_ENCODING 0x0B
#define SI1182_REG_PS1_ADC_MISC 0x0C
#define SI1182_REG_PS1_ADC_GAIN 0x0D
#define SI1182_REG_PS1_ADC_COUNTER 0x0E
#define SI1182_REG_PS1_ADC_CONFIG 0x0F
#define SI1182_REG_ALS_IR_ADC_MISC 0x10
#define SI1182_REG_ALS_IR_ADC_GAIN 0x11
#define SI1182_REG_ALS_IR_ADC_COUNTER 0x12
#define SI1182_REG_ALS_IR_ADC_CONFIG 0x13
#define SI1182_REG_ALS_VIS_ADC_MISC 0x14
#define SI1182_REG_ALS_VIS_ADC_GAIN 0x15
#define SI1182_REG_ALS_VIS_ADC_COUNTER 0x16
#define SI1182_REG_ALS_VIS_ADC_CONFIG 0x17
#define SI1182_REG_PS1_DATA0 0x18
#define SI1182_REG_PS1_DATA1 0x19
#define SI1182_REG_ALS_IR_DATA0 0x1A
#define SI1182_REG_ALS_IR_DATA1 0x1B
#define SI1182_REG_ALS_VIS_DATA0 0x1C
#define SI1182_REG_ALS_VIS_DATA1 0x1D

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id, hw_rev, seq_id;

    if (read_register(handle, SI1182_REG_PART_ID, &part_id) < 0) return -1;
    if (read_register(handle, SI1182_REG_HW_REV, &hw_rev) < 0) return -1;
    if (read_register(handle, SI1182_REG_SEQ_ID, &seq_id) < 0) return -1;

    printf("Si1182 detected: Part ID=0x%02X, HW Rev=0x%02X, Seq ID=0x%02X\n",
           part_id, hw_rev, seq_id);

    if (write_register(handle, SI1182_REG_HW_KEY, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_MEAS_RATE0, 0x08) < 0) return -1;
    if (write_register(handle, SI1182_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_PS_LED21_SELECT, 0x01) < 0) return -1;
    if (write_register(handle, SI1182_REG_PS_ENCODING, 0x03) < 0) return -1;
    if (write_register(handle, SI1182_REG_PS1_ADC_MISC, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_PS1_ADC_GAIN, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_PS1_ADC_COUNTER, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_PS1_ADC_CONFIG, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_ALS_IR_ADC_MISC, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_ALS_IR_ADC_GAIN, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_ALS_IR_ADC_COUNTER, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_ALS_IR_ADC_CONFIG, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_ALS_VIS_ADC_MISC, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_ALS_VIS_ADC_GAIN, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_ALS_VIS_ADC_COUNTER, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_ALS_VIS_ADC_CONFIG, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_INT_CFG, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_IRQ_MODE2, 0x00) < 0) return -1;

    return 0;
}

static int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient_light) {
    uint8_t ps1_data0, ps1_data1, als_ir_data0, als_ir_data1, als_vis_data0, als_vis_data1;

    if (read_register(handle, SI1182_REG_PS1_DATA0, &ps1_data0) < 0) return -1;
    if (read_register(handle, SI1182_REG_PS1_DATA1, &ps1_data1) < 0) return -1;
    if (read_register(handle, SI1182_REG_ALS_IR_DATA0, &als_ir_data0) < 0) return -1;
    if (read_register(handle, SI1182_REG_ALS_IR_DATA1, &als_ir_data1) < 0) return -1;
    if (read_register(handle, SI1182_REG_ALS_VIS_DATA0, &als_vis_data0) < 0) return -1;
    if (read_register(handle, SI1182_REG_ALS_VIS_DATA1, &als_vis_data1) < 0) return -1;

    *proximity = ((uint16_t)ps1_data1 << 8) | ps1_data0;
    *ambient_light = ((uint16_t)als_vis_data1 << 8) | als_vis_data0;

    return 0;
}

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed. Check wiring and sensor presence.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t proximity = 0, ambient_light = 0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !terminate) {
            if (read_sensor_data(i2c_handle, &proximity, &ambient_light) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(10000);
            }
        }

        if (success) {
            log_data(log_file, proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

