#include <errno.h>
#include <pigpio.h>

/* ICU-20201 I2C address (7-bit) */
#define ICU20201_ADDR 0x60

/* ICU-20201 register addresses */
#define REG_WHO_AM_I   0x00
#define REG_DISTANCE   0x01
#define REG_CONFIG     0x02
#define REG_LED_CTRL   0x03

/* Expected WHO_AM_I value for ICU-20201 */
#define ICU20201_WHO_AM_I 0x20

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 17

/* Default distance threshold in mm */
#define DEFAULT_THRESHOLD 100

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Polling interval in microseconds */
#define POLL_INTERVAL_US 50000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a register; returns 0 on success, -1 on error */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from a register; returns 0 on success, -1 on error */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

/* Initialize the ICU-20201 sensor; returns 0 on success, -1 on error */
static int init_sensor(int handle) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg(handle, REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != ICU20201_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, ICU20201_WHO_AM_I);
        return -1;
    }
    printf("ICU-20201 detected (WHO_AM_I = 0x%02X)\n", who_am_i);

    /* Configure sensor: enable continuous measurement mode */
    if (i2c_write_reg(handle, REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        return -1;
    }
    return 0;
}

/* Read distance in mm; returns -1 on error */
static int read_distance(int handle) {
    uint8_t distance = 0;
    if (i2c_read_reg(handle, REG_DISTANCE, &distance) != 0) {
        return -1;
    }
    return (int)distance;
}

/* Log a reading with timestamp to file */
static void log_data(int distance, int led_state) {
    FILE *fp = fopen("tof_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d mm, LED: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                distance, led_state ? "ON" : "OFF");
    } else {
        fprintf(fp, "Timestamp error, Distance: %d mm, LED: %s\n",
                distance, led_state ? "ON" : "OFF");
    }
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold '%s'. Using default: %d mm\n",
                    argv[1], DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }
    printf("Distance threshold: %d mm\n", threshold);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, ICU20201_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Set up signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to set SIGINT handler: %s\n", strerror(errno));
    }

    printf("Starting distance monitoring (Ctrl+C to exit)...\n");

    /* Main loop */
    while (g_running) {
        int distance = read_distance(g_i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        int led_state = (distance < threshold) ? 1 : 0;
        gpioWrite(LED_PIN, led_state);

        log_data(distance, led_state);

        printf("Distance: %d mm, LED: %s\n", distance, led_state ? "ON" : "OFF");

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

