#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x50
#define LOG_FILE       "intrusion_log.txt"
#define THRESHOLD_MM   1000
#define NUM_SAMPLES    10
#define SAMPLE_DELAY_MS 100
#define MEAS_DELAY_MS  10
#define RESP_LEN       15
#define DIST_IDX       11

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_resp(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance_mm) {
    uint8_t cmd[4] = {0x01, 0x02, 0x03, 0x04};
    uint8_t resp[RESP_LEN];

    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) < 0) return -1;
    msleep(MEAS_DELAY_MS);

    if (i2c_read_resp(fd, resp, sizeof(resp)) < 0) return -1;

    if (resp[0] != 0x01) {
        fprintf(stderr, "Unexpected response header: 0x%02X\n", resp[0]);
        return -1;
    }

    *distance_mm = ((uint16_t)resp[DIST_IDX] << 8) | resp[DIST_IDX + 1];
    return 0;
}

static int log_intrusion(const char *filename, uint16_t avg_mm) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s - Intrusion detected! Average distance: %u mm\n", ts, avg_mm);
    } else {
        fprintf(fp, "(unknown time) - Intrusion detected! Average distance: %u mm\n", avg_mm);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl-C to exit.\n");

    while (g_running) {
        long sum = 0;
        int valid = 0;
