#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29

#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x000B
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L0X_REG_RESULT_DISTANCE 0x0096

#define VL53L0X_MODEL_ID 0xEA
#define VL53L0X_RANGE_STATUS_OK 0x00

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_byte(int handle, uint16_t reg, uint8_t *val) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    if (i2cReadDevice(handle, buf, 1) != 1) return -1;
    *val = (uint8_t)buf[0];
    return 0;
}

static int i2c_write_byte(int handle, uint16_t reg, uint8_t val) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    return (i2cWriteDevice(handle, buf, 3) == 0) ? 0 : -1;
}

static int i2c_read_word(int handle, uint16_t reg, uint16_t *val) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int vl53l0x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_byte(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID (I2C error: %s)\n", strerror(errno));
        return -1;
    }
    if (model_id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0x%02X)\n", model_id, VL53L0X_MODEL_ID);
        return -1;
    }
    if (i2c_write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to clear interrupt (I2C error: %s)\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    int timeout = 100;

    while (timeout-- > 0) {
        if (i2c_read_byte(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            fprintf(stderr, "Warning: Failed to read interrupt status (I2C error: %s)\n", strerror(errno));
            return -1;
        }
        if (status & 0x07) break;
        gpioDelay(1000);
    }

    if (timeout < 0) {
        fprintf(stderr, "Warning: Timeout waiting for measurement\n");
        return -1;
    }

    uint8_t range_status = 0;
    if (i2c_read_byte(handle, VL53L0X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Warning: Failed to read range status (I2C error: %s)\n", strerror(errno));
        return -1;
    }
    if (range_status != VL53L0X_RANGE_STATUS_OK) {
        fprintf(stderr, "Warning: Range status error 0x%02X\n", range_status);
        return -1;
    }

    if (i2c_read_word(handle, VL53L0X_REG_RESULT_DISTANCE, distance) != 0) {
        fprintf(stderr, "Warning: Failed to read distance (I2C error: %s)\n", strerror(errno));
        return -1;
    }

    if (i2c_write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt (I2C error: %s)\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (I2C error: %s)\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l0x_init(handle) != 0) {
        fprintf(stderr, "Error: VL53L0X initialization failed\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X sensor initialized. Reading distance every 500ms...\n");

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l0x_read_distance(handle, &distance) == 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s Distance: %u mm\n", timestamp, distance);
            fflush(stdout);
        }
        gpioDelay(500000);
    }

    printf("\nExiting gracefully...\n");
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

