/*
 * Si1182 16-bit proximity reader for Raspberry Pi 3 Model B+
 * I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL), address 0x60.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1182_prox si1182_prox.c
 * Run:    ./si1182_prox
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#include <pigpio.h>

#define SI1182_I2C_BUS        1
#define SI1182_I2C_ADDR       0x60
#define SI1182_REG_PART_ID    0x00
#define SI1182_REG_HW_ID      0x01
#define SI1182_REG_PROX_DATA0 0x22
#define SI1182_REG_PROX_DATA1 0x23
#define SI1182_REG_COMMAND    0x30
#define SI1182_CMD_RESET      0x01
#define SI1182_CMD_PS_FORCE   0x05
#define SI1182_CMD_PS_AUTO    0x0D
#define SI1182_HW_ID_EXPECTED 0x82

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int si1182_reset(int handle)
{
    if (i2c_write_byte(handle, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms reset settling */
    return 0;
}

static int si1182_init(int handle)
{
    uint8_t hw_id = 0;

    if (i2c_read_byte(handle, SI1182_REG_HW_ID, &hw_id) < 0)
        return -1;

    if (hw_id != SI1182_HW_ID_EXPECTED) {
        fprintf(stderr, "Unexpected HW ID 0x%02X (expected 0x%02X) — sensor not present?\n",
                hw_id, SI1182_HW_ID_EXPECTED);
        return -1;
    }

    if (i2c_write_byte(handle, SI1182_REG_COMMAND, SI1182_CMD_PS_FORCE) < 0)
        return -1;
    gpioDelay(10000);

    if (i2c_write_byte(handle, SI1182_REG_COMMAND, SI1182_CMD_PS_AUTO) < 0)
        return -1;

    return 0;
}

static int si1182_read_proximity(int handle, uint16_t *prox)
{
    uint8_t lo = 0, hi = 0;

    if (i2c_read_byte(handle, SI1182_REG_PROX_DATA0, &lo) < 0)
        return -1;
    if (i2c_read_byte(handle, SI1182_REG_PROX_DATA1, &hi) < 0)
        return -1;

    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

int main(void)
{
    int handle = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(SI1182_I2C_BUS, SI1182_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                SI1182_I2C_BUS, SI1182_I2C_ADDR, strerror(errno));
        goto cleanup_gpio;
    }

    /* Sensor-absent detection: a NACK on the first write/read returns < 0. */
    if (si1182_reset(handle) < 0) {
        fprintf(stderr, "Si1182 reset failed — sensor may be absent or bus error\n");
        goto cleanup_i2c;
    }

    if (si1182_init(handle) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        goto cleanup_i2c;
    }

    printf("Si1182 proximity sensor ready. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t prox = 0;

        if (si1182_read_proximity(handle, &prox) == 0) {
            printf("Proximity: %u\n", prox);
        } else {
            fprintf(stderr, "Proximity read failed — continuing\n");
        }

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nExiting cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup_i2c:
    if (handle >= 0)
        i2cClose(handle);

cleanup_gpio:
    gpioTerminate();
    return rc;
}

