#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x50
#define READ_REG       0x00
#define READ_LEN       2
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t buf[READ_LEN];

    ssize_t n = read(fd, buf, READ_LEN);
    if (n < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) {
        fprintf(stderr, "I2C read returned 0 bytes (sensor absent?)\n");
        return -1;
    }
    if (n != READ_LEN) {
        fprintf(stderr, "I2C read short read: got %zd of %d bytes\n", n, READ_LEN);
        return -1;
    }

    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    fd = i2c_open(I2C_BUS, MLX75030_ADDR);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    printf("MLX75030 distance reader started on %s (addr 0x%02X).\n",
           I2C_BUS, MLX75030_ADDR);
    fflush(stdout);

    while (g_running) {
        uint16_t distance = 0;

        if (read_distance(fd, &distance) == 0) {
            printf("Distance: %u mm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying in %d ms...\n",
                    POLL_MS);
        }

        struct timespec ts;
        ts.tv_sec  = POLL_MS / 1000;
        ts.tv_nsec = (POLL_MS % 1000) * 1000000L;

        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running) {
            /* interrupted by signal; loop with remaining time */
        }
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;
    return rc;
}

