#include <string.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define OPT3101_ADDR 0x60

#define REG_RESULT 0x00
#define REG_CONFIG 0x01
#define REG_AMBIENT 0x02
#define REG_ERROR 0x03

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int read_distance(int fd, uint16_t *distance) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, REG_RESULT, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, REG_RESULT + 1, &hi) < 0) return -1;
    *distance = (uint16_t)((hi << 8) | lo);
    return 0;
}

int read_ambient(int fd, uint16_t *ambient) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, REG_AMBIENT, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, REG_AMBIENT + 1, &hi) < 0) return -1;
    *ambient = (uint16_t)((hi << 8) | lo);
    return 0;
}

int read_error(int fd, uint8_t *error) {
    return i2c_read_reg8(fd, REG_ERROR, error);
}

void log_data(uint16_t distance, uint16_t ambient, uint8_t error) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Distance: %u mm, Ambient: %u, Error: 0x%02X\n", ts, distance, ambient, error);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OPT3101_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", OPT3101_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("OPT3101 sensor initialized on %s (addr 0x%02X).\n", I2C_BUS, OPT3101_ADDR);

    while (running) {
        uint16_t distance = 0, ambient = 0;
        uint8_t error = 0;

        if (read_distance(i2c_fd, &distance) < 0) {
            fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        } else if (read_ambient(i2c_fd, &ambient) < 0) {
            fprintf(stderr, "Error reading ambient light: %s\n", strerror(errno));
        } else if (read_error(i2c_fd, &error) < 0) {
            fprintf(stderr, "Error reading error register: %s\n", strerror(errno));
        } else {
            log_data(distance, ambient, error);
        }

        usleep(500000);
    }

    printf("\nShutting down gracefully...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

