/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring (BCM numbering):
 *   GPIO 17 (pin 11) -> HC-SR04 TRIG (output)
 *   GPIO 18 (pin 12) -> HC-SR04 ECHO (input) via 1 kΩ resistor
 *
 * NOTE: The HC-SR04 operates at 5 V; the Raspberry Pi GPIO is only
 * 3.3 V tolerant.  A 1 kΩ resistor on the echo line protects the Pi.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define ECHO_RISE_TIMEOUT_US 200000  /* 200 ms max wait for echo rise  */
#define ECHO_FALL_TIMEOUT_US 200000  /* 200 ms max wait for echo fall  */
#define SAMPLE_PERIOD_S   1          /* 1 second between readings      */
#define MAX_VALID_DISTANCE_CM 400.0  /* HC-SR04 rated max range         */
#define MIN_VALID_DISTANCE_CM 2.0   /* HC-SR04 rated min range         */
#define SPEED_OF_SOUND_CM_PER_US 0.0343  /* 343 m/s in cm/µs            */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Trigger the HC-SR04: 10 µs high pulse on TRIGGER_PIN                 */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);          /* 10 µs pulse                  */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Measure the echo pulse width in microseconds                        */
/* Returns:  pulse width in µs, or -1 on timeout/error                 */
/* ------------------------------------------------------------------ */
static long measure_echo_pulse(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + ECHO_RISE_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1;
        }
        gpioDelay(20);  /* poll every 20 µs */
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + ECHO_FALL_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1;
        }
        gpioDelay(20);
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/* ------------------------------------------------------------------ */
/* Convert pulse width (µs) to distance (cm)                           */
/* ------------------------------------------------------------------ */
static double calculate_distance_cm(long pulse_us)
{
    if (pulse_us <= 0) {
        return -1.0;
    }
    return (pulse_us * SPEED_OF_SOUND_CM_PER_US) / 2.0;
}

/* ------------------------------------------------------------------ */
/* Log a distance reading with timestamp                               */
/* ------------------------------------------------------------------ */
static void log_distance(double distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (distance_cm < 0.0) {
        printf("[%s] Distance: ERROR (invalid reading)\n", timestamp);
    } else if (distance_cm < MIN_VALID_DISTANCE_CM ||
               distance_cm > MAX_VALID_DISTANCE_CM) {
        printf("[%s] Distance: %.2f cm (out of valid range)\n",
               timestamp, distance_cm);
    } else {
        printf("[%s] Distance: %.2f cm\n", timestamp, distance_cm);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure trigger pin is low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, echo pin as input */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance sensor reader started.\n");
    printf("Trigger: GPIO %d | Echo: GPIO %d | Sample: %d s\n",
           TRIGGER_PIN, ECHO_PIN, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main sampling loop */
    while (g_running) {
        trigger_sensor();
        long pulse_us = measure_echo_pulse();
        double distance_cm = calculate_distance_cm(pulse_us);
        log_distance(distance_cm);
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

