#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <pigpio.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0f
#define NUM_RANGE_BINS 64
#define RANGE_PROFILE_SIZE (NUM_RANGE_BINS * 2)
#define MAGIC_WORD_SIZE 8
#define READ_TIMEOUT_SEC 1
#define ALERT_DURATION_SEC 2
#define LOG_FILE "intrusion_log.csv"

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *port, speed_t baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10; /* 1 second timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);

        struct timeval tv = { .tv_sec = READ_TIMEOUT_SEC, .tv_usec = 0 };
        int ret = select(fd + 1, &rfds, NULL, NULL, &tv);

        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            return -1;
        }
        if (ret == 0) {
            fprintf(stderr, "Timeout reading %zu bytes\n", len - total);
            return -1;
        }

        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "read() error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART closed unexpectedly\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int read_range_profile(int fd, uint16_t *profile) {
    uint8_t magic[MAGIC_WORD_SIZE];
    if (read_exact(fd, magic, MAGIC_WORD_SIZE) != 0) {
        return -1;
    }

    for (int i = 0; i < MAGIC_WORD_SIZE; i++) {
        if (magic[i] != (uint8_t)0xAA) {
            fprintf(stderr, "Invalid magic word: 0x%02X\n", magic[i]);
            return -1;
        }
    }

    uint8_t raw[RANGE_PROFILE_SIZE];
    if (read_exact(fd, raw, RANGE_PROFILE_SIZE) != 0) {
        return -1;
    }

    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        profile[i] = (uint16_t)(raw[2 * i] | (raw[2 * i + 1] << 8));
    }
    return 0;
}

static int detect_intrusion(const uint16_t *profile, float *distance) {
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        float dist = (float)profile[i] * 0.1f;
        if (dist < DISTANCE_THRESHOLD) {
            *distance = dist;
            return 1;
        }
    }
    return 0;
}

static int log_intrusion(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r() error\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void trigger_alert(int gpio_pin, int duration_sec) {
    if (gpioWrite(gpio_pin, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d high\n", gpio_pin);
        return;
    }
    gpioDelay(duration_sec * 1000000);
    if (gpioWrite(gpio_pin, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d low\n", gpio_pin);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction() error: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_PORT, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t profile[NUM_RANGE_BINS];
        float distance = 0.0f;

        if (read_range_profile(uart_fd, profile) != 0) {
            fprintf(stderr, "Error reading range profile, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (detect_intrusion(profile, &distance)) {
            printf("Intrusion detected! Distance: %.2f m\n", distance);
            if (log_intrusion(distance) != 0) {
                fprintf(stderr, "Failed to log intrusion\n");
            }
            trigger_alert(GPIO_LED, ALERT_DURATION_SEC);
        }
    }

    printf("\nShutting down...\n");
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
    return 0;
}

