    if (buzzer_line == NULL) {
        fprintf(stderr, "Failed to get buzzer line %d: %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "e18-d80nk") < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
