/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 ultrasonic distance monitor
 *
 * Wiring:
 *   ICU-20201 SDA  -> GPIO 2  (I2C bus 1 SDA, physical pin 3)
 *   ICU-20201 SCL  -> GPIO 3  (I2C bus 1 SCL, physical pin 5)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *   Alert LED / buzzer -> GPIO 17 (BCM 17, physical pin 11) via suitable driver
 *
 * Behaviour:
 *   - Polls the sensor every 100 ms.
 *   - Logs each distance reading with an ISO-8601 timestamp to distance_log.txt.
 *   - Asserts GPIO 17 when the measured distance falls below 10.0 cm.
 *   - Handles I2C errors, sensor-absence, and file I/O errors.
 *   - Cleans up all resources on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ICU20201_ADDR        0x50          /* ICU-20201 default I2C address */
#define GPIO_ALERT           17            /* BCM 17 – alert output */
#define DISTANCE_THRESHOLD   10.0f         /* cm */
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define LOG_FILE             "distance_log.txt"

/*
 * ICU-20201 register map (representative – adjust to your exact part variant).
 * The ICU-20201 is a 16-bit register-addressed device; each write has a 2-byte
 * address payload followed by the data payload, and each read has a 2-byte
 * address payload followed by the data payload.
 */
#define REG_DEVICE_ID        0x00
#define REG_DISTANCE         0x01
#define REG_CONFIG           0x02
#define EXPECTED_DEVICE_ID   0x2020

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static int      g_gpio_alert = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_distance(float *distance_cm);
static void log_distance(float distance_cm);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers -------------------------------- */
static int i2c_write_reg16(uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);
    buf[2] = (char)((value >> 8) & 0xFF);
    return i2cWriteDevice(g_i2c_handle, buf, 3);
}

static int i2c_read_reg16(uint8_t reg, uint16_t *value)
{
    char addr[2];
    char data[2];
    int  rc;

    addr[0] = (char)reg;
    addr[1] = 0x00;                       /* dummy byte to clock out data */

    rc = i2cWriteDevice(g_i2c_handle, addr, 2);
    if (rc < 0)
        return rc;

    rc = i2cReadDevice(g_i2c_handle, data, 2);
    if (rc < 0)
        return rc;

    *value = (uint16_t)((uint8_t)data[0] | ((uint8_t)data[1] << 8));
    return 0;
}

/* ----------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, ICU20201_ADDR, strerror(errno));
        return -1;
    }

    /* Verify device identity */
    uint16_t dev_id = 0;
    if (i2c_read_reg16(REG_DEVICE_ID, &dev_id) < 0) {
        fprintf(stderr, "Error reading DEVICE_ID register: %s\n", strerror(errno));
        return -1;
    }
    if (dev_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected DEVICE_ID: 0x%04X (expected 0x%04X) – "
                        "sensor not present or wrong part\n",
                dev_id, EXPECTED_DEVICE_ID);
        return -1;
    }

    /* Put sensor into measurement mode (example configuration) */
    if (i2c_write_reg16(REG_CONFIG, 0x0001) < 0) {
        fprintf(stderr, "Error writing CONFIG register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ----------------------------- GPIO init ---------------------------------- */
static int init_gpio(void)
{
    if (gpioSetMode(GPIO_ALERT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n",
                GPIO_ALERT, strerror(errno));
        return -1;
    }
    if (gpioWrite(GPIO_ALERT, 0) < 0) {
        fprintf(stderr, "Error clearing GPIO %d: %s\n", GPIO_ALERT, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- Distance read ------------------------------ */
static int read_distance(float *distance_cm)
{
    uint16_t raw = 0;
    int      rc;

    rc = i2c_read_reg16(REG_DISTANCE, &raw);
    if (rc < 0) {
        fprintf(stderr, "Error reading distance register: %s\n", strerror(errno));
        return -1;
    }

    /* Convert raw 16-bit value to cm – adjust per datasheet scaling factor */
    *distance_cm = (float)raw * 0.1f;
    return 0;
}

/* ----------------------------- Logging ------------------------------------ */
static void log_distance(float distance_cm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", ts, distance_cm);
    fclose(fp);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_gpio_alert >= 0) {
        gpioWrite(g_gpio_alert, 0);
        gpioSetMode(g_gpio_alert, PI_INPUT);
        g_gpio_alert = -1;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance;

        if (read_distance(&distance) < 0) {
            /* I2C error – ensure alert is off and back off briefly */
            gpioWrite(GPIO_ALERT, 0);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        log_distance(distance);

        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(GPIO_ALERT, 1);
        } else {
            gpioWrite(GPIO_ALERT, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

