    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance;

        if (read_distance(&distance) < 0) {
            /* I2C error – ensure alert is off and back off briefly */
            gpioWrite(GPIO_ALERT, 0);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        log_distance(distance);

        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(GPIO_ALERT, 1);
        } else {
            gpioWrite(GPIO_ALERT, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
