#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define LOG_FILE "distance_log.csv"
#define POLL_DELAY_US 100000
#define MAX_DISTANCE_MM 4000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_exists(const char *path) {
    return (access(path, F_OK) == 0);
}

static int log_data(FILE *fp, int distance_mm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void parking_assistance(int distance_mm) {
    if (distance_mm < 300) {
        printf("Distance: %d mm - STOP\n", distance_mm);
    } else if (distance_mm < 600) {
        printf("Distance: %d mm - APPROACH\n", distance_mm);
    } else if (distance_mm < 1200) {
        printf("Distance: %d mm - SLOW\n", distance_mm);
    } else {
        printf("Distance: %d mm - CLEAR\n", distance_mm);
    }
}

static int read_distance(int handle, int *distance_mm) {
    char reg = 0x00;
    char data[2];
    int rc;

    rc = i2cWriteDevice(handle, &reg, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg select): %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(1000);

    rc = i2cReadDevice(handle, data, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    if (rc != 2) {
        fprintf(stderr, "I2C read short read: got %d bytes, expected 2\n", rc);
        return -1;
    }

    *distance_mm = ((data[0] << 8) | data[1]) & 0x3FFF;
    return 0;
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    int distance_mm;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    int file_exists_flag = file_exists(LOG_FILE);
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    if (!file_exists_flag) {
        if (fprintf(g_log_file, "timestamp,distance_mm\n") < 0) {
            fprintf(stderr, "Failed to write header: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        if (fflush(g_log_file) != 0) {
            fprintf(stderr, "Failed to flush header: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_distance(g_i2c_handle, &distance_mm) == 0) {
            if (distance_mm > MAX_DISTANCE_MM) {
                fprintf(stderr, "Distance out of range: %d mm\n", distance_mm);
            } else {
                if (log_data(g_log_file, distance_mm) != 0) {
                    fprintf(stderr, "Logging failed, continuing...\n");
                }
                parking_assistance(distance_mm);
            }
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

