#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50
#define LED_PIN        18
#define RETRY_COUNT    3
#define RETRY_DELAY_US 10000
#define LOOP_DELAY_US  100000
#define MIN_FREQ_HZ    1.0f
#define MAX_FREQ_HZ    10.0f
#define MIN_DIST_MM    50.0f
#define MAX_DIST_MM    200.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_retry(int handle, const char *buf, int count)
{
    for (int i = 0; i < RETRY_COUNT; i++) {
        int rc = i2cWriteDevice(handle, (char *)buf, count);
        if (rc == count)
            return 0;
        if (rc < 0)
            fprintf(stderr, "I2C write error (attempt %d): %d\n", i + 1, rc);
        else
            fprintf(stderr, "I2C write short write (attempt %d): %d/%d\n", i + 1, rc, count);
        if (i < RETRY_COUNT - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_retry(int handle, char *buf, int count)
{
    for (int i = 0; i < RETRY_COUNT; i++) {
        int rc = i2cReadDevice(handle, buf, count);
        if (rc == count)
            return 0;
        if (rc < 0)
            fprintf(stderr, "I2C read error (attempt %d): %d\n", i + 1, rc);
        else
            fprintf(stderr, "I2C read short read (attempt %d): %d/%d\n", i + 1, rc, count);
        if (i < RETRY_COUNT - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int read_distance_mm(int handle, float *distance_mm)
{
    char cmd[2] = {0x01, 0x00};
    char data[2];

    if (i2c_write_retry(handle, cmd, 2) != 0)
        return -1;

    gpioDelay(5000);

    if (i2c_read_retry(handle, data, 2) != 0)
        return -1;

    uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    *distance_mm = (float)raw * 0.1f;
    return 0;
}

static float distance_to_frequency(float distance_mm)
{
    if (distance_mm < MIN_DIST_MM)
        distance_mm = MIN_DIST_MM;
    if (distance_mm > MAX_DIST_MM)
        distance_mm = MAX_DIST_MM;
    return MAX_FREQ_HZ - ((distance_mm - MIN_DIST_MM) / (MAX_DIST_MM - MIN_DIST_MM)) * (MAX_FREQ_HZ - MIN_FREQ_HZ);
}

static void log_data(float distance_mm, float frequency_hz)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Distance: %.2f mm, LED Frequency: %.2f Hz\n", timestamp, distance_mm, frequency_hz);
    fflush(stdout);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    bool led_on = false;
    uint32_t next_edge_tick = gpioTick();

    while (g_running) {
        float distance_mm;
        if (read_distance_mm(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Failed to read distance after retries\n");
            distance_mm = -1.0f;
        }

        float frequency_hz = distance_to_frequency(distance_mm);
        uint32_t half_period_us = (uint32_t)(500000.0f / frequency_hz);

        if (half_period_us < 1000)
            half_period_us = 1000;

        uint32_t now = gpioTick();
        if (now >= next_edge_tick) {
            led_on = !led_on;
            gpioWrite(LED_PIN, led_on ? 1 : 0);
            next_edge_tick += half_period_us;
        }

        if (distance_mm >= 0.0f)
            log_data(distance_mm, frequency_hz);

        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

