#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 10000
#define LOG_FILE_NAME "proximity_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        return -1;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_1_GPIO);
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_2_GPIO);
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return 1;
    }

    int prev_state_1 = gpioRead(SENSOR_1_GPIO);
    int prev_state_2 = gpioRead(SENSOR_2_GPIO);

    if (prev_state_1 < 0 || prev_state_2 < 0) {
        fprintf(stderr, "Initial gpioRead failed\n");
        cleanup();
        return 1;
    }

    while (running) {
        int current_state_1 = gpioRead(SENSOR_1_GPIO);
        int current_state_2 = gpioRead(SENSOR_2_GPIO);

        if (current_state_1 < 0 || current_state_2 < 0) {
            fprintf(stderr, "gpioRead failed during polling\n");
            break;
        }

        if (current_state_1 != prev_state_1) {
            if (log_event(1, current_state_1 == 0 ? "DETECTED" : "CLEARED") != 0) {
                fprintf(stderr, "Failed to log event for sensor 1\n");
            }
            prev_state_1 = current_state_1;
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        if (current_state_2 != prev_state_2) {
            if (log_event(2, current_state_2 == 0 ? "DETECTED" : "CLEARED") != 0) {
                fprintf(stderr, "Failed to log event for sensor 2\n");
            }
            prev_state_2 = current_state_2;
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

