#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* VL53L4CX I2C address (ADDR pin tied to GND) */
#define VL53L4CX_ADDR 0x29

/* VL53L4CX register addresses */
#define VL53L4CX_REG_SOFT_RESET              0x0000
#define VL53L4CX_REG_SYSTEM_MODE_START       0x0001
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L4CX_REG_SYSTEM_INTERRUPT_STATUS 0x0088
#define VL53L4CX_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L4CX_REG_RESULT_DISTANCE         0x0096

/* Expected range status value indicating a valid measurement */
#define VL53L4CX_RANGE_STATUS_OK 0x00

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write16(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write16 to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "I2C write (reg select) for 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L4CX driver                                                     */
/* ------------------------------------------------------------------ */
static int vl53l4cx_init(int fd)
{
    /* 1. Soft reset */
    if (i2c_write16(fd, VL53L4CX_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    usleep(1000);

    if (i2c_write16(fd, VL53L4CX_REG_SOFT_RESET, 0x01) < 0)
        return -1;
    usleep(1000);

    /* 2. Start ranging (bit 0 = mode_start) */
    if (i2c_write16(fd, VL53L4CX_REG_SYSTEM_MODE_START, 0x01) < 0)
        return -1;
    usleep(1000);

    return 0;
}

static int vl53l4cx_read_distance(int fd, uint8_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist = 0;

    /* Poll interrupt status register */
    if (i2c_read16(fd, VL53L4CX_REG_SYSTEM_INTERRUPT_STATUS, &status, 1) < 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* No new data ready yet — skip this cycle */
        return 1;
    }

    /* Read distance */
    if (i2c_read16(fd, VL53L4CX_REG_RESULT_DISTANCE, &dist, 1) < 0)
        return -1;

    /* Read range status */
    if (i2c_read16(fd, VL53L4CX_REG_RESULT_RANGE_STATUS, &status, 1) < 0)
        return -1;

    if (status != VL53L4CX_RANGE_STATUS_OK) {
        fprintf(stderr, "VL53L4CX range status error: 0x%02X\n", status);
        return -1;
    }

    /* Clear interrupt so the next measurement can signal */
    if (i2c_write16(fd, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L4CX_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                VL53L4CX_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l4cx_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L4CX initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("VL53L4CX initialized. Reading distance every 500 ms...\n");

    while (g_running) {
        uint8_t distance = 0;
        int rc = vl53l4cx_read_distance(g_i2c_fd, &distance);

        if (rc == 0) {
            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d.%06ld, Distance: %u mm\n",
                       ts.tv_sec / 31536000,
                       (ts.tv_sec % 31536000) / 2592000,
                       (ts.tv_sec % 2592000) / 86400,
                       (ts.tv_sec % 86400) / 3600,
                       (ts.tv_sec % 3600) / 60,
                       ts.tv_sec % 60,
                       ts.tv_nsec / 1000,
                       distance);
            } else {
                fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            }
        } else if (rc < 0) {
            /* Transient I2C error — log and continue */
            fprintf(stderr, "I2C communication error during read.\n");
        }
        /* rc == 1: no new data, silently skip */

        usleep(500000);
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0) {
        /* Put sensor in standby mode */
        (void)i2c_write16(g_i2c_fd, VL53L4CX_REG_SYSTEM_MODE_START, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

