#include <pigpio.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define POLL_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write error (reg 0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *value) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read error (reg 0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int fd) {
    if (i2c_write_reg8(fd, 0x88, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x80, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x00, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x91, 0x3C) < 0) return -1;
    if (i2c_write_reg8(fd, 0x00, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFF, 0x00) < 0) return -1;
