#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define MIN_ANGLE_DEG   -90
#define MAX_ANGLE_DEG    90

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   50000
#define LOOP_DELAY_US     200000
#define LOG_FILE          "sensor_data.log"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int distance_to_angle(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float frac = (distance - MIN_DISTANCE_CM) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return (int)(MIN_ANGLE_DEG + frac * (MAX_ANGLE_DEG - MIN_ANGLE_DEG));
}

static int read_distance(float *distance_out)
{
    if (distance_out == NULL) return -1;

    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    gpioDelay(2);

    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;

    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) return -1;
    }
    uint32_t echo_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) return -1;
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    *distance_out = (float)pulse_us / 58.0f;
    return 0;
}

static int log_data(float distance, int angle)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Angle: %d deg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance, angle);

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = 0.0f;

        if (read_distance(&distance) != 0) {
            fprintf(stderr, "Sensor timeout or error, skipping reading.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle = distance_to_angle(distance);

        if (gpioServo(SERVO_PIN, angle) < 0) {
            fprintf(stderr, "gpioServo failed for pin %d\n", SERVO_PIN);
        }

        if (log_data(distance, angle) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Parking assist system stopped.\n");
    return EXIT_SUCCESS;
}

