#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM          2.0
#define MAX_DISTANCE_CM          400.0
#define DISTANCE_THRESHOLD_CM    30.0
#define ECHO_TIMEOUT_US          30000
#define SAMPLE_PERIOD_US         100000

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_start_tick = 0;
static volatile uint32_t     g_end_tick   = 0;
static volatile int          g_echo_seen  = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_seen  = 0;
    } else if (level == 0) {
        g_end_tick   = tick;
        g_echo_seen  = 1;
    }
}

static double calculate_distance_cm(uint32_t start, uint32_t end)
{
    uint32_t diff = end - start; /* pigpio ticks are uint32_t; subtraction wraps correctly */
    return (diff * SPEED_OF_SOUND_CM_PER_US) / 2.0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin LOW.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise buzzer pin LOW.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register echo interrupt on pin %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler.\n");
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        g_echo_seen = 0;
        g_start_tick = 0;
        g_end_tick   = 0;

        trigger_sensor();

        uint32_t elapsed = 0;
        while (g_running && !g_echo_seen && elapsed < ECHO_TIMEOUT_US) {
            gpioDelay(100);
            elapsed += 100;
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            printf("Warning: no echo received (sensor absent or out of range).\n");
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double distance = calculate_distance_cm(g_start_tick, g_end_tick);

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            printf("Warning: distance out of range: %.2f cm\n", distance);
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);

        if (distance < DISTANCE_THRESHOLD_CM) {
            gpioWrite(BUZZER_PIN, 1);
        } else {
            gpioWrite(BUZZER_PIN, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

