/*
 * Gate controller for Raspberry Pi Zero W
 * Sensor : VL53L1X time-of-flight (I2C bus 1, address 0x29)
 * Servo  : SG90 on GPIO18 (BCM) via hardware PWM
 * Log    : gate_log.txt
 *
 * Build  : gcc -O2 -Wall -o gate gate.c -lpigpio -lrt
 * Run    : sudo ./gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define SERVO_PIN      18
#define DIST_THRESHOLD 20          /* cm */
#define SERVO_OPEN     1500        /* us */
#define SERVO_CLOSE    1000        /* us */
#define LOG_FILE       "gate_log.txt"
#define POLL_DELAY_US  100000      /* 100 ms */
#define MAX_RETRIES    3

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_SOFT_RESET              0x0003
#define VL53L1X_VHV_CONFIG_TIMEOUT_MACROP_LOOP_BOUND 0x0008
#define VL53L1X_SYSTEM_MODE_START_STOP  0x0007
#define VL53L1X_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c = -1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(g_log, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* VL53L1X helpers                                                    */
/* ------------------------------------------------------------------ */
static int vl53l1x_write16(int h, uint16_t reg, uint8_t val)
{
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)val };
    return i2cWriteDevice(h, buf, 3);
}

static int vl53l1x_read16(int h, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(h, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(h, (char *)buf, len);
}

static int vl53l1x_init(int h)
{
    uint8_t id;
    if (vl53l1x_read16(h, 0x010F, &id, 1) < 0) {
        fprintf(stderr, "VL53L1X: cannot read model ID\n");
        return -1;
    }
    if (id != 0xEA) {
        fprintf(stderr, "VL53L1X: unexpected model ID 0x%02X (expected 0xEA)\n", id);
        return -1;
    }

    /* Software reset */
    if (vl53l1x_write16(h, VL53L1X_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);                       /* 1 ms */
    if (vl53l1x_write16(h, VL53L1X_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);                      /* 10 ms */

    /* Wait for boot completion (poll bit 0 of 0x0089) */
    for (int i = 0; i < 50; i++) {
        uint8_t status;
        if (vl53l1x_read16(h, VL53L1X_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
        if (status & 0x01) break;
        gpioDelay(2000);                  /* 2 ms */
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "VL53L1X: boot timeout\n");
        return -1;
    }

    /* Start ranging */
    if (vl53l1x_write16(h, VL53L1X_SYSTEM_MODE_START_STOP, 0x40) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int vl53l1x_read_distance(int h, uint16_t *distance_mm)
{
    uint8_t status;
    if (vl53l1x_read16(h, VL53L1X_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
    if (!(status & 0x01)) return -1;       /* not ready */

    uint8_t data[2];
    if (vl53l1x_read16(h, VL53L1X_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) < 0)
        return -1;

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Servo control                                                      */
/* ------------------------------------------------------------------ */
static void servo_set(int pin, int pulse_us)
{
    if (pulse_us < 500) pulse_us = 500;
    if (pulse_us > 2500) pulse_us = 2500;
    gpioServo(pin, pulse_us);
}

static void gate_open(void)
{
    log_event("Gate opening");
    servo_set(SERVO_PIN, SERVO_OPEN);
    gpioDelay(2000000);                   /* 2 s */
}

static void gate_close(void)
{
    log_event("Gate closing");
    servo_set(SERVO_PIN, SERVO_CLOSE);
    gpioDelay(2000000);
}

/* ------------------------------------------------------------------ */
/* Remote control (simulated driver v2 callback API)                  */
/* ------------------------------------------------------------------ */
typedef enum { CMD_OPEN, CMD_CLOSE, CMD_STATUS } cmd_t;

typedef struct {
    cmd_t cmd;
    int   distance;
} remote_cmd_t;

static void remote_callback(remote_cmd_t *cmd)
{
    (void)cmd;
    /* In a real driver this would be invoked by the driver thread */
}

static void process_remote(remote_cmd_t *cmd)
{
    switch (cmd->cmd) {
    case CMD_OPEN:
        log_event("Remote: open");
        gate_open();
        break;
    case CMD_CLOSE:
        log_event("Remote: close");
        gate_close();
        break;
    case CMD_STATUS:
        log_event("Remote: status request");
        break;
    }
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c < 0) {
        fprintf(stderr, "I2C open failed (addr 0x%02X): %d\n", VL53L1X_ADDR, g_i2c);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (vl53l1x_init(g_i2c) < 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        i2cClose(g_i2c);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Servo init --- */
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    servo_set(SERVO_PIN, SERVO_CLOSE);

    /* --- Log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open log file %s\n", LOG_FILE);
        i2cClose(g_i2c);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_event("Gate controller started");

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Main loop --- */
    int gate_opened = 0;
    int consecutive_errors = 0;

    while (g_running) {
        uint16_t dist_mm;
        int rc = vl53l1x_read_distance(g_i2c, &dist_mm);
        if (rc == 0) {
            consecutive_errors = 0;
            int dist_cm = dist_mm / 10;
            printf("Distance: %d cm\n", dist_cm);

            if (dist_cm < DIST_THRESHOLD && !gate_opened) {
                gate_open();
                gate_opened = 1;
            } else if (dist_cm >= DIST_THRESHOLD && gate_opened) {
                gate_close();
                gate_opened = 0;
            }

            /* Simulated remote commands */
            static int phase = 0;
            phase = (phase + 1) % 10;
            if (phase == 0) {
                remote_cmd_t cmd = { CMD_STATUS, 0 };
                process_remote(&cmd);
            }
            if (phase == 5) {
                remote_cmd_t cmd = { CMD_OPEN, 0 };
                process_remote(&cmd);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "I2C read error (%d)\n", consecutive_errors);
            log_event("I2C read error");
            if (consecutive_errors >= MAX_RETRIES) {
                log_event("Max retries reached, attempting sensor reinit");
                vl53l1x_init(g_i2c);
                consecutive_errors = 0;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    log_event("Gate controller stopping");
    servo_set(SERVO_PIN, SERVO_CLOSE);
    gpioDelay(500000);
    if (g_i2c >= 0) i2cClose(g_i2c);
    if (g_log) fclose(g_log);
    gpioTerminate();
    return EXIT_SUCCESS;
}

