#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIG_PIN      23
#define ECHO_PIN      24

#define SPEED_OF_SOUND_CM_PER_S  34300.0
#define MIN_PULSE_US             100
#define MAX_PULSE_US             30000
#define ECHO_TIMEOUT_US          60000
#define TRIGGER_INTERVAL_US      200000
#define TRIGGER_PULSE_US         10

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
