    get_timestamp(ts, sizeof(ts));

    if (g_log_file) {
        fprintf(g_log_file, "%s %s\n", ts, msg);
        fflush(g_log_file);
    }
    printf("%s %s\n", ts, msg);
}

static void log_distance(float distance_cm)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

