}

/* ------------------------------------------------------------------ */
/* Echo edge callback (runs in libgpiod's event thread)                */
/* ------------------------------------------------------------------ */
static struct gpiod_edge_event_buffer g_edge_buf;

static void echo_callback(struct gpiod_line *line,
                          struct gpiod_edge_event *event)
{
    (void)line;

    struct gpiod_edge_event_buffer *buf = &g_edge_buf;
    int ret = gpiod_edge_event_buffer_add(buf, event);
    if (ret < 0) {
        /* Buffer full — drop oldest event */
        gpiod_edge_event_buffer_pop(buf, NULL);
        ret = gpiod_edge_event_buffer_add(buf, event);
        if (ret < 0) {
            /* Still full — drop silently */
            return;
        }
