    while (true) {
        struct gpiod_edge_event *ev;
        ret = gpiod_edge_event_buffer_get(buf, &ev);
        if (ret < 0) {
            /* No more events */
            break;
        }
        if (ret == 0) {
            /* Buffer empty */
            break;
        }

        uint32_t tick = gpiod_edge_event_get_tick(ev);
        int val = gpiod_edge_event_get_value(ev);

        static uint32_t rising_tick = 0;
        static bool have_rising = false;
        static uint32_t last_falling_tick = 0;

        if (val == 1) {
            /* Rising edge — start of echo pulse */
            rising_tick = tick;
            have_rising = true;
            last_falling_tick = 0;
        } else if (val == 0 && have_rising) {
            /* Falling edge — end of echo pulse */
            uint32_t duration = tick - rising_tick; /* handles 32-bit wrap */

            if (duration < MIN_PULSE_US) {
                char msg[128];
                snprintf(msg, sizeof(msg),
                         "Warning: pulse too short (%u us) — noise", duration);
                log_message(msg);
            } else if (duration > MAX_PULSE_US) {
                char msg[128];
                snprintf(msg, sizeof(msg),
                         "Warning: pulse too long (%u us) — timeout/no object", duration);
