                float distance = (duration * SPEED_OF_SOUND_CM_PER_S) / 2000000.0;
                log_distance(distance);
            }

            have_rising = false;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Trigger helper                                                      */
/* ------------------------------------------------------------------ */
static void trigger_pulse(struct gpiod_line *trig)
{
    if (gpiod_line_set_value(trig, 1) < 0) {
        log_message("Error: failed to set TRIG high");
        return;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        log_message("Error: failed to set TRIG low");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

