        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        goto cleanup;
    }

    /* Get lines */
    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(TRIG)");
        goto cleanup;
    }
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(ECHO)");
        goto cleanup;
    }

    /* Request TRIG as output, initial value LOW */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(TRIG)");
        goto cleanup;
    }

    /* Request ECHO as input with pull-down */
    if (gpiod_line_request_input_flags(echo, "hcsr04-echo",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_input(ECHO)");
        goto cleanup;
    }

    /* Initialize edge event buffer */
    if (gpiod_edge_event_buffer_init(&g_edge_buf, 16) < 0) {
        perror("gpiod_edge_event_buffer_init");
        goto cleanup;
    }

    /* Register echo callback for both edges */
    if (gpiod_line_request_falling_edge_events(echo, "hcsr04-echo-falling") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto cleanup;
    }
    if (gpiod_line_request_both_edges_events(echo, "hcsr04-echo-both") < 0) {
        perror("gpiod_line_request_both_edges_events");
        goto cleanup;
    }

    log_message("HC-SR04 distance measurement started.");

    /* Main loop */
    while (g_running) {
        trigger_pulse(trig);

        /* Wait for echo with timeout */
        uint32_t start = gpiod_edge_event_buffer_get_tick(&g_edge_buf);
        int have_event = 0;
        while (g_running && !have_event) {
            struct gpiod_edge_event *ev;
            int got = gpiod_edge_event_buffer_get(&g_edge_buf, &ev);
            if (got > 0) {
                have_event = 1;
            } else if (got < 0) {
                /* Error — should not happen with our buffer */
                break;
            } else {
                /* Buffer empty — check timeout */
                uint32_t now = gpiod_edge_event_buffer_get_tick(&g_edge_buf);
                uint32_t elapsed = now - start; /* wraps correctly */
                if (elapsed > ECHO_TIMEOUT_US) {
                    log_message("Warning: echo timeout — no object detected");
                    have_event = 1; /* break out of loop */
                }
            }
        }

        usleep(TRIGGER_INTERVAL_US);
    }

    log_message("HC-SR04 distance measurement stopped.");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (g_log_file) fclose(g_log_file);

    gpiod_edge_event_buffer_free(&g_edge_buf);

    return ret;
}

