    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, VL53L1X_ADDR, i2c_handle);
        return -1;
    }

    VL53L1X_Dev_t dev;
    VL53L1X_Results_t results;
    VL53L1X_Error status;

    status = VL53L1X_Initialize(&dev, &results);
    if (status != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "VL53L1X init failed: %d\n", status);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    status = VL53L1X_SoftReset(&dev, &results);
    if (status != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "VL53L1X soft reset failed: %d\n", status);
        VL53L1X_DeInit(&dev);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    status = VL53L1X_SetDistanceMode(&dev, &results, VL53L1X_DISTANCE_MODE_LONG);
    if (status != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "VL53L1X set distance mode failed: %d\n", status);
        VL53L1X_DeInit(&dev);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    status = VL53L1X_SetInterMeasurementPeriod(&dev, &results, 0);
    if (status != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "VL53L1X set inter-measurement period failed: %d\n", status);
        VL53L1X_DeInit(&dev);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    status = VL53L1X_StartRanging(&dev, &results);
    if (status != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "VL53L1X start ranging failed: %d\n", status);
        VL53L1X_DeInit(&dev);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_distance(void) {
    VL53L1X_Results_t results;
    VL53L1X_Error status = VL53L1X_GetRangingMeasurementData(&results);
    if (status != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "VL53L1X read data failed: %d\n", status);
        return -1;
    }
    return results.distance_mm;
}

static void control_gate(int open) {
    if (open) {
        gpioWrite(GPIO_OPEN, 1);
        gpioWrite(GPIO_CLOSE, 0);
        log_event("Gate opened");
    } else {
        gpioWrite(GPIO_OPEN, 0);
        gpioWrite(GPIO_CLOSE, 1);
        log_event("Gate closed");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        VL53L1X_StopRanging(&dev, &results);
        VL53L1X_DeInit(&dev);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 1);
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    log_file = fopen("gate_events.log", "a");
    if (!log_file) {
        perror("fopen gate_events.log");
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO init failed\n");
        cleanup();
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor init failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int gate_open = 0;

    while (!terminate) {
        int dist = read_distance();
        if (dist < 0) {
            log_event("Sensor read error");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (dist <= DISTANCE_THRESHOLD_MM && !gate_open) {
            control_gate(1);
            gate_open = 1;
        } else if (dist > DISTANCE_THRESHOLD_MM && gate_open) {
            control_gate(0);
            gate_open = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

