#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin / bus definitions ---- */
#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define MOTOR_FORWARD  17
#define MOTOR_BACKWARD 18
#define TRIGGER_PIN    24

/* ---- Distance thresholds (mm) ---- */
#define DISTANCE_NEAR  100
#define DISTANCE_FAR   300

/* ---- VL53L1X register addresses ---- */
#define VL53L1X_SOFT_RESET              0x0003
#define VL53L1X_SYSTEM_MODE_START       0x0001
#define VL53L1X_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_RESULT_DISTANCE         0x0096

/* ---- Globals ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* ---- Prototypes ---- */
static int  vl53l1x_write16(int handle, uint16_t reg, uint8_t value);
static int  vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint8_t len);
static int  vl53l1x_read_distance(int handle, uint16_t *distance);
static void motor_forward(void);
static void motor_backward(void);
static void motor_stop(void);
static void trigger_callback(int gpio, int level, uint32_t tick, void *userdata);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- Low-level I2C helpers ---- */
static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint8_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ---- Distance measurement ---- */
static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t status = 0;
    uint8_t data[2] = {0, 0};
    int retries = 0;
    const int max_retries = 5;

    /* Trigger a single measurement */
    if (vl53l1x_write16(handle, VL53L1X_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start measurement\n");
        return -1;
    }

    /* Poll data-ready bit (bit 0 of RESULT_RANGE_STATUS) */
    while (retries < max_retries) {
        if (vl53l1x_read16(handle, VL53L1X_RESULT_RANGE_STATUS, &status, 1) < 0) {
            fprintf(stderr, "Error: I2C read failed (status), retry %d\n", retries + 1);
            retries++;
            gpioDelay(1000 << retries); /* exponential backoff */
            continue;
        }
        if (status & 0x01)
            break;
        gpioDelay(5000); /* 5 ms */
        retries++;
    }

    if (retries >= max_retries) {
        fprintf(stderr, "Error: sensor not ready after %d retries\n", max_retries);
        return -1;
    }

    /* Read 16-bit distance */
    if (vl53l1x_read16(handle, VL53L1X_RESULT_DISTANCE, data, 2) < 0) {
        fprintf(stderr, "Error: failed to read distance data\n");
        return -1;
    }

    *distance = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ---- Motor control ---- */
static void motor_forward(void)
{
    gpioWrite(MOTOR_FORWARD, 1);
    gpioWrite(MOTOR_BACKWARD, 0);
    printf("Motor: FORWARD\n");
}

static void motor_backward(void)
{
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 1);
    printf("Motor: BACKWARD\n");
}

static void motor_stop(void)
{
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 0);
    printf("Motor: STOP\n");
}

/* ---- ISR callback ---- */
static void trigger_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;

    if (level != 1) /* rising edge only */
        return;

    uint16_t distance = 0;
    if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
        printf("Distance: %u mm\n", distance);
        if (distance < DISTANCE_NEAR) {
            motor_forward();
        } else if (distance > DISTANCE_FAR) {
            motor_backward();
        } else {
            motor_stop();
        }
    } else {
        fprintf(stderr, "Error: failed to read distance, stopping motor\n");
        motor_stop();
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    motor_stop();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Soft reset sensor */
    if (vl53l1x_write16(i2c_handle, VL53L1X_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: soft reset failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(1000); /* 1 ms */

    /* Configure motor pins */
    gpioSetMode(MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT);
    motor_stop();

    /* Configure trigger pin */
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_DOWN);

    /* Register ISR on rising edge */
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO%d\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("VL53L1X distance monitor running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

