#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x5C
#define LED_GPIO_BASE  17
#define NUM_ELECTRODES 12
#define POLL_DELAY_US  50000

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG0     0x5E
#define MPR121_SOFTRESET      0x80
#define MPR121_ECR            0x5E
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_MHD_RISE       0x2B
#define MPR121_NHD_RISE       0x2C
#define MPR121_NCL_RISE       0x2D
#define MPR121_FDL_RISE       0x2E
#define MPR121_MHD_FALL       0x2F
#define MPR121_NHD_FALL       0x30
#define MPR121_NCL_FALL       0x31
#define MPR121_FDL_FALL       0x32
#define MPR121_NHD_DATA       0x33
#define MPR121_NCL_DATA       0x34
#define MPR121_FDL_DATA       0x35

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, MPR121_ECR, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read MPR121 ECR (sensor absent or bus error)\n");
        return -1;
    }
    if (part_id != 0x63) {
        fprintf(stderr, "Error: Unexpected MPR121 part ID 0x%02X (expected 0x63)\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg8(fd, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write ECR\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_MHD_RISE, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHD_RISE, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCL_RISE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDL_RISE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_MHD_FALL, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHD_FALL, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCL_FALL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDL_FALL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHD_DATA, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCL_DATA, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDL_DATA, 0x00) < 0) return -1;

    if (i2c_write_reg8(fd, MPR121_ELECONFIG0, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to write ELECONFIG0\n");
        return -1;
    }

    if (i2c_write_reg8(fd, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: Failed to write ECR to enable 12 electrodes\n");
        return -1;
    }
    gpioDelay(10000);

    return 0;
}

static int read_touch_status(int fd, uint16_t *status) {
    uint8_t lo = 0, hi = 0;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = ((uint16_t)hi << 8) | lo;
    return 0;
}

