}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, MPR121_ECR, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read MPR121 ECR (sensor absent or bus error)\n");
        return -1;
    }
    if (part_id != 0x63) {
        fprintf(stderr, "Error: Unexpected MPR121 part ID 0x%02X (expected 0x63)\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset\n");
        return -1;
    }
