static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int mpr121_init(void) {
    uint8_t device_id = 0;
    if (mpr121_read_reg(MPR121_SOFTRESET, &device_id) != 0) {
        return -1;
    }
    if (device_id != 0x63) {
        fprintf(stderr, "MPR121 device ID mismatch: expected 0x63, got 0x%02X\n", device_id);
        return -1;
    }

    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) != 0) return -1;
    gpioDelay(10000);

    if (mpr121_write_reg(MPR121_MHD_RISING, 0x01) != 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_RISING, 0x01) != 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_RISING, 0x00) != 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_RISING, 0x00) != 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_FALLING, 0x01) != 0) return -1;
