        return 1;
    }

    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) != 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (touch_status > 0) {
            gpioWrite(LED_GPIO, 1);
            log_proximity_event();
            gpioDelay(LED_ON_TIME_US);
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

