    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) != 0) return -1;
    if (mpr121_write_reg(MPR121_ECR, 0x8F) != 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *touch_status) {
    uint8_t lo = 0, hi = 0;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &lo) != 0) return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &hi) != 0) return -1;
    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void log_proximity_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s - Proximity detected\n", timestamp);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) != 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (touch_status > 0) {
            gpioWrite(LED_GPIO, 1);
            log_proximity_event();
            gpioDelay(LED_ON_TIME_US);
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

