#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define SPEED_OF_SOUND 34300.0   /* cm/s at 20 °C */
#define MIN_DISTANCE   2.0       /* cm */
#define MAX_DISTANCE   400.0     /* cm */
#define LOG_FILE       "distance_log.txt"

#define TRIGGER_PULSE_US  10
#define TRIGGER_SETTLE_US 5
#define ECHO_TIMEOUT_US   30000   /* 30 ms */
#define LOOP_DELAY_US     1000000 /* 1 s */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm.  Returns >= 0 on success, -1.0 on timeout
 * (echo never rose), -2.0 if the measured pulse width is out of range.
 */
static double measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_SETTLE_US);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout 30 ms) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout (sensor absent?)\n");
            return -1.0;
        }
        gpioDelay(10);
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout 30 ms) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
        gpioDelay(10);
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    double distance = (double)pulse_us * SPEED_OF_SOUND / 2000000.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance out of range: %.2f cm\n", distance);
        return -2.0;
    }
    return distance;
}

static void log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    if (distance < 0.0) {
        fprintf(g_log, "%s, ERROR: %s\n", timestamp,
                distance == -1.0 ? "timeout" : "out of range");
    } else {
        fprintf(g_log, "%s, %.2f\n", timestamp, distance);
    }
    fflush(g_log);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger is low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000); /* 100 ms settle */

    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error: Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();
        log_distance(distance);
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

