#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10
#define SAMPLE_PERIOD_US  1000000  /* 1 second */
#define MIN_PULSE_US      58       /* ~1 cm round trip */
#define MAX_PULSE_US      25000    /* ~4 m round trip */
#define MAX_VALID_US      30000    /* sanity cap */
#define LOG_FILE_NAME     "distance_log.txt"

/* Shared state between ISR and main thread */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_state = 0;   /* 0=idle, 1=rising seen, 2=falling seen */
static volatile int      g_new_sample  = 0;

static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* ISR callback — runs in pigpio thread context                         */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        g_start_tick = tick;
        g_echo_state = 1;
    } else if (level == 0 && g_echo_state == 1) {
        /* Falling edge: end of echo pulse */
        g_end_tick = tick;
        g_echo_state = 2;
        g_new_sample = 1;
    }
}

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe subset only                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 µs high pulse on the trigger pin                        */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped distance reading to the log file               */
/* ------------------------------------------------------------------ */
static void log_distance(float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, %.2f cm\n", timestamp, distance_cm);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call from any exit path                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable ISR first so no more callbacks fire */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);  /* let things settle */

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE_NAME);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: cannot install signal handlers.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register ISR on echo pin ---- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: cannot register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  Trigger: GPIO%d | Echo: GPIO%d (via 1k/2k divider)\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("  Logging to: %s\n", LOG_FILE_NAME);
    printf("  Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Reset state for this cycle */
        g_echo_state = 0;
        g_new_sample = 0;

        trigger_sensor();

        /* Wait up to ~1 s for the echo to arrive */
        uint32_t waited = 0;
        while (g_running && !g_new_sample && waited < SAMPLE_PERIOD_US) {
            gpioDelay(1000);
            waited += 1000;
        }

        if (!g_running) {
            break;
        }

        if (g_new_sample) {
            uint32_t pulse_us;
            if (g_end_tick >= g_start_tick) {
                pulse_us = g_end_tick - g_start_tick;
            } else {
                /* 32-bit tick wrap-around */
                pulse_us = (0xFFFFFFFFu - g_start_tick) + g_end_tick + 1u;
            }

            if (pulse_us >= MIN_PULSE_US && pulse_us <= MAX_VALID_US) {
                /* distance = (pulse_us * speed_of_sound) / 2
                 * speed_of_sound ≈ 343 m/s = 0.0343 cm/µs
                 */
                float distance_cm = (float)pulse_us * 0.0343f / 2.0f;
                log_distance(distance_cm);
            } else {
                fprintf(stderr, "Warning: invalid pulse width %u µs (out of range).\n",
                        pulse_us);
            }
        } else {
            fprintf(stderr, "Warning: no echo received within sample period.\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

