        /* Wait up to ~1 s for the echo to arrive */
        uint32_t waited = 0;
        while (g_running && !g_new_sample && waited < SAMPLE_PERIOD_US) {
            gpioDelay(1000);
            waited += 1000;
        }

        if (!g_running) {
            break;
        }

        if (g_new_sample) {
            uint32_t pulse_us;
            if (g_end_tick >= g_start_tick) {
                pulse_us = g_end_tick - g_start_tick;
            } else {
                /* 32-bit tick wrap-around */
                pulse_us = (0xFFFFFFFFu - g_start_tick) + g_end_tick + 1u;
            }

            if (pulse_us >= MIN_PULSE_US && pulse_us <= MAX_VALID_US) {
                /* distance = (pulse_us * speed_of_sound) / 2
                 * speed_of_sound ≈ 343 m/s = 0.0343 cm/µs
                 */
                float distance_cm = (float)pulse_us * 0.0343f / 2.0f;
                log_distance(distance_cm);
            } else {
                fprintf(stderr, "Warning: invalid pulse width %u µs (out of range).\n",
                        pulse_us);
            }
        } else {
            fprintf(stderr, "Warning: no echo received within sample period.\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

