#define XSHUT_PIN 27
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static VL53L1X_Dev_t *sensor = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

