        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(XSHUT_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set XSHUT pin mode");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(XSHUT_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to write XSHUT pin high");
        cleanup();
        return EXIT_FAILURE;
    }

