    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at bus %d addr 0x%02X: %d", I2C_BUS, VL53L1X_ADDR, i2c_handle);
        cleanup();
        return EXIT_FAILURE;
