#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_GATE 24
#define DISTANCE_THRESHOLD_CM 20
#define POLL_DELAY_US 100000
#define LOG_FILE "gate_log.txt"

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

/* Write a 16-bit register address + 1 byte of data */
static int vl53l1x_write8(uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(i2c_handle, buf, 3);
}

/* Read N bytes from a 16-bit register address */
static int vl53l1x_read_block(uint16_t reg, uint8_t *data, uint8_t len) {
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, addr, 2) != 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)data, len);
}

static int vl53l1x_init(void) {
    uint8_t id = 0;
    if (vl53l1x_read_block(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &id, 1) != 1) {
        log_message("Error: Failed to read VL53L1X model ID");
        return -1;
    }
    if (id != 0xEA) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Error: Unexpected model ID 0x%02X (expected 0xEA)", id);
        log_message(msg);
        return -1;
    }

    if (vl53l1x_write8(VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        log_message("Error: Failed to clear soft reset");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    if (vl53l1x_write8(VL53L1X_REG_SOFT_RESET, 0x01) != 0) {
        log_message("Error: Failed to set soft reset");
        return -1;
    }
    gpioDelay(1000);

    /* Start continuous ranging (bit 0 of SYSTEM_MODE_START) */
    if (vl53l1x_write8(VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) {
        log_message("Error: Failed to start ranging");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance_mm) {
    uint8_t status = 0;
    if (vl53l1x_read_block(VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 1) {
        log_message("Error: Failed to read range status");
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* No new data yet */
    }

    uint8_t dist_data[2] = {0};
    if (vl53l1x_read_block(VL53L1X_REG_RESULT_DISTANCE, dist_data, 2) != 2) {
        log_message("Error: Failed to read distance data");
        return -1;
    }

    *distance_mm = ((uint16_t)dist_data[0] << 8) | dist_data[1];
    return 0;
}

static void control_gate(int open) {
    gpioWrite(GPIO_GATE, open ? 1 : 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        log_message("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init() != 0) {
        log_message("Error: VL53L1X initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_GATE, PI_OUTPUT);
    control_gate(0); /* Start with gate closed */

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started.");

    while (!terminate) {
        uint16_t dist_mm = 0;
        int ret = vl53l1x_read_distance(&dist_mm);

        if (ret == 0) {
            int dist_cm = dist_mm / 10;
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %d cm", dist_cm);
            log_message(msg);

            int gate_open = (dist_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
            if (gate_open != gpioRead(GPIO_GATE)) {
                control_gate(gate_open);
                snprintf(msg, sizeof(msg), "Gate %s", gate_open ? "opened" : "closed");
                log_message(msg);
            }
        } else if (ret < 0) {
            log_message("Error: Failed to read distance");
        }

        gpioDelay(POLL_DELAY_US);
    }

    control_gate(0);
    cleanup();
    return EXIT_SUCCESS;
}

