#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define GPIO_LED       17
#define DIST_THRESHOLD 200
#define BUFFER_SIZE    10
#define POLL_DELAY_US  50000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0000
#define REG_VHV_CONFIG              0x0001
#define REG_PHASECAL_LIMIT          0x0008
#define REG_RANGE_CONFIG            0x0080
#define REG_SYSTEM_CONFIG           0x0081
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define REG_RESULT_INTERRUPT_STATUS 0x0089
#define REG_RESULT_RANGE_STATUS     0x0089
#define REG_RESULT_DISTANCE         0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by one byte of data. */
static int vl53l1x_write8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read N bytes from a 16-bit register address. */
static int vl53l1x_read(int handle, uint16_t reg, uint8_t *data, uint8_t len) {
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int vl53l1x_init(int handle) {
    uint8_t id;
    if (vl53l1x_read(handle, 0x010F, &id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read sensor ID\n");
        return -1;
    }
    if (id != 0xEA) {
        fprintf(stderr, "Error: Unexpected sensor ID 0x%02X (expected 0xEA)\n", id);
        return -1;
    }

    if (vl53l1x_write8(handle, REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (vl53l1x_write8(handle, REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(1000);

    if (vl53l1x_write8(handle, REG_VHV_CONFIG, 0x01) != 0) return -1;
    if (vl53l1x_write8(handle, REG_PHASECAL_LIMIT, 0x00) != 0) return -1;
    if (vl53l1x_write8(handle, REG_RANGE_CONFIG, 0x0A) != 0) return -1;
    if (vl53l1x_write8(handle, REG_SYSTEM_CONFIG, 0x01) != 0) return -1;

    if (vl53l1x_write8(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;
    if (vl53l1x_write8(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x00) != 0) return -1;

    return 0;
}

static int vl53l1x_read_distance(int handle, uint8_t *distance) {
    uint8_t status;
    if (vl53l1x_read(handle, REG_RESULT_INTERRUPT_STATUS, &status, 1) != 1) return -1;
    if ((status & 0x07) == 0) return 1; /* No new data yet */

    uint8_t dist_buf[2];
    if (vl53l1x_read(handle, REG_RESULT_DISTANCE, dist_buf, 2) != 2) return -1;

    *distance = (dist_buf[0] << 8) | dist_buf[1];

    if (vl53l1x_write8(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;
    return 0;
}

static void update_circular_buffer(int *buffer, int size, int new_value) {
    static int index = 0;
    buffer[index] = new_value;
    index = (index + 1) % size;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (code %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int distance_buffer[BUFFER_SIZE];
    for (int i = 0; i < BUFFER_SIZE; i++) distance_buffer[i] = 0;

    while (g_running) {
        uint8_t distance = 0;
        int ret = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (ret == 0) {
            update_circular_buffer(distance_buffer, BUFFER_SIZE, (int)distance);
            gpioWrite(GPIO_LED, (distance < DIST_THRESHOLD) ? 1 : 0);
        } else if (ret < 0) {
            fprintf(stderr, "Warning: I2C read error\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(GPIO_LED, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

