#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <getopt.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_PROXIMITY_THRESHOLD 1000
#define GPIO_INTERRUPT_PIN 27
#define LOG_FILE_NAME "proximity.log"
#define I2C_BUS "/dev/i2c-1"

/* Si1102 register addresses (from datasheet) */
#define SI1102_REG_HW_KEY      0x07
#define SI1102_REG_MEAS_RATE   0x08
#define SI1102_REG_ALS_RATE    0x09
#define SI1102_REG_PS_RATE     0x0A
#define SI1102_REG_PS_LED21    0x0F
#define SI1102_REG_PS1_DATA0   0x10
#define SI1102_REG_PS1_DATA1   0x11
#define SI1102_REG_INT_CFG     0x13
#define SI1102_REG_INT_EN      0x14
#define SI1102_REG_INT_STATUS  0x15

#define SI1102_HW_KEY_VALUE    0x17

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static int proximity_threshold = DEFAULT_PROXIMITY_THRESHOLD;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int initialize_sensor(int fd) {
    if (i2c_write_reg8(fd, SI1102_REG_HW_KEY, SI1102_HW_KEY_VALUE) < 0) return -1;
    if (i2c_write_reg8(fd, SI1102_REG_MEAS_RATE, 0x08) < 0) return -1;
    if (i2c_write_reg8(fd, SI1102_REG_ALS_RATE, 0x08) < 0) return -1;
    if (i2c_write_reg8(fd, SI1102_REG_PS_RATE, 0x08) < 0) return -1;
    if (i2c_write_reg8(fd, SI1102_REG_PS_LED21, 0x03) < 0) return -1;
