#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200.0f
#define MAX_FREQUENCY_HZ 2000.0f
#define ECHO_TIMEOUT_US  200000U
#define SAMPLE_PERIOD_US 10000U
#define TRIGGER_PULSE_US 10U

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        return -1;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM pin mode.\n");
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        return -1;
    }

    if (gpioSetPWMfrequency(PWM_PIN, 1000) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        return -1;
    }
    if (gpioSetPWMrange(PWM_PIN, 1000) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        return -1;
    }
    if (gpioPWM(PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty cycle.\n");
        return -1;
    }

    return 0;
}

static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to set trigger high.\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to set trigger low.\n");
    }
}

static float read_distance_cm(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_tick = gpioTick() + ECHO_TIMEOUT_US;

    trigger_sensor();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Warning: echo start timeout.\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Warning: echo end timeout.\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * 0.0343f / 2.0f;
    return distance;
}

static float map_distance_to_frequency(float distance)
{
    if (distance < 0.0f) {
        return -1.0f;
    }
    if (distance < MIN_DISTANCE_CM) {
        distance = MIN_DISTANCE_CM;
    }
    if (distance > MAX_DISTANCE_CM) {
        distance = MAX_DISTANCE_CM;
    }

    float norm = (distance - MIN_DISTANCE_CM) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    float freq = MIN_FREQUENCY_HZ *
                 powf(MAX_FREQUENCY_HZ / MIN_FREQUENCY_HZ, norm);
    return freq;
}

static void set_speaker_frequency(float frequency)
{
    if (frequency < 0.0f) {
        return;
    }
    int pwm_freq = (int)frequency;
    if (pwm_freq < 1) {
        pwm_freq = 1;
    }
    if (gpioSetPWMfrequency(PWM_PIN, pwm_freq) < 0) {
        fprintf(stderr, "Warning: failed to set PWM frequency to %d Hz.\n",
                pwm_freq);
        return;
    }
    if (gpioPWM(PWM_PIN, 500) < 0) {
        fprintf(stderr, "Warning: failed to set PWM duty cycle.\n");
    }
}

static void cleanup(void)
{
    gpioPWM(PWM_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    float current_frequency = 440.0f;
    set_speaker_frequency(current_frequency);

    while (g_running) {
        float distance = read_distance_cm();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: sensor read failed; holding previous frequency.\n");
        } else {
            float freq = map_distance_to_frequency(distance);
            if (freq < 0.0f) {
                fprintf(stderr, "Error: invalid frequency; holding previous frequency.\n");
            } else {
                current_frequency = freq;
                set_speaker_frequency(current_frequency);
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

