#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM 5.0f
#define MAX_DISTANCE_CM 50.0f
#define MIN_FREQUENCY_HZ 200.0f
#define MAX_FREQUENCY_HZ 2000.0f

#define ECHO_TIMEOUT_US 100000
#define LOOP_DELAY_US   10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode.\n");
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on echo pin.\n");
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        return -1;
    }

    return 0;
}

static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high.\n");
        return -1.0f;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low.\n");
        return -1.0f;
    }

    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout.\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout.\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff / 58.0f;

    if (distance < 2.0f || distance > 400.0f) {
        fprintf(stderr, "Warning: distance %.2f cm out of range, ignoring.\n", distance);
        return -1.0f;
    }
    return distance;
}

static float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float normalized = (distance - MIN_DISTANCE_CM) /
                       (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

    return MIN_FREQUENCY_HZ +
           normalized * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ);
}

static int set_buzzer_frequency(float frequency) {
    if (frequency < 0.0f) frequency = 0.0f;
    if (frequency > 20000.0f) frequency = 20000.0f;

    if (gpioSetPWMfrequency(BUZZER_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {
        fprintf(stderr, "Error: failed to start PWM on buzzer.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    float last_valid_distance = 30.0f;

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Sensor read failed; using last valid distance (%.2f cm).\n",
                    last_valid_distance);
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        float frequency = map_distance_to_frequency(distance);

        if (set_buzzer_frequency(frequency) < 0) {
            fprintf(stderr, "Failed to set buzzer frequency.\n");
        }

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

