#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM          2.0
#define MAX_DISTANCE_CM          400.0
#define TOO_CLOSE_CM             10.0
#define TRIGGER_PULSE_US         10
#define ECHO_TIMEOUT_US          50000
#define LOOP_DELAY_US            500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high.\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low.\n");
        return -1;
    }
    return 0;
}

static long measure_echo_us(void)
{
    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return -1;
        }
    }

    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            return -1;
        }
    }

    end_tick = gpioTick();
    return (long)(end_tick - start_tick);
}

static float calculate_distance_cm(long pulse_duration_us)
{
    if (pulse_duration_us < 0) {
        return -1.0f;
    }
    return (float)pulse_duration_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

static void display_distance(float distance_cm)
{
    if (distance_cm < 0) {
        printf("Distance: Invalid reading\n");
    } else if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        printf("Distance: Invalid reading\n");
    } else {
        printf("Distance: %.2f cm", distance_cm);
        if (distance_cm < TOO_CLOSE_CM) {
            printf("  Too close!\n");
        } else {
            printf("\n");
        }
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (trigger_sensor() != 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        long pulse_duration = measure_echo_us();
        float distance = calculate_distance_cm(pulse_duration);
        display_distance(distance);

        gpioDelay(LOOP_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

