#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */
#define CS_PIN      8        /* BCM GPIO8 = CE0 */
#define LOG_FILE    "distance_log.csv"
#define SAMPLE_US   100000   /* 100 ms between readings */

/* ICU-20201 SPI command opcodes (16-bit, big-endian on wire) */
#define ICU_CMD_READ_REG   0x80
#define ICU_CMD_WRITE_REG  0x00
#define ICU_REG_DISTANCE   0x00
#define ICU_REG_CONFIG     0x01
#define ICU_REG_STATUS     0x02

/* Config register bits */
#define ICU_CFG_RANGE_MM   0x0F00  /* 4-bit range code: 0x0 = 200-5000 mm */
#define ICU_CFG_MODE       0x0001  /* bit 0 = continuous mode */

/* Status register bits */
#define ICU_STATUS_READY   0x0001  /* bit 0 = data ready */
#define ICU_STATUS_ERROR   0x0002  /* bit 1 = error flag */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_fp    = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register via SPI                   */
/* ------------------------------------------------------------------ */
static int spi_write_reg(uint8_t reg, uint16_t value)
{
    char tx[4];
    char rx[4];

    tx[0] = ICU_CMD_WRITE_REG;
    tx[1] = (char)(reg & 0xFF);
    tx[2] = (char)((reg >> 8) & 0xFF);
    tx[3] = (char)(value & 0xFF);          /* low byte */
    /* high byte goes in the next transaction; send separately */
    char tx_hi[2] = { ICU_CMD_WRITE_REG, (char)((value >> 8) & 0xFF) };

    if (spiXfer(g_spi_handle, tx, rx, 4) < 0) {
        fprintf(stderr, "SPI write (low byte) to reg 0x%02X failed\n", reg);
        return -1;
    }
    if (spiXfer(g_spi_handle, tx_hi, rx, 2) < 0) {
        fprintf(stderr, "SPI write (high byte) to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register via SPI                                      */
/* ------------------------------------------------------------------ */
static int spi_read_reg(uint8_t reg, uint16_t *out)
{
    char tx[4];
    char rx[4];

    tx[0] = ICU_CMD_READ_REG;
    tx[1] = (char)(reg & 0xFF);
    tx[2] = (char)((reg >> 8) & 0xFF);
    tx[3] = 0x00;  /* dummy for clocking data out */

    if (spiXfer(g_spi_handle, tx, rx, 4) < 0) {
        fprintf(stderr, "SPI read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)rx[2] << 8) | (uint8_t)rx[3];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ICU-20201 sensor                                     */
/* ------------------------------------------------------------------ */
static int sensor_init(void)
{
    uint16_t cfg = ICU_CFG_RANGE_MM | ICU_CFG_MODE;

    if (spi_write_reg(ICU_REG_CONFIG, cfg) < 0)
        return -1;

    /* Allow the sensor to settle into continuous mode */
    gpioDelay(50000);  /* 50 ms */

    /* Verify configuration was accepted */
    uint16_t cfg_read = 0;
    if (spi_read_reg(ICU_REG_CONFIG, &cfg_read) < 0)
        return -1;
    if (cfg_read != cfg) {
        fprintf(stderr, "Sensor config mismatch: wrote 0x%04X, read 0x%04X\n",
                cfg, cfg_read);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in millimetres                                        */
/* Returns 0 on success, -1 on SPI error, -2 on sensor error flag      */
/* ------------------------------------------------------------------ */
static int read_distance(uint16_t *distance_mm)
{
    uint16_t status = 0;
    if (spi_read_reg(ICU_REG_STATUS, &status) < 0)
        return -1;

    if (status & ICU_STATUS_ERROR) {
        fprintf(stderr, "Sensor error flag set (status=0x%04X)\n", status);
        return -2;
    }

    if (!(status & ICU_STATUS_READY)) {
        /* Data not ready yet — return early */
        return 1;
    }

    uint16_t dist = 0;
    if (spi_read_reg(ICU_REG_DISTANCE, &dist) < 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a distance reading with a timestamp                             */
/* ------------------------------------------------------------------ */
static void log_distance(uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

