    sigaction(SIGTERM, &sa, NULL);

    /* --- sensor init --- */
    if (sensor_init() < 0) {
        fprintf(stderr, "Sensor initialization failed — continuing anyway\n");
    } else {
        printf("ICU-20201 initialized. Logging to %s\n", LOG_FILE);
    }

    /* --- main loop --- */
    while (g_running) {
        uint16_t distance = 0;
        int rc = read_distance(&distance);

        if (rc == 0) {
