static int read_als_data(int fd, uint16_t *als_data) {
    uint8_t reg = 0x22;
    uint8_t buf[2];

    if (i2c_read_block(fd, reg, buf, 2) < 0) {
        fprintf(stderr, "Error: Failed to read ALS data from register 0x22\n");
        return -1;
    }

    *als_data = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int log_data(FILE *fp, uint16_t als_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%u\n", timestamp, als_data) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error: Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: Failed to register SIGTERM handler");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        perror("Error: Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (init_si1175(i2c_fd) < 0) {
        fprintf(stderr, "Error: Failed to initialize Si1175 sensor\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fprintf(log_file, "timestamp,als_visible\n");
    fflush(log_file);

    while (running) {
        uint16_t als_data;

        if (read_als_data(i2c_fd, &als_data) < 0) {
            fprintf(stderr, "Error: Failed to read ALS data\n");
        } else {
            if (log_data(log_file, als_data) < 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

