#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1120 I2C address (7-bit) */
#define SI1120_ADDR 0x60

/* Si1120 register addresses */
#define SI1120_REG_PART_ID      0x00
#define SI1120_REG_HW_KEY       0x07
#define SI1120_REG_COMMAND      0x18
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_ALS_VIS_DATA1 0x23
#define SI1120_REG_PS1_DATA0    0x24
#define SI1120_REG_PS1_DATA1    0x25

/* Si1120 command values */
#define SI1120_CMD_RESET        0x01
#define SI1120_CMD_ALS_FORCE    0x0A
#define SI1120_CMD_PS_FORCE     0x0B

/* Expected part ID */
#define SI1120_PART_ID_EXPECTED 0x0D

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 500000

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown on Ctrl-C                        */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to a Si1120 register with retry                         */
/* ------------------------------------------------------------------ */
static int si1120_write_reg(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed (attempt %d/%d, rc=%d)\n",
                reg, value, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read a byte from a Si1120 register with retry                        */
/* ------------------------------------------------------------------ */
static int si1120_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *out = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "Warning: i2cReadByteData(reg=0x%02X) failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1120 sensor                                        */
/* ------------------------------------------------------------------ */
static int si1120_init(int handle)
{
    uint8_t part_id = 0;

    /* 1. Software reset via command register */
    if (si1120_write_reg(handle, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Error: failed to send reset command\n");
        return -1;
    }
    gpioDelay(10000); /* allow reset to complete */

    /* 2. Verify part ID */
    if (si1120_read_reg(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: failed to read PART_ID register\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID_EXPECTED) {
        fprintf(stderr, "Error: unexpected PART_ID 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID_EXPECTED);
        return -1;
    }

    /* 3. Write HW_KEY (required for proper operation) */
    if (si1120_write_reg(handle, SI1120_REG_HW_KEY, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write HW_KEY\n");
        return -1;
    }

    /* 4. Enable ALS and PS channels (command register) */
    if (si1120_write_reg(handle, SI1120_REG_COMMAND, SI1120_CMD_ALS_FORCE) != 0) {
        fprintf(stderr, "Error: failed to enable ALS\n");
        return -1;
    }
    if (si1120_write_reg(handle, SI1120_REG_COMMAND, SI1120_CMD_PS_FORCE) != 0) {
        fprintf(stderr, "Error: failed to enable PS\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read ambient light (16-bit little-endian)                           */
/* ------------------------------------------------------------------ */
static int si1120_read_als(int handle, uint16_t *als)
{
    uint8_t lo = 0, hi = 0;
    if (si1120_read_reg(handle, SI1120_REG_ALS_VIS_DATA0, &lo) != 0)
        return -1;
    if (si1120_read_reg(handle, SI1120_REG_ALS_VIS_DATA1, &hi) != 0)
        return -1;
    *als = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read proximity (16-bit little-endian)                               */
/* ------------------------------------------------------------------ */
static int si1120_read_ps(int handle, uint16_t *prox)
{
    uint8_t lo = 0, hi = 0;
    if (si1120_read_reg(handle, SI1120_REG_PS1_DATA0, &lo) != 0)
        return -1;
    if (si1120_read_reg(handle, SI1120_REG_PS1_DATA1, &hi) != 0)
        return -1;
    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                        */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t als, uint16_t prox)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s, ALS: %u, Proximity: %u\n", ts, als, prox) < 0) {
        fprintf(stderr, "Error: fprintf() to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush() failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1120 address */
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d)\n",
                I2C_BUS, SI1120_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (si1120_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: Si1120 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open si1120_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    fprintf(stderr, "Si1120 logging started. Press Ctrl-C to stop.\n");

    /* Main sampling loop */
    while (running) {
        uint16_t als = 0, prox = 0;

        if (si1120_read_als(i2c_handle, &als) != 0) {
            fprintf(stderr, "Error: failed to read ALS data\n");
        } else if (si1120_read_ps(i2c_handle, &prox) != 0) {
            fprintf(stderr, "Error: failed to read proximity data\n");
        } else {
            if (log_data(log_file, als, prox) != 0) {
                fprintf(stderr, "Error: failed to log data\n");
            }
        }

        /* Sleep 500 ms (microseconds) */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

