#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60
#define REG_PART_ID    0x00
#define REG_MEAS_RATE  0x08
#define REG_ALS_DATA   0x22
#define REG_PS_DATA    0x24
#define EXPECTED_PART_ID 0x82
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X).\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_MEAS_RATE, 0x0A) != 0) {
        fprintf(stderr, "Failed to set measurement rate.\n");
        return -1;
    }
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

static void log_data(FILE *fp, const char *ts, float lux, uint16_t prox) {
    fprintf(fp, "%s,%.2f,%u\n", ts, lux, prox);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI1182_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Si1182 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als = 0, prox = 0;
        if (i2c_read_reg16(g_i2c_fd, REG_ALS_DATA, &als) != 0 ||
            i2c_read_reg16(g_i2c_fd, REG_PS_DATA, &prox) != 0) {
            fprintf(stderr, "Read error — continuing.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        char ts[32];
        get_timestamp(ts, sizeof(ts));
        float lux = (float)als * 0.1f;
        log_data(g_log_fp, ts, lux, prox);
        printf("%s,%.2f,%u\n", ts, lux, prox);
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

