#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x45
#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

static void log_error(const char *msg) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
    if (log_file) {
        fprintf(log_file, "[%s] ERROR: %s\n", ts, msg);
        fflush(log_file);
    }
}

static int write_reg(uint8_t reg, uint8_t val) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteByteData(i2c_handle, reg, val) == 0) return 0;
        gpioDelay(10000);
    }
    return -1;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int r = i2cReadByteData(i2c_handle, reg);
        if (r >= 0) { *val = (uint8_t)r; return 0; }
        gpioDelay(10000);
    }
    return -1;
}

static int init_si1145(void) {
    if (write_reg(0x17, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x18, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x01, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x02, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x03, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x04, 0x07) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x05, 0x07) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x06, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x07, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x08, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x09, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x0A, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x0B, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x0C, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x0D, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x0E, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x0F, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x10, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x11, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x12, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x13, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x14, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x15, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x16, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg(0x00, 0x01) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_proximity(uint16_t *prox) {
    uint8_t lo, hi;
    if (read_reg(0x22, &lo) != 0) return -1;
    if (read_reg(0x23, &hi) != 0) return -1;
    *prox = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void log_proximity(uint16_t prox) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(log_file, "%s, %u\n", ts, prox);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145() != 0) {
        log_error("Si1145 initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 proximity logger started. Press Ctrl-C to stop.\n");

    while (!terminate) {
        uint16_t prox;
        if (read_proximity(&prox) == 0) {
            log_proximity(prox);
        } else {
            log_error("Failed to read proximity data");
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

