#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define DISTANCE_THRESHOLD_CM   20.0
#define TRIGGER_PULSE_US        10
#define SAMPLE_PERIOD_US        1000000

static volatile sig_atomic_t running = 1;

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_state = 0;   /* 0=idle, 1=rising seen, 2=done */

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        start_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state == 1) {
        end_tick = tick;
        echo_state = 2;
    }
}

static double calculate_distance_cm(uint32_t pulse_us)
{
    return (double)pulse_us * SPEED_OF_SOUND_CM_PER_S / 2000000.0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise BUZZER_PIN low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: BCM %d | Echo: BCM %d | Buzzer: BCM %d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.1f cm. Press Ctrl+C to exit.\n\n", DISTANCE_THRESHOLD_CM);

    while (running) {
        echo_state = 0;
        start_tick = 0;
        end_tick   = 0;

        trigger_sensor();

        uint32_t elapsed = 0;
        while (running && echo_state != 2 && elapsed < 300000) {
            gpioDelay(1000);
            elapsed += 1000;
        }

        if (!running) {
            break;
        }

        if (echo_state != 2) {
            fprintf(stderr, "Warning: echo timeout (no object detected or sensor absent).\n");
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        uint32_t pulse_us = end_tick - start_tick;
        double distance = calculate_distance_cm(pulse_us);

        printf("Distance: %.2f cm\n", distance);

        if (distance < DISTANCE_THRESHOLD_CM) {
            if (gpioWrite(BUZZER_PIN, 1) != 0) {
                fprintf(stderr, "Warning: failed to activate buzzer.\n");
            }
        } else {
            if (gpioWrite(BUZZER_PIN, 0) != 0) {
                fprintf(stderr, "Warning: failed to deactivate buzzer.\n");
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();

    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

