#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define MAX_DISTANCE_CM 200.0
#define MIN_DISTANCE_CM 20.0
#define SERVO_MIN_PULSE_US 500
#define SERVO_MAX_PULSE_US 2500
#define SERVO_ANGLE_MIN 0
#define SERVO_ANGLE_MAX 180
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;
    gpioDelay(2);
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;

    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) return -1.0;
    }
    uint32_t echo_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) return -1.0;
    }
    uint32_t echo_end = gpioTick();

    double pulse_duration = (double)(echo_end - echo_start) / 1000000.0;
    double distance = pulse_duration * 34300.0 / 2.0;
    return distance;
}

static int distance_to_angle(double distance) {
    if (distance < 0) return SERVO_ANGLE_MIN;
    if (distance >= MAX_DISTANCE_CM) return SERVO_ANGLE_MAX;
    double normalized = (distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    int angle = (int)(SERVO_ANGLE_MIN + normalized * (SERVO_ANGLE_MAX - SERVO_ANGLE_MIN));
    if (angle < SERVO_ANGLE_MIN) angle = SERVO_ANGLE_MIN;
    if (angle > SERVO_ANGLE_MAX) angle = SERVO_ANGLE_MAX;
    return angle;
}

static int angle_to_pulse_us(int angle) {
    return SERVO_MIN_PULSE_US + (int)((angle / 180.0) * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));
}

static void set_servo_angle(int angle) {
    int pulse_us = angle_to_pulse_us(angle);
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error setting servo pulse width to %d us\n", pulse_us);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor read error or timeout, retrying...\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle = distance_to_angle(distance);
        set_servo_angle(angle);

        printf("Distance: %.2f cm, Servo Angle: %d\n", distance, angle);
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

