#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define GPIO_SERVO     18
#define DISTANCE_REG   0x1E
#define MODEL_ID_REG   0x010F
#define EXPECTED_MODEL 0xEA
#define TIMING_BUDGET_REG 0x001E
#define TIMING_BUDGET_VAL 0x0A
#define GATE_LOG_FILE  "gate_log.txt"
#define POLL_DELAY_US  50000
#define SERVO_MIN_US   1000
#define SERVO_MAX_US   2000
#define SERVO_NEUTRAL  1500
#define SERVO_STEP_US  100
#define SERVO_SETTLE_MS 50

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t val) {
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), val };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out) {
    uint8_t cmd[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, cmd, 2) != 2) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int vl53l1x_init(int fd) {
    uint16_t model = 0;
    if (i2c_read_reg16(fd, MODEL_ID_REG, &model) < 0) {
        fprintf(stderr, "Error: failed to read model ID\n");
        return -1;
    }
    if (model != EXPECTED_MODEL) {
        fprintf(stderr, "Error: unexpected model ID 0x%04X (expected 0x%04X)\n", model, EXPECTED_MODEL);
        return -1;
    }
    if (i2c_write_reg8(fd, TIMING_BUDGET_REG, TIMING_BUDGET_VAL) < 0) {
        fprintf(stderr, "Error: failed to set timing budget\n");
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance) {
    return i2c_read_reg16(fd, DISTANCE_REG, distance);
}

static void log_event(FILE *f, const char *event) {
    if (!f) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(f, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(f);
}

static void set_servo_pulse(int gpio, int pulse_us) {
    if (pulse_us < SERVO_MIN_US) pulse_us = SERVO_MIN_US;
