#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   50000   /* 50 ms */
#define LOOP_DELAY_US     100000  /* 100 ms */

#define MIN_DISTANCE_CM   2.0
#define MAX_DISTANCE_CM   400.0
#define MIN_SERVO_PULSE   500     /* SG90 at 0°   */
#define MAX_SERVO_PULSE   2500    /* SG90 at 180° */
#define MIN_ANGLE         0.0
#define MAX_ANGLE         180.0

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance with the HC-SR04.
 * Returns distance in cm, or -1.0 on timeout / error.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout 50 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 50 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff / 58.0;  /* 343 m/s -> cm / µs */

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f, %.1f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }
    return distance;
}

/*
 * Map distance (cm) to servo angle (0–180°).
 * Distances <= 20 cm -> 0°, distances >= 200 cm -> 180°, linearly interpolated.
 */
static float distance_to_angle(float distance)
{
    if (distance < 20.0f) return MIN_ANGLE;
    if (distance >= 200.0f) return MAX_ANGLE;
    return MIN_ANGLE + (distance - 20.0f) *
           (MAX_ANGLE - MIN_ANGLE) / (200.0f - 20.0f);
}

/*
 * Set SG90 servo angle (0–180°) via pigpio pulse width.
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(float angle)
{
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: angle %.2f out of range [%.1f, %.1f]\n",
                angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }

    int pulse_width = (int)(MIN_SERVO_PULSE +
                            (angle / MAX_ANGLE) *
                            (MAX_SERVO_PULSE - MIN_SERVO_PULSE));

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", SERVO_PIN, pulse_width);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(servo, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    printf("HC-SR04 distance measurement with SG90 servo control.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: distance measurement failed\n");
        } else {
            float angle = distance_to_angle(distance);
            if (set_servo_angle(angle) == 0) {
                printf("Distance: %.2f cm  ->  Angle: %.2f°\n", distance, angle);
            } else {
                fprintf(stderr, "Error: failed to set servo angle\n");
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown: stop servo and terminate pigpio */
    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);   /* Stop servo pulses */
    gpioDelay(50000);          /* Allow servo to settle */
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

