#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* Si7005 I2C address (7-bit) */
#define SI7005_ADDR 0x40

/* Si7005 register addresses */
#define SI7005_REG_CONFIG      0x03
#define SI7005_REG_HUMIDITY    0x01
#define SI7005_REG_TEMP        0x02

/* Configuration: 0x00 = default (no hold, no interrupt) */
#define SI7005_CONFIG_DEFAULT  0x00

/* Global I2C handle */
static int i2c_handle = -1;

/* Flag to indicate program termination */
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Function to initialize the I2C interface */
static int initialize_i2c(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                SI7005_ADDR, i2c_handle);
        return -1;
    }

    return 0;
}

/* Function to read a 16-bit register from the Si7005 */
static int read_si7005_register(uint8_t reg, uint16_t *value)
{
    int result;

    /* Write the register address to read from */
    result = i2cWriteByte(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error writing register address 0x%02X: %d\n", reg, result);
        return -1;
    }

    /* Wait for conversion (datasheet: typ 8.5ms, max 12ms) */
    gpioDelay(10000); /* 10ms */

    /* Read 2 bytes from the sensor */
    char buf[2];
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }

    /* Combine the bytes (MSB first) */
    *value = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];

    return 0;
}

/* Function to read temperature and humidity from the Si7005 */
static int read_temperature_humidity(float *temperature, float *humidity)
{
    uint16_t raw_humidity, raw_temperature;

    /* Read raw humidity */
    if (read_si7005_register(SI7005_REG_HUMIDITY, &raw_humidity) < 0) {
        return -1;
    }

    /* Read raw temperature */
    if (read_si7005_register(SI7005_REG_TEMP, &raw_temperature) < 0) {
        return -1;
    }

    /* Convert raw values to physical units */
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;
    *temperature = ((float)raw_temperature / 65536.0f) * 125.0f - 40.0f;

    return 0;
}

int main(void)
