/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_TEMP_OUT_H   0x41
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_WHO_AM_I     0x75

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an MPU-6050 register */
static int mpu6050_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
    }
    return rc;
}

/* Read a single byte from an MPU-6050 register */
static int mpu6050_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
    }
    return rc;
}

/* Read a block of bytes starting at the given register */
static int mpu6050_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X (pigpio rc=%d)\n", reg, rc);
    }
    return rc;
}

/* Initialize the MPU-6050 sensor */
static int mpu6050_init(int handle) {
    int who_am_i = mpu6050_read_reg(handle, MPU6050_WHO_AM_I);
    if (who_am_i < 0) {
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Sample rate divider: 1 kHz / (1 + 7) = 125 Hz */
    if (mpu6050_write_reg(handle, MPU6050_SMPLRT_DIV, 0x07) < 0) return -1;

    /* DLPF config: 1 kHz internal, 188 Hz cutoff */
    if (mpu6050_write_reg(handle, MPU6050_CONFIG, 0x01) < 0) return -1;

    /* Gyro full scale: +/- 250 degrees/sec */
    if (mpu6050_write_reg(handle, MPU6050_GYRO_CONFIG, 0x00) < 0) return -1;

    /* Accel full scale: +/- 2 g */
    if (mpu6050_write_reg(handle, MPU6050_ACCEL_CONFIG, 0x00) < 0) return -1;

    return 0;
}

