static int mpu6050_read_data(int handle,
                             int16_t *ax, int16_t *ay, int16_t *az,
                             int16_t *gx, int16_t *gy, int16_t *gz,
                             int16_t *temp) {
    uint8_t buf[14];

    if (mpu6050_read_block(handle, MPU6050_ACCEL_XOUT_H, buf, sizeof(buf)) < 0) {
        return -1;
