    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);
    *temp = (int16_t)((buf[6]  << 8) | buf[7]);
    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

int main(void) {
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X (pigpio rc=%d)\n",
                I2C_BUS, MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (mpu6050_init(g_i2c_handle) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Reading data every 100 ms...\n");
    printf("Press Ctrl+C to exit.\n");

    int16_t ax, ay, az, gx, gy, gz, temp;

    while (g_running) {
        if (mpu6050_read_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz, &temp) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  "
                   "Gyro: X=%6d Y=%6d Z=%6d  "
                   "Temp: %6d\n",
                   ax, ay, az, gx, gy, gz, temp);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

