#define SHT40_CRC_INIT         0xFF
#define SAMPLE_INTERVAL_S      5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion SHT40: polynomial 0x31, init 0xFF, no final XOR. */
static bool sht40_crc_ok(const uint8_t *data, size_t len, uint8_t expected)
{
    uint8_t crc = SHT40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ SHT40_CRC_POLY : (crc << 1);
    }
    return crc == expected;
}

static int sht40_read(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {
        (uint8_t)(SHT40_CMD_HIGHREP >> 8),
        (uint8_t)(SHT40_CMD_HIGHREP & 0xFF)
    };
    uint8_t data[SHT40_READ_LEN];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "[SHT40] I2C write error (cmd 0x%04X)\n", SHT40_CMD_HIGHREP);
        return -1;
    }

    gpioDelay(SHT40_MEAS_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, SHT40_READ_LEN) != SHT40_READ_LEN) {
        fprintf(stderr, "[SHT40] I2C read error (expected %d bytes)\n", SHT40_READ_LEN);
        return -1;
    }

    if (!sht40_crc_ok(data, 2, data[2])) {
        fprintf(stderr, "[SHT40] Temperature CRC mismatch\n");
        return -1;
    }
    if (!sht40_crc_ok(data + 3, 2, data[5])) {
        fprintf(stderr, "[SHT40] Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(1, SHT40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus 1 addr 0x%02X (err %d)\n", SHT40_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temperature, humidity;

        if (sht40_read(handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed; re-opening I2C bus...\n");
            i2cClose(handle);
            handle = i2cOpen(1, SHT40_ADDR, 0);
            if (handle < 0) {
                fprintf(stderr, "i2cOpen retry failed (err %d); exiting\n", handle);
                break;
            }
        }

        /* Sleep in 100 ms slices so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    if (handle >= 0)
        i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

