void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int read_sts30_temperature(int handle, float *temperature) {
    char cmd[2] = {0x06, 0x00};
    char buf[6];
    int result;

    result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        log_error("I2C write failed (trigger measurement)");
        return -1;
    }

    gpioDelay(50000);

    result = i2cReadDevice(handle, buf, 6);
    if (result != 6) {
        log_error("I2C read failed (temperature data)");
        return -1;
    }

    int temp_raw = (buf[0] << 8) | buf[1];
    *temperature = (float)temp_raw / 200.0;
    return 0;
}

