    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);
    fclose(fp);
    return 0;
