            log_error("Failed to read temperature from STS30");
        }
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

