#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si7015 I2C address (7-bit) */
#define SI7015_ADDR 0x40

/* Si7015 commands (No Hold Master mode) */
#define SI7015_CMD_TEMP_HOLD   0xE3
#define SI7015_CMD_HUMID_HOLD  0xE5

/* Measurement conversion time (microseconds) */
#define SI7015_MEAS_TIME_US 20000  /* 20 ms worst-case */

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 5000000 /* 5 seconds */

/* Maximum retries for I2C operations */
#define MAX_RETRIES 3

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a command byte to the Si7015 */
static int si7015_write_cmd(int handle, uint8_t cmd) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByte(handle, cmd);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: i2cWriteByte(0x%02X) failed (attempt %d/%d): %s\n",
                cmd, attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

