        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_sts30(float *temp) {
    uint8_t cmd[2] = {0x36, 0x2F};
