#define MEASUREMENT_DELAY_MS 9
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int sht40_measure(int fd, float *temperature, float *humidity) {
    uint8_t cmd[2] = {
        (uint8_t)((MEASUREMENT_CMD_HIGH_REP >> 8) & 0xFF),
        (uint8_t)(MEASUREMENT_CMD_HIGH_REP & 0xFF)
    };

    if (write(fd, cmd, 2) != 2) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    uint8_t data[6];
    ssize_t bytes = read(fd, data, 6);
    if (bytes != 6) {
        return -2;
    }

    if (sensirion_crc8(&data[0], 2) != data[2]) {
        return -3;
    }
    if (sensirion_crc8(&data[3], 2) != data[5]) {
        return -4;
    }

    uint16_t temp_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t hum_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, humidity);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen log file");
        close(i2c_fd);
        return 1;
    }

    printf("SHT40 greenhouse monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;

        int rc = sht40_measure(i2c_fd, &temperature, &humidity);
        if (rc == 0) {
            log_data(log_fp, temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            const char *err_msg;
            switch (rc) {
                case -1: err_msg = "I2C write failed"; break;
                case -2: err_msg = "I2C read failed"; break;
                case -3: err_msg = "Temperature CRC mismatch"; break;
                case -4: err_msg = "Humidity CRC mismatch"; break;
                default: err_msg = "Unknown error"; break;
            }
            log_error(log_fp, err_msg);
            fprintf(stderr, "Error: %s\n", err_msg);
        }

        for (int i = 0; i < POLL_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

