#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_SEC 1

/* SCD40 commands (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT  0x3F06
#define CMD_GET_DATA_READY_STATUS      0xE4B8
#define CMD_READ_MEASUREMENT           0xEC05

/* SCD40 CRC-8: polynomial 0x31, init 0xFF */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* CRC-8 as used by Sensirion SCD4x sensors */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* Write a 16-bit command to the SCD40 */
static int scd40_write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed for command 0x%04X (rc=%d)\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* Read a 16-bit word from the SCD40 (no CRC on status words) */
static int scd40_read_word(uint16_t *word) {
    uint8_t buf[2];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (rc=%d)\n", rc);
        return -1;
    }
    *word = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* Read the 9-byte measurement block (6 data + 3 CRC bytes) */
static int scd40_read_measurement(uint16_t *co2, uint16_t *temp, uint16_t *rh) {
    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed for measurement (rc=%d)\n", rc);
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on CO2 word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on humidity word\n");
        return -1;
    }
    *co2  = (uint16_t)((buf[0] << 8) | buf[1]);
    *temp = (uint16_t)((buf[3] << 8) | buf[4]);
    *rh   = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

/* Check data-ready flag; returns 1 if ready, 0 if not, -1 on error */
static int scd40_data_ready(void) {
    if (scd40_write_command(CMD_GET_DATA_READY_STATUS) < 0)
        return -1;
    gpioDelay(2000); /* 2 ms processing delay */
    uint16_t status;
    if (scd40_read_word(&status) < 0)
        return -1;
    return (status & 0x07FF) ? 1 : 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd40_write_command(CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, SCD40_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (scd40_write_command(CMD_START_PERIODIC_MEASUREMENT) < 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* First measurement is ready after ~1 s */
    gpioDelay(MEASUREMENT_DELAY_SEC * 1000000);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int ready = scd40_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Error checking data-ready status; retrying in %d s\n",
                    POLL_INTERVAL_SEC);
            gpioDelay(POLL_INTERVAL_SEC * 1000000);
            continue;
        }
        if (!ready) {
            gpioDelay(POLL_INTERVAL_SEC * 1000000);
            continue;
        }

        uint16_t co2_raw, temp_raw, rh_raw;
        if (scd40_read_measurement(&co2_raw, &temp_raw, &rh_raw) < 0) {
            fprintf(stderr, "Measurement read failed; retrying in %d s\n",
                    POLL_INTERVAL_SEC);
            gpioDelay(POLL_INTERVAL_SEC * 1000000);
            continue;
        }

        float co2_ppm = (float)co2_raw;
        float temp_c  = (float)temp_raw / 100.0f;
        float rh_pct  = (float)rh_raw  / 100.0f;

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", ts, co2_ppm, temp_c, rh_pct);
        fflush(log_file);

        printf("%s  CO2: %.2f ppm  T: %.2f C  RH: %.2f %%\n", ts, co2_ppm, temp_c, rh_pct);

        gpioDelay(POLL_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

