#include <pigpio.h>

#define I2C_BUS 1
#define SCD40_ADDR 0x61
#define CO2_THRESHOLD 1000
#define GPIO_LED 17
#define BUFFER_SIZE 20
#define READ_INTERVAL_SEC 5

#define CMD_START_CONT_MEAS 0x21B1
#define CMD_STOP_CONT_MEAS 0x3F06
#define CMD_READ_MEASUREMENT 0xEC05

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
