#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_S 5
#define EDGE_TIMEOUT_US 50000
#define MAX_CONSECUTIVE_ERRORS 3
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int open_log_file(void) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static void log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    if (t != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    if (t != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

static int wait_for_level(int target_level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(GPIO_PIN) != target_level) {
        if ((gpioTick() - start) > timeout_us) {
            return -1;
        }
    }
    return 0;
}

static int read_pulse_widths(uint32_t *high_us, uint32_t *low_us) {
    if (wait_for_level(1, EDGE_TIMEOUT_US) != 0) {
        return -1;
    }
    uint32_t high_start = gpioTick();
    if (wait_for_level(0, EDGE_TIMEOUT_US) != 0) {
        return -1;
    }
    uint32_t high_end = gpioTick();
    *high_us = high_end - high_start;

    if (wait_for_level(1, EDGE_TIMEOUT_US) != 0) {
        return -1;
    }
    uint32_t low_start = gpioTick();
    if (wait_for_level(0, EDGE_TIMEOUT_US) != 0) {
        return -1;
    }
    uint32_t low_end = gpioTick();
    *low_us = low_end - low_start;

    return 0;
}

static double calculate_temperature(uint32_t high_us, uint32_t low_us) {
    if (low_us == 0) {
        return -273.15;
    }
    double duty_cycle = (double)high_us / (double)(high_us + low_us);
    double temperature = (duty_cycle * 100.0 - 50.0) / 10.0;
    return temperature;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    if (open_log_file() != 0) {
        gpioTerminate();
        return 1;
    }

    int consecutive_errors = 0;

    while (running) {
        uint32_t high_us = 0, low_us = 0;

        if (read_pulse_widths(&high_us, &low_us) != 0) {
            log_error("Failed to read pulse widths (timeout).");
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_error("SENSOR MALFUNCTION");
            }
        } else {
            double temperature = calculate_temperature(high_us, low_us);
            if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
                log_error("Temperature reading out of valid range.");
                consecutive_errors++;
                if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                    log_error("SENSOR MALFUNCTION");
                }
            } else {
                log_temperature(temperature);
                consecutive_errors = 0;
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

