#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_CMD 0x2400
#define LOG_FILE "environmental_data.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define MEASUREMENT_DELAY_US 20000
#define LOG_INTERVAL_US 5000000
#define SINE_PERIOD_SEC 3600

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} SensorData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF};
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read 6 bytes from I2C device.\n");
        return -1;
    }

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static void simulate_greenhouse(float *temperature, float *humidity) {
    time_t now = time(NULL);
    double elapsed = difftime(now, (time_t){0});
    double sine_value = sin(2.0 * M_PI * elapsed / SINE_PERIOD_SEC);
    *temperature += 2.0 * (float)sine_value;
    *humidity += 5.0 * (float)sine_value;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);
    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", buf, temperature, humidity);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
