#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44
#define MEASURE_CMD    0x2400  /* single-shot, high repeatability, clock-stretching disabled */
#define MEASURE_DELAY  20000   /* microseconds (20 ms) */
#define SAMPLE_PERIOD  5       /* seconds */
#define CSV_FILE       "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR      */
/* ------------------------------------------------------------------ */
static uint8_t sht_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read temperature (°C) and humidity (%RH) from the SHT35            */
/* ------------------------------------------------------------------ */
static int read_sht35(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t data[6];

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write measurement command to SHT35\n");
        return -1;
    }

    /* Wait for conversion (datasheet: typ 12.5 ms, max 15 ms) */
    gpioDelay(MEASURE_DELAY);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes from SHT35\n");
        return -1;
    }

    /* Validate CRCs */
    if (sht_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }
    if (sht_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        return -1;
    }

    /* Convert raw values to physical units */
    uint16_t t_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t h_raw = (uint16_t)((data[3] << 8) | data[4]);

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the CSV file                        */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float temperature, float humidity)
{
    /* Check whether file exists and is non-empty so we can decide on header */
    int need_header = 0;
    FILE *check = fopen(filename, "r");
    if (check == NULL) {
        need_header = 1;                 /* file does not exist yet */
    } else {
        if (fseek(check, 0, SEEK_END) != 0) {
            fclose(check);
            return -1;
        }
        long sz = ftell(check);
        fclose(check);
        if (sz <= 0) need_header = 1;   /* empty file */
    }

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s for appending\n", filename);
        return -1;
    }

    if (need_header) {
        fprintf(fp, "Timestamp,Temperature (C),Humidity (%%)\n");
    }

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");
    }

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to SHT35 */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: cannot open I2C bus %d at address 0x%02X (pigpio error %d)\n",
                I2C_BUS, SHT35_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    float temperature, humidity;

    while (g_running) {
        if (read_sht35(g_i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(CSV_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
