#define CMD_RESET      0xFE
#define CMD_TEMP_HOLD  0xF3
#define CMD_HUM_HOLD   0xF5
#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t *buf, int n) {
    int total = 0;
    while (total < n) {
        ssize_t r = read(fd, buf + total, n - total);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (int)r;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, float *out) {
    if (i2c_write_cmd(fd, cmd) < 0) return -1;

    uint8_t buf[3];
    int elapsed = 0;
    while (elapsed < POLL_TIMEOUT_MS) {
        if (i2c_read_n(fd, buf, 3) < 0) return -1;
        if (crc8(buf, 2) == buf[2]) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            *out = (float)raw / 65536.0f * 175.72f - 46.85f;
            return 0;
        }
        usleep(1000);
        elapsed++;
    }
    fprintf(stderr, "Measurement 0x%02X: CRC mismatch after %d ms\n", cmd, elapsed);
    return -1;
}

static int read_temperature(int fd, float *temp) {
    return read_measurement(fd, CMD_TEMP_HOLD, temp);
}

static int read_humidity(int fd, float *hum) {
    return read_measurement(fd, CMD_HUM_HOLD, hum);
}

static int log_data(float temp, float hum) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_error(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,ERROR,%s\n", ts, msg);
    } else {
        fprintf(fp, "ERROR,ERROR,ERROR,%s\n", msg);
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
    }
}

static int reset_sensor(int fd) {
    if (i2c_write_cmd(fd, CMD_RESET) < 0) return -1;
    usleep(15000);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
            fclose(fp);
        }
    } else {
        fclose(fp);
    }

    while (g_running) {
        float temp, hum;
        int ok = 1;

        if (read_temperature(g_i2c_fd, &temp) < 0) {
            fprintf(stderr, "Temperature read failed\n");
            log_error("Temperature read failed");
            ok = 0;
        }
        if (ok && read_humidity(g_i2c_fd, &hum) < 0) {
            fprintf(stderr, "Humidity read failed\n");
            log_error("Humidity read failed");
            ok = 0;
        }

        if (ok) {
            if (log_data(temp, hum) < 0) {
                fprintf(stderr, "Logging failed\n");
            }
        }

        if (g_running) sleep(SAMPLE_INTERVAL_S);
    }

    if (g_i2c_fd >= 0) {
        reset_sensor(g_i2c_fd);
        close(g_i2c_fd);
    }
    return 0;
}

