#include <string.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x3C
#define MEASUREMENT_CMD_MSB 0x36
#define MEASUREMENT_CMD_LSB 0x2F
#define MEASUREMENT_DELAY_US 20000
#define SAMPLE_INTERVAL_US 1000000
#define DATA_FILE "airflow.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *data_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp810(float *pressure, float *temperature) {
    uint8_t cmd[2] = {MEASUREMENT_CMD_MSB, MEASUREMENT_CMD_LSB};
    uint8_t buf[9];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from I2C device.\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure = (float)raw_pressure / 60.0f;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static int log_data(float pressure, float temperature) {
    if (data_file == NULL) {
        data_file = fopen(DATA_FILE, "ab");
        if (data_file == NULL) {
            fprintf(stderr, "Error: Failed to open data file: %s\n", strerror(errno));
            return -1;
        }
    }

    if (fwrite(&pressure, sizeof(float), 1, data_file) != 1) {
        fprintf(stderr, "Error: Failed to write pressure to data file.\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, data_file) != 1) {
        fprintf(stderr, "Error: Failed to write temperature to data file.\n");
        return -1;
    }

    fflush(data_file);
    return 0;
}

