#define SDP800_CMD_CONT_MEAS_LSB 0x2F

/* Conversion time: 45 ms (typical for SDP8xx series) */
#define SDP800_CONV_TIME_US 45000

/* Log file name */
#define LOG_FILE "pressure_log.txt"

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* CRC-8 calculation using Sensirion polynomial 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read pressure from SDP800-500Pa sensor */
static int read_sdp800(int handle, float *pressure) {
    uint8_t cmd[2] = {SDP800_CMD_CONT_MEAS_MSB, SDP800_CMD_CONT_MEAS_LSB};
    uint8_t buf[9];
    int16_t raw_pressure;
    int result;

    /* Send continuous measurement command */
    result = i2cWriteDevice(handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(SDP800_CONV_TIME_US);

    /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, scale(2)+crc */
    result = i2cReadDevice(handle, (char *)buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: read %d bytes\n", result);
        return -1;
    }

    /* Validate CRC for pressure word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on pressure data\n");
        return -1;
    }

    /* Validate CRC for temperature word */
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error on temperature data\n");
        return -1;
    }

    /* Validate CRC for scale word */
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error on scale data\n");
        return -1;
    }

    /* Convert raw pressure to Pa (scale factor 60 for SDP800-500Pa) */
    raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw_pressure / 60.0f;

    return 0;
}

