#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Configuration */
#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 100000

/* Calibration parameters (example values; replace with actual calibration data) */
#define ZERO_PRESSURE_OFFSET 0.0
#define SCALE_FACTOR 1.0

/* Global variables */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int read_sensor_data(int handle, int16_t *raw_data);
static double convert_to_pressure(int16_t raw_data);
static double calculate_flow_rate(double pressure);
static int set_fan_speed(double flow_rate);
static void log_data(double pressure, double flow_rate);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

/* Read sensor data from I2C */
static int read_sensor_data(int handle, int16_t *raw_data) {
    char buffer[2];
    int bytes_read = i2cReadDevice(handle, buffer, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading I2C data: expected 2 bytes, got %d\n", bytes_read);
        return -1;
    }
    *raw_data = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

/* Convert raw sensor data to pressure (Pa) */
static double convert_to_pressure(int16_t raw_data) {
    return (double)raw_data * SCALE_FACTOR + ZERO_PRESSURE_OFFSET;
}

/* Calculate flow rate (m^3/s) from pressure (Pa) */
static double calculate_flow_rate(double pressure) {
    /* Placeholder linear relationship; replace with actual calibration data */
    return pressure * 0.1;
}

/* Set fan speed based on flow rate */
static int set_fan_speed(double flow_rate) {
    int pwm_value = (int)(flow_rate * 255.0 / 10.0);
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > 255) pwm_value = 255;
    gpioPWM(FAN_GPIO, pwm_value);
    return 0;
}

/* Log data to file */
static void log_data(double pressure, double flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file);
}

int main(void) {
    int16_t raw_data;
    double pressure, flow_rate;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set GPIO18 as PWM output */
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    /* Register signal handler */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Main loop */
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &raw_data) == 0) {
            pressure = convert_to_pressure(raw_data);
            flow_rate = calculate_flow_rate(pressure);
            set_fan_speed(flow_rate);
            log_data(pressure, flow_rate);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    cleanup();
    return 0;
}

