    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set GPIO18 as PWM output */
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    /* Register signal handler */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Main loop */
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &raw_data) == 0) {
            pressure = convert_to_pressure(raw_data);
            flow_rate = calculate_flow_rate(pressure);
            set_fan_speed(flow_rate);
            log_data(pressure, flow_rate);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    cleanup();
    return 0;
}

