#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define STLM75_ADDR    0x48
#define STLM75_REG_TEMP 0x00
#define LED_PIN        17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define SAMPLE_PERIOD  1.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_push(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static int read_temperature(int handle, float *out_temp)
{
    char reg = STLM75_REG_TEMP;
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to write temperature register address.\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read temperature data.\n");
        return -1;
    }
    int16_t raw = (int16_t)(((uint16_t)data[0] << 8) | (uint8_t)data[1]);
    *out_temp = (float)raw / 100.0f;
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, STLM75_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    while (g_running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) != 0) {
            fprintf(stderr, "Warning: temperature read failed, skipping sample.\n");
        } else {
            cb_push(&temp_buffer, temperature);
            float avg = cb_average(&temp_buffer);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, avg);
            gpioWrite(LED_PIN, (avg > TEMP_THRESHOLD) ? 1 : 0);
        }
        time_sleep(SAMPLE_PERIOD);
    }

    gpioWrite(LED_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

