#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define SCD30_CMD_START_PERIODIC_MEAS 0x0010
#define SCD30_CMD_STOP_PERIODIC_MEAS 0x0104
#define SCD30_CMD_GET_DATA_READY 0x0202
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_SOFT_RESET 0x00EA
#define SCD30_CMD_GET_SERIAL_NUMBER 0x3682
#define SCD30_CMD_GET_FIRMWARE_VERSION 0x3686

#define CO2_LOW_THRESHOLD 800
#define CO2_HIGH_THRESHOLD 1200
#define LOG_FILE "air_quality.log"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int scd30_write_cmd(uint16_t cmd) {
    char buf[2];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    if (i2cWriteDevice(g_i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing command 0x%04X: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int scd30_read_cmd(uint16_t cmd, uint8_t *data, int len) {
    if (scd30_write_cmd(cmd) != 0) return -1;
    gpioDelay(10000);
    if (i2cReadDevice(g_i2c_handle, (char *)data, len) != len) {
        fprintf(stderr, "Error reading command 0x%04X: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int scd30_start_periodic_measurement(void) {
    return scd30_write_cmd(SCD30_CMD_START_PERIODIC_MEAS);
}

static int scd30_stop_periodic_measurement(void) {
    return scd30_write_cmd(SCD30_CMD_STOP_PERIODIC_MEAS);
}

static int scd30_soft_reset(void) {
    return scd30_write_cmd(SCD30_CMD_SOFT_RESET);
}

static int scd30_get_data_ready(uint16_t *ready) {
    uint8_t data[3];
    if (scd30_read_cmd(SCD30_CMD_GET_DATA_READY, data, 3) != 0) return -1;
    *ready = ((data[0] << 8) | data[1]) & 0x07FF;
    return 0;
}

static int scd30_read_measurement(float *co2, float *temp, float *rh) {
    uint8_t data[18];
    if (scd30_read_cmd(SCD30_CMD_READ_MEASUREMENT, data, 18) != 0) return -1;

    uint32_t co2_raw = ((uint32_t)data[0] << 24) | ((uint32_t)data[1] << 16) | ((uint32_t)data[2] << 8) | data[3];
    uint32_t temp_raw = ((uint32_t)data[6] << 24) | ((uint32_t)data[7] << 16) | ((uint32_t)data[8] << 8) | data[9];
    uint32_t rh_raw = ((uint32_t)data[12] << 24) | ((uint32_t)data[13] << 16) | ((uint32_t)data[14] << 8) | data[15];

    uint8_t co2_crc = data[4];
    uint8_t temp_crc = data[10];
    uint8_t rh_crc = data[16];

    if (co2_crc != 0 || temp_crc != 0 || rh_crc != 0) {
        fprintf(stderr, "CRC mismatch on sensor data\n");
        return -1;
    }

    *co2 = co2_raw / 1000.0f;
    *temp = temp_raw / 100.0f;
