#define SDP32_MEASURE_CMD 0x362F
#define SDP32_READ_LEN 9
#define DEFAULT_INTERVAL_MS 1000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp32(int handle, float *pressure) {
    uint8_t cmd[2] = { (SDP32_MEASURE_CMD >> 8) & 0xFF, SDP32_MEASURE_CMD & 0xFF };
    uint8_t buf[SDP32_READ_LEN];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(2000);

    int bytes_read = i2cReadDevice(handle, (char *)buf, SDP32_READ_LEN);
    if (bytes_read != SDP32_READ_LEN) {
        fprintf(stderr, "Error: Failed to read 9 bytes from I2C device (got %d).\n", bytes_read);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: Scale-factor CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    *pressure = (float)raw_pressure / 60.0f;

    return 0;
}

int main(int argc, char *argv[]) {
    int interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Error: Invalid interval '%s'. Using default %d ms.\n", argv[1], DEFAULT_INTERVAL_MS);
            interval_ms = DEFAULT_INTERVAL_MS;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install signal handlers.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    int handle = i2cOpen(1, SDP32_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X. Check wiring and that the sensor is connected.\n", SDP32_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        float pressure;
        if (read_sdp32(handle, &pressure) == 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s - Pressure: %.2f Pa\n", timestamp, pressure);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: Failed to read pressure data.\n");
        }

        if (g_running) {
            gpioDelay(interval_ms * 1000);
        }
    }

    i2cClose(handle);
    gpioTerminate();
    return 0;
}

