#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define READ_LEN       9
#define CONV_DELAY_US  45000   /* 45 ms — SDP810 conversion time */
#define SAMPLE_PERIOD  1.0     /* seconds between samples */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static bool crc8_check(const uint8_t *data, uint8_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

/*
 * Read 9 bytes from the SDP810.
 * Layout: [press_msb press_lsb press_crc] [temp_msb temp_lsb temp_crc]
 *         [scale_msb scale_lsb scale_crc]
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t buf[READ_LEN];
    int n = i2cReadDevice(handle, (char *)buf, READ_LEN);
    if (n != READ_LEN) {
        fprintf(stderr, "I2C read failed: expected %d bytes, got %d (errno %d: %s)\n",
                READ_LEN, n, errno, strerror(errno));
        return -1;
    }

    /* Validate CRC on each 3-byte word */
    if (!crc8_check(&buf[0], 2, buf[2])) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -2;
    }
    if (!crc8_check(&buf[3], 2, buf[5])) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -2;
    }
    if (!crc8_check(&buf[6], 2, buf[8])) {
        fprintf(stderr, "CRC mismatch on scale factor word\n");
        return -2;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temp / (float)scale_factor;
    return 0;
}

int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP810 differential pressure sensor reader\n");
    printf("Bus %d, addr 0x%02X, sample every %.1f s\n",
           I2C_BUS, I2C_ADDR, SAMPLE_PERIOD);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        int rc = read_sdp810(handle, &pressure, &temperature);
        if (rc == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
        } else if (rc == -2) {
            fprintf(stderr, "CRC error — sensor may be absent or wiring faulty\n");
        } else {
            fprintf(stderr, "I2C read error — continuing\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++)
            time_sleep(0.1);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

