#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define HDC1000_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define CONVERSION_DELAY_MS 20
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: expected 2 bytes, got %zd (%s)\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int hdc1000_init(int fd) {
    if (i2c_write_reg16(fd, 0x02, 0x1000) < 0) {
        fprintf(stderr, "Failed to set HDC1000 to 14-bit resolution mode\n");
        return -1;
    }
    return 0;
}

static int hdc1000_read(int fd, float *temperature, float *humidity) {
    if (i2c_write_reg16(fd, 0x00, 0x0000) < 0) {
        fprintf(stderr, "Failed to trigger temperature and humidity conversion\n");
        return -1;
    }

    struct timespec ts;
    ts.tv_sec = CONVERSION_DELAY_MS / 1000;
    ts.tv_nsec = (CONVERSION_DELAY_MS % 1000) * 1000000L;
    nanosleep(&ts, NULL);

    uint16_t raw_temp, raw_hum;
    if (i2c_read_reg16(fd, 0x00, &raw_temp) < 0) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }
    if (i2c_read_reg16(fd, 0x01, &raw_hum) < 0) {
        fprintf(stderr, "Failed to read humidity data\n");
        return -1;
    }

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_hum / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        fprintf(stderr, "Ensure the sensor is connected and i2c enabled (raspi-config).\n");
        return 1;
    }

    if (ioctl(g_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(g_fd);
        g_fd = -1;
        return 1;
    }

    if (hdc1000_init(g_fd) < 0) {
        fprintf(stderr, "HDC1000 initialization failed. Sensor may be absent or not responding.\n");
        close(g_fd);
        g_fd = -1;
        return 1;
    }

    printf("HDC1000 initialized. Reading every %d seconds. Press Ctrl+C to exit.\n", POLL_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;
        if (hdc1000_read(g_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", POLL_INTERVAL_S);
        }

        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    printf("\nExiting gracefully.\n");
    return 0;
}

