#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define SI7051_TEMP_REG 0x00
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteByte(i2c_handle, SI7051_TEMP_REG);
        if (result < 0) {
            fprintf(stderr, "I2C write error (attempt %d/%d): %s\n",
                    attempt + 1, MAX_RETRIES, strerror(errno));
            gpioDelay(100000);
            continue;
        }

        gpioDelay(10000);

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "I2C read error (attempt %d/%d): %s\n",
                    attempt + 1, MAX_RETRIES, strerror(errno));
            gpioDelay(100000);
            continue;
        }

        uint16_t raw_temp = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
        *temperature = (float)raw_temp * 0.00390625;
        return 0;
    }

    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7051 temperature sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            time_t now = time(NULL);
            char time_buf[32];
            strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S",
                     localtime(&now));
            printf("[%s] Temperature: %.2f °C\n", time_buf, temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature after %d attempts.\n",
                    MAX_RETRIES);
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

