#define I2C_BUS 1
#define MLX90833_ADDR 0x48
#define MLX90833_REG_PRESSURE 0x00
#define MLX90833_REG_CONFIG 0x01
#define MLX90833_REG_ID 0x7E
#define MLX90833_ID_VALUE 0x08
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_mlx90833(void) {
    int id = i2cReadByteData(i2c_handle, MLX90833_REG_ID);
    if (id < 0) {
        fprintf(stderr, "Error: Failed to read sensor ID (I2C error %d).\n", id);
