#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_I2C_ADDR 0x25
#define TRIGGER_MEASUREMENT_CMD 0x362F
#define LOG_FILE "airflow_log.csv"
#define MEASUREMENT_DELAY_MS 8
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure) {
    uint8_t data[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(fd, TRIGGER_MEASUREMENT_CMD) < 0) {
            fprintf(stderr, "Error writing trigger command: %s\n", strerror(errno));
            retries++;
            usleep(10000);
            continue;
        }

        usleep(MEASUREMENT_DELAY_MS * 1000);

        if (i2c_read_data(fd, data, 3) < 0) {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            retries++;
            usleep(10000);
            continue;
        }

        if (crc8(data, 2) != data[2]) {
            fprintf(stderr, "CRC mismatch on pressure data\n");
            retries++;
            usleep(10000);
            continue;
        }

