#include <pigpio.h>

#define I2C_BUS 1
#define MLX90821_ADDR 0x28
#define LOG_FILE "pressure_log.csv"
#define SAFE_PRESSURE_MIN 200.0f
#define SAFE_PRESSURE_MAX 250.0f
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, MLX90821_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_out) {
    char buffer[2];
    int result;

    result = i2cReadDevice(g_i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed (returned %d): %s\n", result, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buffer[0] << 8) | (uint8_t)buffer[1];
    *pressure_out = (float)raw * 0.1f;
    return 0;
}

static void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(g_log_file);
}

static void check_pressure_range(float pressure) {
    if (pressure < SAFE_PRESSURE_MIN || pressure > SAFE_PRESSURE_MAX) {
        fprintf(stderr, "WARNING: Pressure %.2f kPa outside safe range [%.1f, %.1f] kPa\n",
                pressure, SAFE_PRESSURE_MIN, SAFE_PRESSURE_MAX);
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    long file_size = ftell(g_log_file);
    if (file_size == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    while (g_running) {
        float pressure;
        int read_ok = 0;

        if (read_pressure(&pressure) == 0) {
            read_ok = 1;
        } else {
            fprintf(stderr, "Retrying I2C read...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioTerminate();
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed, exiting.\n");
                break;
            }
            if (read_pressure(&pressure) == 0) {
                read_ok = 1;
            } else {
                fprintf(stderr, "Retry failed, skipping sample.\n");
            }
        }

        if (read_ok) {
            log_pressure(pressure);
            check_pressure_range(pressure);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

