#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576
#define MEASUREMENT_INTERVAL 5
#define CONVERSION_DELAY_US 40000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor_data(int handle, float *temperature, float *humidity) {
    char data[4];
    int result;

    result = i2cWriteByte(handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", pigpio_error(result));
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    result = i2cReadDevice(handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: expected 4 bytes, got %d\n", result);
        return -1;
    }

    uint16_t raw_data = ((uint16_t)(data[0] & 0xFF) << 8) | (uint16_t)(data[1] & 0xFF);
    uint8_t status = (data[2] >> 6) & 0x03;

    if (status != 0) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", status);
        return -1;
    }

    uint16_t humidity_raw = raw_data & 0x3FFF;
    uint16_t temperature_raw = (raw_data >> 14) & 0x03;

    *humidity = ((float)humidity_raw / 16383.0f) * 100.0f;
    *temperature = ((float)temperature_raw / 3.0f) * 165.0f - 40.0f;

    return 0;
}

static int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(fp);
    return 0;
}

static int check_log_file_size(FILE *fp) {
    long file_size = ftell(fp);
    if (file_size < 0) {
        fprintf(stderr, "Error getting file size\n");
        return -1;
    }
    if (file_size > LOG_FILE_SIZE_LIMIT) {
        if (ftruncate(fileno(fp), 0) != 0) {
            fprintf(stderr, "Error truncating log file: %s\n", strerror(errno));
            return -1;
        }
        rewind(fp);
        return 0;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Starting environmental monitoring. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_sensor_data(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(log_file, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
            if (check_log_file_size(log_file) != 0) {
                fprintf(stderr, "Error checking log file size\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        for (int i = 0; i < MEASUREMENT_INTERVAL && !terminate; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

