    if (file_size > LOG_FILE_SIZE_LIMIT) {
        if (ftruncate(fileno(fp), 0) != 0) {
            fprintf(stderr, "Error truncating log file: %s\n", strerror(errno));
            return -1;
        }
        rewind(fp);
        return 0;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Starting environmental monitoring. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_sensor_data(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(log_file, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
            if (check_log_file_size(log_file) != 0) {
                fprintf(stderr, "Error checking log file size\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        for (int i = 0; i < MEASUREMENT_INTERVAL && !terminate; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

