#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <stdint.h>

#define SENT_GPIO 4
#define TICK_US 3
#define SYNC_TICKS 56
#define MIN_TICKS 12
#define MAX_TICKS 271
#define LOG_FILE "pressure_log.txt"
#define READ_TIMEOUT_MS 1000
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sent_word(uint32_t *word) {
    uint32_t start_tick, pulse_start, pulse_end;
    int level;

    /* Wait for falling edge (start of sync pulse) */
    start_tick = gpioTick();
    while (gpioRead(SENT_GPIO) == 1) {
        if (gpioTick() - start_tick > READ_TIMEOUT_MS * 1000) return -1;
    }
    pulse_start = gpioTick();

    /* Wait for rising edge (end of sync pulse) */
    while (gpioRead(SENT_GPIO) == 0) {
        if (gpioTick() - pulse_start > READ_TIMEOUT_MS * 1000) return -1;
    }
    pulse_end = gpioTick();

    uint32_t sync_width = pulse_end - pulse_start;
    if (sync_width < SYNC_TICKS - 5 || sync_width > SYNC_TICKS + 5) return -2;

    uint32_t nibbles = 0;
    uint32_t nibble_data = 0;

    for (int i = 0; i < 5; i++) {
        /* Wait for falling edge */
        while (gpioRead(SENT_GPIO) == 1) {
            if (gpioTick() - pulse_end > READ_TIMEOUT_MS * 1000) return -1;
        }
        pulse_start = gpioTick();

        /* Wait for rising edge */
        while (gpioRead(SENT_GPIO) == 0) {
            if (gpioTick() - pulse_start > READ_TIMEOUT_MS * 1000) return -1;
        }
        pulse_end = gpioTick();

        uint32_t width = pulse_end - pulse_start;
        if (width < MIN_TICKS || width > MAX_TICKS) return -3;

        int ticks = (width - MIN_TICKS) / TICK_US;
        nibble_data = (nibble_data << 4) | (ticks & 0x0F);
        nibbles++;
    }

    if (nibbles != 5) return -4;

    /* Checksum validation: (S + D1 + D2 + D3) mod 15 == C */
    uint8_t status = (nibble_data >> 12) & 0x0F;
    uint8_t d1 = (nibble_data >> 8) & 0x0F;
    uint8_t d2 = (nibble_data >> 4) & 0x0F;
    uint8_t d3 = nibble_data & 0x0F;
    uint8_t checksum = (status + d1 + d2 + d3) & 0x0F;

    if (checksum != d3) return -5;

    *word = (status << 12) | (d1 << 8) | (d2 << 4) | d3;
    return 0;
}

static float convert_to_pressure(uint32_t sent_word) {
    uint8_t status = (sent_word >> 12) & 0x0F;
    uint8_t d1 = (sent_word >> 8) & 0x0F;
    uint8_t d2 = (sent_word >> 4) & 0x0F;
    uint8_t d3 = sent_word & 0x0F;

    if (status != 0x0F) {
        fprintf(stderr, "Warning: SENT status nibble is 0x%X (expected 0x0F)\n", status);
    }

    uint16_t raw = ((uint16_t)d1 << 8) | ((uint16_t)d2 << 4) | d3;
    return (float)raw * 0.1f;
}

static int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP);

    printf("Reading SENT pressure sensor on GPIO%d. Press Ctrl+C to exit.\n", SENT_GPIO);

    while (running) {
        uint32_t sent_word = 0;
        int ret = read_sent_word(&sent_word);

        if (ret == 0) {
            float pressure = convert_to_pressure(sent_word);
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Failed to log pressure reading\n");
            }
        } else {
            const char *err_msg;
            switch (ret) {
                case -1: err_msg = "Timeout (sensor absent or bus error)"; break;
                case -2: err_msg = "Synchronization pulse out of range"; break;
                case -3: err_msg = "Pulse width out of valid range"; break;
                case -4: err_msg = "Incomplete nibble sequence"; break;
                case -5: err_msg = "Checksum mismatch"; break;
                default: err_msg = "Unknown error"; break;
            }
            fprintf(stderr, "SENT read error: %s\n", err_msg);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

