#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT40_ADDR             0x44
#define SHT40_CMD_MEASURE_T_RH 0x2C07
#define SHT40_CMD_SLEEP        0xB098
#define SHT40_CMD_WAKE         0x3517
#define SHT40_MEAS_DELAY_US    9000   /* 9 ms — covers worst-case 8.5 ms */
#define SAMPLE_INTERVAL_S      5
#define LOG_FILE               "environmental_data.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;

/* ---- CRC-8 (polynomial 0x31, init 0xFF, no final XOR) per Sensirion SHT4x datasheet ---- */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            crc = (crc & 0x80) ? (uint8_t)((crc << 1) ^ 0x31)
                               : (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int sht40_measure(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {
        (uint8_t)(SHT40_CMD_MEASURE_T_RH >> 8),
        (uint8_t)(SHT40_CMD_MEASURE_T_RH & 0xFF)
    };
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error: I2C write failed for measurement command.\n");
        return -1;
    }

    gpioDelay(SHT40_MEAS_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed (got less than 6 bytes).\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (sht40_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }

    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (sht40_crc8(&data[3], 2) != data[5]) {
