#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define CONFIG_REG 0x01
#define LOG_FILE "temperature_log.dat"
#define BUFFER_SIZE 10
#define SAMPLE_INTERVAL_SEC 5

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

static TemperatureReading temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n",
                TMP117_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int configure_tmp117(void) {
    int status = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Failed to write TMP117 config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Failed to read temperature register: %s\n", strerror(errno));
        return -1;
    }

    int16_t temp_data = (int16_t)raw_temp;
    *temperature = (float)temp_data / 100.0f;
    return 0;
}

static void add_temperature_reading(float temperature) {
    temperature_buffer[buffer_index].timestamp = time(NULL);
    temperature_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static int write_buffer_to_file(const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t elements_to_write = (size_t)buffer_count;
    if (fwrite(temperature_buffer, sizeof(TemperatureReading), elements_to_write, fp) != elements_to_write) {
        fprintf(stderr, "Failed to write data to file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_i2c() != 0) {
        return 1;
    }

    if (configure_tmp117() != 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_temperature_reading(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping sample.\n");
        }

        if (write_buffer_to_file(LOG_FILE) != 0) {
            fprintf(stderr, "Failed to write buffer to file.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    if (write_buffer_to_file(LOG_FILE) != 0) {
        fprintf(stderr, "Failed to write buffer to file during shutdown.\n");
    }
    cleanup();
    return 0;
}

