#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHTC3_ADDR             0x44
#define SHTC3_CMD_MEASURE_T_RH 0x2C07
#define SHTC3_CMD_CLEANING     0x3046
#define SHTC3_CMD_SLEEP        0xB098
#define SHTC3_CMD_WAKEUP       0x3517
#define SHTC3_CMD_RESET        0x805D

#define LOG_FILE_NAME "shtc3_environment.log"
#define SAMPLE_INTERVAL_S 5
#define CONVERSION_DELAY_US 15000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int shtc3_write_cmd(uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int shtc3_read_data(uint8_t *data, int len)
{
    if (i2cReadDevice(g_i2c_handle, (char *)data, len) != len) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }
    return 0;
}

static int shtc3_reset(void)
{
    if (shtc3_write_cmd(SHTC3_CMD_RESET) != 0)
        return -1;
    gpioDelay(2000);
    return 0;
}

static int shtc3_wakeup(void)
{
    if (shtc3_write_cmd(SHTC3_CMD_WAKEUP) != 0)
        return -1;
    gpioDelay(2000);
    return 0;
}

static int shtc3_sleep(void)
{
    if (shtc3_write_cmd(SHTC3_CMD_SLEEP) != 0)
        return -1;
    gpioDelay(2000);
    return 0;
}

static int shtc3_cleaning(void)
{
    if (shtc3_write_cmd(SHTC3_CMD_CLEANING) != 0)
        return -1;
    gpioDelay(2000);
    return 0;
}

static int read_shtc3(float *temperature, float *humidity)
{
    uint8_t data[6];

    if (shtc3_wakeup() != 0)
        return -1;

    if (shtc3_write_cmd(SHTC3_CMD_MEASURE_T_RH) != 0)
        return -1;

    gpioDelay(CONVERSION_DELAY_US);

    if (shtc3_read_data(data, 6) != 0)
        return -1;

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw  = (data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity    = 100.0f * (float)hum_raw / 65535.0f;

    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Error: Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Error: Humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }

    shtc3_sleep();
    return 0;
}

static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE_NAME);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);

    fclose(fp);
    return 0;
}

int main(void)
{
