        fprintf(stderr, "Error: SHTC3 reset failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (shtc3_cleaning() != 0) {
        fprintf(stderr, "Warning: SHTC3 cleaning failed\n");
    }

    float temperature, humidity;

    while (g_running) {
        if (read_shtc3(&temperature, &humidity) == 0) {
