static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Initialize the Si7202 sensor */
static int init_si7202(int handle) {
    /* Set the sensor to continuous conversion mode */
    if (i2cWriteByteData(handle, SI7202_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to Si7202 config register\n");
        return -1;
    }
    return 0;
}

/* Read rotational speed from the Si7202 */
static int read_rotational_speed(int handle, float *speed) {
    int raw_speed = i2cReadWordData(handle, SI7202_REG_SPEED);
    if (raw_speed < 0) {
        fprintf(stderr, "Error reading rotational speed from Si7202\n");
        return -1;
    }
    /* Convert raw data to RPM (example conversion) */
    *speed = (float)raw_speed * 0.1f;
    return 0;
}

/* Read temperature from the Si7202 */
static int read_temperature(int handle, float *temperature) {
    int raw_temp = i2cReadWordData(handle, SI7202_REG_TEMP);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature from Si7202\n");
        return -1;
    }
    /* Convert raw data to Celsius (example conversion) */
    *temperature = (float)raw_temp * 0.01f;
    return 0;
}

