    i2c_handle = i2cOpen(1, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize the Si7202 sensor */
    if (init_si7202(i2c_handle) < 0) {
        fprintf(stderr, "Si7202 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Open the log file in append mode */
    log_file = fopen("mag_temp_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Write the header row if the file is new */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Speed (RPM),Temperature (C)\n");
        fflush(log_file);
    }

    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    /* Main loop */
    while (running) {
        float speed = NAN, temperature = NAN;

        if (read_rotational_speed(i2c_handle, &speed) < 0) {
            fprintf(stderr, "Failed to read speed, logging NaN\n");
        }
        if (read_temperature(i2c_handle, &temperature) < 0) {
            fprintf(stderr, "Failed to read temperature, logging NaN\n");
        }

        if (log_data(log_file, speed, temperature) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(1);
    }

    /* Clean up resources */
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

