#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

/* ---- Pin and timing constants (DHT11) ---- */
#define DHT11_PIN        4          /* BCM 4, physical pin 7 */
#define DHT11_MAX_READS  5          /* retries per cycle */
#define DHT11_INTERVAL_S 2         /* seconds between reads */
#define DHT11_TIMEOUT_US 1000      /* 1 ms timeout for each phase */

/* ---- Status codes ---- */
#define DHT11_OK          0
#define DHT11_ERROR       -1
#define DHT11_TIMEOUT     -2
#define DHT11_CHECKSUM    -3
#define DHT11_NO_RESPONSE -4
#define DHT11_INVALID     -5

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ---- Microsecond timing (pigpio) ---- */
static void delay_us(unsigned int us) {
    gpioDelay(us);
}

/* ---- Timestamp helper ---- */
static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

/* ---- Log a line to stderr and the log file ---- */
static void log_line(const char *msg) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(stderr, "[%s] %s\n", ts, msg);
    if (g_log_fp) {
        fprintf(g_log_fp, "[%s] %s\n", ts, msg);
        fflush(g_log_fp);
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Read one DHT11 sensor ---- */
static int read_dht11(int pin, float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int i;

    /* --- Start signal: pull low >= 18 ms, then release --- */
    if (gpioSetMode(pin, PI_OUTPUT) < 0) return DHT11_ERROR;
    if (gpioWrite(pin, 0) < 0) return DHT11_ERROR;
    delay_us(20000);                 /* 20 ms low (>= 18 ms) */
    if (gpioWrite(pin, 1) < 0) return DHT11_ERROR;
    if (gpioSetMode(pin, PI_INPUT) < 0) return DHT11_ERROR;
    delay_us(40);                    /* 40 us release */

    /* --- Wait for sensor response: 80 us low + 80 us high --- */
    int level;
    int count = 0;
    while ((level = gpioRead(pin)) == 1) {
        if (++count > DHT11_TIMEOUT_US) return DHT11_NO_RESPONSE;
        delay_us(1);
    }
    count = 0;
    while (level == 0) {
        if (++count > DHT11_TIMEOUT_US) return DHT11_TIMEOUT;
        delay_us(1);
    }
    count = 0;
    while (level == 1) {
        if (++count > DHT11_TIMEOUT_US) return DHT11_TIMEOUT;
        delay_us(1);
    }

    /* --- Read 40 data bits --- */
    for (bit_idx = 0; bit_idx < 40; bit_idx++) {
        /* Low pulse (~50 us) */
        count = 0;
        while (gpioRead(pin) == 0) {
            if (++count > DHT11_TIMEOUT_US) return DHT11_TIMEOUT;
            delay_us(1);
        }
        /* High pulse: ~26-28 us = '0', ~70 us = '1' */
        count = 0;
        while (gpioRead(pin) == 1) {
            if (++count > DHT11_TIMEOUT_US) return DHT11_TIMEOUT;
            delay_us(1);
        }
        data[bit_idx / 8] <<= 1;
        if (count > 40) {
            data[bit_idx / 8] |= 1;
        }
    }

    /* --- Checksum --- */
    int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) return DHT11_CHECKSUM;

    *humidity    = (float)data[0] + (float)data[1] / 10.0f;
    *temperature = (float)data[2] + (float)data[3] / 10.0f;
    return DHT11_OK;
}

/* ---- Append a reading to the log file ---- */
static int log_reading(float humidity, float temperature) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    FILE *fp = fopen("dht11_readings.txt", "a");
    if (!fp) {
        perror("fopen dht11_readings.txt");
        return -1;
    }
    fprintf(fp, "%s, Humidity: %.1f%%, Temperature: %.1fC\n",
            ts, humidity, temperature);
    fclose(fp);
    return 0;
}

/* ---- Main ---- */
int main(void) {
    float humidity = 0.0f, temperature = 0.0f;
    int status;
    int retries;

    /* --- Open log file --- */
    g_log_fp = fopen("dht11_log.txt", "a");
    if (!g_log_fp) {
        perror("fopen dht11_log.txt");
        return 1;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_line("DHT11 monitor started.");

    /* --- Main loop --- */
    while (g_running) {
        retries = 0;
        do {
            status = read_dht11(DHT11_PIN, &humidity, &temperature);
            if (status != DHT11_OK) {
                char msg[128];
                snprintf(msg, sizeof(msg),
                         "DHT11 read failed (status=%d), attempt %d/%d",
                         status, retries + 1, DHT11_MAX_READS);
                log_line(msg);
            }
            retries++;
            if (retries < DHT11_MAX_READS) delay_us(200000); /* 200 ms */
        } while (status != DHT11_OK && retries < DHT11_MAX_READS && g_running);

        if (status == DHT11_OK) {
            log_reading(humidity, temperature);
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Reading: Humidity=%.1f%%, Temperature=%.1fC",
                     humidity, temperature);
            log_line(msg);
        } else {
            log_line("DHT11 read failed after all retries.");
        }

        /* Sleep DHT11_INTERVAL_S seconds, but wake early on signal */
        for (int s = 0; s < DHT11_INTERVAL_S && g_running; s++) {
            sleep(1);
        }
    }

    /* --- Cleanup --- */
    log_line("Shutting down.");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return 0;
}

