static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) — SHT3x datasheet  */
/* ------------------------------------------------------------------ */
static uint8_t sht31_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read temperature (°C) and humidity (%RH) from the SHT31-D           */
/* ------------------------------------------------------------------ */
static int read_sht31d(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {
        (uint8_t)((SHT31_MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)( SHT31_MEASURE_CMD        & 0xFF)
    };
    uint8_t data[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /* Send measurement command */
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
            fprintf(stderr, "[attempt %d] I2C write failed\n", attempt + 1);
            gpioDelay(100000); /* 100 ms back-off */
            continue;
        }

        gpioDelay(SHT31_MEASURE_DELAY_US);

        /* Read 6 bytes: T_MSB T_LSB T_CRC  RH_MSB RH_LSB RH_CRC */
        if (i2cReadDevice(handle, (char *)data, 6) != 6) {
            fprintf(stderr, "[attempt %d] I2C read failed\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }

        /* Validate CRCs */
        if (sht31_crc8(&data[0], 2) != data[2]) {
            fprintf(stderr, "[attempt %d] temperature CRC mismatch\n", attempt + 1);
            continue;
        }
        if (sht31_crc8(&data[3], 2) != data[5]) {
            fprintf(stderr, "[attempt %d] humidity CRC mismatch\n", attempt + 1);
            continue;
        }

        uint16_t t_raw = (uint16_t)((data[0] << 8) | data[1]);
        uint16_t h_raw = (uint16_t)((data[3] << 8) | data[4]);

        *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        *humidity    = 100.0f * (float)h_raw / 65535.0f;

        return 0;
    }

    return -1;
}

