{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Log an error with a timestamp                                       */
/* ------------------------------------------------------------------ */
static void log_error(FILE *fp, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open (bus 1, address 0x44) ----------------------------- */
    g_i2c_handle = i2cOpen(1, SHT31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file ---------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SHT31-D logger started. Logging to %s every 5 s. Ctrl-C to stop.\n",
           LOG_FILE);

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        float temperature, humidity;

        if (read_sht31d(g_i2c_handle, &temperature, &humidity) == 0) {
            log_data(g_log_file, temperature, humidity);
            printf("%s  T=%.2f °C  RH=%.2f %%\n",
                   __TIME__, temperature, humidity);
        } else {
            log_error(g_log_file, "Sensor read failed after retries");
            fprintf(stderr, "Sensor read failed after %d retries\n", MAX_RETRIES);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000); /* 100 ms × 50 = 5 s */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

