#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD105_ADDR_1 0x50
#define ADPD105_ADDR_2 0x51
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

/* ADPD105 register addresses (16-bit, big-endian on the bus) */
#define ADPD105_REG_CHIP_ID      0x00
#define ADPD105_REG_CHIP_REV     0x01
#define ADPD105_REG_INT_STATUS   0x02
#define ADPD105_REG_INT_MASK     0x03
#define ADPD105_REG_INT_ENABLE   0x04
#define ADPD105_REG_LED1_CURRENT 0x05
#define ADPD105_REG_LED2_CURRENT 0x06
#define ADPD105_REG_LED3_CURRENT 0x07
#define ADPD105_REG_LED4_CURRENT 0x08
#define ADPD105_REG_LED5_CURRENT 0x09
#define ADPD105_REG_LED6_CURRENT 0x0A
#define ADPD105_REG_LED7_CURRENT 0x0B
#define ADPD105_REG_LED8_CURRENT 0x0C
#define ADPD105_REG_DATA0        0x10
#define ADPD105_REG_DATA1        0x11
#define ADPD105_REG_DATA2        0x12
#define ADPD105_REG_DATA3        0x13
#define ADPD105_REG_DATA4        0x14
#define ADPD105_REG_DATA5        0x15
#define ADPD105_REG_DATA6        0x16
#define ADPD105_REG_DATA7        0x17
#define ADPD105_REG_DATA8        0x18
#define ADPD105_REG_DATA9        0x19
#define ADPD105_REG_DATA10       0x1A
#define ADPD105_REG_DATA11       0x1B
#define ADPD105_REG_DATA12       0x1C
#define ADPD105_REG_DATA13       0x1D
#define ADPD105_REG_DATA14       0x1E
#define ADPD105_REG_DATA15       0x1F

#define ADPD105_CHIP_ID_EXPECTED 0x105

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address + 1 byte of data in one I2C transaction. */
static int adpd105_write_reg(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read N bytes from a 16-bit register address. */
static int adpd105_read_block(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char addr_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr_buf, 2) < 0) {
        return -1;
    }
    return i2cReadDevice(handle, (char *)buf, len);
}

/* Initialize an ADPD105 sensor: verify chip ID and clear any pending interrupts. */
static int adpd105_init(int handle) {
    uint8_t chip_id = 0;
    if (adpd105_read_block(handle, ADPD105_REG_CHIP_ID, &chip_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read chip ID from handle %d\n", handle);
        return -1;
    }
    if (chip_id != ADPD105_CHIP_ID_EXPECTED) {
        fprintf(stderr, "Error: unexpected chip ID 0x%02X (expected 0x%02X) on handle %d\n",
                chip_id, ADPD105_CHIP_ID_EXPECTED, handle);
        return -1;
    }
    if (adpd105_write_reg(handle, ADPD105_REG_INT_STATUS, 0xFF) < 0) {
        fprintf(stderr, "Error: failed to clear interrupt status on handle %d\n", handle);
        return -1;
    }
    return 0;
}

/* Read 16-bit data from two consecutive registers (e.g., DATA0 and DATA1). */
static int adpd105_read_data16(int handle, uint16_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (adpd105_read_block(handle, reg, buf, 2) < 0) {
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* Compute CCT from two 16-bit sensor readings using a placeholder linear model. */
static float calculate_cct(uint16_t data1, uint16_t data2) {
    return 1000.0f + (float)data1 * 0.1f - (float)data2 * 0.05f;
}

/* Log a data row to the CSV file. */
static void log_data(float cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s,%.2f\n", timestamp, cct);
        fflush(g_log_fp);
    }
}

int main(void) {
    int handle1 = -1, handle2 = -1;
    int ret_code = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    handle1 = i2cOpen(I2C_BUS, ADPD105_ADDR_1, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X (code %d)\n", ADPD105_ADDR_1, handle1);
        goto cleanup_gpio;
    }

    handle2 = i2cOpen(I2C_BUS, ADPD105_ADDR_2, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X (code %d)\n", ADPD105_ADDR_2, handle2);
        goto cleanup_handle1;
    }

    if (adpd105_init(handle1) < 0) {
        fprintf(stderr, "Error: ADPD105 sensor 1 not detected or init failed\n");
        goto cleanup_handle2;
    }
    if (adpd105_init(handle2) < 0) {
        fprintf(stderr, "Error: ADPD105 sensor 2 not detected or init failed\n");
        goto cleanup_handle2;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        goto cleanup_handles;
    }

    /* Write header if file is empty. */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Average_CCT\n");
        fflush(g_log_fp);
    }

    printf("Starting CCT logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        uint16_t data1 = 0, data2 = 0;

        if (adpd105_read_data16(handle1, ADPD105_REG_DATA0, &data1) < 0) {
            fprintf(stderr, "Error: failed to read sensor 1 data\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (adpd105_read_data16(handle2, ADPD105_REG_DATA0, &data2) < 0) {
            fprintf(stderr, "Error: failed to read sensor 2 data\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float cct = calculate_cct(data1, data2);
        log_data(cct);
        printf("CCT: %.2f K\n", cct);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    ret_code = 0;

cleanup_handles:
    if (handle2 >= 0) i2cClose(handle2);
cleanup_handle2:
    if (handle1 >= 0) i2cClose(handle1);
cleanup_handle1:
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
cleanup_gpio:
    gpioTerminate();
    return ret_code;
}

