#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* MLX90824 I2C address (7-bit) */
#define MLX90824_ADDR 0x48

/* Register addresses (16-bit, big-endian on the bus) */
#define MLX90824_REG_PRESSURE 0x00
#define MLX90824_REG_TEMP     0x01

/* Conversion constants (example values; replace with datasheet values) */
#define PRESSURE_SCALE 0.01f
#define TEMP_SCALE     0.1f
#define TEMP_OFFSET    0.0f

/* Globals for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register from the MLX90824                 */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int read_register16(int handle, uint8_t reg, int16_t *out)
{
    char buf[2];

    /* Write the 8-bit register pointer */
    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read two bytes back (big-endian) */
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure and temperature from the sensor                       */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, float *pressure, float *temperature)
{
    int16_t raw_pressure, raw_temperature;

    if (read_register16(handle, MLX90824_REG_PRESSURE, &raw_pressure) != 0)
        return -1;

    if (read_register16(handle, MLX90824_REG_TEMP, &raw_temperature) != 0)
        return -1;

    *pressure    = (float)raw_pressure * PRESSURE_SCALE;
    *temperature = (float)raw_temperature * TEMP_SCALE + TEMP_OFFSET;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped line to the log file                           */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
            timestamp, pressure, temperature);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped error line to the log file                     */
/* ------------------------------------------------------------------ */
static void log_error(FILE *fp, const char *message)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(fp, "%s, ERROR: %s\n", timestamp, message);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup — release all resources                                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float pressure, temperature;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MLX90824 address */
    i2c_handle = i2cOpen(1, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                MLX90824_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90824 pressure logger started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (running) {
        if (read_sensor_data(i2c_handle, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
        } else {
            log_error(log_file, "Failed to read sensor data");
            fprintf(stderr, "Failed to read sensor data\n");
        }

        /* Sleep 2 seconds, but wake early on signal */
        for (int i = 0; i < 20 && running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

