#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define LM75B_TEMP_REG 0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   26.0f
#define SAMPLE_INTERVAL_US   1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_temperature(int handle, float *temperature)
{
    int raw = i2cReadWordData(handle, LM75B_TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature from LM75B: %d\n", raw);
        return -1;
    }

    /* LM75B returns 16-bit two's-complement data, left-justified in a 16-bit word.
     * i2cReadWordData returns the raw byte-swapped value; pigpio does the swap
     * for us, so the high byte is in bits 15:8 and the low byte in bits 7:0. */
    int16_t temp_raw = (int16_t)raw;
    *temperature = (float)temp_raw / 256.0f;
    return 0;
}

static void control_fan(float average_temp)
{
    static bool fan_on = false;

    if (average_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON  (avg %.2f C)\n", average_temp);
        } else {
            fprintf(stderr, "Error turning fan ON\n");
        }
    } else if (average_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (avg %.2f C)\n", average_temp);
        } else {
            fprintf(stderr, "Error turning fan OFF\n");
        }
    }
}

int main(void)
{
    float temperature_buffer[BUFFER_SIZE];
    int   buffer_index = 0;
    int   sample_count = 0;
    float sum = 0.0f;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, LM75B_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing fan GPIO %d to OFF\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LM75B temperature monitor started. Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;
        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            sum -= temperature_buffer[buffer_index];
            temperature_buffer[buffer_index] = temperature;
            sum += temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (sample_count < BUFFER_SIZE) {
                sample_count++;
            }

            float average_temp = sum / (float)sample_count;
            control_fan(average_temp);
            printf("Temperature: %.2f C, Average: %.2f C, Fan: %s\n",
                   temperature, average_temp, (average_temp > TEMP_THRESHOLD_HIGH) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying next cycle.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

