#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x48
#define GPIO_LED       17
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define I2C_RETRIES     3
#define POLL_INTERVAL_S  1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static float read_temperature(int fd)
{
    uint16_t raw;
    int retries = I2C_RETRIES;

    while (retries > 0) {
        if (i2c_read_reg16(fd, 0x00, &raw) == 0) {
            return (float)raw * 0.01f;
        }
        retries--;
        if (retries > 0) {
            fprintf(stderr, "I2C read failed (retries left: %d): %s\n",
                    retries, strerror(errno));
            sleep(1);
        }
    }

    fprintf(stderr, "I2C read failed after %d retries: %s\n",
            I2C_RETRIES, strerror(errno));
    return -1000.0f;
}

static int control_led(float temperature)
{
    int level;

    if (temperature > TEMP_THRESHOLD_HIGH) {
        level = 1;
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        level = 0;
    } else {
        return 0;
    }

    if (gpioWrite(GPIO_LED, level) != 0) {
        fprintf(stderr, "Failed to write GPIO %d: %s\n",
                GPIO_LED, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_LED, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO %d low\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioWrite(GPIO_LED, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioWrite(GPIO_LED, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temperature = read_temperature(g_i2c_fd);

        if (temperature > -999.0f) {
            printf("Temperature: %.2f °C\n", temperature);
            fflush(stdout);

            if (control_led(temperature) != 0) {
                fprintf(stderr, "LED control failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    fprintf(stderr, "\nShutting down...\n");

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

