#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60          /* seconds between readings */
#define MAX_RETRIES    3
#define MEASURE_RH_NOHOLD  0xE5
#define MEASURE_TEMP_NOHOLD 0xE3
#define READ_PREV_TEMP  0xF3
#define RESET_CMD      0xFE
#define REV_ID_CMD     0x84
#define REV_ID_LEN     8
#define ID_0           0x0F
#define ID_1           0x0D
#define ID_2           0x0B
#define ID_3           0x08
#define ID_4           0x06
#define ID_5           0x04
#define ID_6           0x0B
#define ID_7           0x0D

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

static void log_error(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
    if (g_log_fp) {
        fprintf(g_log_fp, "%s,ERROR,%s\n", ts, msg);
        fflush(g_log_fp);
    }
}

static int read_bytes(int handle, uint8_t *buf, int len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "I2C read failed: expected %d bytes, got %d\n", len, n);
        return -1;
    }
    return 0;
}

static int write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "I2C write failed for cmd 0x%02X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_sensor(int handle, uint8_t cmd, uint16_t *raw)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write_cmd(handle, cmd) != 0) {
            gpioDelay(10000);
            continue;
        }
        gpioDelay(20000); /* 20 ms conversion wait */

        uint8_t buf[2];
        if (read_bytes(handle, buf, 2) == 0) {
            *raw = ((uint16_t)buf[0] << 8) | buf[1];
            return 0;
        }
        gpioDelay(10000);
    }
    return -1;
}

static float convert_temperature(uint16_t raw)
{
    return (175.72f * raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw)
{
    float rh = (125.0f * raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

static int verify_sensor(int handle)
{
    if (write_cmd(handle, RESET_CMD) != 0) return -1;
    gpioDelay(15000);

    if (write_cmd(handle, REV_ID_CMD) != 0) return -1;
    gpioDelay(10000);

    uint8_t id[REV_ID_LEN];
    if (read_bytes(handle, id, REV_ID_LEN) != 0) return -1;

    if (id[0] != ID_0 || id[1] != ID_1 || id[2] != ID_2 ||
        id[3] != ID_3 || id[4] != ID_4 || id[5] != ID_5 ||
        id[6] != ID_6 || id[7] != ID_7) {
        fprintf(stderr, "Sensor ID mismatch: got %02X %02X %02X %02X %02X %02X %02X %02X\n",
                id[0], id[1], id[2], id[3], id[4], id[5], id[6], id[7]);
        return -1;
    }
    return 0;
}

static void log_data(float temp, float rh)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_fp, "%s,%.2f,%.2f\n", ts, temp, rh);
    fflush(g_log_fp);
    printf("%s,%.2f,%.2f\n", ts, temp, rh);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_sensor(g_i2c_handle) != 0) {
        log_error("Si7021 sensor not detected or ID mismatch");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# Si7021 environmental logger started\n");
    fflush(g_log_fp);

    while (g_running) {
        uint16_t raw_rh = 0, raw_temp = 0;

        if (read_sensor(g_i2c_handle, MEASURE_RH_NOHOLD, &raw_rh) == 0 &&
            read_sensor(g_i2c_handle, READ_PREV_TEMP, &raw_temp) == 0) {
            float rh = convert_humidity(raw_rh);
            float temp = convert_temperature(raw_temp);
            log_data(temp, rh);
        } else {
            log_error("Failed to read sensor data after retries");
        }

        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    log_error("Shutting down gracefully");
    cleanup();
    return EXIT_SUCCESS;
}

