#include <unistd.h>
#include <pigpio.h>

#define HDC1080_ADDR 0x40
#define HDC1080_TEMP_REG 0x00
#define HDC1080_CONFIG_REG 0x02
#define HDC1080_CONV_TIME_US 20000
#define LOG_INTERVAL_US 5000000
#define LOG_FILE "enviro_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hdc1080_init(int handle) {
    if (i2cWriteByteData(handle, HDC1080_CONFIG_REG, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to write HDC1080 config register.\n");
        return -1;
    }
    return 0;
}

static int hdc1080_read(int handle, float *temperature, float *humidity) {
    char buf[4];

    if (i2cWriteByte(handle, HDC1080_TEMP_REG) < 0) {
        fprintf(stderr, "Error: Failed to write temperature register address.\n");
        return -1;
    }

    gpioDelay(HDC1080_CONV_TIME_US);

    if (i2cReadDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "Error: Failed to read 4 bytes from HDC1080.\n");
        return -1;
    }

    uint16_t temp_raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    uint16_t hum_raw = ((uint16_t)(buf[2] & 0xFF) << 8) | (uint16_t)(buf[3] & 0xFF);

    *temperature = ((float)temp_raw / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)hum_raw / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    int handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", HDC1080_ADDR);
        gpioTerminate();
        return 1;
    }

    if (hdc1080_init(handle) != 0) {
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;

    while (running) {
        if (hdc1080_read(handle, &temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry.\n");
        }

        gpioDelay(LOG_INTERVAL_US);
    }

    i2cClose(handle);
    gpioTerminate();
    return 0;
}

