int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    int handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", HDC1080_ADDR);
        gpioTerminate();
        return 1;
    }

    if (hdc1080_init(handle) != 0) {
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;

    while (running) {
        if (hdc1080_read(handle, &temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry.\n");
        }

        gpioDelay(LOG_INTERVAL_US);
    }

    i2cClose(handle);
    gpioTerminate();
    return 0;
}

