    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int send_command(uint8_t command) {
    char cmd[1] = {command};
    int result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "Failed to send command 0x%02X: %d", command, result);
        log_error(error_message);
        return -1;
    }
    return 0;
}

static int read_data(uint16_t *co2, float *temperature, float *humidity) {
    char cmd[1] = {SCD40_CMD_READ_MEASUREMENT};
    int result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        log_error("Failed to write read measurement command");
        return -1;
