#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10110_ADDR 0x28
#define FILENAME "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define SENSOR_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void msleep(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_icp10110(int fd, float *pressure, float *temperature) {
    uint8_t buf[3];

    if (i2c_write(fd, 0x36, 0x00) < 0) return -1;
    msleep(1);

    if (i2c_read(fd, 0x00, buf, 3) < 0) return -1;

    uint32_t raw = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    raw >>= 8;

    *pressure = (float)raw / 100.0f;
    *temperature = (float)((raw >> 12) & 0x0FFF) / 100.0f;

    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", t);
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ICP10110_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ICP10110_ADDR, strerror(errno));
        goto cleanup;
    }

    fp = fopen(FILENAME, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", FILENAME, strerror(errno));
        goto cleanup;
    }

    printf("Starting data logging to %s. Press Ctrl+C to stop.\n", FILENAME);

    while (running) {
        float pressure, temperature;

        if (read_icp10110(fd, &pressure, &temperature) == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));

            fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n", ts, pressure, temperature);
            fflush(fp);

            printf("%s, Pressure: %.2f Pa, Temperature: %.2f C\n", ts, pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully.\n");
    ret = 0;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return ret;
}

