#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define HTTP_PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sht40(float *temperature, float *humidity) {
    unsigned char cmd[2] = {0x36, 0x2F};
    unsigned char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        unsigned short temp_raw = (buf[0] << 8) | buf[1];
        unsigned short hum_raw = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
        *humidity = 100.0f * (float)hum_raw / 65535.0f;

        if (*humidity > 100.0f) *humidity = 100.0f;
        if (*humidity < 0.0f) *humidity = 0.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1;
}

static void send_all(int fd, const char *buf, size_t len) {
    size_t sent = 0;
    while (sent < len) {
        ssize_t n = send(fd, buf + sent, len - sent, 0);
        if (n <= 0) {
            if (errno == EINTR) continue;
            break;
        }
        sent += (size_t)n;
    }
}

static void handle_client(int client_fd) {
    char response[1024];
    float temperature, humidity;

    if (read_sht40(&temperature, &humidity) == 0) {
        snprintf(response, sizeof(response),
                 "HTTP/1.1 200 OK\r\n"
                 "Content-Type: text/html\r\n"
                 "Connection: close\r\n"
                 "\r\n"
                 "<!DOCTYPE html><html><head><title>SHT40 Sensor</title>"
                 "<meta http-equiv=\"refresh\" content=\"5\"></head><body>"
                 "<h1>SHT40 Sensor Data</h1>"
                 "<p>Temperature: %.2f &deg;C</p>"
                 "<p>Humidity: %.2f %%</p>"
                 "</body></html>\r\n",
                 temperature, humidity);
    } else {
        snprintf(response, sizeof(response),
                 "HTTP/1.1 500 Internal Server Error\r\n"
                 "Content-Type: text/html\r\n"
                 "Connection: close\r\n"
                 "\r\n"
                 "<!DOCTYPE html><html><body><h1>500 Internal Server Error</h1>"
                 "<p>Failed to read sensor data.</p></body></html>\r\n");
    }

    send_all(client_fd, response, strlen(response));
    close(client_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(HTTP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", HTTP_PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);

        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            if (errno != EINTR) perror("accept");
            continue;
        }

        handle_client(client_fd);
    }

    printf("\nShutting down...\n");
    if (server_fd >= 0) close(server_fd);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

