#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* HDC2010 I2C address (7-bit) */
#define HDC2010_ADDR 0x40

/* HDC2010 register addresses */
#define REG_TEMP_LOW       0x00
#define REG_HUM_LOW        0x02
#define REG_MEAS_CONFIG    0x0E
#define REG_INT_CONFIG     0x0F
#define REG_INT_STATUS     0x12

/* Measurement configuration bits */
#define MEAS_CONFIG_MEAS_TRIG 0x01  /* bit 0: start a measurement */
#define MEAS_CONFIG_MEAS_MODE 0x00  /* bit 1: 1-shot mode */

/* Polling timeout for measurement completion (microseconds) */
#define MEAS_TIMEOUT_US 500000

/* Maximum retries for transient I2C errors */
#define MAX_RETRIES 3

/* Global I2C handle */
static int i2c_handle = -1;

/* Flag for graceful shutdown */
static volatile sig_atomic_t shutdown_requested = 0;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig)
{
    (void)sig;
    shutdown_requested = 1;
}

/* Write a byte to an HDC2010 register; returns 0 on success, -1 on error */
static int hdc_write_reg(uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(i2c_handle, reg, value);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed (attempt %d/%d, rc=%d)\n",
                reg, value, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000); /* 10 ms backoff */
    }
    return -1;
}

/* Read a byte from an HDC2010 register; returns 0 on success, -1 on error */
static int hdc_read_reg(uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(i2c_handle, reg);
        if (rc >= 0) {
            *value = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "Warning: i2cReadByteData(reg=0x%02X) failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000);
    }
    return -1;
}

/* Read a 16-bit little-endian word from two consecutive registers */
static int hdc_read_word(uint8_t reg_low, uint16_t *out)
{
    uint8_t lo, hi;
    if (hdc_read_reg(reg_low, &lo) != 0) {
        return -1;
    }
    if (hdc_read_reg(reg_low + 1, &hi) != 0) {
        return -1;
    }
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* Trigger a measurement and wait for completion; returns 0 on success, -1 on error */
static int hdc_trigger_measurement(void)
{
    /* Set 1-shot mode and trigger */
    if (hdc_write_reg(REG_MEAS_CONFIG,
                      MEAS_CONFIG_MEAS_TRIG | MEAS_CONFIG_MEAS_MODE) != 0) {
        return -1;
    }

    /* Poll bit 0 of MEAS_CONFIG until it clears (measurement complete) */
    uint32_t elapsed = 0;
    uint8_t cfg;
    while (elapsed < MEAS_TIMEOUT_US) {
        if (hdc_read_reg(REG_MEAS_CONFIG, &cfg) != 0) {
            return -1;
        }
        if ((cfg & MEAS_CONFIG_MEAS_TRIG) == 0) {
            return 0; /* measurement finished */
        }
        gpioDelay(1000); /* 1 ms poll interval */
        elapsed += 1000;
    }

    fprintf(stderr, "Error: measurement timeout (%u us)\n", elapsed);
    return -1;
}

/* Read temperature and humidity; returns 0 on success, -1 on error */
static int hdc_read_temperature_humidity(float *temperature, float *humidity)
{
    if (hdc_trigger_measurement() != 0) {
        return -1;
    }

    uint16_t raw_temp, raw_hum;
    if (hdc_read_word(REG_TEMP_LOW, &raw_temp) != 0) {
        return -1;
    }
    if (hdc_read_word(REG_HUM_LOW, &raw_hum) != 0) {
        return -1;
    }

    /* HDC2010 conversion formulas (datasheet) */
    *temperature = ((float)raw_temp / 65535.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum / 65535.0f) * 100.0f;

    /* Sanity-check ranges */
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Warning: temperature out of range: %.2f C\n", *temperature);
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Warning: humidity out of range: %.2f %%\n", *humidity);
    }

    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the HDC2010 address */
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed (rc=%d)\n",
                HDC2010_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading INT_CONFIG */
    uint8_t int_cfg;
    if (hdc_read_reg(REG_INT_CONFIG, &int_cfg) != 0) {
        fprintf(stderr, "Error: HDC2010 not detected at address 0x%02X (sensor absent or bus error)\n",
                HDC2010_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("HDC2010 sensor reader started. Press Ctrl+C to exit.\n");

    while (!shutdown_requested) {
        float temperature, humidity;

        if (hdc_read_temperature_humidity(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Error: failed to read temperature/humidity\n");
        }

        /* Sleep 5 seconds, checking shutdown flag every 100 ms */
        for (int i = 0; i < 50 && !shutdown_requested; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

