#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x25
#define MEASURE_CMD    0x3615
#define MEASURE_DELAY_US 45000
#define LOOP_DELAY_US  500000
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static bool sdp_crc8(const uint8_t *data, size_t len, uint8_t expected) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

static int sdp_read(int handle, uint16_t *pressure, uint16_t *temperature) {
    uint8_t cmd[2] = { (uint8_t)(MEASURE_CMD >> 8), (uint8_t)(MEASURE_CMD & 0xFF) };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes from sensor\n");
        return -1;
    }

    if (!sdp_crc8(&buf[0], 2, buf[2])) {
        fprintf(stderr, "Error: pressure CRC mismatch\n");
        return -1;
    }
    if (!sdp_crc8(&buf[3], 2, buf[5])) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }

    *pressure    = (uint16_t)((buf[0] << 8) | buf[1]);
    *temperature = (uint16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

int main(void) {
    int handle = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (addr 0x%02X): %d\n", SDP800_ADDR, handle);
        goto cleanup_gpio;
    }

    printf("SDP800-500Pa reader started on I2C bus %d, addr 0x%02X\n", I2C_BUS, SDP800_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t pressure = 0, temperature = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sdp_read(handle, &pressure, &temperature) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000);
        }

        if (ok) {
            printf("Pressure: %u Pa, Temperature: %u °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Warning: sensor read failed after %d attempts\n", MAX_RETRIES);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    rc = EXIT_SUCCESS;

cleanup_i2c:
    if (handle >= 0) {
        i2cClose(handle);
    }
cleanup_gpio:
    gpioTerminate();
    return rc;
}

