    char tx[2] = {0x00, 0x00};
    char rx[2] = {0, 0};

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed\n");
        return MAX6675_READ_ERROR;
    }

    int raw = ((rx[0] & 0xFF) << 8) | (rx[1] & 0xFF);
    if (raw & 0x0001) {
        fprintf(stderr, "MAX6675 thermocouple open circuit or fault\n");
        return MAX6675_READ_ERROR;
    }
    if (raw & 0x0002) {
        fprintf(stderr, "MAX6675 short to GND\n");
        return MAX6675_READ_ERROR;
    }
    if (raw & 0x0004) {
        fprintf(stderr, "MAX6675 short to VCC\n");
        return MAX6675_READ_ERROR;
    }

    return (float)(raw >> 2) * 0.25f;
}

static float calculate_pid(PIDController *pid, float setpoint, float actual) {
    float error = setpoint - actual;
    pid->integral += error;
    float derivative = error - pid->previous_error;
    float output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
    pid->previous_error = error;
    return output;
}

static void set_ssr_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > 1.0f) duty_cycle = 1.0f;
    if (gpioWrite(SSR_GPIO, (duty_cycle > 0.5f) ? 1 : 0) < 0) {
