static float get_target_temperature(float elapsed_time) {
    if (profile_size == 0) return 0.0f;
    if (elapsed_time <= profile[0].time) return profile[0].temperature;
    if (elapsed_time >= profile[profile_size - 1].time) return profile[profile_size - 1].temperature;
    for (int i = 0; i < profile_size - 1; i++) {
        if (elapsed_time >= profile[i].time && elapsed_time <= profile[i + 1].time) {
            float t1 = profile[i].time, t2 = profile[i + 1].time;
            float temp1 = profile[i].temperature, temp2 = profile[i + 1].temperature;
            return temp1 + (elapsed_time - t1) * (temp2 - temp1) / (t2 - t1);
