        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SSR_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SSR GPIO %d as output\n", SSR_GPIO);
        gpioTerminate();
        return 1;
    }
