#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/pwm.h>

#define HEATER_GPIO 17
#define PWM_GPIO 18
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 10000000  /* 10 ms => 100 Hz */
#define PWM_DUTY_MAX 1000000    /* 1 000 000 ns = 100 % */
#define LOG_FILE "greenhouse.log"
#define SENSOR_READ_INTERVAL 5
#define SENSOR_ERROR_TEMP -1000.0
#define MAX_SENSORS 4
#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define W1_SLAVE_ID_PREFIX "28-"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int setpoint = 25.0;
static double Kp = 1.0, Ki = 0.1, Kd = 0.01;
static double integral = 0.0, previous_error = 0.0;
static int pwm_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    ssize_t len = (ssize_t)strlen(value);
    ssize_t wr = write(fd, value, len);
    close(fd);
    return (wr == len) ? 0 : -1;
}

static int read_file(const char *path, char *buf, size_t len) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    ssize_t n = read(fd, buf, len - 1);
    close(fd);
    if (n < 0) return -1;
    buf[n] = '\0';
    return 0;
}

static int init_pwm(void) {
    pwm_fd = open("/dev/pwm0", O_RDWR);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to open /dev/pwm0: %s\n", strerror(errno));
        return -1;
    }
    struct pwm_chip chip;
    if (ioctl(pwm_fd, PWM_GET_CHIP, &chip) < 0) {
        fprintf(stderr, "PWM_GET_CHIP failed: %s\n", strerror(errno));
        close(pwm_fd); pwm_fd = -1; return -1;
    }
    struct pwm_config config = {
        .channel = PWM_CHANNEL,
        .period = PWM_PERIOD_NS,
        .duty_cycle = 0,
        .flags = PWM_ENABLE_OUTPUT
    };
    if (ioctl(pwm_fd, PWM_CONFIGURE, &config) < 0) {
        fprintf(stderr, "PWM_CONFIGURE failed: %s\n", strerror(errno));
        close(pwm_fd); pwm_fd = -1; return -1;
    }
    if (ioctl(pwm_fd, PWM_ENABLE, PWM_CHANNEL) < 0) {
        fprintf(stderr, "PWM_ENABLE failed: %s\n", strerror(errno));
        close(pwm_fd); pwm_fd = -1; return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (pwm_fd >= 0) {
        ioctl(pwm_fd, PWM_DISABLE, PWM_CHANNEL);
        ioctl(pwm_fd, PWM_SET_DUTY_CYCLE, 0);
        close(pwm_fd);
        pwm_fd = -1;
    }
    write_file("/sys/class/gpio/gpio17/value", "0");
    write_file("/sys/class/pwm/pwm0/export", "0");
    if (log_file) { fclose(log_file); log_file = NULL; }
}

static int set_relay(int state) {
    return write_file("/sys/class/gpio/gpio17/value", state ? "1" : "0");
}

static int set_pwm_duty(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int duty_ns = (duty_percent * PWM_DUTY_MAX) / 100;
    return ioctl(pwm_fd, PWM_SET_DUTY_CYCLE, duty_ns);
}

static int read_temperature(double *temp) {
    DIR *dir = opendir(W1_DEVICES_DIR);
    if (!dir) return -1;
    struct dirent *ent;
    char path[256];
    int count = 0;
    while ((ent = readdir(dir)) != NULL && count < MAX_SENSORS) {
        if (strncmp(ent->d_name, W1_SLAVE_ID_PREFIX, 4) == 0) {
            snprintf(path, sizeof(path), "%s%s/w1_slave", W1_DEVICES_DIR, ent->d_name);
            char buf[256];
            if (read_file(path, buf, sizeof(buf)) == 0) {
                char *crc = strstr(buf, "crc=");
                if (crc) {
                    crc += 4;
                    char *temp_str = strstr(crc, "t=");
                    if (temp_str) {
                        temp_str += 2;
                        long val = strtol(temp_str, NULL, 10);
                        *temp = val / 1000.0;
                        count++;
                    }
                }
            }
        }
    }
    closedir(dir);
    if (count == 0) return -1;
    return 0;
}

static double calculate_pid(double current_temp) {
    double error = setpoint - current_temp;
    integral += error;
    if (integral > 100.0) integral = 100.0;
    if (integral < 0.0) integral = 0.0;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;
    return output;
}

static void log_data(double avg_temp, double pid_output, int pwm_duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", ts, avg_temp, setpoint, pid_output, pwm_duty);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }
    setpoint = atoi(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);
    if (setpoint < 0 || setpoint > 50) {
        fprintf(stderr, "Setpoint must be between 0 and 50\n");
        return 1;
    }
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }
    if (init_pwm() < 0) {
        fprintf(stderr, "PWM initialization failed\n");
        cleanup();
        return 1;
    }
    if (write_file("/sys/class/gpio/export", "17") < 0) {
        fprintf(stderr, "Failed to export GPIO17: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (write_file("/sys/class/gpio/gpio17/direction", "out") < 0) {
        fprintf(stderr, "Failed to set GPIO17 direction: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    set_relay(0);
    while (running) {
        double temp = 0.0;
        if (read_temperature(&temp) < 0) {
            fprintf(stderr, "Sensor read error\n");
            temp = SENSOR_ERROR_TEMP;
        }
        double pid_output = calculate_pid(temp);
        int pwm_duty = (int)pid_output;
        set_pwm_duty(pwm_duty);
        set_relay(pwm_duty > 0 ? 1 : 0);
        log_data(temp, pid_output, pwm_duty);
        sleep(SENSOR_READ_INTERVAL);
    }
    cleanup();
    return 0;
}

