#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define AHT20_ADDR             0x38
#define AHT20_CMD_TRIGGER      0xAC
#define AHT20_CMD_READ_ID      0x00
#define AHT20_CMD_SOFT_RESET   0xBA
#define AHT20_CMD_CALIBRATE    0xE1
#define AHT20_ID               0x00
#define AHT20_RESET_DELAY_US   20000
#define AHT20_CALIB_DELAY_US   20000
#define AHT20_MEAS_DELAY_US    80000
#define AHT20_POLL_INTERVAL_S  5
#define AHT20_MAX_RETRIES      3
#define AHT20_RETRY_DELAY_US   10000
#define DEHUMIDIFIER_GPIO      17
#define HUMIDITY_HIGH          60.0f
#define HUMIDITY_LOW           55.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    for (int attempt = 0; attempt < AHT20_MAX_RETRIES; attempt++) {
        if (write(fd, &cmd, 1) == 1)
            return 0;
        if (attempt < AHT20_MAX_RETRIES - 1)
            gpioDelay(AHT20_RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < AHT20_MAX_RETRIES; attempt++) {
        if (read(fd, buf, len) == len)
            return 0;
        if (attempt < AHT20_MAX_RETRIES - 1)
            gpioDelay(AHT20_RETRY_DELAY_US);
    }
    return -1;
}

static int aht20_soft_reset(int fd)
{
    if (i2c_write_cmd(fd, AHT20_CMD_SOFT_RESET) != 0) {
        fprintf(stderr, "AHT20 soft reset write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(AHT20_RESET_DELAY_US);
    return 0;
}

static int aht20_calibrate(int fd)
{
    if (i2c_write_cmd(fd, AHT20_CMD_CALIBRATE) != 0) {
        fprintf(stderr, "AHT20 calibration write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(AHT20_CALIB_DELAY_US);
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity)
{
    uint8_t id_buf[8];
    if (i2c_read_bytes(fd, id_buf, 8) != 0) {
        fprintf(stderr, "AHT20 ID read failed: %s\n", strerror(errno));
        return -1;
    }
    if (id_buf[0] != AHT20_ID) {
        fprintf(stderr, "AHT20 ID mismatch: got 0x%02X, expected 0x%02X\n",
                id_buf[0], AHT20_ID);
        return -1;
    }

    if (i2c_write_cmd(fd, AHT20_CMD_TRIGGER) != 0) {
        fprintf(stderr, "AHT20 trigger write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(AHT20_MEAS_DELAY_US);

    uint8_t data[6];
    if (i2c_read_bytes(fd, data, 6) != 0) {
        fprintf(stderr, "AHT20 data read failed: %s\n", strerror(errno));
        return -1;
    }

    uint8_t status = data[0] & 0x80;
    if (status) {
        fprintf(stderr, "AHT20 busy or not calibrated (status=0x%02X)\n", status);
        return -1;
    }

    uint32_t raw_humidity = ((uint32_t)data[1] << 12) |
                           ((uint32_t)data[2] << 4)  |
                           ((uint32_t)data[3] >> 4);
    *humidity = (float)raw_humidity / 1048576.0f * 100.0f;
    return 0;
}

static void control_dehumidifier(float humidity)
{
    if (humidity > HUMIDITY_HIGH) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1);
        printf("Dehumidifier ON  (humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_LOW) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0);
        printf("Dehumidifier OFF (humidity: %.2f%%)\n", humidity);
    }
}

static void log_humidity(float humidity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("[%s] Humidity: %.2f%%\n", ts, humidity);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", DEHUMIDIFIER_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(DEHUMIDIFIER_GPIO, 0);

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (aht20_soft_reset(g_i2c_fd) != 0 || aht20_calibrate(g_i2c_fd) != 0) {
        fprintf(stderr, "AHT20 init failed; continuing with retries in loop\n");
    }

    while (g_running) {
        float humidity;
        if (aht20_read_humidity(g_i2c_fd, &humidity) == 0) {
            log_humidity(humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }
        sleep(AHT20_POLL_INTERVAL_S);
    }

    gpioWrite(DEHUMIDIFIER_GPIO, 0);
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    gpioTerminate();
    return 0;
}

