#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sock_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_humidity(float *humidity) {
    uint8_t cmd[2] = {0x02, 0x00};
    uint8_t buf[3];

    if (write(i2c_fd, cmd, 2) != 2) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }

    usleep(50000);

    if (read(i2c_fd, buf, 3) != 3) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        syslog(LOG_ERR, "CRC mismatch on humidity data");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    raw &= 0xFFFC;
    *humidity = -6.0 + 125.0 * (float)raw / 65536.0;

    return 0;
}

static int send_http_request(const char *json_data) {
    struct sockaddr_in server_addr;
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);

    if (inet_pton(AF_INET, "93.184.216.34", &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address: 93.184.216.34");
        close(fd);
        return -1;
    }

    if (connect(fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    char request[512];
    int request_len = snprintf(request, sizeof(request),
        "POST /humidity HTTP/1.1\r\n"
        "Host: api.example.com\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        strlen(json_data), json_data);

    if (request_len < 0 || request_len >= (int)sizeof(request)) {
        syslog(LOG_ERR, "Request buffer overflow");
        close(fd);
        return -1;
    }

    ssize_t sent = 0;
    while (sent < request_len) {
        ssize_t w = write(fd, request + sent, request_len - sent);
        if (w < 0) {
            if (errno == EINTR) continue;
            syslog(LOG_ERR, "Write failed: %s", strerror(errno));
            close(fd);
            return -1;
        }
        sent += w;
    }

    char response[1024];
    ssize_t r = read(fd, response, sizeof(response) - 1);
    if (r < 0) {
        syslog(LOG_ERR, "Read failed: %s", strerror(errno));
        close(fd);
        return -1;
    }
    response[r] = '\0';

    close(fd);
    return 0;
}

int main(void) {
    openlog("htu21d_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D monitor started");

    while (running) {
        float humidity = 0.0f;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_humidity(&humidity) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(1);
            }
        }

        if (success) {
            char json_data[64];
            snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);

            if (send_http_request(json_data) != 0) {
                syslog(LOG_ERR, "Failed to send HTTP request");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

