#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "pressure_log.txt"
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_SEC 2
#define CONVERSION_DELAY_MS 10

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_init(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bmp280_init(void) {
    uint8_t chip_id;
    if (i2c_read_reg8(i2c_fd, BMP280_REG_ID, &chip_id) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg8(i2c_fd, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    if (i2c_write_reg8(i2c_fd, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg8(i2c_fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    uint8_t calib_buf[24];
    if (i2c_read_block(i2c_fd, BMP280_REG_CALIB, calib_buf, 24) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    calib.dig_T1 = (uint16_t)(calib_buf[0] | (calib_buf[1] << 8));
    calib.dig_T2 = (int16_t)(calib_buf[2] | (calib_buf[3] << 8));
    calib.dig_T3 = (int16_t)(calib_buf[4] | (calib_buf[5] << 8));
    calib.dig_P1 = (uint16_t)(calib_buf[6] | (calib_buf[7] << 8));
    calib.dig_P2 = (int16_t)(calib_buf[8] | (calib_buf[9] << 8));
    calib.dig_P3 = (int16_t)(calib_buf[10] | (calib_buf[11] << 8));
    calib.dig_P4 = (int16_t)(calib_buf[12] | (calib_buf[13] << 8));
    calib.dig_P5 = (int16_t)(calib_buf[14] | (calib_buf[15] << 8));
    calib.dig_P6 = (int16_t)(calib_buf[16] | (calib_buf[17] << 8));
    calib.dig_P7 = (int16_t)(calib_buf[18] | (calib_buf[19] << 8));
    calib.dig_P8 = (int16_t)(calib_buf[20] | (calib_buf[21] << 8));
    calib.dig_P9 = (int16_t)(calib_buf[22] | (calib_buf[23] << 8));

    return 0;
}

static int bmp280_read_raw(int32_t *temp, int32_t *press) {
    uint8_t data[6];
    if (i2c_read_block(i2c_fd, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;

    *press = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *temp = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_temp) {
    double var1 = ((double)raw_temp / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * (double)calib.dig_T3;
    t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

static double bmp280_compensate_press(int32_t raw_press) {
    double var1 = ((double)t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * (double)calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)calib.dig_P4 * 65536.0);
    var1 = ((double)calib.dig_P3 * var1 * var1 / 524288.0 + (double)calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)calib.dig_P1;

    if (var1 == 0.0) return 0.0;

    double p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)calib.dig_P7) / 16.0;

    return p;
}

static void log_pressure(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f hPa\n", ts, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        i2c_fd = i2c_init();
        if (i2c_fd < 0) {
            fprintf(stderr, "I2C init failed, retrying (%d/%d)...\n", attempt + 1, RETRY_COUNT);
            sleep(1);
            continue;
        }
        if (bmp280_init() == 0) break;
        fprintf(stderr, "BMP280 init failed, retrying (%d/%d)...\n", attempt + 1, RETRY_COUNT);
        close(i2c_fd);
        i2c_fd = -1;
        sleep(1);
    }
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize BMP280 after %d attempts.\n", RETRY_COUNT);
        return 1;
    }

    printf("BMP280 initialized. Monitoring pressure...\n");

    while (running) {
        int32_t raw_temp, raw_press;
        if (bmp280_read_raw(&raw_temp, &raw_press) < 0) {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        double temp = bmp280_compensate_temp(raw_temp);
        double press = bmp280_compensate_press(raw_press);

        printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temp, press);

        if (press > PRESSURE_HIGH_THRESHOLD || press < PRESSURE_LOW_THRESHOLD) {
            log_pressure(press);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

