#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define I2C_BUS "/dev/i2c-1"
#define PIR_GPIO_LINE 17
#define GPIO_CHIP_NAME "gpiochip4"
#define LOG_FILE_PREFIX "sensor_data"
#define LOG_FILE_SUFFIX ".csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, buf, 2) != 2) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        *out = (int16_t)((buf[0] << 8) | buf[1]);
        return 0;
    }
    return -1;
}

static int read_temperature(float *temp) {
    int16_t raw;
    if (i2c_read_reg16(i2c_fd, 0x00, &raw) < 0) {
        fprintf(stderr, "Error: Failed to read TMP117 temperature after retries.\n");
        return -1;
    }
    *temp = (float)raw / 100.0f;
    return 0;
}

static int read_humidity(float *hum) {
    int16_t raw;
    if (i2c_read_reg16(i2c_fd, 0x00, &raw) < 0) {
        fprintf(stderr, "Error: Failed to read AHT20 humidity after retries.\n");
        return -1;
    }
    *hum = (float)raw / 1000.0f;
    return 0;
}

static int read_motion(int *motion) {
    int val = gpiod_line_get_value(pir_line);
    if (val < 0) {
        fprintf(stderr, "Error: Failed to read PIR sensor value.\n");
        return -1;
    }
    *motion = (val == 1) ? 1 : 0;
    return 0;
}

static int create_log_file(void) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char filename[256];
    strftime(filename, sizeof(filename), "%Y-%m-%d", tm_info);
    snprintf(filename + strlen(filename), sizeof(filename) - strlen(filename), "_%s%s", LOG_FILE_PREFIX, LOG_FILE_SUFFIX);

    log_file = fopen(filename, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    }
    return 0;
}

static void log_data(float temp, float hum, int motion) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temp, hum, motion);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Error setting TMP117 address");
    } else {
        printf("TMP117 initialized.\n");
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("Error setting AHT20 address");
    } else {
        printf("AHT20 initialized.\n");
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir_line) {
        perror("Error getting PIR GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        perror("Error requesting PIR GPIO line as input");
        cleanup();
        return 1;
    }

    if (create_log_file() < 0) {
        cleanup();
        return 1;
    }

    printf("Starting data logging...\n");

    while (running) {
        float temp = 0.0f, hum = 0.0f;
        int motion = 0;

        if (read_temperature(&temp) < 0) temp = -999.0f;
        if (read_humidity(&hum) < 0) hum = -999.0f;
        if (read_motion(&motion) < 0) motion = -1;

        log_data(temp, hum, motion);

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

