#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN  22
#define MOTOR_IN1_PIN  23
#define MOTOR_IN2_PIN  24

#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_SEC     5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int safe_set_value(struct gpiod_line *line, int val)
{
    if (gpiod_line_set_value(line, val) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Error: failed to set GPIO line value: %s", strerror(errno));
        log_message(buf);
        return -1;
    }
    return 0;
}

static int safe_set_output(struct gpiod_line *line)
{
    if (gpiod_line_request_output(line, "rain_window", 0) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Error: failed to request GPIO line as output: %s", strerror(errno));
        log_message(buf);
        return -1;
    }
    return 0;
}

static void motor_stop(struct gpiod_line *ena, struct gpiod_line *in1, struct gpiod_line *in2)
{
    safe_set_value(ena, 0);
    safe_set_value(in1, 0);
    safe_set_value(in2, 0);
}

static int motor_close_window(struct gpiod_line *ena, struct gpiod_line *in1, struct gpiod_line *in2)
{
    log_message("Closing window...");

    if (safe_set_value(in1, 1) < 0) return -1;
    if (safe_set_value(in2, 0) < 0) return -1;
    if (safe_set_value(ena, 1) < 0) return -1;

    for (int i = 0; i < MOTOR_RUN_SEC && g_running; i++)
        sleep(1);

    motor_stop(ena, in1, in2);
    log_message("Window closed.");
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *ena_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_message("Error: cannot open gpiochip4");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena_line  = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    in1_line  = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line  = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_line || !ena_line || !in1_line || !in2_line) {
        log_message("Error: cannot get one or more GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        log_message("Error: cannot request rain sensor line as input");
        goto cleanup;
    }

    if (safe_set_output(ena_line) < 0 ||
        safe_set_output(in1_line) < 0 ||
        safe_set_output(in2_line) < 0) {
        goto cleanup;
    }

    log_message("Rain sensor monitoring started.");

    while (g_running) {
        int val = gpiod_line_get_value(rain_line);
        if (val < 0) {
            char buf[128];
            snprintf(buf, sizeof(buf), "Error: failed to read rain sensor: %s", strerror(errno));
            log_message(buf);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (val == 0) {
            log_message("Rain detected!");
            if (motor_close_window(ena_line, in1_line, in2_line) < 0) {
                log_message("Error: motor control failed");
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    log_message("Shutting down...");
    ret = EXIT_SUCCESS;

cleanup:
    motor_stop(ena_line, in1_line, in2_line);
    if (rain_line) gpiod_line_release(rain_line);
    if (ena_line)  gpiod_line_release(ena_line);
    if (in1_line)  gpiod_line_release(in1_line);
    if (in2_line)  gpiod_line_release(in2_line);
    if (chip)      gpiod_chip_close(chip);
    return ret;
}

