#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read CPU idle and non-idle jiffies from /proc/stat. */
static int read_cpu_jiffies(unsigned long long *idle, unsigned long long *non_idle)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strncmp(line, "cpu ", 4) != 0) {
        fprintf(stderr, "Unexpected format in /proc/stat\n");
        return -1;
    }

    unsigned long long vals[8];
    int n = sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu",
                   &vals[0], &vals[1], &vals[2], &vals[3],
                   &vals[4], &vals[5], &vals[6], &vals[7]);
    if (n < 4) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        return -1;
    }

    *idle    = vals[3];
    *non_idle = vals[0] + vals[1] + vals[2] + vals[4] + vals[5] + vals[6] + vals[7];
    return 0;
}

/* Map 0..100 % load to a color between green and red. */
static void load_to_color(int load, int *r, int *g, int *b)
{
    if (load < 0) load = 0;
    if (load > 100) load = 100;

    if (load < 50) {
        *r = (load * 255) / 50;
        *g = 255;
        *b = 0;
    } else {
        *r = 255;
        *g = 255 - ((load - 50) * 255) / 50;
        *b = 0;
    }
}

/* Common-anode: LED off = full PWM (255). */
static void set_led_color(int r, int g, int b)
{
    gpioPWM(RED_PIN,   255 - r);
    gpioPWM(GREEN_PIN, 255 - g);
    gpioPWM(BLUE_PIN,  255 - b);
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure PWM pins --- */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 0..255 for each channel. */
    gpioSetPWMrange(RED_PIN,   255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN,  255);

    /* Start with LED off (full PWM for common anode). */
    set_led_color(0, 0, 0, 0);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        set_led_color(0, 0, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    unsigned long long prev_idle = 0, prev_non_idle = 0;
    int first_sample = 1;

    while (g_running) {
        unsigned long long idle, non_idle;

        if (read_cpu_jiffies(&idle, &non_idle) != 0) {
            /* Sensor read failed: turn LED off and retry. */
            set_led_color(0, 0, 0, 0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (first_sample) {
            prev_idle    = idle;
            prev_non_idle = non_idle;
            first_sample = 0;
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        unsigned long long totald = (idle    - prev_idle)    +
                                    (non_idle - prev_non_idle);
        unsigned long long idled  = idle    - prev_idle;
        unsigned long long nidle  = non_idle - prev_non_idle;

        int load = 0;
        if (totald > 0) {
            load = (int)((1.0 - (double)idled / totald) * 100.0);
            if (load < 0) load = 0;
            if (load > 100) load = 100;
        }

        int r, g, b;
        load_to_color(load, &r, &g, &b);
        set_led_color(r, g, b);

        prev_idle    = idle;
        prev_non_idle = non_idle;

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* --- Cleanup --- */
    set_led_color(0, 0, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

