#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define BUFFER_SIZE 20

#define TEMP_THRESHOLD_LOW 25.0
#define TEMP_THRESHOLD_MEDIUM 40.0
#define TEMP_THRESHOLD_HIGH 60.0
#define DUTY_CYCLE_LOW 0
#define DUTY_CYCLE_MEDIUM 127
#define DUTY_CYCLE_HIGH 200
#define DUTY_CYCLE_FULL 255

#define MAX31855_FAULT_MASK 0x00000004
#define MAX31855_OPEN_CIRCUIT_MASK 0x00000002
#define MAX31855_GND_SHORT_MASK 0x00000001

typedef struct {
    time_t timestamp;
    float temperature;
    int pwm_duty_cycle;
} LogEntry;

typedef struct {
    LogEntry entries[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static CircularBuffer log_buffer;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialise PWM duty cycle on GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

static int read_max31855(float *temperature) {
    char tx_buffer[4] = {0x00, 0x00, 0x00, 0x00};
    char rx_buffer[4] = {0x00, 0x00, 0x00, 0x00};

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw_data = ((uint32_t)(uint8_t)rx_buffer[0] << 24) |
                        ((uint32_t)(uint8_t)rx_buffer[1] << 16) |
                        ((uint32_t)(uint8_t)rx_buffer[2] << 8)  |
                        ((uint32_t)(uint8_t)rx_buffer[3]);

    if (raw_data & MAX31855_FAULT_MASK) {
        if (raw_data & MAX31855_OPEN_CIRCUIT_MASK) {
            fprintf(stderr, "MAX31855 fault: Open circuit\n");
        } else if (raw_data & MAX31855_GND_SHORT_MASK) {
            fprintf(stderr, "MAX31855 fault: Short to GND\n");
        } else {
            fprintf(stderr, "MAX31855 fault: Unknown\n");
        }
        return -1;
    }

    int16_t thermocouple_data = (int16_t)((raw_data >> 18) & 0x3FFF);
    if (thermocouple_data & 0x2000) {
        thermocouple_data |= 0xC000;
    }
    *temperature = thermocouple_data * 0.25;
    return 0;
}

static int calculate_pwm_duty_cycle(float temperature) {
    if (temperature < TEMP_THRESHOLD_LOW) {
        return DUTY_CYCLE_LOW;
    } else if (temperature < TEMP_THRESHOLD_MEDIUM) {
        return (int)(((temperature - TEMP_THRESHOLD_LOW) / (TEMP_THRESHOLD_MEDIUM - TEMP_THRESHOLD_LOW)) * DUTY_CYCLE_MEDIUM);
    } else if (temperature < TEMP_THRESHOLD_HIGH) {
        return DUTY_CYCLE_MEDIUM + (int)(((temperature - TEMP_THRESHOLD_MEDIUM) / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_MEDIUM)) * (DUTY_CYCLE_HIGH - DUTY_CYCLE_MEDIUM));
    } else {
        return DUTY_CYCLE_FULL;
    }
}

static void update_fan_speed(int pwm_duty_cycle) {
    if (gpioPWM(FAN_GPIO, pwm_duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle to %d\n", pwm_duty_cycle);
    }
}

static void add_to_circular_buffer(CircularBuffer *buffer, time_t timestamp, float temperature, int pwm_duty_cycle) {
    buffer->entries[buffer->head].timestamp = timestamp;
    buffer->entries[buffer->head].temperature = temperature;
    buffer->entries[buffer->head].pwm_duty_cycle = pwm_duty_cycle;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

static void print_circular_buffer(CircularBuffer *buffer) {
    printf("\n--- Log Buffer Contents ---\n");
    int start_index = (buffer->count == BUFFER_SIZE) ? buffer->head : 0;
    for (int i = 0; i < buffer->count; i++) {
        int index = (start_index + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&buffer->entries[index].timestamp);
        if (tm_info != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            snprintf(time_str, sizeof(time_str), "Invalid Time");
        }
        printf("[%s] Temp: %.2f C, PWM: %d\n", time_str, buffer->entries[index].temperature, buffer->entries[index].pwm_duty_cycle);
    }
    printf("--- End of Log Buffer ---\n\n");
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    log_buffer.head = 0;
    log_buffer.count = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register signal handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring and fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31855(&temperature) == 0) {
            int pwm_duty_cycle = calculate_pwm_duty_cycle(temperature);
            update_fan_speed(pwm_duty_cycle);
            add_to_circular_buffer(&log_buffer, time(NULL), temperature, pwm_duty_cycle);
            printf("Temp: %.2f C, PWM: %d\n", temperature, pwm_duty_cycle);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping fan update.\n");
        }
        sleep(1);
    }

    print_circular_buffer(&log_buffer);
    cleanup();
    printf("Exiting.\n");
    return 0;
}

