#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define LOG_FILE "rtd_log.csv"
#define R0 4300.0
#define A 0.0039083
#define B -0.0000005775
#define C -0.000000000004183
#define RTD_NOMINAL_RESISTANCE 100.0
#define RTD_MAX_RESISTANCE 200.0
#define RTD_MIN_RESISTANCE 0.0
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    uint8_t bits = 8;
    uint8_t mode = SPI_MODE_0;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto fail;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto fail;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto fail;
    }
    return 0;

fail:
    close(spi_fd);
    spi_fd = -1;
    return -1;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }
    return 0;
}

static int read_max31865(uint16_t *rtd_raw, uint8_t *fault) {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};

    if (spi_transfer(tx, rx, 4) < 0) {
        return -1;
    }

    *fault = rx[3] & 0x07;
    if (*fault != 0) {
        return -2;
    }

    *rtd_raw = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static float rtd_resistance(uint16_t rtd_raw) {
    uint16_t rtd_code = rtd_raw >> 1;
    return (rtd_code * RTD_NOMINAL_RESISTANCE) / 32768.0;
}

static float calculate_temperature(float rtd_resistance) {
    if (rtd_resistance < RTD_MIN_RESISTANCE || rtd_resistance > RTD_MAX_RESISTANCE) {
        return -999.0;
    }
    float Z = rtd_resistance / RTD_NOMINAL_RESISTANCE;
    float Z2 = Z * Z;
    float Z3 = Z2 * Z;
    float temp = -A + sqrt(A * A - 4 * B * (1 - Z));
    temp = temp / (2 * B);
    if (temp < 0) {
        temp = -A - sqrt(A * A - 4 * B * (1 - Z));
        temp = temp / (2 * B);
    }
    temp = temp - C * Z3;
    return temp;
}

static void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp != NULL) {
        fprintf(log_fp, "%s,%.2f\n", timestamp, temperature);
        fflush(log_fp);
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp != NULL) {
