#define B -0.0000005775
#define C -0.000000000004183
#define RTD_NOMINAL_RESISTANCE 100.0
#define RTD_MAX_RESISTANCE 200.0
#define RTD_MIN_RESISTANCE 0.0
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    uint8_t bits = 8;
    uint8_t mode = SPI_MODE_0;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto fail;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto fail;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto fail;
    }
    return 0;

fail:
    close(spi_fd);
    spi_fd = -1;
    return -1;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

