    if (init_bme280(i2c_fd, &cal) < 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }
    log_file = fopen("bme280_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    while (running) {
        float temp, hum, press;
        if (read_bme280_data(i2c_fd, &cal, &temp, &hum, &press) == 0) {
            log_data(log_file, temp, hum, press);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(5);
    }
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

