    if (i2c_read_block(fd, 0xE1, h_buf, 7) < 0) return -1;
    cal->dig_H2 = (int16_t)(h_buf[1] << 8 | h_buf[0]);
    cal->dig_H3 = h_buf[2];
    cal->dig_H4 = (int16_t)((h_buf[3] << 4) | (h_buf[4] & 0x0F));
    cal->dig_H5 = (int16_t)((h_buf[5] << 4) | (h_buf[4] >> 4));
    cal->dig_H6 = (int8_t)h_buf[6];
    return 0;
