static int init_bme280(int fd, bme280_calib_data *cal) {
    uint8_t id;
    if (i2c_read_reg8(fd, BME280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BME280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", id, BME280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
        return -1;
    }
    uint8_t status;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg8(fd, BME280_REG_STATUS, &status) < 0) {
            fprintf(stderr, "Error reading status: %s\n", strerror(errno));
            return -1;
        }
        if ((status & 0x01) == 0) break;
        usleep(2000);
    }
    if (i2c_write_reg8(fd, BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg8(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    if (read_calibration_data(fd, cal) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bme280_data(int fd, const bme280_calib_data *cal, float *temp, float *hum, float *press) {
    uint8_t data[8];
    if (i2c_read_block(fd, BME280_REG_DATA, data, 8) < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }
    int32_t adc_P = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t adc_T = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t adc_H = (data[6] << 8) | data[7];
    int32_t t_fine;
    *temp = compensate_temperature(adc_T, cal, &t_fine) / 100.0f;
    *press = compensate_pressure(adc_P, cal, t_fine) / 100.0f;
    *hum = compensate_humidity(adc_H, cal, t_fine) / 1024.0f;
    return 0;
}

static void log_data(FILE *fp, float temp, float hum, float press) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum, press);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    bme280_calib_data cal;
    if (init_bme280(i2c_fd, &cal) < 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }
    log_file = fopen("bme280_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    while (running) {
        float temp, hum, press;
        if (read_bme280_data(i2c_fd, &cal, &temp, &hum, &press) == 0) {
            log_data(log_file, temp, hum, press);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(5);
    }
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

