#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define BMP180_I2C_ADDR 0x77
#define ALERT_GPIO 24
#define BUFFER_SIZE 120
#define DEVIATION_THRESHOLD 5.0f
#define SAMPLE_INTERVAL_MS 50

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    time_t timestamp;
    float pressure;
} PressureReading;

static PressureReading pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t reg, char *buf, int count) {
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, count) != count) {
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int handle, int16_t *raw_temp) {
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) {
        return -1;
    }
    gpioDelay(5000);
    char buf[2];
    if (i2c_read_bytes(handle, BMP180_REG_MSB, buf, 2) != 0) {
        return -1;
    }
    *raw_temp = (int16_t)((buf[0] << 8) | (buf[1] & 0xFF));
    return 0;
}

static int read_raw_pressure(int handle, int32_t *raw_pressure) {
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE0) != 0) {
        return -1;
    }
    gpioDelay(5000);
    char buf[3];
    if (i2c_read_bytes(handle, BMP180_REG_MSB, buf, 3) != 0) {
        return -1;
    }
    *raw_pressure = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | (buf[2] & 0xFF)) >> 8;
    return 0;
}

static float calculate_pressure(int16_t raw_temp, int32_t raw_pressure) {
    float temperature = (float)raw_temp / 10.0f;
    float pressure = (float)raw_pressure / 256.0f;
    return pressure;
}

static void add_reading(float pressure) {
    pressure_buffer[buffer_index].timestamp = time(NULL);
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static float calculate_average() {
    if (buffer_count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) {
        sum += pressure_buffer[i].pressure;
    }
    return sum / (float)buffer_count;
}

static void check_deviation(float current_pressure) {
    float average = calculate_average();
    float deviation = current_pressure - average;
    if (deviation < 0) deviation = -deviation;
    if (deviation > DEVIATION_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1);
        fprintf(stderr, "ALERT: Pressure deviation %.2f hPa exceeds threshold %.2f hPa\n", deviation, DEVIATION_THRESHOLD);
    } else {
        gpioWrite(ALERT_GPIO, 0);
    }
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int16_t raw_temp;
    int32_t raw_pressure;
    if (read_raw_temperature(i2c_handle, &raw_temp) != 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return;
    }
    if (read_raw_pressure(i2c_handle, &raw_pressure) != 0) {
        fprintf(stderr, "Error reading pressure: %s\n", strerror(errno));
        return;
    }
    float pressure = calculate_pressure(raw_temp, raw_pressure);
    add_reading(pressure);
    check_deviation(pressure);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);
    signal(SIGINT, signal_handler);
    if (gpioSetTimerFunc(0, SAMPLE_INTERVAL_MS, timer_callback) != 0) {
        fprintf(stderr, "Error setting timer: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) {
        gpioDelay(100000);
    }
    gpioSetTimerFunc(0, SAMPLE_INTERVAL_MS, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

