static int read_calibration(bmp180_cal_t *cal) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read 22 bytes of calibration data\n");
        return -1;
