#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS          "/dev/i2c-1"
#define LM75_ADDR        0x48
#define ALERT_GPIO       18
#define BUFFER_SIZE      60
#define TEMP_THRESHOLD   28.0f
#define SAMPLE_PERIOD_S  1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static pthread_mutex_t buffer_mutex;
static float temp_buffer[BUFFER_SIZE];
static int   buffer_index = 0;
static int   buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALERT_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(ALERT_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialise GPIO %d state\n", ALERT_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp) {
    uint8_t reg = 0x00;
    uint8_t buf[2];

    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error (register select): %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error (temperature): %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = (float)raw / 256.0f;
    return 0;
}

static void add_temperature(float temp) {
    pthread_mutex_lock(&buffer_mutex);
    temp_buffer[buffer_index] = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    pthread_mutex_unlock(&buffer_mutex);
}

static float calculate_average(void) {
    float sum = 0.0f;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < buffer_count; i++) sum += temp_buffer[i];
    pthread_mutex_unlock(&buffer_mutex);
    return (buffer_count > 0) ? (sum / buffer_count) : 0.0f;
}

static void *alert_thread(void *arg) {
    (void)arg;
    while (running) {
        float avg;
        pthread_mutex_lock(&buffer_mutex);
        avg = calculate_average();
        pthread_mutex_unlock(&buffer_mutex);

        if (avg > TEMP_THRESHOLD) {
            if (gpioWrite(ALERT_GPIO, 1) < 0) {
                fprintf(stderr, "Failed to set alert GPIO high\n");
            }
        } else {
            if (gpioWrite(ALERT_GPIO, 0) < 0) {
                fprintf(stderr, "Failed to set alert GPIO low\n");
            }
        }
        sleep(1);
    }
    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        pthread_mutex_destroy(&buffer_mutex);
        return 1;
    }

    if (init_gpio() != 0) {
        close(i2c_fd);
        pthread_mutex_destroy(&buffer_mutex);
        return 1;
