    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        pthread_mutex_destroy(&buffer_mutex);
        return 1;
    }

    if (init_gpio() != 0) {
        close(i2c_fd);
        pthread_mutex_destroy(&buffer_mutex);
        return 1;
    }

    pthread_t alert_tid;
    if (pthread_create(&alert_tid, NULL, alert_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create alert thread\n");
        gpioTerminate();
        close(i2c_fd);
        pthread_mutex_destroy(&buffer_mutex);
        return 1;
    }

    while (running) {
