static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer g_buffer;
static int16_t        g_ac1, g_ac2, g_ac3, g_b1, g_b2, g_mb, g_mc, g_md;
static uint16_t       g_ac4, g_ac5, g_ac6;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(handle, reg, val) < 0) return -1;
    return 0;
}

static int read_calibration(int handle) {
    uint8_t buf[BMP180_CALIB_LEN];
    if (i2c_read_block(handle, BMP180_REG_CALIB_START, buf, sizeof(buf)) < 0) {
        fprintf(stderr, "Error: failed to read calibration data\n");
        return -1;
    }
    g_ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    g_ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    g_ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    g_ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    g_ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    g_ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    g_b1  = (int16_t)((buf[12] << 8) | buf[13]);
    g_b2  = (int16_t)((buf[14] << 8) | buf[15]);
    g_mb  = (int16_t)((buf[16] << 8) | buf[17]);
    g_mc  = (int16_t)((buf[18] << 8) | buf[19]);
    g_md  = (int16_t)((buf[20] << 8) | buf[21]);
    if (g_ac1 == 0 && g_ac1 == 0 && g_ac1 == 0) {
        fprintf(stderr, "Error: calibration data all zero (sensor absent?)\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int handle, int32_t *raw) {
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2c_read_block(handle, BMP180_REG_MSB, buf, 2) < 0) return -1;
    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *raw) {
    uint8_t cmd = BMP180_CMD_PRESS_BASE | (BMP180_OSS << 6);
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, cmd) < 0) return -1;
    gpioDelay(2 + (3 << BMP180_OSS));
    uint8_t buf[3];
    if (i2c_read_block(handle, BMP180_REG_MSB, buf, 3) < 0) return -1;
    *raw = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static float calculate_temperature(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)g_ac6) * (int32_t)g_ac5) >> 15;
    int32_t x2 = ((int32_t)g_mc << 11) / (x1 + (int32_t)g_md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = ((ut - (int32_t)g_ac6) * (int32_t)g_ac5) >> 15;
    int32_t x2 = ((int32_t)g_mc << 11) / (x1 + (int32_t)g_md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)g_b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)g_ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)g_ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)g_ac3 * b6) >> 13;
    x2 = ((int32_t)g_b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)g_ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else                 p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p;
}

static void buffer_add(CircularBuffer *buf, SensorData d) {
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void timer_callback(void *user) {
    (void)user;
    if (!g_running) return;
    int32_t ut, up;
    if (read_raw_temperature(g_i2c_handle, &ut) < 0) {
        fprintf(stderr, "Error: temperature read failed\n");
        return;
    }
    if (read_raw_pressure(g_i2c_handle, &up) < 0) {
        fprintf(stderr, "Error: pressure read failed\n");
        return;
    }
    float temp = calculate_temperature(ut);
    float pres = calculate_pressure(up, ut);
    SensorData d;
    d.timestamp = time(NULL);
    d.temperature = temp;
    d.pressure = pres;
    buffer_add(&g_buffer, d);
    printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n",
           (long)d.timestamp, d.temperature, d.pressure);
    gpioWrite(FAN_GPIO, temp > TEMP_THRESHOLD ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (addr 0x%02X): %d\n", BMP180_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration(g_i2c_handle) < 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);
    g_buffer.head = 0;
    g_buffer.count = 0;
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to set timer\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (g_running) gpioDelay(100000);
    gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, NULL, NULL);
    gpioWrite(FAN_GPIO, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

