#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 0
#define DEBOUNCE_MS 200
#define LOG_INTERVAL_S 2
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static int i2c_fd = -1;
static FILE *log_file = NULL;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg16u(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int bmp180_read_calibration(int fd, bmp180_cal_t *cal) {
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1, &cal->ac1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC2, &cal->ac2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC3, &cal->ac3) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC4, &cal->ac4) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC5, &cal->ac5) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC6, &cal->ac6) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B1, &cal->b1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B2, &cal->b2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MB, &cal->mb) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MC, &cal->mc) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MD, &cal->md) < 0) return -1;
    return 0;
}

static int bmp180_read_raw_temp(int fd, int32_t *raw_temp) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    *raw_temp = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int bmp180_read_raw_pressure(int fd, int32_t *raw_pressure) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) return -1;
    gpioDelay(2000 + (3000 << BMP180_OSS));
    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_XLSB, &xlsb) < 0) return -1;
    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

static double bmp180_compute_pressure(int32_t raw_temp, int32_t raw_pressure, const bmp180_cal_t *cal) {
    int32_t x1 = ((raw_temp - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal->ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)raw_pressure - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (double)p;
}

static void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, %.2f\n", ts, pressure);
    fflush(log_file);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

static void cleanup(void) {
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
