#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 25.0
#define KP 1.0
#define KI 0.1
#define MAX_DUTY_CYCLE 80.0
#define LOG_FILE "heater_log.csv"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temperature) {
    char buffer[4] = {0};
    int bytes_read = spiRead(handle, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "SPI read error: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)buffer[0] << 24) |
                   ((uint32_t)(uint8_t)buffer[1] << 16) |
                   ((uint32_t)(uint8_t)buffer[2] << 8)  |
                   ((uint32_t)(uint8_t)buffer[3]);
    if (raw & 0x00010000) {
        if (raw & 0x00000004) fprintf(stderr, "MAX31855 fault: open circuit\n");
        if (raw & 0x00000002) fprintf(stderr, "MAX31855 fault: short to GND\n");
        if (raw & 0x00000001) fprintf(stderr, "MAX31855 fault: short to VCC\n");
        return -2;
    }
    int16_t temp_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (temp_raw & 0x2000) temp_raw |= 0xC000;
    *temperature = temp_raw * 0.25;
    return 0;
}

static void set_heater_duty(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;
    gpioPWM(HEATER_GPIO, (int)duty_cycle);
}

static void log_data(float temperature, float duty_cycle, const char *error_msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    if (error_msg) {
        fprintf(log_file, "%s,%.2f,%.2f,%s\n", timestamp, temperature, duty_cycle, error_msg);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f,\n", timestamp, temperature, duty_cycle);
    }
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%),Error\n");
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    float integral = 0.0;
    float last_temperature = 0.0;
    while (running) {
        float temperature;
        int rc = read_max31855(spi_handle, &temperature);
        if (rc == 0) {
            float error = TARGET_TEMPERATURE - temperature;
            integral += error;
            float duty_cycle = KP * error + KI * integral;
            if (duty_cycle < 0.0) duty_cycle = 0.0;
            if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;
            set_heater_duty(duty_cycle);
            log_data(temperature, duty_cycle, NULL);
            last_temperature = temperature;
        } else {
            set_heater_duty(0.0);
            log_data(0.0, 0.0, "SPI or MAX31855 fault");
            if (rc == -2) {
                integral = 0.0;
            }
        }
        time_sleep(1.0);
    }
    set_heater_duty(0.0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

