#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define POLL_DELAY_US 500000  /* 0.5 s */

/* Common-anode RGB: 0 duty = full brightness, 255 duty = off */
#define PWM_OFF  255
#define PWM_ON   0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        if (ferror(fp))
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        else
            fprintf(stderr, "Temperature read failed (unexpected format)\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "Warning: error closing %s: %s\n", TEMP_FILE, strerror(errno));

    return temp;
}

static int set_led_color(int red, int green, int blue)
{
    int rc = 0;

    if (gpioPWM(RED_PIN,   red)   < 0) { fprintf(stderr, "gpioPWM red failed\n");   rc = -1; }
    if (gpioPWM(GREEN_PIN, green) < 0) { fprintf(stderr, "gpioPWM green failed\n"); rc = -1; }
    if (gpioPWM(BLUE_PIN,  blue)  < 0) { fprintf(stderr, "gpioPWM blue failed\n");  rc = -1; }

    return rc;
}

static void turn_off_led(void)
{
    gpioPWM(RED_PIN,   PWM_OFF);
    gpioPWM(GREEN_PIN, PWM_OFF);
    gpioPWM(BLUE_PIN,  PWM_OFF);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM pins: 0‑255 range, 1000 Hz */
    if (gpioSetPWMrange(RED_PIN,   255) < 0 ||
