#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_IP "yourserver.com"
#define SERVER_PORT 80
#define MAX_RETRIES 3
#define DHT22_TIMEOUT 200
#define DHT22_MAX_PULSES 85

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(int gpio, int level, int timeout_us) {
    int elapsed = 0;
    while (gpioRead(gpio) != level) {
        if (elapsed >= timeout_us) return -1;
        gpioDelay(1);
        elapsed++;
    }
    return elapsed;
}

static int read_dht22(int gpio, float *temperature, float *humidity) {
    int pulses[DHT22_MAX_PULSES];
    int pulse_count = 0;
    int last_state = 1;
    int timeout;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(2000);
    gpioWrite(gpio, 1);
    gpioDelay(30);
    gpioSetMode(gpio, PI_INPUT);

    timeout = wait_for_level(gpio, 0, DHT22_TIMEOUT);
    if (timeout < 0) return -1;
    timeout = wait_for_level(gpio, 1, DHT22_TIMEOUT);
    if (timeout < 0) return -1;
    timeout = wait_for_level(gpio, 0, DHT22_TIMEOUT);
    if (timeout < 0) return -1;

    for (int i = 0; i < DHT22_MAX_PULSES; i++) {
        timeout = wait_for_level(gpio, 1, DHT22_TIMEOUT);
        if (timeout < 0) return -1;
        timeout = wait_for_level(gpio, 0, DHT22_TIMEOUT);
        if (timeout < 0) return -1;
        pulses[i] = timeout;
        if (pulse_count == 0 && timeout < 5) return -1;
        last_state = 0;
        pulse_count++;
    }

    if (pulse_count < 40) return -1;

    unsigned char data[5] = {0};
    for (int i = 0; i < 40; i++) {
        int idx = i / 8;
        int bit = i % 8;
        if (pulses[i] > 50) {
            data[idx] |= (1 << (7 - bit));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -2;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

static int send_http_request(const char *ip, int port, const char *json_payload) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect");
        close(sock);
        return -1;
    }

    char request[512];
    int request_len = snprintf(request, sizeof(request),
        "POST /api/humidity HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        ip, strlen(json_payload), json_payload);

    if (request_len < 0 || (size_t)request_len >= sizeof(request)) {
        fprintf(stderr, "Request buffer overflow\n");
        close(sock);
        return -1;
    }

    ssize_t sent = 0;
    while (sent < request_len) {
        ssize_t w = write(sock, request + sent, request_len - sent);
        if (w < 0) {
            perror("write");
            close(sock);
            return -1;
        }
        sent += w;
    }

    char response[1024];
    ssize_t r = read(sock, response, sizeof(response) - 1);
    if (r < 0) {
        perror("read");
        close(sock);
        return -1;
    }
    response[r] = '\0';

    close(sock);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    float temperature, humidity;
    int retries = 0;
    int success = 0;

    while (retries < MAX_RETRIES && running) {
        int result = read_dht22(DHT22_GPIO, &temperature, &humidity);
        if (result == 0) {
            success = 1;
            break;
        } else if (result == -2) {
            fprintf(stderr, "DHT22 checksum error\n");
        } else {
            fprintf(stderr, "DHT22 read error\n");
        }
        retries++;
        if (retries < MAX_RETRIES) {
            sleep(2);
        }
    }

    if (!success) {
        fprintf(stderr, "Failed to read DHT22 after %d retries\n", MAX_RETRIES);
        gpioTerminate();
        return 1;
    }

    char json_payload[128];
    snprintf(json_payload, sizeof(json_payload),
             "{\"temperature\": %.1f, \"humidity\": %.1f}",
             temperature, humidity);

    retries = 0;
    success = 0;
    while (retries < MAX_RETRIES && running) {
        if (send_http_request(SERVER_IP, SERVER_PORT, json_payload) == 0) {
            success = 1;
            break;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            sleep(2);
        }
    }

    if (!success) {
        fprintf(stderr, "Failed to send HTTP request after %d retries\n", MAX_RETRIES);
    }

    gpioTerminate();
    return 0;
}

