#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define BMP180_TEMP_CMD 0x2E
#define BMP180_PRESSURE_CMD 0x34
#define DEBOUNCE_US 200000
#define LOG_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 26000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_interrupt_tick = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_word(int handle, uint8_t reg, int16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_word_u(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_calibration_data(int handle) {
    if (i2c_read_word(handle, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (i2c_read_word_u(handle, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (i2c_read_word_u(handle, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (i2c_read_word_u(handle, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_MD, &md) < 0) return -1;
    if (ac1 == 0 && ac2 == 0 && ac3 == 0 && ac4 == 0 && ac5 == 0 && ac6 == 0) {
        fprintf(stderr, "Error: BMP180 calibration data is invalid (all zeros).\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int handle, int32_t *raw_temp) {
    char buf[2];
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_TEMP_CMD) < 0) return -1;
    gpioDelay(5000);
    if (i2cWriteByte(handle, BMP180_REG_MSB) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *raw_temp = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *raw_pressure) {
    char buf[3];
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_PRESSURE_CMD + (BMP180_OSS << 6)) < 0) return -1;
    gpioDelay(CONVERSION_DELAY_US);
    if (i2cWriteByte(handle, BMP180_REG_MSB) < 0) return -1;
    if (i2cReadDevice(handle, buf, 3) != 3) return -1;
    *raw_pressure = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
