        start_tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 1) {
            if (gpioTick() - start_tick > 100000) {
                syslog(LOG_ERR, "DHT22: timeout waiting for bit %d (high)", i);
                return -1;
            }
        }
        end_tick = gpioTick();
        duration = end_tick - start_tick;
        if (duration > 50) {
            bits[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if ((bits[0] + bits[1] + bits[2] + bits[3]) != bits[4]) {
        syslog(LOG_ERR, "DHT22: checksum error");
        return -1;
    }

    data->humidity = (float)((bits[0] << 8) | bits[1]) / 10.0;
    data->temperature = (float)(((bits[2] & 0x7F) << 8) | bits[3]) / 10.0;
    if (bits[2] & 0x80) {
        data->temperature = -data->temperature;
    }
    data->error = 0;
    return 0;
}

static int format_json(DHT22Data *data, char *json_string, size_t max_len) {
    int ret = snprintf(json_string, max_len, "{\"temperature\":%.1f,\"humidity\":%.1f}", data->temperature, data->humidity);
    if (ret < 0 || (size_t)ret >= max_len) {
        syslog(LOG_ERR, "JSON formatting failed");
        return -1;
    }
    return 0;
}

static size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    (void)contents;
    (void)userp;
    return size * nmemb;
}

static int send_http_request(const char *json_string) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "curl_slist_append() failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, api_endpoint);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    int ret = 0;
    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        ret = -1;
    } else {
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code < 200 || http_code >= 300) {
            syslog(LOG_ERR, "HTTP request failed with code: %ld", http_code);
            ret = -1;
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

static void cleanup(void) {
    gpioTerminate();
    curl_global_cleanup();
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_endpoint = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <api_endpoint>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting DHT22 monitor");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        DHT22Data data;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && !read_ok && running) {
            if (read_dht22(&data) == 0) {
                read_ok = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    syslog(LOG_WARNING, "DHT22 read failed, retrying in %d seconds...", RETRY_DELAY);
                    sleep(RETRY_DELAY);
                }
            }
        }

        if (read_ok) {
            char json_string[MAX_JSON_LENGTH];
            if (format_json(&data, json_string, sizeof(json_string)) == 0) {
                syslog(LOG_INFO, "JSON: %s", json_string);
                int post_retries = 0;
                int post_ok = 0;
                while (post_retries < MAX_RETRIES && !post_ok && running) {
                    if (send_http_request(json_string) == 0) {
                        post_ok = 1;
                    } else {
                        post_retries++;
                        if (post_retries < MAX_RETRIES) {
                            syslog(LOG_WARNING, "HTTP POST failed, retrying in %d seconds...", RETRY_DELAY);
                            sleep(RETRY_DELAY);
                        }
                    }
                }
                if (!post_ok) {
                    syslog(LOG_ERR, "HTTP POST failed after %d retries", MAX_RETRIES);
                }
            } else {
                syslog(LOG_ERR, "Failed to format JSON");
            }
        } else {
            syslog(LOG_ERR, "DHT22 read failed after %d retries", MAX_RETRIES);
        }

        if (running) {
            sleep(READ_INTERVAL);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

