#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_file(const char *path, char *buf, size_t len) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fgets(buf, (int)len, fp) == NULL) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int write_file(const char *path, const char *value) {
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s", value) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_cpu_temp(int *temp_out) {
    char buf[16];
    if (read_file(TEMP_FILE, buf, sizeof(buf)) != 0) {
        return -1;
    }
    char *endptr;
    long val = strtol(buf, &endptr, 10);
    if (endptr == buf || *endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Invalid temperature format: %s", buf);
        return -1;
    }
    *temp_out = (int)val;
    return 0;
}

static int read_fan_max_state(int *max_out) {
    char buf[16];
    if (read_file(FAN_MAX_STATE_FILE, buf, sizeof(buf)) != 0) {
        return -1;
    }
    char *endptr;
    long val = strtol(buf, &endptr, 10);
    if (endptr == buf || *endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Invalid max_state format: %s", buf);
        return -1;
    }
    *max_out = (int)val;
    return 0;
}

static int read_fan_state(int *state_out) {
    char buf[16];
    if (read_file(FAN_STATE_FILE, buf, sizeof(buf)) != 0) {
        return -1;
    }
    char *endptr;
    long val = strtol(buf, &endptr, 10);
    if (endptr == buf || *endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Invalid fan state format: %s", buf);
        return -1;
    }
    *state_out = (int)val;
    return 0;
}

static int set_fan_state(int state) {
    char state_str[16];
    snprintf(state_str, sizeof(state_str), "%d", state);
    return write_file(FAN_STATE_FILE, state_str);
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int determine_fan_speed(int cpu_temp) {
    if (cpu_temp < 45000) return 0;
    if (cpu_temp < 55000) return 1;
    if (cpu_temp < 65000) return 2;
    return 3;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    int max_state = 0;
    if (read_fan_max_state(&max_state) != 0) {
        fprintf(stderr, "Failed to read max fan state. Exiting.\n");
        return 1;
    }
    if (max_state < 0 || max_state > 3) {
        fprintf(stderr, "Invalid max fan state (%d). Exiting.\n", max_state);
        return 1;
    }

    int current_state = 0;
    if (read_fan_state(&current_state) != 0) {
        fprintf(stderr, "Failed to read initial fan state. Assuming 0.\n");
        current_state = 0;
    }

    log_event("Fan control started.");

    while (g_running) {
        int cpu_temp;
        if (read_cpu_temp(&cpu_temp) != 0) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int new_state = determine_fan_speed(cpu_temp);
        if (new_state > max_state) {
            new_state = max_state;
        }

        if (new_state != current_state) {
            if (set_fan_state(new_state) == 0) {
                char log_msg[256];
                snprintf(log_msg, sizeof(log_msg), "Fan speed changed to state %d (CPU: %d m°C)", new_state, cpu_temp);
                log_event(log_msg);
                current_state = new_state;
            } else {
                fprintf(stderr, "Failed to set fan state to %d.\n", new_state);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (set_fan_state(0) == 0) {
        log_event("Fan control stopped. Fan set to state 0.");
    } else {
        fprintf(stderr, "Failed to set fan to state 0 on shutdown.\n");
    }
    return 0;
}

