#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 50.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define LOG_FILE "heater_log.txt"

#define KP 1.0
#define KI 0.1
#define KD 0.01

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

typedef struct {
    double kp;
    double ki;
    double kd;
    double integral;
    double previous_error;
} PIDController;

static PIDController pid = {KP, KI, KD, 0.0, 0.0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(double temperature, int duty_cycle, double pid_output) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f, Duty Cycle: %d, PID Output: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle, pid_output);
    fclose(fp);
}

static void set_heater_duty(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(HEATER_GPIO, duty_cycle) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
    }
}

static double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    pid.integral += error;
    double derivative = error - pid.previous_error;
    double output = pid.kp * error + pid.ki * pid.integral + pid.kd * derivative;
    pid.previous_error = error;
    return output;
}

static void reset_pid() {
    pid.integral = 0.0;
    pid.previous_error = 0.0;
}

static int read_thermocouple(double *temperature) {
    char buffer[4] = {0};
    int bytes_read = spiRead(spi_handle, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from SPI: read %d bytes\n", bytes_read);
        return -1;
    }

    uint32_t raw_data = ((uint32_t)(uint8_t)buffer[0] << 24) |
                        ((uint32_t)(uint8_t)buffer[1] << 16) |
                        ((uint32_t)(uint8_t)buffer[2] << 8)  |
                        ((uint32_t)(uint8_t)buffer[3]);

    if (raw_data & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected: 0x%08X\n", raw_data);
        if (raw_data & 0x00000004) fprintf(stderr, "  Open circuit\n");
        if (raw_data & 0x00000002) fprintf(stderr, "  Short to GND\n");
        if (raw_data & 0x00000001) fprintf(stderr, "  Short to VCC\n");
        return -2;
    }

    int16_t thermocouple_data = (int16_t)(raw_data >> 18);
    *temperature = thermocouple_data * 0.25;
    return 0;
}

static void cleanup() {
    set_heater_duty(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature control started. Target: %.1f C\n", TARGET_TEMPERATURE);

    while (running) {
        double temperature;
        int ret = read_thermocouple(&temperature);

        if (ret == 0) {
            if (temperature > MAX_TEMPERATURE || temperature < MIN_TEMPERATURE) {
                fprintf(stderr, "Temperature out of range: %.2f C\n", temperature);
                set_heater_duty(0);
                reset_pid();
            } else {
                double pid_output = calculate_pid(TARGET_TEMPERATURE, temperature);
                int duty_cycle = (int)pid_output;
                if (duty_cycle < 0) duty_cycle = 0;
                if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
                set_heater_duty(duty_cycle);
                log_data(temperature, duty_cycle, pid_output);
            }
        } else if (ret == -2) {
            set_heater_duty(0);
            reset_pid();
        } else {
            set_heater_duty(0);
            reset_pid();
        }

        time_sleep(1.0);
    }

    cleanup();
    printf("Temperature control stopped.\n");
    return 0;
}

