#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define LOG_FILE "cooling_log.csv"
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define PWM_FREQ 25000
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float read_cpu_temp(void) {
    FILE *fp = popen("vcgencmd measure_temp", "r");
    if (!fp) {
        fprintf(stderr, "Error opening vcgencmd: %s\n", strerror(errno));
        return -1.0f;
    }

    char buffer[16];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading temperature from vcgencmd\n");
        pclose(fp);
        return -1.0f;
    }
    pclose(fp);

    if (sscanf(buffer, "temp=%f", &buffer[0]) != 1) {
        fprintf(stderr, "Error parsing temperature from vcgencmd output\n");
        return -1.0f;
    }
    return (float)buffer[0];
}

static int set_fan_speed(float temp) {
    float duty;
    if (temp <= TEMP_MIN) {
        duty = 0.0f;
    } else if (temp >= TEMP_MAX) {
        duty = 100.0f;
    } else {
        duty = ((temp - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * 100.0f;
    }

    int pwm_value = (int)(duty * 255.0f / 100.0f);
    if (gpioPWM(FAN_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle to %d\n", pwm_value);
        return -1;
    }
    return 0;
}

static int log_data(float temp, float duty) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temp, duty) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", PWM_FREQ);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            fprintf(stderr, "Error creating log file: %s\n", strerror(errno));
            gpioTerminate();
            return EXIT_FAILURE;
        }
        fprintf(fp, "Timestamp,Temperature(C),DutyCycle(%%)\n");
        fclose(fp);
    } else {
        fclose(fp);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CPU Temperature Monitoring and Fan Control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp = read_cpu_temp();
        if (temp < 0.0f) {
            fprintf(stderr, "Error reading CPU temperature, skipping cycle\n");
        } else {
            if (set_fan_speed(temp) != 0) {
                fprintf(stderr, "Error setting fan speed\n");
            }
            float duty = ((temp <= TEMP_MIN) ? 0.0f : ((temp >= TEMP_MAX) ? 100.0f : ((temp - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * 100.0f));
            if (log_data(temp, duty) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
            printf("Temperature: %.2f C, Fan Speed: %.2f %%\n", temp, duty);
        }
        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Fan control stopped.\n");
    return EXIT_SUCCESS;
}

