        i2cClose(handle1);
        gpioTerminate();
        return 1;
    }

    printf("Starting flow monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = read_flow_rate(handle1, &flow1);
        int ok2 = read_flow_rate(handle2, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            if (log_data(flow1, flow2) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            if (ok1 != 0)
