        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = gpioRead(GPIO_A) << 1 | gpioRead(GPIO_B);
    if (last_state < 0) {
        fprintf(stderr, "Failed to read initial GPIO state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double position = 0.0;
    int direction = 0;

    while (running) {
        int a = gpioRead(GPIO_A);
        int b = gpioRead(GPIO_B);

        if (a < 0 || b < 0) {
            fprintf(stderr, "Error reading GPIO pins\n");
            break;
        }

        int current_state = a << 1 | b;

        if (current_state != last_state) {
            if (current_state == 0b00) {
                if (last_state == 0b01) direction = 1;
                else if (last_state == 0b10) direction = -1;
            } else if (current_state == 0b01) {
                if (last_state == 0b11) direction = 1;
                else if (last_state == 0b00) direction = -1;
            } else if (current_state == 0b10) {
                if (last_state == 0b00) direction = 1;
                else if (last_state == 0b11) direction = -1;
            } else if (current_state == 0b11) {
                if (last_state == 0b10) direction = 1;
                else if (last_state == 0b01) direction = -1;
            }

            position += direction / PULSES_PER_REV * 360.0;
            if (position < 0.0) position += 360.0;
            else if (position >= 360.0) position -= 360.0;

            if (log_position(position) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }

            last_state = current_state;
        }

        gpioDelay(1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

