#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x50
#define GPIO_LED 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "adpd144ri_log.txt"

#define REG_MODE 0x00
#define REG_DATA 0x04
#define REG_CONFIG 0x0A

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int initialize_sensor(int fd) {
    if (i2c_write_reg8(fd, REG_MODE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write MODE register.\n");
        return -1;
    }
    if (i2c_write_reg8(fd, REG_CONFIG, 0x0A) < 0) {
        fprintf(stderr, "Error: Failed to write CONFIG register.\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, uint16_t *red, uint16_t *ir) {
    if (i2c_read_reg16(fd, REG_DATA, red) < 0) {
        fprintf(stderr, "Error: Failed to read RED data.\n");
        return -1;
    }
    if (i2c_read_reg16(fd, REG_DATA + 2, ir) < 0) {
        fprintf(stderr, "Error: Failed to read IR data.\n");
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Error: Failed to acquire I2C bus access");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Error: Sensor initialization failed. Check wiring and address.\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        cleanup();
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", GPIO_LED);
        cleanup();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    printf("ADPD144RI sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t red, ir;
        if (read_sensor_data(i2c_fd, &red, &ir) == 0) {
            log_data(log_file, red, ir);
            if (ir > IR_THRESHOLD) {
                gpioWrite(GPIO_LED, 1);
            } else {
                gpioWrite(GPIO_LED, 0);
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    gpioWrite(GPIO_LED, 0);
    cleanup();
    return 0;
}

