#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define AUDIO_PIN 17
#define GAIN_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %d\n", timestamp, level) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GAIN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GAIN_PIN %d as output\n", GAIN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GAIN_PIN, 0) != 0) {
        fprintf(stderr, "Error setting GAIN_PIN %d LOW (60 dB gain)\n", GAIN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(AUDIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting AUDIO_PIN %d as input\n", AUDIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Audio event detection started. Press Ctrl+C to exit.\n");
    printf("Audio input: GPIO%d, Gain select: GPIO%d (LOW = 60 dB)\n", AUDIO_PIN, GAIN_PIN);

    int last_state = gpioRead(AUDIO_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error reading initial state of AUDIO_PIN %d\n", AUDIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(AUDIO_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error reading AUDIO_PIN %d\n", AUDIO_PIN);
            break;
        }

        if (current_state == 1 && last_state == 0) {
            if (log_event(1) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
        }

        last_state = current_state;
        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("\nAudio event detection stopped.\n");
    return EXIT_SUCCESS;
}

