#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x00
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL 5
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "Error writing register address 0x%02X\n", reg);
        return -1;
    }
    int bytes_read = i2cReadDevice(handle, (char *)buf, len);
    if (bytes_read != (int)len) {
        fprintf(stderr, "Error reading register 0x%02X: expected %u, got %d\n", reg, len, bytes_read);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *tvoc, uint16_t *eco2) {
    uint8_t buf[4];
    if (read_register(handle, 0x01, buf, 4) < 0) {
        return -1;
    }
    *tvoc = (buf[0] << 8) | buf[1];
    *eco2 = (buf[2] << 8) | buf[3];
    return 0;
}

static float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float tvoc_ppb = (float)tvoc * 0.5f;
    float eco2_ppm = (float)eco2 * 0.5f;
    float iaq = 0.0f;
    if (tvoc_ppb > 0.0f) {
        iaq = 50.0f + (tvoc_ppb / 100.0f) * 50.0f;
        if (iaq > 100.0f) iaq = 100.0f;
    }
    if (eco2_ppm > 400.0f) {
        float eco2_excess = eco2_ppm - 400.0f;
        float eco2_contribution = eco2_excess * 0.1f;
        iaq += eco2_contribution;
        if (iaq > 100.0f) iaq = 100.0f;
    }
    return iaq;
}

static void log_data(FILE *fp, float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t tvoc = 0, eco2 = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
            if (read_sensor_data(i2c_handle, &tvoc, &eco2) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Sensor read failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                gpioDelay(1000000);
            }
        }

        if (success) {
            float iaq = calculate_iaq(tvoc, eco2);
            log_data(log_file, iaq, tvoc, eco2);
            printf("IAQ: %.2f, TVOC: %u ppb, eCO2: %u ppm\n", iaq, tvoc, eco2);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d attempts\n", MAX_RETRIES);
        }

        for (int i = 0; i < SAMPLE_INTERVAL && !terminate; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nCleaning up...\n");
    cleanup();
    return EXIT_SUCCESS;
}

