#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip4"
#define GPIO_LINE_OFFSET    17
#define POLL_INTERVAL_MS    100
#define INTRUSION_THRESHOLD 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static long elapsed_ms(const struct timespec *start, const struct timespec *end)
{
    long ms = (long)(end->tv_sec - start->tv_sec) * 1000L
             + (long)(end->tv_nsec - start->tv_nsec) / 1000000L;
    return ms;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, "ttp223_tamper") < 0) {
        fprintf(stderr, "gpiod_line_request_input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value: %s\n", strerror(errno));
            goto cleanup;
        }

        if (val == 1) {
            struct timespec touch_start;
            if (clock_gettime(CLOCK_MONOTONIC, &touch_start) == -1) {
                fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
                goto cleanup;
            }

            while (g_running) {
                struct timespec now;
                if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                    fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
                    goto cleanup;
                }

                if (elapsed_ms(&touch_start, &now) > INTRUSION_THRESHOLD) {
                    printf("Intrusion detected! Sensor HIGH for > %d seconds.\n",
                           INTRUSION_THRESHOLD);
                    fflush(stdout);
                    break;
                }

                struct timespec sleep_ts = {0, POLL_INTERVAL_MS * 1000000L};
                nanosleep(&sleep_ts, NULL);
            }
        }

        struct timespec sleep_ts = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&sleep_ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");

    return ret;
}

