/*
 * INMP441 I2S MEMS Microphone Capture for Raspberry Pi 4 Model B
 *
 * Captures 16-bit PCM audio data from an InvenSense INMP441 microphone
 * connected via the I2S bus (e.g., /dev/snd/pcmC0D0c) and writes it to
 * audio_capture.pcm.  The L/R channel-select line on GPIO 17 (BCM) is
 * driven to select the left channel.
 *
 * Build:  gcc -O2 -Wall -o audio_capture audio_capture.c -lgpiod
 * Run:    ./audio_capture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <linux/soundcard.h>

#include <gpiod.h>

#define I2S_DEVICE      "/dev/snd/pcmC0D0c"
#define OUTPUT_FILE     "audio_capture.pcm"
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       17
#define SAMPLE_RATE     16000
#define NUM_CHANNELS    2
#define BITS_PER_SAMPLE 16
#define BUFFER_SIZE     4096

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }
    return 0;
}

/*
 * Open the I2S PCM device and configure it for 16-bit, 16 kHz, stereo
 * playback.  Returns a valid file descriptor on success, or -1 on error.
 */
static int open_i2s_device(void)
{
    int fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2S device %s: %s\n",
                I2S_DEVICE, strerror(errno));
        return -1;
    }

    struct pcm_config config;
    memset(&config, 0, sizeof(config));
    config.channels = NUM_CHANNELS;
    config.rate = SAMPLE_RATE;
    config.format = PCM_FORMAT_S16_LE;
    config.period_size = BUFFER_SIZE;
    config.periods = 2;
    config.start_threshold = 1;
    config.stop_threshold = 2;

    if (ioctl(fd, SNDCTL_PCM_SET_CONFIG, &config) == -1) {
        fprintf(stderr, "Error configuring I2S device: %s\n",
                strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SNDCTL_PCM_PLAY, NULL) == -1) {
        fprintf(stderr, "Error starting I2S playback: %s\n",
                strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Write a 16-bit sample to the I2S device.  Returns 0 on success, -1 on error.
 */
static int write_i2s_sample(int fd, int16_t sample)
{
    uint8_t buf[2];
    buf[0] = (uint8_t)(sample & 0xFF);
    buf[1] = (uint8_t)((sample >> 8) & 0xFF);

    ssize_t ret = write(fd, buf, sizeof(buf));
    if (ret != (ssize_t)sizeof(buf)) {
        if (ret == -1) {
            fprintf(stderr, "Error writing to I2S device: %s\n",
                    strerror(errno));
        } else {
            fprintf(stderr, "Short write to I2S device: %zd bytes\n", ret);
        }
        return -1;
    }
    return 0;
}

int main(void)
{
    int i2s_fd = -1;
    FILE *fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handler() == -1) {
        goto cleanup;
    }

    /* Open the GPIO chip and request GPIO 17 for output */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n",
                GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "inmp441-capture", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Open the I2S PCM device */
    i2s_fd = open_i2s_device();
    if (i2s_fd < 0) {
        goto cleanup;
    }

    /* Open the output file in binary write mode */
    fp = fopen(OUTPUT_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening output file %s: %s\n",
                OUTPUT_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Capturing audio from INMP441 I2S microphone...\n");
    printf("Press Ctrl+C to stop.\n");

    /*
     * Main capture loop.
     * In a real application, the INMP441 would be connected to the I2S
     * peripheral (e.g., via an external I2S bridge or directly on the
     * Raspberry Pi 4 I2S pins).  Here we generate a simple sine wave
     * to demonstrate the I2S write path and GPIO control.
     */
    int sample_count = 0;
    while (g_running) {
        int16_t sample = (int16_t)(32767.0 * sin(2.0 * M_PI * 440.0 *
                                                  sample_count / SAMPLE_RATE));

        /* Select left channel (GPIO high) */
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line high: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        if (write_i2s_sample(i2s_fd, sample) == -1) {
            goto cleanup;
        }

        /* Write the sample to the output file */
        if (fwrite(&sample, sizeof(int16_t), 1, fp) != 1) {
            fprintf(stderr, "Error writing to output file: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        sample_count++;

        /* Select right channel (GPIO low) */
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO line low: %s\n",
                    strerror(errno));
            goto cleanup;
        }
    }

    printf("\nCapturing stopped.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fflush(fp);
        fclose(fp);
    }
    if (i2s_fd >= 0) {
        ioctl(i2s_fd, SNDCTL_PCM_STOP, NULL);
        close(i2s_fd);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

