#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PWM_PIN 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 50000
#define SENSOR_TIMEOUT_US 5000000
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        return -1;
    }
    if (gpioSetMode(FAN_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan PWM pin mode\n");
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return -1;
    }
    if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(FAN_PWM_PIN, 0);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PWM_PIN, PI_OUTPUT);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    log_event("System started");

    int flame_detected = 0;
    uint32_t last_valid_read_tick = gpioTick();
    int first_reading = 1;

    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading flame sensor\n");
            log_event("Error reading flame sensor");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (first_reading) {
            first_reading = 0;
            last_valid_read_tick = gpioTick();
        }

        if (sensor_value == 0) {
            if (!flame_detected) {
                flame_detected = 1;
                log_event("Flame detected");
                if (gpioPWM(FAN_PWM_PIN, 128) != 0) {
                    fprintf(stderr, "Failed to start fan PWM\n");
                    log_event("Failed to start fan PWM");
                }
            }
        } else {
            if (flame_detected) {
                flame_detected = 0;
                log_event("Flame no longer detected");
                if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
                    fprintf(stderr, "Failed to stop fan PWM\n");
                    log_event("Failed to stop fan PWM");
                }
            }
        }

        uint32_t current_tick = gpioTick();
        if (current_tick - last_valid_read_tick > SENSOR_TIMEOUT_US) {
            fprintf(stderr, "Sensor timeout: no valid readings for 5 seconds\n");
            log_event("Sensor timeout");
            last_valid_read_tick = current_tick;
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Program shutting down");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    return EXIT_SUCCESS;
}

