        fprintf(stderr, "Error setting trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting data ready pin mode\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing trigger pin low\n");
        return -1;
    }
    return 0;
}

static int initialize_logging(void) {
    log_file = fopen(LOG_FILE_NAME, "wb");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    ConfigHeader config_header;
    config_header.magic_number = MAGIC_NUMBER;
    config_header.timestamp = (uint64_t)time(NULL);
