#include <gpiod.h>

#define FLAME_SENSOR_LINE 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_flame_status(int value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("%s Flame Detected: %s\n", timestamp, value == 0 ? "YES" : "NO");
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_request_config *req_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    int ret;

    /* Install signal handler for Ctrl+C */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the line for the flame sensor */
    line = gpiod_chip_get_line(chip, FLAME_SENSOR_LINE);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", FLAME_SENSOR_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Configure the line as input with pull-up */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Failed to allocate line settings\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    req_cfg = gpiod_line_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Failed to allocate request config\n");
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_request_config_set_consumer(req_cfg, "flame-sensor");

    ret = gpiod_line_request(line, req_cfg, settings);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", FLAME_SENSOR_LINE, strerror(errno));
        gpiod_line_request_config_free(req_cfg);
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", FLAME_SENSOR_LINE);
    fflush(stdout);

    /* Main loop */
    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line %d: %s\n", FLAME_SENSOR_LINE, strerror(errno));
        } else {
            log_flame_status(value);
        }
        sleep(POLL_INTERVAL_SEC);
    }

    /* Cleanup */
    printf("\nCleaning up and exiting...\n");
    gpiod_line_release(line);
    gpiod_line_request_config_free(req_cfg);
    gpiod_line_settings_free(settings);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

