#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 100

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] ", buffer);
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int i;
    int ret;

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: Failed to get GPIO line %u: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_CHANNELS; i++) {
        ret = gpiod_line_request_input(lines[i], "ttp226_touch");
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to request GPIO line %u as input: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 Touch Sensor Reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int values[NUM_CHANNELS];
        int read_error = 0;

        for (i = 0; i < NUM_CHANNELS; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Error: Failed to read GPIO line %u: %s\n", gpio_pins[i], strerror(errno));
                read_error = 1;
                break;
            }
            values[i] = ret;
        }

        if (read_error) {
            break;
        }

        print_timestamp();
        printf("Channel States: %d%d%d%d%d%d%d%d\n",
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("\nProgram terminated.\n");
    return EXIT_SUCCESS;
}

