/*
 * TMAG5110 Hall-Effect Latch Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Reads two TMAG5110 sensors on BCM GPIO4 and BCM GPIO5 every 500 ms.
 * The TMAG5110 output is open-drain; external pull-ups keep the line
 * HIGH when no magnet is detected and the latch is LOW when a magnet
 * is present.  We invert the raw reading so that a HIGH console value
 * means "magnet detected" and LOW means "no magnet".
 *
 * Build:  gcc -Wall -o hall_effect hall_effect.c -lthe_driver -lrt
 * Run:    ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <the_driver.h>   /* Replace with the actual TMAG5110 driver header */

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 5
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int setup_gpio_pin(int pin)
{
    if (the_driver_set_mode(pin, THE_DRIVER_MODE_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", pin);
        return -1;
    }

    /* TMAG5110 output is open-drain; enable internal pull-up so the
     * line reads HIGH when no magnet is present. */
    if (the_driver_set_pull_up(pin, THE_DRIVER_PULL_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO%d\n", pin);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/* Returns 0 or 1 for HIGH or LOW, or -1 on error.                      */
static int read_sensor(int pin)
{
    int raw = the_driver_read(pin);
    if (raw < 0) {
        fprintf(stderr, "Error: failed to read GPIO%d\n", pin);
        return -1;
    }
    if (raw != 0 && raw != 1) {
        fprintf(stderr, "Error: invalid reading %d on GPIO%d\n", raw, pin);
        return -1;
    }
    return raw;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc = EXIT_SUCCESS;

    /* --- Install signal handlers early so Ctrl+C always works --- */
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* --- Initialize the TMAG5110 driver library --- */
    if (the_driver_init() != 0) {
        fprintf(stderr, "Error: TMAG5110 driver initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (setup_gpio_pin(SENSOR_1_PIN) != 0 ||
        setup_gpio_pin(SENSOR_2_PIN) != 0) {
        fprintf(stderr, "Error: GPIO setup failed\n");
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: sensor read failure, exiting\n");
            rc = EXIT_FAILURE;
            break;
        }

        printf("Sensor 1: %s, Sensor 2: %s\n",
               s1 ? "HIGH" : "LOW",
               s2 ? "HIGH" : "LOW");

        fflush(stdout);

        /* Sleep 500 ms while remaining responsive to signals */
        struct timespec ts = { 0, POLL_INTERVAL_MS * 1000000L };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running) {
            /* interrupted by signal; loop with remaining time */
        }
    }

cleanup:
    /* --- Release resources on all exit paths --- */
    the_driver_terminate();
    return rc;
}

