#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 50000  /* 50 ms */

/* BCM pin numbers for the 8 TTP226 channels */
static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

int main(void)
{
    char timestamp[32];
    int i;
    int line_handles[NUM_CHANNELS];
    int ret;
    int pigpio_initialised = 0;
    int lines_requested = 0;

    memset(line_handles, -1, sizeof(line_handles));

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d): %s\n",
                ret, strerror(errno));
        return EXIT_FAILURE;
    }
    pigpio_initialised = 1;

    /* Request each GPIO line as an input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        line_handles[i] = gpioSetMode(channel_pins[i], PI_INPUT);
        if (line_handles[i] < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
        lines_requested++;
    }

    /* Main polling loop */
    while (program_running) {
        get_timestamp(timestamp, sizeof(timestamp));

        for (i = 0; i < NUM_CHANNELS; i++) {
            int state = gpioRead(channel_pins[i]);
            if (state < 0) {
                fprintf(stderr, "Failed to read GPIO %d: %s\n",
                        channel_pins[i], strerror(errno));
                state = -1;
            }
            printf("%s,%d", timestamp, state);
            if (i < NUM_CHANNELS - 1) {
                printf(",");
            }
        }
        printf("\n");
        fflush(stdout);

        usleep(POLL_DELAY_US);
    }

cleanup:
    /* Release all requested lines */
    for (i = 0; i < lines_requested; i++) {
        if (line_handles[i] >= 0) {
            gpioSetMode(channel_pins[i], PI_INPUT);
        }
    }

    if (pigpio_initialised) {
        gpioTerminate();
    }

    return EXIT_SUCCESS;
}

