#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_SENSOR_PIN 4          /* BCM GPIO4, physical pin 7 */
#define POLL_DELAY_US  100000      /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    /* --- Install SIGINT handler for clean shutdown on Ctrl-C --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure tilt sensor pin as input with internal pull-up --- */
    if (gpioSetMode(TILT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", TILT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", TILT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Allow pull-up to settle --- */
    gpioDelay(10000);  /* 10 ms */

    printf("Tilt sensor monitoring started on GPIO%d. Press Ctrl-C to exit.\n",
           TILT_SENSOR_PIN);
    fflush(stdout);

    int last_state = -1;   /* force initial print */

    while (g_running) {
        int level = gpioRead(TILT_SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on pin %d.\n", TILT_SENSOR_PIN);
            break;
        }

        if (level != last_state) {
            if (level == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
            last_state = level;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

