#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x28
#define SENSOR2_ADDR 0x29
#define ALARM_GPIO 17
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE "flow_log.txt"
#define START_CMD_MSB 0x36
#define START_CMD_LSB 0x08
#define MEAS_DELAY_US 100000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_flow_rate(int fd, float *flow_rate) {
    if (i2c_write_cmd(fd, START_CMD_MSB, START_CMD_LSB) < 0) {
        fprintf(stderr, "Error: Failed to send start command.\n");
        return -1;
    }
    usleep(MEAS_DELAY_US);

    uint8_t data[6];
    if (i2c_read_data(fd, data, 6) < 0) {
        fprintf(stderr, "Error: Failed to read flow data.\n");
        return -1;
    }

    if (sensirion_crc8(&data[0], 2) != data[2] || sensirion_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: CRC check failed.\n");
        return -1;
    }

    int16_t raw_flow = (data[0] << 8) | data[1];
    *flow_rate = (float)raw_flow / 100.0f;
    return 0;
}

static void log_flow_rate(float avg_flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Average Flow Rate: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, avg_flow_rate);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s.\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float flow_rate1 = 0.0f, flow_rate2 = 0.0f;
        int valid1 = 0, valid2 = 0;

        if (ioctl(i2c_fd, I2C_SLAVE, SENSOR1_ADDR) < 0) {
            fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X.\n", SENSOR1_ADDR);
        } else {
            if (read_flow_rate(i2c_fd, &flow_rate1) == 0) {
                valid1 = 1;
            }
        }

        if (ioctl(i2c_fd, I2C_SLAVE, SENSOR2_ADDR) < 0) {
            fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X.\n", SENSOR2_ADDR);
        } else {
            if (read_flow_rate(i2c_fd, &flow_rate2) == 0) {
                valid2 = 1;
            }
        }

        float avg_flow_rate = 0.0f;
        if (valid1 && valid2) {
            avg_flow_rate = (flow_rate1 + flow_rate2) / 2.0f;
        } else if (valid1) {
            avg_flow_rate = flow_rate1;
        } else if (valid2) {
            avg_flow_rate = flow_rate2;
        } else {
            fprintf(stderr, "Error: No valid sensor readings.\n");
        }

        log_flow_rate(avg_flow_rate);

        if (valid1 && valid2 && avg_flow_rate < FLOW_THRESHOLD) {
            gpioWrite(ALARM_GPIO, 1);
        } else {
            gpioWrite(ALARM_GPIO, 0);
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

