#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000

typedef struct {
    struct timespec timestamp;
    int value;
} SensorData;

static SensorData sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void add_to_buffer(int value) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime failed");
        return;
    }

    sensor_buffer[buffer_index].timestamp = ts;
    sensor_buffer[buffer_index].value = value;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm tm_info;
        if (localtime_r(&sensor_buffer[index].timestamp.tv_sec, &tm_info) != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("[%s.%03ld] Sensor Value: %d\n",
                   time_str, sensor_buffer[index].timestamp.tv_nsec / 1000000,
                   sensor_buffer[index].value);
        } else {
            printf("[timestamp error] Sensor Value: %d\n", sensor_buffer[index].value);
        }
    }
    printf("--- End of Log ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (program_running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", SENSOR_PIN);
            break;
        }

        add_to_buffer(sensor_value);

        if (sensor_value == 0) {
            printf("Obstacle detected!\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    print_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

