#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x28
#define REG_MODE       0x00
#define REG_X_LSB      0x01
#define REG_X_MSB      0x02
#define REG_Y_LSB      0x03
#define REG_Y_MSB      0x04
#define REG_Z_LSB      0x05
#define REG_Z_MSB      0x06
#define MODE_ACTIVE    0x01
#define POLL_MS        500
#define MAX_INIT_MS    1000
#define CSV_FILE       "fan_health.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int d7s_init(int fd) {
    if (i2c_write_reg8(fd, REG_MODE, MODE_ACTIVE) < 0) return -1;
    for (int i = 0; i < MAX_INIT_MS; i += 10) {
        uint8_t mode = 0;
        if (i2c_read_reg8(fd, REG_MODE, &mode) == 0 && mode == MODE_ACTIVE) return 0;
        msleep(10);
    }
    fprintf(stderr, "D7S did not become active within %d ms\n", MAX_INIT_MS);
    return -1;
}

static int d7s_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg8(fd, REG_X_LSB, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, REG_X_MSB, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, REG_Y_LSB, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, REG_Y_MSB, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, REG_Z_LSB, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, REG_Z_MSB, &zh) < 0) return -1;
    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static void log_sample(FILE *f, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    } else {
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");
    }
    fprintf(f, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(f);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
