#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define STALL_DURATION_SEC 2
#define POLL_DELAY_US 100000
#define LOG_FILE "stall_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

static int stall_detected(void) {
    int s1 = read_sensor(SENSOR_1_PIN);
    int s2 = read_sensor(SENSOR_2_PIN);
    if (s1 < 0 || s2 < 0) return 0;
    return (s1 == 0 && s2 == 0);
}

static void log_stall(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s - Stall detected\n", ts);
    } else {
        fprintf(fp, "(unknown time) - Stall detected\n");
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP);

    printf("Monitoring conveyor belt for stalls (Ctrl+C to exit)...\n");

    while (running) {
        if (stall_detected()) {
            printf("Stall detected!\n");
            log_stall();
            uint32_t elapsed = 0;
            while (running && stall_detected()) {
                gpioDelay(POLL_DELAY_US);
                elapsed += POLL_DELAY_US;
                if (elapsed >= STALL_DURATION_SEC * 1000000) {
                    break;
                }
            }
            if (running && stall_detected()) {
                printf("Stall confirmed for %d seconds.\n", STALL_DURATION_SEC);
            } else {
                printf("Stall cleared.\n");
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

