#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170-Q1 I2C 3D Hall-Effect sensor */
#define I2C_BUS        1
#define I2C_ADDR       0x0E
#define LOG_FILE       "magnetic_log.csv"
#define SAMPLE_US      100000  /* 100 ms */

/* TMAG5170 register addresses */
#define REG_DEVICE_ID  0x00
#define REG_X_CH_RESULT 0x01
#define REG_Y_CH_RESULT 0x03
#define REG_Z_CH_RESULT 0x05
#define REG_CONFIG     0x0A

/* Expected device ID for TMAG5170-Q1 */
#define DEV_ID_EXPECTED 0x5170

/* Config: 50 mT range, continuous conversion, all axes enabled */
#define CONFIG_50MT  0x0000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits, then clean up        */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit-addressed register                 */
/* ------------------------------------------------------------------ */
static int reg_write16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);          /* LSB first */
    buf[2] = (char)((value >> 8) & 0xFF);   /* MSB second */

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit-addressed register                */
/* ------------------------------------------------------------------ */
static int reg_read16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = (uint16_t)((uint8_t)data[0] | ((uint8_t)data[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the TMAG5170 sensor                                     */
/* ------------------------------------------------------------------ */
static int init_sensor(int handle)
{
    uint16_t dev_id = 0;

    if (reg_read16(handle, REG_DEVICE_ID, &dev_id) != 0) {
        fprintf(stderr, "Cannot read DEVICE_ID — sensor absent or bus error\n");
        return -1;
    }
    if (dev_id != DEV_ID_EXPECTED) {
