        fprintf(stderr, "Unexpected DEVICE_ID 0x%04X (expected 0x%04X)\n",
                dev_id, DEV_ID_EXPECTED);
        return -1;
    }

    if (reg_write16(handle, REG_CONFIG, CONFIG_50MT) != 0) {
