        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        log_event("GPIO initialization failed");
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
            log_event("GPIO read error");
            sleep(REINIT_DELAY_SEC);
            if (init_gpio() != 0) {
                log_event("GPIO re-initialization failed");
            } else {
                log_event("GPIO re-initialized successfully");
            }
            continue;
        }

        if (level == 1) {
            printf("Water detected!\n");
            log_event("ALERT: Water detected");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    cleanup_gpio();
    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

