#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdatomic.h>
#include <pigpio.h>

#define SENSOR_PIN      4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE        "rpm_log.txt"
#define SAMPLE_PERIOD_S 1          /* seconds between samples */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Pulse counter (rising-edge alert)                                   */
/* ------------------------------------------------------------------ */
static atomic_uint g_pulse_count = 0;

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == PI_HIGH) {
        atomic_fetch_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_rpm(double rpm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        perror("localtime_r");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log, "%s %.2f\n", ts, rpm) < 0) {
        perror("fprintf");
        return;
    }
    if (fflush(g_log) != 0) {
        perror("fflush");
    }

    printf("%s %.2f\n", ts, rpm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable alert so no more callbacks fire during teardown */
    gpioSetAlertFunc(SENSOR_PIN, NULL);

    /* Cancel the one‑second timer */
    gpioSetTimerFunc(0, 0, NULL);

    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n",
                SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- install alert callback (rising edge) ---- */
    if (gpioSetAlertFunc(SENSOR_PIN, pulse_callback) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc failed for pin %d.\n",
                SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- one-second timer ---- */
    if (gpioSetTimerFunc(0, SAMPLE_PERIOD_S * 1000, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFunc failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90217 RPM monitor started.  Sensor pin BCM %d, logging to %s.\n",
           SENSOR_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        /* Sleep for the sample period (interruptible by signals) */
        gpioDelay(SAMPLE_PERIOD_S * 1000000);

        if (!g_running) {
            break;
        }

        /* Atomically read and reset the pulse count */
        unsigned int pulses = atomic_exchange(&g_pulse_count, 0);

        /* RPM = pulses per second * 60 */
        double rpm = (double)pulses * 60.0;

        log_rpm(rpm);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

