#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"

/* Quadrature state machine: encode the two-bit sensor pair as an integer */
typedef enum {
    QUAD_STATE_00 = 0,
    QUAD_STATE_01 = 1,
    QUAD_STATE_10 = 2,
    QUAD_STATE_11 = 3
} QuadratureState;

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static QuadratureState last_state = QUAD_STATE_00;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR — called on every edge of either sensor pin                     */
/* ------------------------------------------------------------------ */
static void sensor_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)tick;
    (void)userdata;

    if (level != PI_HIGH && level != PI_LOW) {
        return; /* ignore timeout / watchdog events */
    }

    int a = gpioRead(SENSOR_A_PIN);
    int b = gpioRead(SENSOR_B_PIN);

    if (a < 0 || b < 0) {
        return; /* read error — skip this event */
    }

    QuadratureState current = (QuadratureState)((a << 1) | b);

    pthread_mutex_lock(&state_mutex);
    QuadratureState prev = last_state;
    last_state = current;
    pthread_mutex_unlock(&state_mutex);

    /* Quadrature direction: if the state changed, decode the transition */
    if (current != prev) {
        int direction;
        switch (current) {
            case QUAD_STATE_00: direction = (prev == QUAD_STATE_10) ? 1 : -1; break;
            case QUAD_STATE_01: direction = (prev == QUAD_STATE_00) ? 1 : -1; break;
            case QUAD_STATE_10: direction = (prev == QUAD_STATE_01) ? 1 : -1; break;
            case QUAD_STATE_11: direction = (prev == QUAD_STATE_00) ? 1 : -1; break;
            default: direction = 0; break;
        }

        if (direction != 0) {
            log_rotation(direction);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Log a rotation event with millisecond timestamp                     */
/* ------------------------------------------------------------------ */
static void log_rotation(int direction)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    int ms = (int)(ts.tv_nsec / 1000000);

    pthread_mutex_lock(&state_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s.%03d, Direction: %s\n",
                timestamp, ms,
                (direction > 0) ? "Clockwise" : "Counter-Clockwise");
        fflush(log_file);
    }
    pthread_mutex_unlock(&state_mutex);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins as inputs with pull-ups ---- */
    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_A_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_B_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR_A_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR_B_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register ISRs on both edges ---- */
    if (gpioSetISRFuncEx(SENSOR_A_PIN, EITHER_EDGE, 0, sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR for GPIO%d.\n", SENSOR_A_PIN);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(SENSOR_B_PIN, EITHER_EDGE, 0, sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR for GPIO%d.\n", SENSOR_B_PIN);
        gpioSetISRFuncEx(SENSOR_A_PIN, EITHER_EDGE, 0, NULL, NULL);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Quadrature sensor logging started. Press Ctrl+C to exit.\n");

    /* ---- Main loop — sleep until signal sets running = 0 ---- */
    while (running) {
        sleep(1);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(SENSOR_A_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(SENSOR_B_PIN, EITHER_EDGE, 0, NULL, NULL);
    pthread_mutex_lock(&state_mutex);
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&state_mutex);
    gpioTerminate();

    return EXIT_SUCCESS;
}

