#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define TOUCH_SENSOR_LINE   23   /* BCM 23, physical pin 16 */
#define LED_LINE            18   /* BCM 18, physical pin 12 */
#define POLL_INTERVAL_US    50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        goto cleanup;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip '%s': %s", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* Get the touch sensor line */
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_LINE);
    if (touch_line == NULL) {
        syslog(LOG_ERR, "Failed to get touch sensor line %d: %s", TOUCH_SENSOR_LINE, strerror(errno));
        goto cleanup;
    }

    /* Get the LED line */
    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (led_line == NULL) {
        syslog(LOG_ERR, "Failed to get LED line %d: %s", LED_LINE, strerror(errno));
        goto cleanup;
    }

    /* Request the touch sensor line as input */
    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line as input: %s", strerror(errno));
        goto cleanup;
    }

    /* Request the LED line as output, initial value 0 (off) */
    if (gpiod_line_request_output(led_line, "touch_sensor_led", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        goto cleanup;
    }

    syslog(LOG_INFO, "Touch sensor monitoring started (GPIO%d input, GPIO%d output).", TOUCH_SENSOR_LINE, LED_LINE);

    int prev_state = 0;

    while (g_running) {
        int val = gpiod_line_get_value(touch_line);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor: %s", strerror(errno));
            break;
        }

        if (val != prev_state) {
            if (val == 1) {
                syslog(LOG_INFO, "Touch detected!");
            } else {
                syslog(LOG_INFO, "Touch released.");
            }
            prev_state = val;
        }

        if (gpiod_line_set_value(led_line, val) < 0) {
            syslog(LOG_ERR, "Failed to write LED: %s", strerror(errno));
            break;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Ensure LED is off on exit */
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
    }

    ret = EXIT_SUCCESS;

cleanup:
    syslog(LOG_INFO, "Touch sensor monitoring stopped.");
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

