#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} TouchEvent;

static TouchEvent touch_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_overflow_count = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_2_PIN);
        return -1;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED on GPIO%d\n", LED_1_PIN);
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED on GPIO%d\n", LED_2_PIN);
        return -1;
    }

    return 0;
}

static void log_touch_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    touch_buffer[buffer_index].sensor_pin = sensor_pin;
    touch_buffer[buffer_index].timestamp = now;
    touch_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        buffer_overflow_count++;
    }
}

static void print_touch_events(void) {
    printf("\n--- Touch Event Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (touch_buffer[i].timestamp == 0) {
            continue;
        }
        char time_str[32];
        struct tm *tm_info = localtime(&touch_buffer[i].timestamp);
        if (tm_info != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "INVALID TIME", sizeof(time_str) - 1);
            time_str[sizeof(time_str) - 1] = '\0';
        }
        printf("Sensor: GPIO%d, Timestamp: %s, State: %d\n",
               touch_buffer[i].sensor_pin, time_str, touch_buffer[i].state);
    }
    printf("Buffer Overflow Count: %d\n", buffer_overflow_count);
    printf("-----------------------\n");
}

static void cleanup_gpio(void) {
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    int prev_state1 = 0;
    int prev_state2 = 0;

    while (program_running) {
        int state1 = gpioRead(SENSOR_1_PIN);
        int state2 = gpioRead(SENSOR_2_PIN);

        if (state1 < 0) {
            fprintf(stderr, "Failed to read GPIO%d\n", SENSOR_1_PIN);
        } else if (state1 != prev_state1) {
            log_touch_event(SENSOR_1_PIN, state1);
            prev_state1 = state1;
        }

        if (state2 < 0) {
            fprintf(stderr, "Failed to read GPIO%d\n", SENSOR_2_PIN);
        } else if (state2 != prev_state2) {
            log_touch_event(SENSOR_2_PIN, state2);
            prev_state2 = state2;
        }

        if (gpioWrite(LED_1_PIN, state1) != 0) {
            fprintf(stderr, "Failed to write GPIO%d\n", LED_1_PIN);
        }
        if (gpioWrite(LED_2_PIN, state2) != 0) {
            fprintf(stderr, "Failed to write GPIO%d\n", LED_2_PIN);
        }

        gpioDelay(POLL_DELAY_US);
    }

    print_touch_events();
    cleanup_gpio();
    return 0;
}

