        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — close log file and terminate pigpio               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pin as input with pull-up ---- */
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", RAIN_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", RAIN_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file for appending ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           RAIN_SENSOR_PIN);

    int last_state = -1;  /* force initial log */

    /* ---- Main polling loop ---- */
    while (g_running) {
        int level = gpioRead(RAIN_SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed for pin %d\n", RAIN_SENSOR_PIN);
            break;
        }

        /* Active-low: LOW (0) => rain, HIGH (1) => no rain */
        const char *msg = (level == 0) ? "Rain Detected" : "No Rain";

        if (level != last_state) {
            if (log_event(msg) != 0) {
                fprintf(stderr, "Logging failed; continuing to monitor.\n");
            } else {
                printf("%s\n", msg);
            }
            last_state = level;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

