#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define DEBOUNCE_DELAY_US 5000
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(FILE *fp, int s1, int s2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, s1, s2) < 0) {
        fprintf(stderr, "Error: fprintf() to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush() failed\n");
        return -1;
    }

    return 0;
}

int main(void) {
    FILE *fp = NULL;
    int prev_s1 = -1, prev_s2 = -1;
    uint32_t last_tick_s1 = 0, last_tick_s2 = 0;
    uint32_t last_log_tick = 0;
    int ret = EXIT_FAILURE;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register SIGINT handler\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        goto cleanup_gpio;
    }

    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        goto cleanup_gpio;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup_gpio;
    }

    printf("Monitoring shaft RPM. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: GPIO read failed\n");
            break;
        }

        uint32_t now = gpioTick();

        if (s1 != prev_s1) {
            if (now - last_tick_s1 > DEBOUNCE_DELAY_US) {
                prev_s1 = s1;
                last_tick_s1 = now;
                if (log_data(fp, s1, prev_s2) != 0) {
                    fprintf(stderr, "Error: Failed to log sensor 1 data\n");
                    break;
                }
            }
        }

        if (s2 != prev_s2) {
            if (now - last_tick_s2 > DEBOUNCE_DELAY_US) {
                prev_s2 = s2;
                last_tick_s2 = now;
                if (log_data(fp, prev_s1, s2) != 0) {
                    fprintf(stderr, "Error: Failed to log sensor 2 data\n");
                    break;
                }
            }
        }

        if (now - last_log_tick > 1000000) {
            uint32_t diff_s1 = now - last_tick_s1;
            uint32_t diff_s2 = now - last_tick_s2;
            double rpm_s1 = (diff_s1 > 0) ? (60000000.0 / (double)diff_s1) : 0.0;
            double rpm_s2 = (diff_s2 > 0) ? (60000000.0 / (double)diff_s2) : 0.0;
            printf("RPM: Sensor 1: %.2f, Sensor 2: %.2f\n", rpm_s1, rpm_s2);
            last_log_tick = now;
        }

        gpioDelay(1000);
    }

    ret = EXIT_SUCCESS;

    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Warning: fclose() failed\n");
        }
    }

cleanup_gpio:
    gpioTerminate();
    return ret;
}

