#include <stdint.h>
#include <stdbool.h>
#include <i2c/i2c.h>

#define SI1182_I2C_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "biometric_log.txt"
#define READ_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, int *heart_rate, int *spo2) {
    uint8_t hr_low, hr_high, spo2_low, spo2_high;

    if (read_register(handle, 0x00, &hr_low) < 0) return -1;
    if (read_register(handle, 0x01, &hr_high) < 0) return -1;
    if (read_register(handle, 0x02, &spo2_low) < 0) return -1;
    if (read_register(handle, 0x03, &spo2_high) < 0) return -1;

    *heart_rate = (hr_high << 8) | hr_low;
    *spo2 = (spo2_high << 8) | spo2_low;
    return 0;
}

static void log_data(FILE *fp, int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Heart Rate: %d BPM, SpO2: %d%%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            heart_rate, spo2);
    fflush(fp);
}

int main(void) {
    int handle = -1;
    FILE *fp = NULL;
    int heart_rate, spo2;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (i2cInit() < 0) {
        fprintf(stderr, "Error initializing I2C library: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, SI1182_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, SI1182_I2C_ADDR, strerror(errno));
        goto cleanup_i2c;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup_handle;
    }

    while (g_running) {
        if (read_sensor_data(handle, &heart_rate, &spo2) == 0) {
            log_data(fp, heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup_handle:
    if (handle >= 0) {
        i2cClose(handle);
    }
cleanup_i2c:
    if (fp != NULL) {
        fclose(fp);
    }
    i2cClose();
    return ret;
}

