#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27

#define TILT_THRESHOLD_SEC 2
#define POLL_INTERVAL_US   100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 timestamped line to the log file                 */
/* ------------------------------------------------------------------ */
static void log_event(const char *event_type, int sensor_id)
{
    if (g_log_file == NULL)
        return;

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    fprintf(g_log_file, "%s - Sensor %d: %s\n", ts, sensor_id, event_type);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin via pigpio; returns 0 or 1, or -1 on error        */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Activate alarm (HIGH)                                              */
/* ------------------------------------------------------------------ */
static void activate_alarm(void)
{
    if (gpioWrite(ALARM_PIN, 1) < 0)
        fprintf(stderr, "gpioWrite(ALARM_PIN, 1) failed\n");
}

/* ------------------------------------------------------------------ */
/* Deactivate alarm (LOW)                                             */
/* ------------------------------------------------------------------ */
static void deactivate_alarm(void)
{
    if (gpioWrite(ALARM_PIN, 0) < 0)
        fprintf(stderr, "gpioWrite(ALARM_PIN, 0) failed\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — always safe to call                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    deactivate_alarm();
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs with pull-down ---- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_1_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_2_PIN) failed\n");
        cleanup();
