/*
 * seismic.c — Raspberry Pi 3 Model B+ seismic monitor
 *
 * Hardware:
 *   Omron D7S-A0011 seismic sensor on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 *   Alert LED on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -o seismic seismic.c -lthe_driver_library -lm -lrt
 *
 * Run:
 *   ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS            1
#define I2C_ADDR           0x0A          /* D7S-A0011 default I2C address */
#define ALERT_LED_PIN      17            /* BCM pin for alert LED */
#define VIBRATION_THRESHOLD 500.0f       /* Euclidean magnitude threshold */
#define POLL_INTERVAL_US   100000        /* 100 ms between polls */
#define LED_ON_TIME_US     1000000       /* 1 s LED alert */
#define MAX_RETRIES        3
#define LOG_FILE_NAME      "seismic_events.log"

/* ---- D7S-A0011 register map ---- */
#define REG_CTRL1          0x00
#define REG_CTRL2          0x01
#define REG_STATUS         0x02
#define REG_VIBRATION_X    0x03
#define REG_VIBRATION_Y    0x04
#define REG_VIBRATION_Z    0x05

/* CTRL1 bits */
#define CTRL1_PD           0x01          /* Power-down bit */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- Prototypes ---- */
static int  init_i2c(void);
static int  init_sensor(void);
static int  read_vibration(float *x, float *y, float *z);
static float calc_magnitude(float x, float y, float z);
static void log_event(float magnitude);
static void trigger_alert(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure alert LED */
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);
    gpioWrite(ALERT_LED_PIN, 0);

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "Error: I2C initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        float x, y, z;

        if (read_vibration(&x, &y, &z) == 0) {
            float magnitude = calc_magnitude(x, y, z);

            if (magnitude > VIBRATION_THRESHOLD) {
                log_event(magnitude);
                trigger_alert();
            }
        } else {
            fprintf(stderr, "Warning: vibration read failed (I2C error).\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_sensor(void)
{
    /* Verify sensor presence by reading CTRL1 */
    int ctrl1 = i2cReadByteData(g_i2c_handle, REG_CTRL1);
    if (ctrl1 < 0) {
        fprintf(stderr, "Error: failed to read CTRL1 (I2C error).\n");
        return -1;
    }

    /* Sensor absent if CTRL1 reads 0xFF (stuck high) */
    if (ctrl1 == 0xFF) {
        fprintf(stderr, "Error: sensor not responding at 0x%02X.\n", I2C_ADDR);
        return -1;
    }

    /* Clear power-down bit to wake the sensor */
    if (i2cWriteByteData(g_i2c_handle, REG_CTRL1, ctrl1 & ~CTRL1_PD) < 0) {
        fprintf(stderr, "Error: failed to clear power-down bit.\n");
        return -1;
    }

    /* Allow sensor to settle */
    gpioDelay(10000);  /* 10 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_vibration(float *x, float *y, float *z)
{
    int rx, ry, rz;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        rx = i2cReadWordData(g_i2c_handle, REG_VIBRATION_X);
        ry = i2cReadWordData(g_i2c_handle, REG_VIBRATION_Y);
        rz = i2cReadWordData(g_i2c_handle, REG_VIBRATION_Z);

        if (rx >= 0 && ry >= 0 && rz >= 0) {
            /* D7S-A0011 returns 16-bit two's-complement data */
            *x = (float)((int16_t)rx);
            *y = (float)((int16_t)ry);
            *z = (float)((int16_t)rz);
            return 0;
        }

        fprintf(stderr, "Warning: I2C read error (rx=%d ry=%d rz=%d), retry %d/%d\n",
                rx, ry, rz, retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(1000);  /* 1 ms backoff */
    }

    return -1;
}

/* ------------------------------------------------------------------ */
static float calc_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
static void log_event(float magnitude)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    fprintf(g_log_file, "%s - Magnitude: %.2f\n", ts, magnitude);
    fflush(g_log_file);
    printf("%s - Magnitude: %.2f\n", ts, magnitude);
}

/* ------------------------------------------------------------------ */
static void trigger_alert(void)
{
    gpioWrite(ALERT_LED_PIN, 1);
    gpioDelay(LED_ON_TIME_US);
    gpioWrite(ALERT_LED_PIN, 0);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(ALERT_LED_PIN, 0);
    gpioTerminate();

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

