/*
 * flame_monitor.c — Raspberry Pi 3 Model B+
 *
 * Monitors five Keyes KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27.
 * On a HIGH -> LOW transition (debounced 50 ms) logs an event to
 *   /var/log/flame_events.log
 * and reports via syslog (facility LOG_USER, ident "flame_monitor").
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor   (root needed for /var/log write)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS   5
#define LOG_FILE      "/var/log/flame_events.log"
#define DEBOUNCE_MS   50
#define POLL_MS       1000

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(int sensor_id, unsigned int pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open %s: %s", LOG_FILE, strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_WARNING, "flock failed on %s: %s", LOG_FILE, strerror(errno));
        /* Non-fatal: continue logging without lock. */
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_WARNING, "time() failed: %s", strerror(errno));
        now = 0;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_WARNING, "gmtime_r failed");
        now = 0;
    }

    char ts[32];
    if (now != 0) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        syslog(LOG_ERR, "fprintf to log failed: %s", strerror(errno));
    } else {
        syslog(LOG_INFO, "Flame detected on sensor %d (GPIO %u)", sensor_id, pin);
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush failed: %s", strerror(errno));
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_WARNING, "flock UN failed: %s", strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose failed: %s", strerror(errno));
    }
}

int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting flame sensor monitoring...");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to get line %u: %s", sensor_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "Failed to request line %u as input: %s",
                   sensor_pins[i], strerror(errno));
            for (int j = 0; j < NUM_SENSORS; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    int prev_state[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        int v = gpiod_line_get_value(lines[i]);
        if (v < 0) {
            syslog(LOG_ERR, "Initial read failed on line %u: %s",
                   sensor_pins[i], strerror(errno));
            prev_state[i] = 0;
        } else {
            prev_state[i] = v;
        }
    }

    syslog(LOG_INFO, "Monitoring %d sensors on pins %u, %u, %u, %u, %u",
           NUM_SENSORS,
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "Read failed on line %u: %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            /* Detect HIGH -> LOW transition (flame present) */
            if (prev_state[i] == 1 && val == 0) {
                syslog(LOG_INFO, "Potential flame on sensor %d (GPIO %u)",
                       i + 1, sensor_pins[i]);

                /* Debounce: re-read after 50 ms */
                usleep(DEBOUNCE_MS * 1000);
                val = gpiod_line_get_value(lines[i]);
                if (val < 0) {
                    syslog(LOG_ERR, "Debounce read failed on line %u: %s",
                           sensor_pins[i], strerror(errno));
                    continue;
                }

                if (val == 0) {
                    log_event(i + 1, sensor_pins[i]);
                }
            }
            prev_state[i] = val;
        }
        usleep(POLL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down flame sensor monitoring...");

    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

