#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define VEML7700_REG_ALS_CONF 0x00
#define VEML7700_REG_ALS_DATA 0x04
#define VEML7700_REG_PS_CONF 0x08
#define VEML7700_REG_PS_DATA 0x0C
#define VEML7700_REG_INT_CFG 0x0F
#define VEML7700_REG_INT_STA 0x10
#define VEML7700_REG_INT_ENA 0x11
#define VEML7700_REG_INT_SIG 0x12
#define VEML7700_REG_HW_KEY 0x07
#define VEML7700_HW_KEY_VAL 0x17
#define VEML7700_ALS_CONF_DEFAULT 0x0000
#define VEML7700_PS_CONF_DEFAULT 0x0000
#define VEML7700_INT_ENA_DEFAULT 0x0000
#define VEML7700_INT_CFG_DEFAULT 0x0000
#define VEML7700_INT_STA_DEFAULT 0x0000
#define VEML7700_INT_SIG_DEFAULT 0x0000
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL 1.0
#define MAX_LUX 1000000.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_write_reg16(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);
    buf[2] = (char)((value >> 8) & 0xFF);
    if (i2cWriteDevice(handle, buf, 3) < 0) {
        return -1;
    }
    return 0;
}

static int veml7700_read_reg16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

static int veml7700_init(int handle) {
    if (veml7700_write_reg16(handle, VEML7700_REG_HW_KEY, VEML7700_HW_KEY_VAL) < 0) {
        fprintf(stderr, "Error writing HW_KEY: %s\n", strerror(errno));
        return -1;
    }
    if (veml7700_write_reg16(handle, VEML7700_REG_ALS_CONF, VEML7700_ALS_CONF_DEFAULT) < 0) {
        fprintf(stderr, "Error writing ALS_CONF: %s\n", strerror(errno));
        return -1;
    }
    if (veml7700_write_reg16(handle, VEML7700_REG_PS_CONF, VEML7700_PS_CONF_DEFAULT) < 0) {
        fprintf(stderr, "Error writing PS_CONF: %s\n", strerror(errno));
        return -1;
    }
    if (veml7700_write_reg16(handle, VEML7700_REG_INT_ENA, VEML7700_INT_ENA_DEFAULT) < 0) {
        fprintf(stderr, "Error writing INT_ENA: %s\n", strerror(errno));
        return -1;
    }
    if (veml7700_write_reg16(handle, VEML7700_REG_INT_CFG, VEML7700_INT_CFG_DEFAULT) < 0) {
        fprintf(stderr, "Error writing INT_CFG: %s\n", strerror(errno));
        return -1;
    }
    if (veml7700_write_reg16(handle, VEML7700_REG_INT_STA, VEML7700_INT_STA_DEFAULT) < 0) {
        fprintf(stderr, "Error writing INT_STA: %s\n", strerror(errno));
        return -1;
    }
    if (veml7700_write_reg16(handle, VEML7700_REG_INT_SIG, VEML7700_INT_SIG_DEFAULT) < 0) {
        fprintf(stderr, "Error writing INT_SIG: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux) {
    uint16_t als_data;
    if (veml7700_read_reg16(handle, VEML7700_REG_ALS_DATA, &als_data) < 0) {
        return -1;
    }
    *lux = (float)als_data;
    return 0;
}

static int set_led_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, VEML7700_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (veml7700_init(i2c_handle) < 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Grow light system started. Press Ctrl+C to exit.\n");
    while (running) {
        float lux = 0.0f;
        int error_code = 0;
        if (veml7700_read_lux(i2c_handle, &lux) < 0) {
            fprintf(stderr, "Error reading lux value: %s\n", strerror(errno));
            error_code = 1;
            lux = MAX_LUX;
        }
        int brightness;
        if (lux < 100.0f) {
            brightness = 100;
        } else if (lux < 500.0f) {
            brightness = 75;
        } else if (lux < 1000.0f) {
            brightness = 50;
        } else {
            brightness = 25;
        }
        if (set_led_brightness(LED_GPIO, brightness) < 0) {
            fprintf(stderr, "Error setting LED brightness\n");
        }
        if (log_data(log_file, lux, brightness, error_code) < 0) {
            fprintf(stderr, "Error logging data\n");
        }
        time_sleep(SAMPLE_INTERVAL);
    }
    printf("\nShutting down...\n");
    set_led_brightness(LED_GPIO, 0);
    cleanup();
    return EXIT_SUCCESS;
}

