                fprintf(stderr, "gpioWrite failed for LED pin %d\n", LED_PIN);
            } else {
                led_on = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

