#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define OPT3001_ADDR   0x44
#define REG_RESULT     0x00
#define REG_CONFIG     0x01
#define LOG_FILE       "light_data.txt"
#define SAMPLE_PERIOD  1.0
#define CONFIG_DELAY   0.1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* OPT3001 sends data in big-endian; pigpio I2C word order is little-endian,
 * so we must swap bytes when writing the configuration and after reading
 * the result. */
static uint16_t swap16(uint16_t v)
{
    return (uint16_t)((v >> 8) | (v << 8));
}

static int opt3001_write_config(int handle, uint16_t config)
{
    uint16_t swapped = swap16(config);
    int rc = i2cWriteWordData(handle, REG_CONFIG, swapped);
    if (rc < 0) {
        fprintf(stderr, "Error writing config to OPT3001 (pigpio rc=%d): %s\n",
                rc, strerror(errno));
        return -1;
    }
    return 0;
}

static int opt3001_read_result(int handle, uint16_t *result)
{
    int rc = i2cReadWordData(handle, REG_RESULT);
    if (rc < 0) {
        fprintf(stderr, "Error reading result from OPT3001 (pigpio rc=%d): %s\n",
                rc, strerror(errno));
        return -1;
    }
    *result = (uint16_t)rc;
    return 0;
}

static int log_data(const char *filename, float lux)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (pigpio rc=%d): %s\n",
                I2C_BUS, OPT3001_ADDR, g_i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configuration: 0x3FFF = 16-bit resolution, 100 ms conversion time,
     * continuous mode, no fault count, no interrupt. */
    uint16_t config = 0x3FFF;

    while (g_running) {
        if (opt3001_write_config(g_i2c_handle, config) != 0) {
            fprintf(stderr, "Skipping iteration due to config write failure\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        time_sleep(CONFIG_DELAY);

        uint16_t raw;
        if (opt3001_read_result(g_i2c_handle, &raw) != 0) {
            fprintf(stderr, "Skipping iteration due to result read failure\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        /* OPT3001 result: 0xFFFF = overflow, 0x0000 = no light / error.
         * lux = raw * 0.01 for 16-bit resolution. */
        float lux = (float)swap16(raw) * 0.01f;

        if (log_data(LOG_FILE, lux) != 0) {
            fprintf(stderr, "Warning: failed to log data\n");
        }

        printf("%s, %.2f lux\n", "reading", lux);

        time_sleep(SAMPLE_PERIOD);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

