        int current_state = gpioRead(TOUCH_PIN);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead failed for pin %d\n", TOUCH_PIN);
            break;
        }

        if (first_read) {
            last_state = current_state;
            first_read = 0;
        } else if (current_state != last_state) {
            if (current_state == 1) {
                if (log_event("Touch Detected") != 0) {
                    fprintf(stderr, "Failed to log touch detected event.\n");
                }
            } else {
                if (log_event("Touch Released") != 0) {
                    fprintf(stderr, "Failed to log touch released event.\n");
                }
            }
            last_state = current_state;
        }

        gpioDelay(DEBOUNCE_US);
    }

    printf("\nCleaning up...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

