#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x3C
#define LOG_FILE "cooling_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MEAS_DELAY_US 2000
#define FLOW_MIN 0.0f
#define FLOW_MAX 100.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, SLF3S_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_flow_rate(float *flow_rate, uint8_t *flags) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[3];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing measurement command\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error reading 3 bytes from sensor\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n", crc8(buf, 2), buf[2]);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flags = buf[1] & 0x0F;
    *flow_rate = (float)raw / 60.0f;
    return 0;
}

static const char *status_str(int status) {
    switch (status) {
        case 0: return "OK";
        case 1: return "INVALID";
        case 2: return "ERROR";
        default: return "UNKNOWN";
    }
}

static int log_data(float flow_rate, uint8_t flags, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fseek(log_file, 0, SEEK_END);
        if (ftell(log_file) == 0) {
            fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        }
    }

    fprintf(log_file, "%s,%.2f,%s\n", ts, flow_rate, status_str(status));
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    float flow_rate;
    uint8_t flags;
    int status;

    while (!terminate) {
        status = read_flow_rate(&flow_rate, &flags);
        if (status == 0) {
            if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
                fprintf(stderr, "Flow rate out of range: %.2f ml/min\n", flow_rate);
                status = 1;
            }
        } else {
            fprintf(stderr, "Read failed, re-initializing I2C\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-init failed, exiting\n");
                break;
            }
            status = 2;
        }
        log_data(flow_rate, flags, status);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

