    flame_line = gpiod_chip_get_line(chip, FLAME_BCM_PIN);
    if (!flame_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                FLAME_BCM_PIN, strerror(errno));
        goto cleanup;
    }
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_BCM_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                BUZZER_BCM_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- Request lines --- */
    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "request_input(flame) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "request_output(buzzer) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    log_event(log, "System started");

    int prev_flame = 1;   /* assume no flame at startup (DO HIGH) */

    while (g_running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value(flame) failed: %s\n",
                    strerror(errno));
            break;
        }

        /* Detect HIGH -> LOW transition (flame newly detected) */
        if (val == 0 && prev_flame == 1) {
            log_event(log, "FLAME DETECTED");
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "set buzzer HIGH failed: %s\n",
                        strerror(errno));
            }
            /* Buzz for 2 s, but check g_running every 100 ms */
            for (int elapsed = 0; elapsed < BUZZER_ON_MS && g_running; elapsed += SLICE_MS)
                usleep(SLICE_MS * 1000);
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                fprintf(stderr, "set buzzer LOW failed: %s\n",
                        strerror(errno));
            }
        }
        prev_flame = val;

        /* Poll interval, sliceable for prompt shutdown */
        for (int elapsed = 0; elapsed < POLL_INTERVAL_MS && g_running; elapsed += SLICE_MS)
            usleep(SLICE_MS * 1000);
    }

    /* --- Cleanup --- */
    if (buzzer_line)
        gpiod_line_set_value(buzzer_line, 0);
    log_event(log, "System stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (flame_line)
        gpiod_line_release(flame_line);
    if (buzzer_line)
        gpiod_line_release(buzzer_line);
    if (chip)
        gpiod_chip_close(chip);
    if (log)
        fclose(log);
    return ret;
}

