#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "touch_log.txt"
#define POLL_DELAY_US 10000   /* 10 ms */
#define DEBOUNCE_DELAY_US 200000 /* 200 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

static int log_touch_event(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

int main(void)
{
    int last_touch_state = 0;
    int led_state = 0;
    int ret = EXIT_SUCCESS;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    /* Configure LED pin as output and ensure it starts OFF */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        ret = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d to LOW\n", LED_PIN);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d\n", TOUCH_SENSOR_PIN);
            ret = EXIT_FAILURE;
            break;
        }

        /* Detect rising edge: LOW -> HIGH transition */
        if (touch_state == 1 && last_touch_state == 0) {
            led_state = !led_state;
            if (gpioWrite(LED_PIN, led_state) != 0) {
                fprintf(stderr, "Failed to write GPIO%d\n", LED_PIN);
                ret = EXIT_FAILURE;
                break;
            }

            if (log_touch_event() != 0) {
                fprintf(stderr, "Failed to log touch event\n");
            }
        }

        last_touch_state = touch_state;
        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    cleanup();
    return ret;
}

