/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern GPIO API)
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4   (physical pin 7)
 *   Sensor 2 OUT -> GPIO17  (physical pin 11)
 *   Sensor 3 OUT -> GPIO27  (physical pin 13)
 *
 * TMAG5110A1 latch output is open-drain: it pulls the line LOW
 * when a south-pole magnet is present and releases it HIGH when
 * the magnet is removed.  Internal pull-ups are enabled so that
 * an unpowered sensor or disconnected line reads HIGH (magnet
 * removed) rather than floating.
 *
 * Build:  gcc -Wall -Wextra -O2 -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27

#define LOG_FILE_NAME "magnet_log.txt"
#define POLL_DELAY_US  100000   /* 100 ms */

/* ------------------------------------------------------------------ */
/* Globals for signal-handler cleanup                                 */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits, then clean up        */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped event to the log file                           */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S%z", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    /* state == 0 -> magnet present (line LOW)
     * state == 1 -> magnet removed (line HIGH) */
    const char *status = (state == 0) ? "MAGNET_PRESENT" : "MAGNET_REMOVED";

    if (fprintf(g_log_file, "%s - Sensor %d: %s\n",
                timestamp, sensor_id, status) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1, or -1 on error                   */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on pin %d (pigpio error %d)\n",
                pin, level);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Configure a pin as input with pull-up; abort on failure             */
/* ------------------------------------------------------------------ */
static int configure_pin(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int pins[3] = { SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN };
    int prev_state[3] = { -1, -1, -1 };   /* unknown until first read */
    int first_read[3] = { 1, 1, 1 };

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins ---- */
    for (int i = 0; i < 3; i++) {
        if (configure_pin(pins[i]) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO%d, GPIO%d, GPIO%d.\n",
           SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN);
    printf("Logging to '%s'.  Press Ctrl+C to exit.\n", LOG_FILE_NAME);

    /* ---- Main polling loop ---- */
    while (g_running) {
        for (int i = 0; i < 3; i++) {
            int state = read_sensor(pins[i]);

            if (state < 0) {
                /* Error already reported to stderr; skip this sensor */
                continue;
            }

            if (first_read[i]) {
                /* Record initial state without logging a false transition */
                prev_state[i] = state;
                first_read[i] = 0;
            } else if (state != prev_state[i]) {
                log_event(i + 1, state);
                prev_state[i] = state;
            }
        }
        usleep(POLL_DELAY_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

