#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define LOG_FILE "heart_rate.csv"

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_HR_RATE 0x0A
#define REG_CONFIG 0x0B

#define EXPECTED_PART_ID 0x82
#define EXPECTED_HW_REV 0x02

#define MIN_HR 30
#define MAX_HR 220
#define MOVING_AVG_SIZE 5

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_heart_rate(int handle, int *heart_rate) {
    uint8_t hr_raw;
    if (read_register(handle, REG_HR_RATE, &hr_raw) != 0) {
        return -1;
    }
    *heart_rate = (int)hr_raw;
    return 0;
}

static int apply_moving_average(int new_hr, int *history, int size, int *filtered_hr) {
    static int index = 0;
    static int initialized = 0;

    if (!initialized) {
        for (int i = 0; i < size; i++) {
            history[i] = 0;
        }
        initialized = 1;
    }

    history[index] = new_hr;
    index = (index + 1) % size;

    int sum = 0;
    for (int i = 0; i < size; i++) {
        sum += history[i];
    }

    *filtered_hr = sum / size;
    return 0;
}

static int log_heart_rate(FILE *file, int heart_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(file, "%s,%d\n", timestamp, heart_rate) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    if (fflush(file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int heart_rate_history[MOVING_AVG_SIZE] = {0};
    int heart_rate = 0;
    int filtered_heart_rate = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t part_id = 0, hw_rev = 0;
    if (read_register(i2c_handle, REG_PART_ID, &part_id) != 0 ||
        read_register(i2c_handle, REG_HW_REV, &hw_rev) != 0) {
        fprintf(stderr, "Failed to read sensor identification registers\n");
        cleanup();
        return 1;
    }

    if (part_id != EXPECTED_PART_ID || hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Sensor identification failed. Part ID: 0x%02X (expected 0x%02X), HW Rev: 0x%02X (expected 0x%02X)\n",
                part_id, EXPECTED_PART_ID, hw_rev, EXPECTED_HW_REV);
        cleanup();
        return 1;
    }

    if (write_register(i2c_handle, REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fprintf(log_file, "# Heart rate log started\n");
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file header\n");
        cleanup();
        return 1;
    }

    printf("Heart rate monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_heart_rate(i2c_handle, &heart_rate) == 0) {
            if (apply_moving_average(heart_rate, heart_rate_history, MOVING_AVG_SIZE, &filtered_heart_rate) == 0) {
                if (filtered_heart_rate >= MIN_HR && filtered_heart_rate <= MAX_HR) {
                    if (log_heart_rate(log_file, filtered_heart_rate) != 0) {
                        fprintf(stderr, "Error logging heart rate\n");
                    }
                } else {
                    fprintf(stderr, "Heart rate out of range: %d\n", filtered_heart_rate);
                }
            } else {
                fprintf(stderr, "Error applying moving average\n");
            }
        } else {
            fprintf(stderr, "Error reading heart rate, retrying...\n");
        }

        sleep(1);
    }

    printf("\nHeart rate monitoring stopped.\n");
    cleanup();
    return 0;
}

