        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: opening log file '%s' failed: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
