/*
 * TTP226 8‑channel capacitive touch sensor -> 8‑bit binary counter.
 *
 * Board:  Raspberry Pi Zero W
 * Library: libgpiod (modern Linux GPIO character-device API)
 *
 * Wiring:
 *   TTP226 OUT1..OUT8 -> BCM 5, 6, 7, 8, 9, 10, 11, 12
 *   Counter bit 0..7  -> BCM 17, 18, 19, 20, 21, 22, 23, 24
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 *
 * Run:
 *   sudo ./touch_counter
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 10000   /* 10 ms */
#define STABILIZE_US    200000   /* 200 ms */

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int counter_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* Write the 8‑bit counter value to all counter pins in one bulk request. */
static int update_counter(struct gpiod_line_bulk *bulk, unsigned int value)
{
    int vals[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++)
        vals[i] = (value >> i) & 1;

    if (gpiod_line_set_value_bulk(bulk, vals) < 0) {
        fprintf(stderr, "Failed to set counter output values: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* Append a timestamped touch event to the log file. */
static int log_touch_event(int channel, unsigned int counter_value)
{
    FILE *fp = fopen("touch_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s, Channel: %d, Counter: %u\n", ts, channel, counter_value);
    fclose(fp);
    return 0;
}

int main(void)
{
    install_signal_handlers();

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line_bulk sensor_bulk, counter_bulk;
    gpiod_line_bulk_init(&sensor_bulk);
    gpiod_line_bulk_init(&counter_bulk);

    /* Acquire sensor input lines. */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!line) {
            fprintf(stderr, "Failed to get sensor line %u: %s\n", sensor_pins[i], strerror(errno));
            gpiod_line_bulk_release(&sensor_bulk);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (gpiod_line_bulk_add(&sensor_bulk, line) < 0) {
            fprintf(stderr, "Failed to add sensor line %u: %s\n", sensor_pins[i], strerror(errno));
            gpiod_line_bulk_release(&sensor_bulk);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    /* Acquire counter output lines. */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, counter_pins[i]);
        if (!line) {
            fprintf(stderr, "Failed to get counter line %u: %s\n", counter_pins[i], strerror(errno));
            gpiod_line_bulk_release(&sensor_bulk);
            gpiod_line_bulk_release(&counter_bulk);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (gpiod_line_bulk_add(&counter_bulk, line) < 0) {
            fprintf(stderr, "Failed to add counter line %u: %s\n", counter_pins[i], strerror(errno));
            gpiod_line_bulk_release(&sensor_bulk);
            gpiod_line_bulk_release(&counter_bulk);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    /* Request sensor lines as inputs. */
    if (gpiod_line_request_bulk_input(&sensor_bulk, "ttp226-sensor") < 0) {
        fprintf(stderr, "Failed to request sensor lines as input: %s\n", strerror(errno));
        gpiod_line_bulk_release(&sensor_bulk);
        gpiod_line_bulk_release(&counter_bulk);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request counter lines as outputs, initial value 0. */
    if (gpiod_line_request_bulk_output(&counter_bulk, "ttp226-counter", 0) < 0) {
        fprintf(stderr, "Failed to request counter lines as output: %s\n", strerror(errno));
        gpiod_line_release_bulk(&sensor_bulk);
        gpiod_line_bulk_release(&counter_bulk);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Stabilize: let the module settle and produce a known baseline. */
    usleep(STABILIZE_US);

    int last_states[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++)
        last_states[i] = gpiod_line_get_value(sensor_bulk.lines[i]);

    unsigned int counter_value = 0;
    update_counter(&counter_bulk, counter_value);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(sensor_bulk.lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading sensor channel %d: %s\n", i + 1, strerror(errno));
                continue;
            }

            /* Rising-edge detection: idle (0) -> touched (1). */
            if (val == 1 && last_states[i] == 0) {
                counter_value = (counter_value + 1) & 0xFF;
                if (update_counter(&counter_bulk, counter_value) < 0) {
                    fprintf(stderr, "Error updating counter output.\n");
                }
                log_touch_event(i + 1, counter_value);
                printf("Touch on channel %d | Counter: %u\n", i + 1, counter_value);
            }
            last_states[i] = val;
        }
        usleep(POLL_INTERVAL_US);
    }

    /* Graceful shutdown: reset all counter outputs to 0. */
    update_counter(&counter_bulk, 0);
    gpiod_line_release_bulk(&sensor_bulk);
    gpiod_line_bulk_release(&counter_bulk);
    gpiod_chip_close(chip);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

