    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }

    int pins[4] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        /* KY-033 modules have onboard pull-up resistors; enable internal
           pull-down as a safety net so a disconnected sensor reads 0 rather
           than floating high. */
        if (gpioSetPullUpDown(pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Warning: failed to set pull-down on GPIO %d.\n", pins[i]);
        }
    }
    return 0;
}

