{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", ts, s1, s2, s3, s4) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

