        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file: %s\n",
                strerror(errno));
    }
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Safe to call even if gpioInitialise failed */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,sensor1,sensor2,led_state\n") < 0 ||
            fflush(g_log_fp) != 0) {
            fprintf(stderr, "Error: cannot write CSV header: %s\n",
                    strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
