#include <errno.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define LED_PIN     22
#define LOG_FILE    "obstacle_log.csv"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        return -1;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_PIN);
        return -1;
    }

    return 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n", pin, v);
        return -1;
    }
    return v;
}

static int control_led(int state)
{
    if (gpioWrite(LED_PIN, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on GPIO%d (state %d).\n",
                LED_PIN, state);
        return -1;
    }
    return 0;
}

static void log_data(int s1, int s2, int led)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file: %s\n",
                strerror(errno));
    }
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Safe to call even if gpioInitialise failed */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,sensor1,sensor2,led_state\n") < 0 ||
            fflush(g_log_fp) != 0) {
            fprintf(stderr, "Error: cannot write CSV header: %s\n",
                    strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: sensor read failure, skipping cycle.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int led_state = (s1 == 0 && s2 == 0) ? 1 : 0;
        if (control_led(led_state) != 0) {
            fprintf(stderr, "Error: LED control failure, skipping cycle.\n");
        }

        log_data(s1, s2, led_state);
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

