    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED_PIN %d to LOW.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

