#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN  17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN  22
#define POLL_DELAY_US     100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int left_state, center_state, right_state;
    int rc;

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs with internal pull-ups --- */
    rc = gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d).\n", LEFT_SENSOR_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d (code %d).\n", LEFT_SENSOR_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d).\n", CENTER_SENSOR_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d (code %d).\n", CENTER_SENSOR_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d).\n", RIGHT_SENSOR_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d (code %d).\n", RIGHT_SENSOR_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main polling loop --- */
    while (g_running) {
        left_state  = gpioRead(LEFT_SENSOR_PIN);
        center_state = gpioRead(CENTER_SENSOR_PIN);
        right_state  = gpioRead(RIGHT_SENSOR_PIN);

        if (left_state < 0 || center_state < 0 || right_state < 0) {
            fprintf(stderr, "Error: GPIO read failure (left=%d, center=%d, right=%d).\n",
                    left_state, center_state, right_state);
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n",
               left_state, center_state, right_state);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    return EXIT_SUCCESS;
}

