#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1175_ADDR 0x53
#define ALS_VIS_DATA_LSB 0x22
#define ALS_VIS_DATA_MSB 0x23
#define READ_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_si1175_als(int handle, uint16_t *als_out) {
    int lsb, msb;

    lsb = i2cReadByteData(handle, ALS_VIS_DATA_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA_LSB: %d\n", lsb);
        return -1;
    }

    msb = i2cReadByteData(handle, ALS_VIS_DATA_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA_MSB: %d\n", msb);
        return -1;
    }

    *als_out = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

int main(void) {
    int handle;
    uint16_t als_value;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", SI1175_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1175 ALS reader started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_si1175_als(handle, &als_value) == 0) {
            printf("ALS: %u\n", als_value);
        } else {
            fprintf(stderr, "Failed to read ALS data. Retrying...\n");
        }
        gpioDelay(READ_INTERVAL_US);
    }

    i2cClose(handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

