/*
 * TTP226 8‑channel capacitive touch sensor poller for Raspberry Pi 3 Model B+.
 *
 * Wiring (TTP226 module -> RPi 3B+):
 *   TP1 -> GPIO5  (BCM 5)
 *   TP2 -> GPIO6  (BCM 6)
 *   TP3 -> GPIO13 (BCM 13)
 *   TP4 -> GPIO19 (BCM 19)
 *   TP5 -> GPIO26 (BCM 26)
 *   TP6 -> GPIO12 (BCM 12)
 *   TP7 -> GPIO16 (BCM 16)
 *   TP8 -> GPIO20 (BCM 20)
 *
 *   VCC -> 3.3 V (Pin 1)
 *   GND -> GND  (Pin 9)
 *
 * Build: gcc -o touch_poll touch_poll.c -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <rtdkit.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int gpio_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void print_timestamp_monotonic(struct timespec *ts)
{
    printf("[%ld.%03ld] ", (long)ts->tv_sec,
           (ts->tv_nsec + 500000) / 1000000);
}

int main(void)
{
    struct rtk_chip *chip = NULL;
    struct rtk_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = rtk_chip_open(NULL);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open RTDK GPIO chip: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = rtk_line_request_input(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to request GPIO%u as input: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    while (g_running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
            perror("clock_gettime");
            goto cleanup;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = rtk_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "Failed to read GPIO%u: %s\n",
                        gpio_pins[i], strerror(errno));
                goto cleanup;
            }
            values[i] = v;
        }

        print_timestamp_monotonic(&ts);
        printf("CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            rtk_line_release(lines[i]);
    }
    if (chip != NULL)
        rtk_chip_close(chip);

    return ret;
}

