#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_RANGE  255
#define PWM_FREQ   1000
#define FADE_STEPS 50
#define FADE_DELAY_US (5000000 / FADE_STEPS)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int clamp(int v)
{
    if (v < 0)   return 0;
    if (v > 255) return 255;
    return v;
}

static int set_pwm(int pin, int value)
{
    if (gpioPWM(pin, value) < 0) {
        syslog(LOG_ERR, "gpioPWM(pin=%d, val=%d) failed", pin, value);
        return -1;
    }
    return 0;
}

static int fade_to_hue(int r, int g, int b)
{
    int r0 = gpioGetPWMdutycycle(RED_PIN);
    int g0 = gpioGetPWMdutycycle(GREEN_PIN);
    int b0 = gpioGetPWMdutycycle(BLUE_PIN);

    if (r0 < 0 || g0 < 0 || b0 < 0) {
        syslog(LOG_ERR, "gpioGetPWMdutycycle failed");
        return -1;
    }

    for (int i = 0; i < FADE_STEPS && g_running; i++) {
        int nr = r0 + (int)((r - r0) * (FADE_STEPS - i) / FADE_STEPS);
        int ng = g0 + (int)((g - g0) * (FADE_STEPS - i) / FADE_STEPS);
        int nb = b0 + (int)((b - b0) * (FADE_STEPS - i) / FADE_STEPS);

        if (set_pwm(RED_PIN,   clamp(nr)) < 0) return -1;
        if (set_pwm(GREEN_PIN, clamp(ng)) < 0) return -1;
        if (set_pwm(BLUE_PIN,  clamp(nb)) < 0) return -1;

        gpioDelay(FADE_DELAY_US);
    }
    return 0;
}

static int random_hue(int *r, int *g, int *b)
{
    *r = rand() % 256;
    *g = rand() % 256;
    *b = rand() % 256;
    return 0;
}

int main(void)
{
    openlog("rgb_fader", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioPWM(RED_PIN, 0) < 0 || gpioPWM(GREEN_PIN, 0) < 0 || gpioPWM(BLUE_PIN, 0) < 0) {
        syslog(LOG_ERR, "Initial gpioPWM off failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        int r, g, b;
        if (random_hue(&r, &g, &b) < 0) {
            syslog(LOG_ERR, "random_hue failed");
            break;
        }
        if (fade_to_hue(r, g, b) < 0) {
            syslog(LOG_ERR, "fade_to_hue failed");
            break;
        }
    }

    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

