/*
 * Raspberry Pi 4 Model B – BH1750 ambient light sensor → WS2812B LED strip
 *
 * Hardware:
 *   - BH1750 on I2C bus 1 (ADDR 0x23, ADDR 0x5C)
 *   - WS2812B data line on GPIO18 (BCM 18, hardware PWM/WS2812B output)
 *
 * Build:
 *   gcc -O2 -Wall -o light_led light_led.c -lpigpio -lrt
 *   (pigpio must be preloaded: sudo modprobe pigpio)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x23          /* ADDR pin low  */
#define BH1750_ADDR_ALT 0x5C          /* ADDR pin high */
#define NUM_LEDS       10
#define WS2812B_GPIO   18            /* BCM 18 = hardware WS2812B output */
#define PWM_RANGE      255
#define PWM_FREQ       800000        /* 800 kHz WS2812B data clock */
#define BH1750_CONV_MS 180           /* conversion time for One-Time H-Resolution */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * WS2812B bit-banging via pigpio hardware PWM.
 * Each bit is a 800 kHz square wave: ~0.4 us high for '1', ~0.85 us low for '1',
 * ~0.4 us high for '0', ~0.85 us low for '0'.  We use a 1 us PWM period
 * (1 MHz) and vary the duty cycle to approximate the timing.
 */
static void ws2812b_send_bit(int bit)
{
    if (bit) {
        gpioPWM(WS2812B_GPIO, 255);          /* 100 % duty → ~0.4 us high */
        gpioDelay(1);                        /* ~1 us total period → ~0.85 us low */
    } else {
        gpioPWM(WS2812B_GPIO, 0);            /* 0 % duty → ~0.4 us high (falling) */
        gpioDelay(1);                        /* ~1 us total period → ~0.85 us low */
    }
}

static void ws2812b_send_byte(uint8_t byte)
{
    for (int i = 7; i >= 0; i--) {
        ws2812b_send_bit((byte >> i) & 1);
    }
}

static void ws2812b_clear(void)
{
    for (int i = 0; i < NUM_LEDS * 3; i++) {
        ws2812b_send_byte(0x00);
    }
}

static void ws2812b_set_color(uint8_t r, uint8_t g, uint8_t b)
{
    for (int i = 0; i < NUM_LEDS; i++) {
        ws2812b_send_byte(g);                 /* WS2812B expects GRB order */
        ws2812b_send_byte(r);
        ws2812b_send_byte(b);
    }
}

/*
 * Read lux from BH1750.
 * Returns 0 on success, -1 on error.
 */
static int read_bh1750(float *lux_out)
{
    char cmd = 0x10;                          /* One-Time H-Resolution mode */
    char buf[2];

    if (i2cWriteDevice(g_i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "BH1750: write command failed\n");
        return -1;
    }

    gpioDelay(BH1750_CONV_MS * 1000);        /* wait for conversion */

    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "BH1750: read failed\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int map_lux_to_brightness(float lux)
{
    if (lux < 0.0f) lux = 0.0f;
    float log_lux = log10f(lux + 1.0f);
    float norm = log_lux / log10f(1000.0f);
    if (norm > 1.0f) norm = 1.0f;
    if (norm < 0.0f) norm = 0.0f;
    return (int)(norm * 255.0f);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Try both common BH1750 addresses */
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR_ALT, 0);
        if (g_i2c_handle < 0) {
            fprintf(stderr, "Failed to open I2C device (handle=%d)\n", g_i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure GPIO18 for hardware PWM (pigpio handles the WS2812B timing) */
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(WS2812B_GPIO, PWM_FREQ);
    gpioSetPWMrange(WS2812B_GPIO, PWM_RANGE);

    ws2812b_clear();

    while (g_running) {
        float lux = 0.0f;
        int retries = 0;
        bool read_ok = false;

        while (retries < MAX_RETRIES && g_running) {
            if (read_bh1750(&lux) == 0) {
                read_ok = true;
                break;
            }
            retries++;
            gpioDelay(100000);                 /* 100 ms between retries */
        }

        if (!read_ok) {
            fprintf(stderr, "BH1750 read failed after %d retries; clearing LEDs\n", MAX_RETRIES);
            ws2812b_clear();
            gpioDelay(500000);
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        ws2812b_set_color(brightness, brightness, brightness);

        gpioDelay(500000);                    /* 0.5 s loop interval */
    }

    /* Graceful shutdown */
    ws2812b_clear();
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

