#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define NUM_SENSORS 3
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_LEDS 10
#define FADE_DURATION_MS 500
#define LOOP_DELAY_MS 100
#define BH1750_CONV_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handles[NUM_SENSORS];
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle) {
    if (i2cWriteByte(handle, 0x10) < 0) {
        fprintf(stderr, "Error: BH1750 write failed (handle %d)\n", handle);
        return -1;
    }
    gpioDelay(BH1750_CONV_MS * 1000);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: BH1750 read failed (handle %d)\n", handle);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static void set_apa102_brightness(uint8_t brightness) {
    uint8_t frame[4 + NUM_LEDS * 4 + 4];
    int idx = 0;
    frame[idx++] = 0x00;
    frame[idx++] = 0x00;
    frame[idx++] = 0x00;
    frame[idx++] = 0x00;
    for (int i = 0; i < NUM_LEDS; i++) {
        frame[idx++] = 0xE0 | (brightness >> 3);
        frame[idx++] = brightness & 0x07;
        frame[idx++] = 0x00;
        frame[idx++] = 0x00;
    }
    frame[idx++] = 0xFF;
    frame[idx++] = 0xFF;
    frame[idx++] = 0xFF;
    frame[idx++] = 0xFF;
    if (spiWrite(spi_handle, (char *)frame, idx) != idx) {
        fprintf(stderr, "Error: SPI write failed\n");
    }
}

static void fade_brightness(uint8_t target) {
    uint8_t current = 0;
    int step = (target > current) ? 1 : -1;
    int range = target - current;
    int steps = range * 255 / 100;
    if (steps == 0) steps = 1;
    int delay_us = (FADE_DURATION_MS * 1000) / steps;
    for (int i = 0; i <= steps && running; i++) {
        uint8_t val = current + (uint8_t)((float)i / steps * range);
        set_apa102_brightness(val);
        gpioDelay(delay_us);
    }
    set_apa102_brightness(target);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        set_apa102_brightness(0);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = -1;
    }

    int addrs[NUM_SENSORS] = {BH1750_ADDR_1, BH1750_ADDR_2, BH1750_ADDR_1};
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, addrs[i], 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Warning: BH1750 at 0x%02X not found, skipping\n", addrs[i]);
        }
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting light sensor loop. Press Ctrl+C to exit.\n");

    while (running) {
        long total = 0;
        int valid = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                int val = read_bh1750(i2c_handles[i]);
                if (val >= 0) {
                    total += val;
                    valid++;
                }
            }
        }
        if (valid > 0) {
            long avg = total / valid;
            uint8_t brightness = (uint8_t)(avg / 100);
            if (brightness > 255) brightness = 255;
            fade_brightness(brightness);
        }
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

