#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_REG_ALS_CONF 0x00
#define VEML7700_REG_ALS_DATA 0x04
#define GPIO_PIN 18
#define NUM_LEDS 10
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void delay_ms(unsigned int ms) {
    struct timespec ts = { ms / 1000, (ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_lux(int fd, uint16_t *lux) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(fd, VEML7700_REG_ALS_DATA, lux) == 0) {
            return 0;
        }
        fprintf(stderr, "I2C read error (attempt %d/%d): %s\n", attempt + 1, MAX_RETRIES, strerror(errno));
        delay_ms(RETRY_DELAY_MS);
    }
    return -1;
}

static uint8_t calculate_brightness(uint16_t lux) {
    if (lux > 1000) lux = 1000;
    float normalized = (float)lux / 1000.0f;
    float gamma_corrected = powf(normalized, 0.5f);
    return (uint8_t)(gamma_corrected * 255.0f);
}

static void ws2812b_send_byte(int gpio, uint8_t byte) {
    for (int i = 0; i < 8; i++) {
        bool bit = (byte >> (7 - i)) & 1;
        if (bit) {
            // 700 ns high, 600 ns low (approximate)
            gpioWrite(gpio, 1);
            delay_ms(1);
            gpioWrite(gpio, 0);
            delay_ms(1);
        } else {
            // 350 ns high, 950 ns low (approximate)
            gpioWrite(gpio, 1);
            delay_ms(1);
            gpioWrite(gpio, 0);
            delay_ms(1);
        }
    }
}

static void ws2812b_set_color(int gpio, uint8_t r, uint8_t g, uint8_t b) {
    uint8_t grb[3] = { g, r, b };
    for (int i = 0; i < 3; i++) {
        ws2812b_send_byte(gpio, grb[i]);
    }
}

static void ws2812b_update(int gpio, uint8_t brightness) {
    uint8_t r = brightness;
    uint8_t g = brightness;
    uint8_t b = brightness;
    for (int i = 0; i < NUM_LEDS; i++) {
        ws2812b_set_color(gpio, r, g, b);
    }
}

static void ws2812b_off(int gpio) {
    for (int i = 0; i < NUM_LEDS; i++) {
        ws2812b_set_color(gpio, 0, 0, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Configure VEML7700: ALS range 0-1000 lux, 50ms integration time
    if (i2c_write_reg8(i2c_fd, VEML7700_REG_ALS_CONF, 0x00) < 0) {
        fprintf(stderr, "Failed to configure VEML7700: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    printf("VEML7700 light sensor and WS2812B LED strip control started.\n");

    while (running) {
        uint16_t lux = 0;
        if (read_lux(i2c_fd, &lux) == 0) {
            uint8_t brightness = calculate_brightness(lux);
            ws2812b_update(GPIO_PIN, brightness);
            printf("Lux: %u, Brightness: %u\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read lux after %d retries.\n", MAX_RETRIES);
        }
        delay_ms(LOOP_DELAY_MS);
    }

    printf("\nShutting down...\n");
