#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define FLAME_DETECTED 0
#define FLAME_NOT_DETECTED 1

#define LOG_FILE "flame_detection.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor: %s\n", pigpio_error(value));
        return -1;
    }
    return value;
}

static void activate_buzzer(int duration_ms) {
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Error activating buzzer\n");
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error deactivating buzzer\n");
    }
}

static void activate_buzzer_pattern(void) {
    activate_buzzer(200);
    activate_buzzer(200);
    activate_buzzer(600);
    activate_buzzer(200);
    activate_buzzer(200);
    activate_buzzer(600);
    activate_buzzer(200);
}

static void activate_led(int duration_ms) {
    if (gpioWrite(LED_PIN, 1) < 0) {
        fprintf(stderr, "Error activating LED\n");
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error deactivating LED\n");
    }
}

static void activate_led_rapidly(void) {
    for (int i = 0; i < 5; i++) {
        activate_led(100);
    }
}

static int self_test(void) {
    printf("Starting self-test...\n");
    log_event("Self-test started");

    for (int i = 0; i < 2; i++) {
        activate_led(500);
    }

    int flame_detected = 0;
    for (int i = 0; i < 5; i++) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            log_event("Self-test failed: error reading flame sensor");
            return -1;
        }
        if (sensor_value == FLAME_DETECTED) {
            flame_detected = 1;
        }
        gpioDelay(100 * 1000);
    }

    if (flame_detected) {
        log_event("Self-test failed: flame detected during test");
        printf("Self-test failed: flame detected during test\n");
        activate_led_rapidly();
        activate_buzzer_pattern();
        return -1;
    }

    log_event("Self-test passed");
    printf("Self-test passed\n");
    return 0;
}

static void cleanup(void) {
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting flame sensor pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (self_test() != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");
    log_event("Flame detection system started");

    int flame_detected = 0;

    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            log_event("Error reading flame sensor");
            gpioDelay(100 * 1000);
            continue;
        }

        if (sensor_value == FLAME_DETECTED) {
            if (!flame_detected) {
                log_event("Flame detected");
                printf("Flame detected!\n");
                flame_detected = 1;
            }
            if (gpioWrite(BUZZER_PIN, 1) < 0) {
                fprintf(stderr, "Error activating buzzer\n");
            }
            if (gpioWrite(LED_PIN, 1) < 0) {
                fprintf(stderr, "Error activating LED\n");
            }
        } else {
            if (flame_detected) {
                log_event("Flame cleared");
                printf("Flame cleared.\n");
                flame_detected = 0;
            }
            if (gpioWrite(BUZZER_PIN, 0) < 0) {
                fprintf(stderr, "Error deactivating buzzer\n");
            }
            if (gpioWrite(LED_PIN, 0) < 0) {
                fprintf(stderr, "Error deactivating LED\n");
            }
        }

        gpioDelay(50 * 1000);
    }

    printf("\nExiting gracefully...\n");
    log_event("Flame detection system stopped");
    cleanup();
    return 0;
}

