#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CMD_CONT 0x10
#define LED_PIN        17
#define BUFFER_SIZE    60
#define MIN_FREQ_HZ    0.5
#define MAX_FREQ_HZ    5.0
#define MIN_LUX        0.0
#define MAX_LUX        1000.0
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    if (i2c_write_cmd(fd, BH1750_CMD_CONT) < 0) {
        return -1;
    }
    usleep(180000);
    uint8_t buf[2];
    if (i2c_read_data(fd, buf, 2) < 0) {
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void set_gpio_export(int pin) {
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY) {
            perror("export");
        }
    } else {
        char buf[16];
        snprintf(buf, sizeof(buf), "%d", pin);
        if (write(fd, buf, strlen(buf)) < 0) {
            perror("export write");
        }
        close(fd);
    }
}

static void set_gpio_unexport(int pin) {
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY) {
            perror("unexport");
        }
    } else {
        char buf[16];
        snprintf(buf, sizeof(buf), "%d", pin);
        if (write(fd, buf, strlen(buf)) < 0) {
            perror("unexport write");
        }
        close(fd);
    }
}

static void set_gpio_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("direction open");
        return;
    }
    if (write(fd, dir, strlen(dir)) < 0) {
        perror("direction write");
    }
    close(fd);
}

static void set_gpio_value(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("value open");
        return;
    }
    char buf[2] = {value ? '1' : '0', '\n'};
    if (write(fd, buf, 2) < 0) {
        perror("value write");
    }
    close(fd);
}

static float calculate_average(const float *buf, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buf[i];
    }
    return sum / (float)size;
}

static float mapf(float x, float in_min, float in_max, float out_min, float out_max) {
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open i2c");
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }

    set_gpio_export(LED_PIN);
    usleep(100000);
    set_gpio_direction(LED_PIN, "out");
    set_gpio_value(LED_PIN, 0);

    float buffer[BUFFER_SIZE];
    int buf_idx = 0;
    int buf_count = 0;

    while (g_running) {
        float lux;
        if (read_bh1750(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Error reading BH1750: %s\n", strerror(errno));
            sleep(SAMPLE_PERIOD);
            continue;
