#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

/* Segment mapping: a,b,c,d,e,f,g,dp (dp unused) */
static const unsigned char digit5[8] = {1, 1, 0, 1, 0, 1, 1, 0};

static int data_line, clock_line, latch_line;

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    data_line = gpioSetMode(DATA_PIN, PI_OUTPUT);
    if (data_line < 0) {
        fprintf(stderr, "Error: failed to set DATA_PIN %d as output.\n", DATA_PIN);
        gpioTerminate();
        return -1;
    }

    clock_line = gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    if (clock_line < 0) {
        fprintf(stderr, "Error: failed to set CLOCK_PIN %d as output.\n", CLOCK_PIN);
        gpioTerminate();
        return -1;
    }

    latch_line = gpioSetMode(LATCH_PIN, PI_OUTPUT);
    if (latch_line < 0) {
        fprintf(stderr, "Error: failed to set LATCH_PIN %d as output.\n", LATCH_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure all lines start LOW */
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    return 0;
}

static void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        if (gpioWrite(DATA_PIN, (data >> i) & 1) < 0) {
            fprintf(stderr, "Warning: failed to write data bit to DATA_PIN.\n");
        }
        if (gpioWrite(CLOCK_PIN, 1) < 0) {
            fprintf(stderr, "Warning: failed to set CLOCK_PIN high.\n");
        }
        gpioDelay(1); /* 1 us high pulse */
        if (gpioWrite(CLOCK_PIN, 0) < 0) {
            fprintf(stderr, "Warning: failed to set CLOCK_PIN low.\n");
        }
        gpioDelay(1); /* 1 us low pulse */
    }
}

static void display_digit(const unsigned char *segments) {
    shift_out(segments[0]); /* a */
    shift_out(segments[1]); /* b */
    shift_out(segments[2]); /* c */
    shift_out(segments[3]); /* d */
    shift_out(segments[4]); /* e */
    shift_out(segments[5]); /* f */
    shift_out(segments[6]); /* g */
    shift_out(segments[7]); /* dp (unused) */
    if (gpioWrite(LATCH_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to set LATCH_PIN high.\n");
    }
    gpioDelay(1);
    if (gpioWrite(LATCH_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to set LATCH_PIN low.\n");
    }
}

static void cleanup(void) {
    /* Turn off display (clear shift register) */
    shift_out(0x00);
    shift_out(0x00);
    shift_out(0x00);
    shift_out(0x00);
    shift_out(0x00);
    shift_out(0x00);
    shift_out(0x00);
    shift_out(0x00);
    gpioWrite(LATCH_PIN, 0);

    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    gpioTerminate();
}

int main(void) {
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        display_digit(digit5);
        gpioDelay(500000); /* 500 ms on */

        /* Turn off display by clearing all segments */
        shift_out(0x00);
        shift_out(0x00);
        shift_out(0x00);
        shift_out(0x00);
        shift_out(0x00);
        shift_out(0x00);
        shift_out(0x00);
        shift_out(0x00);
        gpioWrite(LATCH_PIN, 1);
        gpioDelay(1);
        gpioWrite(LATCH_PIN, 0);
        gpioDelay(500000); /* 500 ms off */
    }

    /* Unreachable in normal operation, but kept for completeness */
    cleanup();
    return EXIT_SUCCESS;
}

