#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN    17
#define BUTTON_PIN 18
#define CHIP_NAME  "gpiochip0"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret;

    /* Install SIGINT handler for clean shutdown on Ctrl-C */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the button line as input with pull-up and falling-edge event detection */
    ret = gpiod_line_request_falling_edge_events_flags(button_line, "blink_button",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_falling_edge_events_flags (button)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Blinking LED on GPIO%d. Press the button on GPIO%d to exit.\n",
           LED_PIN, BUTTON_PIN);
    fflush(stdout);

    while (running) {
        /* Blink the LED: 1 second on, 1 second off */
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED on)");
            break;
        }
        sleep(1);
        if (!running) break;

        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED off)");
            break;
        }
        sleep(1);
        if (!running) break;

        /* Poll for a falling-edge event with a 1-second timeout so we can
         * re-check the running flag periodically even if no event arrives. */
        ret = gpiod_line_event_wait(button_line, &(struct timespec){1, 0});
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            /* Timeout — no event, continue blinking */
            continue;
        }

        /* Event detected — read it to clear the event queue */
        struct gpiod_line_event event;
        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        /* Turn off the LED and exit */
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED off final)");
            break;
        }

        printf("Button pressed! Exiting.\n");
        fflush(stdout);
        break;
    }

    /* Clean up all resources on every exit path */
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

