#include <gpiod.h>

#define LED_PIN    24   /* BCM 24, physical pin 18 */
#define BUTTON_PIN 22   /* BCM 22, physical pin 15 */
#define BLINK_MS   500

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led  = NULL;
    struct gpiod_line *btn  = NULL;
    int ret;

    /* --- signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- open the default gpiochip (gpiochip0 on Pi 3/4/5) --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* --- get the LED line --- */
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line(LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* --- get the button line --- */
    btn = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!btn) {
        perror("gpiod_chip_get_line(BUTTON)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* --- request LED as output, initial value LOW --- */
    ret = gpiod_line_request_output(led, "led-blink", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(LED)");
        goto cleanup;
    }

    /* --- request button as input with pull-down --- */
    ret = gpiod_line_request_input_flags(btn, "button-read",
                                         GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags(BUTTON)");
        goto cleanup;
    }

    printf("Press and hold the button (BCM %d) to blink the LED (BCM %d).\n",
           BUTTON_PIN, LED_PIN);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (running) {
        int val = gpiod_line_get_value(btn);
        if (val < 0) {
            perror("gpiod_line_get_value(BUTTON)");
            break;
        }

        if (val == 1) {
            /* button pressed: blink until released */
            while (running) {
                ret = gpiod_line_set_value(led, 1);
                if (ret < 0) {
                    perror("gpiod_line_set_value(LED, 1)");
                    goto cleanup;
                }
                usleep(BLINK_MS * 1000);

                if (!running)
                    break;

                ret = gpiod_line_set_value(led, 0);
                if (ret < 0) {
                    perror("gpiod_line_set_value(LED, 0)");
                    goto cleanup;
                }
                usleep(BLINK_MS * 1000);

                val = gpiod_line_get_value(btn);
                if (val < 0) {
                    perror("gpiod_line_get_value(BUTTON)");
                    goto cleanup;
                }
                if (val == 0)
                    break;   /* released */
            }
        } else {
            /* button not pressed: ensure LED off */
            ret = gpiod_line_set_value(led, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value(LED, 0)");
                goto cleanup;
            }
            usleep(10000);   /* 10 ms poll */
        }
    }

cleanup:
    /* --- release lines and close chip --- */
    if (led) {
        gpiod_line_release(led);
    }
    if (btn) {
        gpiod_line_release(btn);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (running == 0) {
        printf("\nExiting cleanly.\n");
    }
    return EXIT_SUCCESS;
}

