#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_FREQ_HZ   100
#define PWM_PERIOD_US (1000000 / PWM_FREQ_HZ)  /* 10 000 us */
#define STEP_US       100                     /* 100 us per PWM step  */
#define STEP_COUNT    (PWM_PERIOD_US / STEP_US) /* 100 steps per cycle */
#define COLOR_CHANGE_MS 100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_pwm_step(int pin, int step, int max_step)
{
    int duty = (step * 255) / max_step;  /* 0..255 */
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "gpioPWM failed on pin %d: %s\n",
                pin, pigpio_error(gpioGetMode(pin)));
        return -1;
    }
    return 0;
}

static int run_pwm_cycle(int r, int g, int b)
{
    int max_step = (r > g && r > b) ? r : (g > b ? g : b);
    if (max_step == 0) {
        /* All-off: drive every line low and skip the loop. */
        if (gpioWrite(RED_PIN, 0) < 0 ||
            gpioWrite(GREEN_PIN, 0) < 0 ||
            gpioWrite(BLUE_PIN, 0) < 0) {
            fprintf(stderr, "gpioWrite failed during all-off: %s\n",
                    pigpio_error(gpioGetMode(RED_PIN)));
            return -1;
        }
        return 0;
    }

    for (int step = 0; step <= STEP_COUNT && g_running; ++step) {
        if (set_pwm_step(RED_PIN,   r, max_step) < 0) return -1;
        if (set_pwm_step(GREEN_PIN, g, max_step) < 0) return -1;
        if (set_pwm_step(BLUE_PIN,  b, max_step) < 0) return -1;

        /* Busy-wait sub-millisecond PWM using clock_nanosleep. */
        struct timespec ts = { 0, STEP_US * 1000 };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running) {
            /* interrupted by signal; loop may continue if still running */
        }
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handler for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure RGB pins as outputs. */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed: %s\n", pigpio_error(gpioGetMode(RED_PIN)));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off. */
    if (gpioWrite(RED_PIN, 0) < 0 ||
        gpioWrite(GREEN_PIN, 0) < 0 ||
        gpioWrite(BLUE_PIN, 0) < 0) {
        fprintf(stderr, "Initial gpioWrite failed: %s\n",
                pigpio_error(gpioGetMode(RED_PIN)));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        int r = rand() % 101;
        int g = rand() % 101;
        int b = rand() % 101;

        if (run_pwm_cycle(r, g, b) < 0) {
            break;
        }

        /* Wait 100 ms before changing to the next random colour. */
        struct timespec ts = { 0, COLOR_CHANGE_MS * 1000000L };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running) {
            /* interrupted by signal; loop may continue if still running */
        }
    }

    /* Clean shutdown: drive all lines low and release pigpio. */
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

