#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* ADPD188BI I2C address (7-bit, default 0x48 when A0/A1 pins low) */
#define ADPD188BI_ADDR 0x48

/* ADPD188BI register addresses */
#define REG_ALS_LSB   0x00
#define REG_ALS_MSB   0x01
#define REG_RED_LSB   0x02
#define REG_RED_MSB   0x03
#define REG_GREEN_LSB 0x04
#define REG_GREEN_MSB 0x05
#define REG_BLUE_LSB  0x06
#define REG_BLUE_MSB  0x07
#define REG_CONFIG    0x0F

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 18

/* Sampling interval in microseconds (500 ms) */
#define SAMPLE_INTERVAL_US 500000

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup happens   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register (little-endian on wire)   */
/* ------------------------------------------------------------------ */
static int adpd_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);          /* LSB first */
    buf[2] = (char)((value >> 8) & 0xFF);   /* MSB second */

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register (little-endian on wire)  */
/* ------------------------------------------------------------------ */
static int adpd_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }

    *out = (uint16_t)((uint8_t)data[0] | ((uint8_t)data[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADPD188BI sensor                                    */
/* ------------------------------------------------------------------ */
static int adpd188bi_init(int handle)
{
    /* Put device into standby mode before configuration */
    if (adpd_write_reg16(handle, REG_CONFIG, 0x0000) != 0)
        return -1;

    /* Enable ALS channel and set integration time / range */
    if (adpd_write_reg16(handle, REG_CONFIG, 0x0001) != 0)
        return -1;

    /* Allow time for the sensor to settle */
    gpioDelay(10000); /* 10 ms */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit channel value                                        */
/* ------------------------------------------------------------------ */
static int read_channel(int handle, uint8_t lsb_reg, uint8_t msb_reg,
                        uint16_t *value)
{
    uint16_t lsb, msb;

    if (adpd_read_reg16(handle, lsb_reg, &lsb) != 0)
        return -1;
    if (adpd_read_reg16(handle, msb_reg, &msb) != 0)
        return -1;

    *value = (msb << 8) | lsb;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all four channels                                             */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, uint16_t *als,
                            uint16_t *red, uint16_t *green, uint16_t *blue)
{
    if (read_channel(handle, REG_ALS_LSB, REG_ALS_MSB, als) != 0)
        return -1;
    if (read_channel(handle, REG_RED_LSB, REG_RED_MSB, red) != 0)
        return -1;
    if (read_channel(handle, REG_GREEN_LSB, REG_GREEN_MSB, green) != 0)
        return -1;
    if (read_channel(handle, REG_BLUE_LSB, REG_BLUE_MSB, blue) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Map ALS value to PWM duty cycle (0–255)                            */
/* ------------------------------------------------------------------ */
static int map_als_to_pwm(uint16_t als)
{
    int pwm;
    if (als > 65535)
        pwm = 255;
    else
        pwm = (int)((als * 255UL) / 65535UL);
    return pwm;
}

/* ------------------------------------------------------------------ */
/* Log one row to the CSV file                                        */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t als, uint16_t red,
                     uint16_t green, uint16_t blue)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Turn off LED and terminate pigpio */
    gpioPWM(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ADPD188BI address */
    g_i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, ADPD188BI_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (adpd188bi_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: ADPD188BI initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin for hardware PWM */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(LED_PIN, 1000); /* 1 kHz */
    gpioPWM(LED_PIN, 0);                /* start off */

    /* Open CSV file for logging */
    g_log_file = fopen("color_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Could not open color_log.csv for writing\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(g_log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADPD188BI color sensor logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t als, red, green, blue;

        if (read_sensor_data(g_i2c_handle, &als, &red, &green, &blue) == 0) {
            log_data(g_log_file, als, red, green, blue);
            int pwm = map_als_to_pwm(als);
            gpioPWM(LED_PIN, pwm);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying in 100 ms...\n");
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        gpioDelay(SAMPLE_INTERVAL_US); /* 500 ms */
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

