#define FXOS8700_STATUS_ZYXDR    0x08

/* ---- Application constants ---- */
#define ACCEL_RANGE_2G          2.0f
#define ACCEL_SENSITIVITY       (ACCEL_RANGE_2G / 32768.0f)
#define IMPACT_THRESHOLD        2.5f
