/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %d\n",
                reg, len, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "Short read: expected %u bytes, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_fxos8700(int handle)
{
    uint8_t who = 0;
    if (i2c_read_block(handle, FXOS8700_WHO_AM_I, &who, 1) != 0)
        return -1;
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode (clear ACTIVE bit) */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Configure magnetometer: 10 Hz ODR, default range */
    if (i2c_write_byte(handle, FXOS8700_M_CTRL_REG1, 0x1F) != 0)
        return -1;
    if (i2c_write_byte(handle, FXOS8700_M_CTRL_REG2, 0x20) != 0)
        return -1;

    /* Accelerometer: ±2 g range, 200 Hz ODR, standby */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Enable XYZ axes, set to active mode (bit 0 = ACTIVE) */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x01) != 0)
        return -1;

    return 0;
