                FXOS8700_I2C_BUS, FXOS8700_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_fxos8700(g_i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialised. Monitoring for impacts (threshold %.2f g)...\n",
           IMPACT_THRESHOLD);

    while (g_running) {
        float x, y, z;
        if (read_accelerometer(g_i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error — continuing\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > IMPACT_THRESHOLD) {
            printf("Impact detected! Magnitude: %.3f g\n", magnitude);
            log_impact(x, y, z, magnitude);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

