    if (i2c_write_reg8(fd, CTRL_REG4, 0x80) != 0) return -1;
    return 0;
}

static int gyro_read_raw(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg8(fd, OUT_X_L, &xl) != 0) return -1;
    if (i2c_read_reg8(fd, OUT_X_H, &xh) != 0) return -1;
    if (i2c_read_reg8(fd, OUT_Y_L, &yl) != 0) return -1;
    if (i2c_read_reg8(fd, OUT_Y_H, &yh) != 0) return -1;
    if (i2c_read_reg8(fd, OUT_Z_L, &zl) != 0) return -1;
    if (i2c_read_reg8(fd, OUT_Z_H, &zh) != 0) return -1;
    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static int calibrate_gyro(int fd, float *x_off, float *y_off, float *z_off) {
    int16_t x, y, z;
    float sx = 0, sy = 0, sz = 0;
    printf("Calibrating gyroscope (keep sensor stationary)...\n");
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        if (g_running == 0) return -1;
        if (gyro_read_raw(fd, &x, &y, &z) != 0) return -1;
        sx += x; sy += y; sz += z;
        usleep(10000);
    }
    *x_off = sx / CALIB_SAMPLES;
    *y_off = sy / CALIB_SAMPLES;
    *z_off = sz / CALIB_SAMPLES;
    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", *x_off, *y_off, *z_off);
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(fp);
}

static void check_alert(float x, float y, float z) {
    if (x > ALERT_THRESHOLD || x < -ALERT_THRESHOLD ||
        y > ALERT_THRESHOLD || y < -ALERT_THRESHOLD ||
        z > ALERT_THRESHOLD || z < -ALERT_THRESHOLD) {
        time_t t = time(NULL);
        struct tm tm;
        if (localtime_r(&t, &tm) == NULL) return;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(g_log_fp, "%s,ALERT,%.2f,%.2f,%.2f\n", ts, x, y, z);
        fflush(g_log_fp);
        fprintf(stderr, "ALERT: %.2f, %.2f, %.2f\n", x, y, z);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }
    if (gyro_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    float x_off = 0, y_off = 0, z_off = 0;
    if (calibrate_gyro(g_i2c_fd, &x_off, &y_off, &z_off) != 0) {
        fprintf(stderr, "Calibration failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen("gyro_log.txt", "a");
    if (g_log_fp == NULL) {
        perror("fopen gyro_log.txt");
        close(g_i2c_fd);
        return 1;
    }

    printf("Logging gyroscope data to gyro_log.txt (Ctrl+C to stop)...\n");
    while (g_running) {
        int16_t xr, yr, zr;
        if (gyro_read_raw(g_i2c_fd, &xr, &yr, &zr) != 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        float x = (float)xr - x_off;
        float y = (float)yr - y_off;
        float z = (float)zr - z_off;
        log_data(g_log_fp, x, y, z);
        check_alert(x, y, z);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

