#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (SDO tied to GND) */
#define ADXL345_ADDR 0x53

/* ADXL345 registers */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID_VAL   0xE5

/* Full-resolution, ±2 g range, 10 Hz ODR */
#define ADXL345_CFG_VAL     0x0B

/* LED GPIO (BCM 17) */
#define LED_PIN 17

/* ±2 g full-resolution sensitivity: 4 mg/LSB => 1 g = 256 LSB */
#define G_PER_LSB 0.004

/* Log file path */
#define LOG_FILE "accel_log.txt"

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int adxl345_write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int adxl345_read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int adxl345_init(void)
{
    uint8_t devid = 0;

    if (adxl345_read_reg(ADXL345_DEVID, &devid) != 0)
        return -1;

    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }

    /* Standby first (clear measure bit) */
    if (adxl345_write_reg(ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Full resolution, ±2 g, 10 Hz ODR */
    if (adxl345_write_reg(ADXL345_DATA_FORMAT, ADXL345_CFG_VAL) != 0)
        return -1;

    /* Enable measurement */
    if (adxl345_write_reg(ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

static int read_acceleration(float *x, float *y, float *z)
{
    char raw[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(g_i2c_handle, ADXL345_DATAX0, raw, 6) != 6) {
        fprintf(stderr, "Failed to read 6-byte acceleration block\n");
        return -1;
    }

    x_raw = (int16_t)(((uint8_t)raw[1] << 8) | (uint8_t)raw[0]);
    y_raw = (int16_t)(((uint8_t)raw[3] << 8) | (uint8_t)raw[2]);
    z_raw = (int16_t)(((uint8_t)raw[5] << 8) | (uint8_t)raw[4]);

    *x = x_raw * G_PER_LSB;
    *y = y_raw * G_PER_LSB;
    *z = z_raw * G_PER_LSB;

    return 0;
}

static void log_data(float x, float y, float z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(g_log_file);
}

static void control_led(float x, float y, float z)
{
    float threshold = 2.0f;
    if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

int main(void)
{
    float x, y, z;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n",
                ADXL345_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
            control_led(x, y, z);
        } else {
            fprintf(stderr, "Read error; skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

