code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_CRA_REG_M     0x00
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03

/* ---- Sensitivities ---- */
#define ACCEL_SENSITIVITY 0.000061f   /* g/LSB at +/-2g */
#define MAG_SENSITIVITY   0.00014f    /* gauss/LSB at +/-1.3gauss */

/* ---- Globals for cleanup ---- */
static int i2c_handle_accel = -1;
static int i2c_handle_mag   = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle_accel >= 0) {
        i2cClose(i2c_handle_accel);
        i2c_handle_accel = -1;
    }
    if (i2c_handle_mag >= 0) {
        i2cClose(i2c_handle_mag);
        i2c_handle_mag = -1;
    }
    gpioTerminate();
}

/* ---- Accelerometer helpers ---- */
static int init_accelerometer(int handle)
{
    /* Enable accelerometer, normal mode, +/-2g, 100 Hz ODR */
    if (i2cWriteByteData(handle, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error: failed to write accelerometer control register\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(int handle, float *x, float *y, float *z)
{
    char buffer[6];
    if (i2cReadI2CBlockData(handle, LSM303_ACCEL_OUT_X_L_A, buffer, 6) != 6) {
        fprintf(stderr, "Error: failed to read accelerometer data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

/* ---- Magnetometer helpers ---- */
static int init_magnetometer(int handle)
{
    /* Continuous conversion mode, 80 Hz output data rate */
    if (i2cWriteByteData(handle, LSM303_MAG_CRA_REG_M, 0x70) < 0) {
        fprintf(stderr, "Error: failed to write magnetometer CRA register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write magnetometer MR register\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int handle, float *x, float *y, float *z)
{
    char buffer[6];
    if (i2cReadI2CBlockData(handle, LSM303_MAG_OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error: failed to read magnetometer data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[0] << 8) | (uint8_t)buffer[1]);
    int16_t raw_z = (int16_t)((buffer[2] << 8) | (uint8_t)buffer[3]);
    int16_t raw_y = (int16_t)((buffer[4] << 8) | (uint8_t)buffer[5]);

    *x = (float)raw_x * MAG_SENSITIVITY;
    *y = (float)raw_y * MAG_SENSITIVITY;
    *z = (float)raw_z * MAG_SENSITIVITY;
    return 0;
}

/* ---- Tilt-compensated heading ---- */
static float calculate_heading(float ax, float ay, float az,
                                float mx, float my, float mz)
{
    float pitch = asinf(-ax / sqrtf(ax * ax + ay * ay + az * az));
    float roll  = asinf(ay / sqrtf(ax * ax + ay * ay + az * az));

    float x_h = mx * cosf(pitch) + mz * sinf(pitch);
    float y_h = mx * sinf(roll) * sinf(pitch) +
                my * cosf(roll) -
                mz * sinf(roll) * cosf(pitch);

    float heading = atan2f(y_h, x_h) * 180.0f / M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ---- Logging ---- */
static void log_data(float heading, float ax, float ay, float az,
                     float mx, float my, float mz)
{
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: failed to open compass_log.txt\n");
        return;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }

    time_t t = time(NULL);
    struct tm tm;
