#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x28
#define SENSOR2_ADDR 0x29
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE_NAME "audio_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %s\n",
                bus, addr, strerror(errno));
        return -1;
    }
    return handle;
}

static int read_audio_sample(int handle, int16_t *sample) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C handle %d: expected 2 bytes, got %d\n",
                handle, bytes_read);
        return -1;
    }
    *sample = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void log_data(FILE *fp, int16_t s1, int16_t s2, long long tdoa_ns) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%ld,%lld,%d,%d,%lld\n", ts.tv_sec, ts.tv_nsec, s1, s2, tdoa_ns);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    printf("Audio logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t sample1 = 0, sample2 = 0;
        int rc1 = read_audio_sample(i2c_handle1, &sample1);
        int rc2 = read_audio_sample(i2c_handle2, &sample2);

        if (rc1 == 0 && rc2 == 0) {
            long long tdoa_ns = (long long)(sample2 - sample1) * 1000LL;
            log_data(log_file, sample1, sample2, tdoa_ns);
        } else {
            fprintf(stderr, "Read error — skipping sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    printf("Audio logging stopped.\n");
    return 0;
}

