#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A SPI configuration */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0x00000003 /* Mode 3: CPOL=1, CPHA=1, 16-bit words */

/* ADIS16488A register addresses (7-bit, MSB of command word = 0) */
#define REG_GYRO_X_OUT  0x04
#define REG_GYRO_Y_OUT  0x06
#define REG_GYRO_Z_OUT  0x08
#define REG_ACCEL_X_OUT 0x0A
#define REG_ACCEL_Y_OUT 0x0C
#define REG_ACCEL_Z_OUT 0x0E

/* Sensitivity: 0.005 deg/sec/LSB for gyro, 0.00025 g/LSB for accel */
#define GYRO_SENSITIVITY  0.005f
#define ACCEL_SENSITIVITY 0.00025f

/* Stall time between read request and data transfer (>= 40 us) */
#define STALL_US         40

/* Sampling interval */
#define SAMPLE_US        100000

/* SPI command word: MSB = 0 (read), bits[6:0] = register address */
#define CMD_READ(reg)    ((uint16_t)(reg) & 0x007F)

/* Globals for cleanup */
static int  spi_handle = -1;
static FILE *fp        = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — called on normal exit via atexit()                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16488A                          */
/* Returns 0 on success, -1 on SPI transfer failure                   */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx_cmd[2] = { (char)(CMD_READ(reg) >> 8),
                       (char)(CMD_READ(reg) & 0xFF) };
    char rx_cmd[2] = { 0, 0 };
    char tx_data[2] = { 0, 0 };
    char rx_data[2] = { 0, 0 };

    /* Phase 1: send read command, receive dummy */
    if (spiXfer(spi_handle, tx_cmd, rx_cmd, 2) != 2) {
        fprintf(stderr, "SPI command transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    /* Stall time between request and data phase */
    gpioDelay(STALL_US);

    /* Phase 2: send dummy, receive data */
    if (spiXfer(spi_handle, tx_data, rx_data, 2) != 2) {
        fprintf(stderr, "SPI data transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx_data[0] << 8) | (uint8_t)rx_data[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all six axes and convert to engineering units                  */
/* ------------------------------------------------------------------ */
static int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z)
{
    int16_t raw_gx, raw_gy, raw_gz;
    int16_t raw_ax, raw_ay, raw_az;

    if (read_register(REG_GYRO_X_OUT, &raw_gx) != 0) return -1;
    if (read_register(REG_GYRO_Y_OUT, &raw_gy) != 0) return -1;
    if (read_register(REG_GYRO_Z_OUT, &raw_gz) != 0) return -1;
    if (read_register(REG_ACCEL_X_OUT, &raw_ax) != 0) return -1;
    if (read_register(REG_ACCEL_Y_OUT, &raw_ay) != 0) return -1;
    if (read_register(REG_ACCEL_Z_OUT, &raw_az) != 0) return -1;

    *gyro_x = (float)raw_gx * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_gy * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_gz * GYRO_SENSITIVITY;
    *accel_x = (float)raw_ax * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_ay * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_az * ACCEL_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample with millisecond timestamp                           */
/* ------------------------------------------------------------------ */
static void log_data(FILE *f, long long timestamp_ms,
                     float gx, float gy, float gz,
                     float ax, float ay, float az)
{
    fprintf(f, "%lld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp_ms, gx, gy, gz, ax, ay, az);
    fflush(f);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 3, 16-bit words */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file for appending */
    fp = fopen("imu_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening imu_data.csv for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
