    uint8_t rx[2] = { 0 };

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        return -1;
    }

    *value = (int16_t)((rx[1] << 8) | rx[0]);
    return 0;
}

