        float gyro_y = (float)gy * GYRO_SCALE;
        float gyro_z = (float)gz * GYRO_SCALE;
        float accel_x = (float)ax * ACCEL_SCALE;
        float accel_y = (float)ay * ACCEL_SCALE;
        float accel_z = (float)az * ACCEL_SCALE;

        printf("Gyro: X=%.3f dps, Y=%.3f dps, Z=%.3f dps | Accel: X=%.6f g, Y=%.6f g, Z=%.6f g\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        fflush(stdout);

        usleep(SAMPLE_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

