#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* ADIS16448 register addresses (bits 0-13 of the 16-bit command word) */
#define ADIS16448_REG_GYRO_X_OUT 0x04
#define ADIS16448_REG_GYRO_Y_OUT 0x06
#define ADIS16448_REG_GYRO_Z_OUT 0x08
#define ADIS16448_REG_ACCEL_X_OUT 0x0A
#define ADIS16448_REG_ACCEL_Y_OUT 0x0C
#define ADIS16448_REG_ACCEL_Z_OUT 0x0E

/* Scaling factors (from ADIS16448 datasheet) */
#define GYRO_SCALE 0.05f   /* degrees/sec per LSB */
#define ACCEL_SCALE 0.00025f /* g per LSB */

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 /* 1 MHz */
#define SPI_FLAGS 0        /* Mode 0, active-low CE */

/* Stall time between the two 16-bit transfers (>= 40 us) */
#define STALL_US 40

/* Global SPI handle for signal handler cleanup */
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a 16-bit register from the ADIS16448 using the two-cycle SPI protocol.
 * Returns 0 on success, -1 on SPI transfer failure. */
static int read_register(uint8_t reg_addr, int16_t *out) {
    char tx_cmd[2];
    char rx_cmd[2];
    char tx_dummy[2] = {0x00, 0x00};
    char rx_data[2];

    /* Phase 1: send read command (reg address | 0x80) */
    tx_cmd[0] = (char)(reg_addr | 0x80);
    tx_cmd[1] = 0x00;

    if (spiXfer(spi_handle, tx_cmd, rx_cmd, 2) != 2) {
        fprintf(stderr, "SPI command transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    /* Stall time to allow the device to prepare the response */
    gpioDelay(STALL_US);

    /* Phase 2: send dummy bytes to clock out the 16-bit data */
    if (spiXfer(spi_handle, tx_dummy, rx_data, 2) != 2) {
        fprintf(stderr, "SPI data transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    /* Data is returned MSB first */
    *out = (int16_t)(((uint8_t)rx_data[0] << 8) | (uint8_t)rx_data[1]);
    return 0;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 (CE0 on GPIO8) at 1 MHz, Mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU Reader (SPI0, 1 MHz, Mode 0)\n");
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (running) {
        int16_t gyro_x, gyro_y, gyro_z;
        int16_t accel_x, accel_y, accel_z;

        /* Read gyroscope data */
        if (read_register(ADIS16448_REG_GYRO_X_OUT, &gyro_x) != 0 ||
            read_register(ADIS16448_REG_GYRO_Y_OUT, &gyro_y) != 0 ||
            read_register(ADIS16448_REG_GYRO_Z_OUT, &gyro_z) != 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
        } else {
            /* Read accelerometer data */
            if (read_register(ADIS16448_REG_ACCEL_X_OUT, &accel_x) != 0 ||
                read_register(ADIS16448_REG_ACCEL_Y_OUT, &accel_y) != 0 ||
                read_register(ADIS16448_REG_ACCEL_Z_OUT, &accel_z) != 0) {
                fprintf(stderr, "Failed to read accelerometer data\n");
            } else {
                /* Convert raw data to physical units */
                float gyro_x_deg = (float)gyro_x * GYRO_SCALE;
                float gyro_y_deg = (float)gyro_y * GYRO_SCALE;
                float gyro_z_deg = (float)gyro_z * GYRO_SCALE;
                float accel_x_g = (float)accel_x * ACCEL_SCALE;
                float accel_y_g = (float)accel_y * ACCEL_SCALE;
                float accel_z_g = (float)accel_z * ACCEL_SCALE;

                /* Print the data to the console */
                printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n",
                       gyro_x_deg, gyro_y_deg, gyro_z_deg);
                printf("Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n\n",
                       accel_x_g, accel_y_g, accel_z_g);
            }
        }

        /* Wait 100 ms before the next reading */
        gpioDelay(100000); /* 100 ms in microseconds */
    }

    /* Clean up resources on exit */
    printf("\nExiting...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

