#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6886_ADDR 0x68

#define MPU6886_REG_SMPLRT_DIV   0x19
#define MPU6886_REG_PWR_MGMT_1   0x6B
#define MPU6886_REG_ACCEL_XOUT_H 0x3B
#define MPU6886_REG_GYRO_XOUT_H  0x43

#define ACCEL_SCALE 16384.0f
#define GYRO_SCALE  131.0f

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int read_axis(int fd, uint8_t reg, float scale, float *out) {
    uint8_t buf[6];
    for (int attempt = 0; attempt < 3; attempt++) {
        if (i2c_read_burst(fd, reg, buf, 6) == 0) {
            int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
            *out = (float)raw / scale;
            return 0;
        }
        fprintf(stderr, "I2C read error (attempt %d): %s\n", attempt + 1, strerror(errno));
        usleep(10000);
    }
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6886_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg8(fd, MPU6886_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU6886: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    usleep(100000);

    if (i2c_write_reg8(fd, MPU6886_REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Failed to set sample rate divider: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("MPU6886 initialized. Reading data every 50ms...\n");

    while (g_running) {
        float ax, ay, az, gx, gy, gz;

        if (read_axis(fd, MPU6886_REG_ACCEL_XOUT_H, ACCEL_SCALE, &ax) < 0 ||
            read_axis(fd, MPU6886_REG_ACCEL_XOUT_H + 2, ACCEL_SCALE, &ay) < 0 ||
            read_axis(fd, MPU6886_REG_ACCEL_XOUT_H + 4, ACCEL_SCALE, &az) < 0 ||
            read_axis(fd, MPU6886_REG_GYRO_XOUT_H, GYRO_SCALE, &gx) < 0 ||
            read_axis(fd, MPU6886_REG_GYRO_XOUT_H + 2, GYRO_SCALE, &gy) < 0 ||
            read_axis(fd, MPU6886_REG_GYRO_XOUT_H + 4, GYRO_SCALE, &gz) < 0) {
            fprintf(stderr, "Failed to read sensor data after retries.\n");
            break;
        }

        printf("Accel: X=%.2f, Y=%.2f, Z=%.2f  Gyro: X=%.2f, Y=%.2f, Z=%.2f\n", ax, ay, az, gx, gy, gz);
        usleep(50000);
    }

    printf("\nExiting...\n");
    close(fd);
    return 0;
}

