static int i2c_write_checked(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block_checked(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(g_i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, want %u, got %d)\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int adxl345_init(void)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (i2c_read_block_checked(ADXL345_REG_DEVID, &devid, 1) != 0)
        return -1;

    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby -> configure -> measure */
    if (i2c_write_checked(ADXL345_REG_POWER_CTL, 0x00) != 0)
        return -1;
    if (i2c_write_checked(ADXL345_REG_DATA_FORMAT,
                          ADXL345_DATA_FORMAT_FULL_RES |
                          ADXL345_DATA_FORMAT_RANGE_2G) != 0)
        return -1;
    if (i2c_write_checked(ADXL345_REG_POWER_CTL,
                          ADXL345_POWER_CTL_MEASURE) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_accel(accel_t *out)
{
    uint8_t buf[6];

    if (i2c_read_block_checked(ADXL345_REG_DATAX0, buf, 6) != 0)
        return -1;

    out->x = (int16_t)((buf[1] << 8) | buf[0]);
    out->y = (int16_t)((buf[3] << 8) | buf[2]);
    out->z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
static float accel_magnitude(const accel_t *a)
{
    float x = (float)a->x / SCALE_FACTOR;
    float y = (float)a->y / SCALE_FACTOR;
    float z = (float)a->z / SCALE_FACTOR;
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
static void log_impact(float mag, const accel_t *a)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_file,
            "%s  Impact  mag=%.3f g  X=%d  Y=%d  Z=%d\n",
            ts, mag, a->x, a->y, a->z);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE_NAME ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring acceleration (threshold %.1f g) ...  Ctrl-C to exit\n",
           ACCEL_THRESHOLD_G);

    while (g_running) {
        accel_t a;

        if (read_accel(&a) != 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float mag = accel_magnitude(&a);

        if (mag > ACCEL_THRESHOLD_G) {
            gpioWrite(LED_GPIO, 1);
            log_impact(mag, &a);
            gpioDelay(LED_ON_TIME_US);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

