#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* MMA8451Q I2C address (SA0 tied to VCC) */
#define MMA8451_ADDR 0x1D

/* MMA8451Q registers */
#define MMA8451_REG_STATUS   0x00
#define MMA8451_REG_OUT_X_MSB 0x01
#define MMA8451_REG_WHOAMI   0x0D
#define MMA8451_REG_XYZ_DATA_CFG 0x0E
#define MMA8451_REG_CTRL_REG1 0x2A

/* Expected device ID */
#define MMA8451_WHOAMI_VAL 0x1A

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 17

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Threshold: 2.0 g in ±2 g mode (1 g = 1024 counts) */
#define G_THRESHOLD 2.0f
#define COUNTS_PER_G 1024.0f

/* Sampling interval */
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* LED on duration */
#define LED_ON_US 500000  /* 500 ms */

/* Global handles for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a single byte to a register */
static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X (rc=%d)\n", value, reg, rc);
    }
    return rc;
}

/* Read a single byte from a register */
static int read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X (rc=%d)\n", reg, rc);
    }
    return rc;
}

/* Read multiple bytes starting at a register */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading block from reg 0x%02X (rc=%d)\n", reg, rc);
    }
    return rc;
}

/* Initialize the MMA8451Q accelerometer */
static int init_mma8451(int handle) {
    /* Verify device identity */
    int whoami = read_reg(handle, MMA8451_REG_WHOAMI);
    if (whoami < 0) {
        return -1;
    }
    if (whoami != MMA8451_WHOAMI_VAL) {
        fprintf(stderr, "WHOAMI mismatch: got 0x%02X, expected 0x%02X\n", whoami, MMA8451_WHOAMI_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (write_reg(handle, MMA8451_REG_CTRL_REG1, 0x00) < 0) {
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */

    /* Set range to ±2 g (default) */
    if (write_reg(handle, MMA8451_REG_XYZ_DATA_CFG, 0x00) < 0) {
        return -1;
    }

    /* Enable XYZ axes, 800 Hz ODR, active mode */
    if (write_reg(handle, MMA8451_REG_CTRL_REG1, 0x01) < 0) {
        return -1;
    }

    gpioDelay(1000); /* 1 ms settle */
    return 0;
}

/* Read acceleration data (6 bytes, little-endian) */
static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (read_block(handle, MMA8451_REG_OUT_X_MSB, buf, 6) < 0) {
        return -1;
    }

    /* Data is little-endian: LSB first, then MSB */
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

/* Log a reading with timestamp */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X=%d, Y=%d, Z=%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

/* Check if any axis exceeds the threshold */
static bool threshold_exceeded(int16_t x, int16_t y, int16_t z) {
    float gx = (float)x / COUNTS_PER_G;
    float gy = (float)y / COUNTS_PER_G;
    float gz = (float)z / COUNTS_PER_G;
    return (fabsf(gx) > G_THRESHOLD || fabsf(gy) > G_THRESHOLD || fabsf(gz) > G_THRESHOLD);
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, MMA8451_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (rc=%d)\n", I2C_BUS, MMA8451_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_mma8451(i2c_handle) < 0) {
        fprintf(stderr, "MMA8451 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring acceleration (threshold: %.1f g)... Press Ctrl+C to exit.\n", G_THRESHOLD);

    /* Main loop */
    while (running) {
        int16_t x, y, z;

        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);

            if (threshold_exceeded(x, y, z)) {
                printf("Impact detected! X=%d, Y=%d, Z=%d\n", x, y, z);
                gpioWrite(LED_PIN, 1);
                gpioDelay(LED_ON_US);
                gpioWrite(LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

