#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADXL345_ADDR   0x53
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       17

#define ADXL345_REG_DEVID       0x00
#define ADXL345_REG_POWER_CTL   0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0      0x32
#define ADXL345_REG_THRESH_FF   0x28
#define ADXL345_REG_TIME_FF     0x29
#define ADXL345_REG_INT_ENABLE  0x2E
#define ADXL345_REG_INT_MAP     0x2F
#define ADXL345_REG_INT_SOURCE  0x30

#define ADXL345_DEVID          0xE5
#define ADXL345_MODE_STANDBY   0x00
#define ADXL345_MODE_MEASURE   0x08
#define ADXL345_DATA_FORMAT_16BIT 0x0B
#define ADXL345_INT_FREEFALL   0x04
#define ADXL345_INT_MAP_FF     0x04
#define ADXL345_INT_ENABLE_FF  0x04

#define FREEFALL_THRESHOLD     2
#define FREEFALL_TIME          2
#define SAMPLE_DELAY_US        10000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_REG_DEVID, &devid) < 0) return -1;
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n", devid, ADXL345_DEVID);
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, ADXL345_MODE_STANDBY) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_DATA_FORMAT, ADXL345_DATA_FORMAT_16BIT) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_THRESH_FF, FREEFALL_THRESHOLD) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_TIME_FF, FREEFALL_TIME) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_INT_MAP, ADXL345_INT_MAP_FF) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_INT_ENABLE, ADXL345_INT_ENABLE_FF) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, ADXL345_MODE_MEASURE) < 0) return -1;
    return 0;
}

static void log_data(FILE *f, int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(f, "%s.%03ld,%d,%d,%d\n", tbuf, ts.tv_nsec / 1000000, x, y, z);
    fflush(f);
}

static void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
