#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6A

/* LSM6DSR register addresses */
#define WHO_AM_I        0x0F
#define CTRL1_XL        0x10
#define CTRL2_G         0x11
#define OUTX_L_G        0x22
#define OUTX_H_G        0x23
#define OUTY_L_G        0x24
#define OUTY_H_G        0x25
#define OUTZ_L_G        0x26
#define OUTZ_H_G        0x27
#define OUTX_L_A        0x28
#define OUTX_H_A        0x29
#define OUTY_L_A        0x2A
#define OUTY_H_A        0x2B
#define OUTZ_L_A        0x2C
#define OUTZ_H_A        0x2D

/* Expected device ID */
#define LSM6DSR_WHO_AM_I 0x6A

/* Fall detection thresholds (g) and timing (seconds) */
#define FREEFALL_THRESHOLD  0.2f
#define IMPACT_THRESHOLD    2.5f
#define FREEFALL_TIMEOUT    1.0f

/* Accelerometer range: ±2 g  ->  16384 LSB/g */
#define ACCEL_SCALE 16384.0f

/* Gyroscope range: ±250 dps ->  131.072 LSB/dps */
#define GYRO_SCALE 131.072f

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Sampling interval (microseconds) for 104 Hz */
#define SAMPLE_INTERVAL_US 9615

/* Global state */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Fall detection state machine */
typedef enum {
    STATE_IDLE,
    STATE_FREEFALL,
    STATE_IMPACT
} FallState;

static FallState current_state = STATE_IDLE;
static double freefall_start_time = 0.0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    return i2cWriteByteData(handle, reg, val);
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_lsm6dsr(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (i2c_read_reg8(handle, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who_am_i, LSM6DSR_WHO_AM_I);
        return -1;
    }

    /* CTRL1_XL: ODR = 104 Hz (0x60), FS_XL = ±2 g (0x00) */
    if (i2c_write_reg8(handle, CTRL1_XL, 0x60) != 0) {
        fprintf(stderr, "Error: failed to write CTRL1_XL\n");
        return -1;
    }

    /* CTRL2_G: ODR = 104 Hz (0x60), FS_G = ±250 dps (0x00) */
    if (i2c_write_reg8(handle, CTRL2_G, 0x60) != 0) {
        fprintf(stderr, "Error: failed to write CTRL2_G\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                    */
/* ------------------------------------------------------------------ */
static int read_accel_gyro(int handle, float *ax, float *ay, float *az,
                           float *gx, float *gy, float *gz)
{
    uint8_t buf[12];

    /* Read 12 bytes starting at OUTX_L_G (0x22) */
    int rc = i2cReadI2CBlockData(handle, OUTX_L_G, (char *)buf, 12);
    if (rc != 12) {
        return -1;
    }

    /* Gyroscope: little-endian, 16-bit signed */
    int16_t raw_gx = (int16_t)((buf[1]  << 8) | buf[0]);
    int16_t raw_gy = (int16_t)((buf[3]  << 8) | buf[2]);
    int16_t raw_gz = (int16_t)((buf[5]  << 8) | buf[4]);

    /* Accelerometer: little-endian, 16-bit signed */
    int16_t raw_ax = (int16_t)((buf[7]  << 8) | buf[6]);
    int16_t raw_ay = (int16_t)((buf[9]  << 8) | buf[8]);
    int16_t raw_az = (int16_t)((buf[11] << 8) | buf[10]);

    *gx = (float)raw_gx / GYRO_SCALE;
    *gy = (float)raw_gy / GYRO_SCALE;
    *gz = (float)raw_gz / GYRO_SCALE;
    *ax = (float)raw_ax / ACCEL_SCALE;
    *ay = (float)raw_ay / ACCEL_SCALE;
    *az = (float)raw_az / ACCEL_SCALE;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Fall detection state machine                                        */
/* ------------------------------------------------------------------ */
static void update_fall_detection(float accel_magnitude)
{
    double now = time_time();

    switch (current_state) {
    case STATE_IDLE:
        if (accel_magnitude < FREEFALL_THRESHOLD) {
            current_state = STATE_FREEFALL;
            freefall_start_time = now;
            printf("Freefall detected (magnitude: %.3f g)\n", accel_magnitude);
        }
        break;

    case STATE_FREEFALL:
        if (accel_magnitude > IMPACT_THRESHOLD) {
            current_state = STATE_IMPACT;
            printf("Impact detected (magnitude: %.3f g)\n", accel_magnitude);
        } else if ((now - freefall_start_time) > FREEFALL_TIMEOUT) {
            current_state = STATE_IDLE;
            printf("Freefall timeout, returning to IDLE\n");
        }
        break;

    case STATE_IMPACT:
        current_state = STATE_IDLE;
        printf("Returning to IDLE after impact\n");
        break;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, LSM6DSR_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_lsm6dsr(i2c_handle) != 0) {
        fprintf(stderr, "Error: LSM6DSR initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open motion_log.txt\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z,fall_state\n");
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LSM6DSR fall detection running. Press Ctrl+C to stop.\n");

    /* Main acquisition loop */
    while (program_running) {
        float ax, ay, az, gx, gy, gz;

        if (read_accel_gyro(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) != 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float accel_magnitude = sqrtf(ax * ax + ay * ay + az * az);

        /* Log data to CSV */
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%d\n",
                timestamp, ax, ay, az, gx, gy, gz, current_state);
        fflush(log_file);

        /* Fall detection */
        update_fall_detection(accel_magnitude);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

