#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 register addresses */
#define ADIS16266_WHO_AM_I   0x02
#define ADIS16266_GYRO_X_OUT 0x04
#define ADIS16266_GYRO_Y_OUT 0x06
#define ADIS16266_GYRO_Z_OUT 0x08

#define ADIS16266_WHO_AM_I_VAL 0x2A

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0x3       /* mode 3: CPOL=1, CPHA=1 */

/* Sampling interval */
#define SAMPLE_INTERVAL_US 10000  /* 10 ms */

/* Scale factor: 0.0305 deg/sec/LSB */
#define SCALE_FACTOR 0.0305f

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from the ADIS16266.
 * The ADIS16266 requires a 2-byte transfer for each register access:
 *   tx[0] = address | 0x80  (read command)
 *   tx[1] = 0x00       (dummy, response clocked out)
 * The 16-bit response is returned in big-endian order.
 * Returns 0 on success, -1 on SPI error. */
static int read_register(uint8_t address, uint16_t *value)
{
    char tx[2] = { (char)(address | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (ret=%d)\n",
                address, ret);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* Write a 16-bit value to a register.
 * The ADIS16266 requires a 2-byte transfer for each write:
 *   tx[0] = address & 0x7F  (write command)
 *   tx[1] = data & 0x00FF   (low byte first)
 * Returns 0 on success, -1 on SPI error. */
static int write_register(uint8_t address, uint16_t value)
{
    char tx[2] = { (char)(address & 0x7F), (char)(value & 0xFF) };
    char rx[2] = { 0, 0 };

    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X (ret=%d)\n",
                address, ret);
        return -1;
    }
    return 0;
}

/* Initialize the ADIS16266: verify WHO_AM_I and configure gyro range. */
static int initialize_gyro(void)
{
    uint16_t who_am_i = 0;

    if (read_register(ADIS16266_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who_am_i, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }

    printf("ADIS16266 detected (WHO_AM_I = 0x%04X)\n", who_am_i);

    /* Set gyro range to +/- 250 deg/sec (register 0x36, bits 1:0 = 00) */
    if (write_register(0x36, 0x0000) != 0) {
        fprintf(stderr, "Failed to configure gyro range\n");
        return -1;
    }

    return 0;
}

/* Read angular rate from a given axis register. */
static int read_gyro_axis(uint8_t address, float *rate)
{
    uint16_t raw = 0;

    if (read_register(address, &raw) != 0) {
        return -1;
    }

    /* Sign-extend 16-bit value to 32-bit float */
    int16_t signed_raw = (int16_t)raw;
    *rate = (float)signed_raw * SCALE_FACTOR;
    return 0;
}

/* Append a timestamped reading to the CSV log file. */
static void log_data(float x, float y, float z)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 (CE0 on GPIO8), mode 3, 1 MHz */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (initialize_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_Rate,Y_Rate,Z_Rate\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging gyroscope data to gyro_log.csv (Ctrl+C to stop)...\n");

    /* Main sampling loop */
    while (!terminate) {
        float x_rate, y_rate, z_rate;

        if (read_gyro_axis(ADIS16266_GYRO_X_OUT, &x_rate) != 0 ||
            read_gyro_axis(ADIS16266_GYRO_Y_OUT, &y_rate) != 0 ||
            read_gyro_axis(ADIS16266_GYRO_Z_OUT, &z_rate) != 0) {
            fprintf(stderr, "Error reading gyroscope data, skipping sample\n");
        } else {
            log_data(x_rate, y_rate, z_rate);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

