#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

/* L3G4200D I2C address (SA0 tied high on GY-50) */
#define GYRO_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I   0x0F
#define CTRL_REG1  0x20
#define CTRL_REG4  0x23
#define OUT_X_L    0x28
#define OUT_X_H    0x29
#define OUT_Y_L    0x2A
#define OUT_Y_H    0x2B
#define OUT_Z_L    0x2C
#define OUT_Z_H    0x2D

/* Expected device ID */
#define WHO_AM_I_EXPECTED 0xD3

/* Sensitivity: 8.75 mdps/LSB => 1 dps = 114.285 LSB */
#define SENSITIVITY 114.285f

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register, retrying up to 3 times                */
/* ------------------------------------------------------------------ */
static bool i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < 3; ++attempt) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return true;
        gpioDelay(1000); /* 1 ms back-off */
    }
    return false;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register                                       */
/* ------------------------------------------------------------------ */
static bool i2c_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0)
        return false;
    *out = (uint8_t)rc;
    return true;
}

/* ------------------------------------------------------------------ */
/* Initialize the L3G4200D: verify identity, then configure            */
/* ------------------------------------------------------------------ */
static bool gyro_init(int handle)
{
    uint8_t who_am_i = 0;

    if (!i2c_read_reg(handle, WHO_AM_I, &who_am_i)) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register (I2C bus error).\n");
        return false;
    }

    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who_am_i, WHO_AM_I_EXPECTED);
        return false;
    }

    /* CTRL_REG1: 100 Hz ODR, normal mode, all axes enabled */
    if (!i2c_write_reg(handle, CTRL_REG1, 0x0F)) {
        fprintf(stderr, "Error: failed to write CTRL_REG1.\n");
        return false;
    }

    /* CTRL_REG4: full-scale +/-250 dps (0x00) */
    if (!i2c_write_reg(handle, CTRL_REG4, 0x00)) {
        fprintf(stderr, "Error: failed to write CTRL_REG4.\n");
        return false;
    }

    return true;
}

/* ------------------------------------------------------------------ */
/* Read a 6-byte block of angular-rate data                            */
/* ------------------------------------------------------------------ */
static bool gyro_read(int handle, float *x, float *y, float *z)
{
    char buffer[6];

    int bytes = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
    if (bytes != 6) {
        fprintf(stderr, "Error: I2C block read returned %d bytes (expected 6).\n", bytes);
        return false;
    }

    int16_t raw_x = (int16_t)(((uint8_t)buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)(((uint8_t)buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)(((uint8_t)buffer[5] << 8) | (uint8_t)buffer[4]);

    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;

    return true;
}

/* ------------------------------------------------------------------ */
