    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%09ld,%.3f,%.3f,%.3f\n",
                timestamp, ts.tv_nsec, x, y, z) < 0) {
        perror("fprintf");
        return false;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return false;
    }

    return true;
}

