#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME     "flame_events.log"
#define POLL_INTERVAL_US  500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for Ctrl-C (SIGINT)                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int signal)
{
    (void)signal;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file and flush immediately.     */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    if (log_file == NULL) {
        fprintf(stderr, "Error: log file is not open.\n");
        return -1;
    }

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(log_file, "%s – %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the flame sensor digital output.                               */
/* Returns: 1 (flame detected / LOW), 0 (no flame / HIGH), or -1 error.*/
/* ------------------------------------------------------------------ */
static int read_flame_sensor(int gpio_pin)
{
    int level = gpioRead(gpio_pin);
    if (level == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead failed for GPIO %d (PI_BAD_GPIO).\n",
                gpio_pin);
        return -1;
    }
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed for GPIO %d (returned %d).\n",
                gpio_pin, level);
        return -1;
    }
    return (level == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources.                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_SUCCESS;

    /* --- Initialize pigpio library ------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO17 as input with pull-up ------------------ */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file for appending ----------------------------- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install SIGINT handler for graceful shutdown -------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl-C to exit.\n",
           FLAME_SENSOR_GPIO);

    /* --- Main polling loop --------------------------------------- */
    while (program_running) {
        int flame_detected = read_flame_sensor(FLAME_SENSOR_GPIO);

        if (flame_detected < 0) {
            /* Sensor read error — log the failure and keep polling. */
            log_event("ERROR: flame sensor read failure");
        } else if (flame_detected) {
            /* LOW = flame detected (active-LOW open-collector). */
            log_event("Flame detected: YES");
            printf("FLAME DETECTED!\n");
            fflush(stdout);
        } else {
            /* HIGH = no flame. */
            log_event("Flame detected: NO");
        }

        /* Sleep 500 ms (microseconds). */
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return ret;
}

