#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_I2C_ADDR   0x0A
#define SAMPLE_PERIOD  100000  /* microseconds (100 ms) */
#define CSV_FILENAME   "vibration_log.csv"

/* Omron D7S-0001: 6 bytes starting at register 0x10 */
#define D7S_REG_XYZ     0x10
#define D7S_READ_LEN    6

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_fp    = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_fp) {
        fflush(g_fp);
        fclose(g_fp);
        g_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static int init_i2c(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                D7S_I2C_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t reg = D7S_REG_XYZ;
    uint8_t buf[D7S_READ_LEN];

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register pointer: %s\n", strerror(errno));
        return -1;
    }

    /* Read 6 bytes: X[2], Y[2], Z[2] */
    ssize_t n = read(fd, buf, D7S_READ_LEN);
    if (n != D7S_READ_LEN) {
        if (n < 0)
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        else
            fprintf(stderr, "Short read: got %zd of %d bytes\n", n, D7S_READ_LEN);
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
