#include <unistd.h>
#include <pigpio.h>

#define HALL_SENSOR_1 17
#define HALL_SENSOR_2 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_sensor_data(FILE *fp, int s1, int s2) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%03ld, Sensor1: %d, Sensor2: %d\n",
                timestamp, ts.tv_nsec / 1000000, s1, s2) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int ret = EXIT_SUCCESS;

    if (gpioSetMode(HALL_SENSOR_1, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", HALL_SENSOR_1);
        ret = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpioSetMode(HALL_SENSOR_2, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", HALL_SENSOR_2);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    if (gpioSetPullUpDown(HALL_SENSOR_1, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", HALL_SENSOR_1);
        ret = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpioSetPullUpDown(HALL_SENSOR_2, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", HALL_SENSOR_2);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Monitoring Hall sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           HALL_SENSOR_1, HALL_SENSOR_2);

    while (running) {
        int s1 = gpioRead(HALL_SENSOR_1);
        int s2 = gpioRead(HALL_SENSOR_2);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading GPIOs (s1=%d, s2=%d)\n", s1, s2);
            ret = EXIT_FAILURE;
            break;
        }

        if (log_sensor_data(fp, s1, s2) != 0) {
            ret = EXIT_FAILURE;
            break;
        }

        if (s1 == 1 && s2 == 1) {
            printf("Conveyor halted (both sensors active)\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        ret = EXIT_FAILURE;
    }

cleanup:
    gpioTerminate();
    return ret;
}

