#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x1A
#define CTRL_REG1      0x2A
#define OUT_X_MSB      0x01
#define DATA_REG_SIZE  6
#define LOG_FILE       "fall_log.txt"
#define TILT_THRESHOLD 45.0
#define LOOP_DELAY_US  10000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_accelerometer(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    uint8_t ctrl1 = 0;
    if (i2c_read_reg8(fd, CTRL_REG1, &ctrl1) < 0) {
        return -1;
    }

    if (i2c_write_reg8(fd, CTRL_REG1, 0x00) < 0) {
        return -1;
    }
    usleep(1000);

    if (i2c_write_reg8(fd, CTRL_REG1, ctrl1 | 0x02) < 0) {
        return -1;
    }
    usleep(1000);

    return 0;
}

static int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[DATA_REG_SIZE];
    if (i2c_read_block(fd, OUT_X_MSB, data, DATA_REG_SIZE) < 0) {
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]) >> 4;
    *y = (int16_t)((data[2] << 8) | data[3]) >> 4;
    *z = (int16_t)((data[4] << 8) | data[5]) >> 4;
    return 0;
}

static double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double x_d = (double)x;
    double y_d = (double)y;
    double z_d = (double)z;
    double xy = sqrt(x_d * x_d + y_d * y_d);
    double tilt = atan2(xy, z_d) * 180.0 / M_PI;
    return fabs(tilt);
}

static void log_fall_event(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(g_log_fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(g_log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_accelerometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Accelerometer initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Monitoring tilt events... (Ctrl+C to exit)\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_accelerometer_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, skipping iteration.\n");
            usleep(LOOP_DELAY_US);
            continue;
        }

        double tilt = calculate_tilt(x, y, z);
        if (tilt > TILT_THRESHOLD) {
            log_fall_event(x, y, z);
            printf("Tilt event detected: %.2f degrees\n", tilt);
        }

        usleep(LOOP_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return 0;
}

