#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define LIS3MDL_ADDR 0x1E

#define CTRL_REG1_A 0x20
#define CTRL_REG2_A 0x21
#define CTRL_REG3_A 0x22
#define CTRL_REG4_A 0x23
#define CTRL_REG5_A 0x24
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

#define X_OFFSET 0.0f
#define Y_OFFSET 0.0f
#define Z_OFFSET 0.0f
#define X_SCALE 1.0f
#define Y_SCALE 1.0f
#define Z_SCALE 1.0f

#define METAL_THRESHOLD 800.0f
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define MAX_RETRIES 3

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lis3mdl(void) {
    if (i2c_write_reg(CTRL_REG1_A, 0x70) < 0) return -1;
    if (i2c_write_reg(CTRL_REG2_A, 0x00) < 0) return -1;
    if (i2c_write_reg(CTRL_REG3_A, 0x00) < 0) return -1;
    if (i2c_write_reg(CTRL_REG4_A, 0x0C) < 0) return -1;
    if (i2c_write_reg(CTRL_REG5_A, 0x00) < 0) return -1;
    return 0;
}

static int read_magnetometer(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(OUT_X_L_A | 0x80, buf, 6) < 0) return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = ((float)raw_x - X_OFFSET) * X_SCALE;
    *y = ((float)raw_y - Y_OFFSET) * Y_SCALE;
    *z = ((float)raw_z - Z_OFFSET) * Z_SCALE;
    return 0;
}

static void log_data(float x, float y, float z) {
    fprintf(log_file, "%.2f,%.2f,%.2f\n", x, y, z);
    fflush(log_file);
}

static void check_metal(float x, float y, float z) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detected! Magnitude: %.2f mG\n", magnitude);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int retries = 0;
    while (init_lis3mdl() < 0 && retries < MAX_RETRIES) {
        retries++;
        fprintf(stderr, "LIS3MDL init failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
        usleep(100000);
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "LIS3MDL initialization failed after %d retries.\n", MAX_RETRIES);
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float x, y, z;
        if (read_magnetometer(&x, &y, &z) == 0) {
            log_data(x, y, z);
            check_metal(x, y, z);
        } else {
            fprintf(stderr, "Failed to read magnetometer data.\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

