#define ADXL354B_REG_ZDATA_H  0x0D
#define ADXL354B_REG_TEMP_L  0x0E
#define ADXL354B_REG_TEMP_H  0x0F
#define ADXL354B_REG_FIFO_ENTRIES 0x10
#define ADXL354B_REG_FIFO_DATA  0x11
#define ADXL354B_REG_RANGE     0x2C
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_RESET     0x2E
#define ADXL354B_REG_PARTID    0x00

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* ADXL354B Constants */
#define ADXL354B_PARTID_VALUE 0x534C
#define ADXL354B_RANGE_2G     0x00
#define ADXL354B_POWER_CTL_RUN 0x02
#define ADXL354B_POWER_CTL_STANDBY 0x00
#define ADXL354B_RESET_CMD    0x52

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg & 0x7F), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg | 0x80), (char)value };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        return -1;
    }
    return 0;
}

static int adxl354b_reset(void) {
    if (spi_write_register(ADXL354B_REG_RESET, ADXL354B_RESET_CMD) != 0) {
        fprintf(stderr, "Error: SPI write failed during reset.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    if (spi_write_register(ADXL354B_REG_POWER_CTL, ADXL354B_POWER_CTL_STANDBY) != 0) {
        fprintf(stderr, "Error: SPI write failed clearing RUN bit.\n");
        return -1;
    }

    uint8_t status = 0xFF;
    int retries = 10;
    while (retries-- > 0) {
        if (spi_read_register(ADXL354B_REG_STATUS, &status) != 0) {
            fprintf(stderr, "Error: SPI read failed reading status.\n");
            return -1;
        }
        if ((status & 0x01) == 0) {
            break;
        }
        gpioDelay(1000); /* 1 ms */
    }

    if (retries < 0) {
        fprintf(stderr, "Error: ADXL354B not stable after reset.\n");
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_POWER_CTL, ADXL354B_POWER_CTL_RUN) != 0) {
        fprintf(stderr, "Error: SPI write failed setting RUN bit.\n");
        return -1;
    }
    return 0;
}

static int adxl354b_verify_partid(void) {
    uint8_t partid = 0;
    if (spi_read_register(ADXL354B_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Error: SPI read failed reading PARTID.\n");
        return -1;
    }
    if (partid != ADXL354B_PARTID_VALUE) {
        fprintf(stderr, "Error: Incorrect PARTID (0x%02X). Expected 0x%02X.\n", partid, ADXL354B_PARTID_VALUE);
        return -1;
    }
    return 0;
}

static int read_accelerometer_data(accelerometer_data_t *data) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;

    if (spi_read_register(ADXL354B_REG_XDATA_L, &x_l) != 0) return -1;
    if (spi_read_register(ADXL354B_REG_XDATA_H, &x_h) != 0) return -1;
    if (spi_read_register(ADXL354B_REG_YDATA_L, &y_l) != 0) return -1;
    if (spi_read_register(ADXL354B_REG_YDATA_H, &y_h) != 0) return -1;
    if (spi_read_register(ADXL354B_REG_ZDATA_L, &z_l) != 0) return -1;
    if (spi_read_register(ADXL354B_REG_ZDATA_H, &z_h) != 0) return -1;

    data->x = (int16_t)(((uint16_t)x_h << 8) | x_l);
    data->y = (int16_t)(((uint16_t)y_h << 8) | y_l);
    data->z = (int16_t)(((uint16_t)z_h << 8) | z_l);
    return 0;
}

static void log_data(accelerometer_data_t data) {
    time_t rawtime;
