#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        if (strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo) > 0) {
            printf("[%s] ", buffer);
            return;
        }
    }
    printf("[unknown-time] ");
}

int main(void)
{
    int ret;
    int s1, s2;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        fprintf(stderr, "       Is the pigpio daemon running? Try: sudo killall pigpiod\n");
        return EXIT_FAILURE;
    }

    /* --- Configure both sensor pins as inputs --- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main polling loop --- */
    while (g_running) {
        /* Read both sensor lines in a single bulk call */
        ret = gpioRead(SENSOR_1_GPIO);
        if (ret < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n",
                    SENSOR_1_GPIO, ret);
            break;
        }
        s1 = ret;

        ret = gpioRead(SENSOR_2_GPIO);
        if (ret < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n",
                    SENSOR_2_GPIO, ret);
            break;
        }
        s2 = ret;

        /* KY-032 is active-low: 0 => obstacle detected, 1 => clear */
        int s1_obstacle = (s1 == 0);
        int s2_obstacle = (s2 == 0);

        print_timestamp();
        printf("Sensor 1 (GPIO%d): %s | Sensor 2 (GPIO%d): %s\n",
               SENSOR_1_GPIO,
               s1_obstacle ? "OBSTACLE DETECTED" : "CLEAR",
               SENSOR_2_GPIO,
               s2_obstacle ? "OBSTACLE DETECTED" : "CLEAR");
        fflush(stdout);

        /* Sleep 100 ms; pigpio's gpioDelay is microseconds */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

