#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define GYRO_SCALE      0.02f
#define SAMPLE_PERIOD_MS 100
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       8

#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        return -1;
    }
    return 0;
}

static int read_gyro_axis(int fd, uint8_t reg, float *rate) {
    uint8_t tx[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(fd, tx, rx, 3) < 0) {
        return -1;
    }

    int16_t raw = (int16_t)((rx[1] << 8) | rx[2]);
    *rate = (float)raw * GYRO_SCALE;
    return 0;
}

int main(void) {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "adis16266-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADIS16266 Gyroscope Reader (SPI0 CE0, GPIO8 CS)\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
            break;
        }

        float x_rate, y_rate, z_rate;
        bool err = false;

        if (read_gyro_axis(spi_fd, ADIS16266_REG_XGYRO_OUT, &x_rate) < 0) {
            fprintf(stderr, "SPI read error on X axis: %s\n", strerror(errno));
            err = true;
        }
        if (read_gyro_axis(spi_fd, ADIS16266_REG_YGYRO_OUT, &y_rate) < 0) {
            fprintf(stderr, "SPI read error on Y axis: %s\n", strerror(errno));
            err = true;
        }
        if (read_gyro_axis(spi_fd, ADIS16266_REG_ZGYRO_OUT, &z_rate) < 0) {
            fprintf(stderr, "SPI read error on Z axis: %s\n", strerror(errno));
            err = true;
        }

        if (gpiod_line_set_value(cs_line, 1) < 0) {
            fprintf(stderr, "Failed to deassert CS: %s\n", strerror(errno));
            break;
        }

        if (err) {
            break;
        }

        printf("X: %+.2f deg/sec, Y: %+.2f deg/sec, Z: %+.2f deg/sec\n",
               x_rate, y_rate, z_rate);

        struct timespec ts;
        ts.tv_sec = SAMPLE_PERIOD_MS / 1000;
        ts.tv_nsec = (SAMPLE_PERIOD_MS % 1000) * 1000000L;
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

