        printf("X: %+.2f deg/sec, Y: %+.2f deg/sec, Z: %+.2f deg/sec\n",
               x_rate, y_rate, z_rate);

        struct timespec ts;
        ts.tv_sec = SAMPLE_PERIOD_MS / 1000;
        ts.tv_nsec = (SAMPLE_PERIOD_MS % 1000) * 1000000L;
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

