/* LSM6DSR I2C address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6A

/* LSM6DSR register addresses */
#define WHO_AM_I     0x0F
#define CTRL1_XL     0x10
#define CTRL2_G      0x11
#define OUTX_L_G     0x22
#define OUTX_H_G     0x23
#define OUTY_L_G     0x24
#define OUTY_H_G     0x25
#define OUTZ_L_G     0x26
#define OUTZ_H_G     0x27
#define OUTX_L_A     0x28
#define OUTX_H_A     0x29
#define OUTY_L_A     0x2A
#define OUTY_H_A     0x2B
#define OUTZ_L_A     0x2C
#define OUTZ_H_A     0x2D

#define WHO_AM_I_VAL 0x6A

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read block failed (reg 0x%02X, len %u): pigpio error %d\n",
                reg, len, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C read block short read (reg 0x%02X): got %d, expected %u\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write byte failed (reg 0x%02X, val 0x%02X): pigpio error %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle)
{
    uint8_t who_am_i = 0;
    if (i2c_read_block(handle, WHO_AM_I, &who_am_i, 1) != 0)
        return -1;

    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* Accelerometer: 100 Hz, 12.5 Hz BW, normal mode */
    if (i2c_write_byte(handle, CTRL1_XL, 0x60) != 0)
        return -1;

    /* Gyroscope: 100 Hz, 12.5 Hz BW, normal mode */
    if (i2c_write_byte(handle, CTRL2_G, 0x60) != 0)
        return -1;

    return 0;
}

static int read_axis(int handle, uint8_t reg_l, uint8_t reg_h, int16_t *out)
