    if (i2c_read_block(handle, reg_l, buf, 2) != 0)
        return -1;
    *out = (int16_t)((uint16_t)buf[1] << 8 | buf[0]);
    return 0;
}

static int read_all(int handle,
                    int16_t *ax, int16_t *ay, int16_t *az,
                    int16_t *gx, int16_t *gy, int16_t *gz)
{
    if (read_axis(handle, OUTX_L_A, OUTX_H_A, ax) != 0) return -1;
    if (read_axis(handle, OUTY_L_A, OUTY_H_A, ay) != 0) return -1;
    if (read_axis(handle, OUTZ_L_A, OUTZ_H_A, az) != 0) return -1;
    if (read_axis(handle, OUTX_L_G, OUTX_H_G, gx) != 0) return -1;
    if (read_axis(handle, OUTY_L_G, OUTY_H_G, gy) != 0) return -1;
    if (read_axis(handle, OUTZ_L_G, OUTZ_H_G, gz) != 0) return -1;
    return 0;
}

int main(void)
{
    int handle = -1;
    int rc = EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed: pigpio error %d\n", handle);
        goto cleanup_gpio;
    }

    if (init_lsm6dsr(handle) != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        goto cleanup_i2c;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        goto cleanup_i2c;
    }

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;
        if (read_all(handle, &ax, &ay, &az, &gx, &gy, &gz) != 0) {
            fprintf(stderr, "Sensor read failed; aborting\n");
            goto cleanup_i2c;
        }
        printf("%d %d %d %d %d %d\n", ax, ay, az, gx, gy, gz);
        fflush(stdout);
        gpioDelay(100000); /* 100 ms */
    }

    rc = EXIT_SUCCESS;

cleanup_i2c:
    if (handle >= 0)
        i2cClose(handle);

cleanup_gpio:
    gpioTerminate();
    return rc;
}

