#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700 register definitions (from datasheet) ---- */
#define FXOS8700_I2C_ADDR        0x1F
#define FXOS8700_REG_STATUS      0x00
#define FXOS8700_REG_OUT_X_MSB   0x01
#define FXOS8700_REG_WHOAMI      0x0D
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E
#define FXOS8700_REG_CTRL_REG1   0x2A
#define FXOS8700_REG_M_CTRL_REG1 0x5B
#define FXOS8700_REG_M_CTRL_REG2 0x5C
#define FXOS8700_REG_M_DATA_CFG  0x5E
#define FXOS8700_REG_M_OUT_X_MSB 0x01

#define FXOS8700_WHOAMI_VAL      0xC7
#define FXOS8700_STATUS_ACTIVE   0x01

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ---- Sensor initialization ---- */
static int init_fxos8700(int handle)
{
    uint8_t whoami = 0;

    if (i2c_read_reg(handle, FXOS8700_REG_WHOAMI, &whoami) != 0)
        return -1;

    if (whoami != FXOS8700_WHOAMI_VAL) {
        fprintf(stderr, "WHOAMI mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, FXOS8700_WHOAMI_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2c_write_reg(handle, FXOS8700_REG_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Accelerometer: 14-bit, 800 Hz ODR, normal mode */
    if (i2c_write_reg(handle, FXOS8700_REG_XYZ_DATA_CFG, 0x0E) != 0)
        return -1;

    /* Magnetometer: 16-bit, 80 Hz ODR, normal mode */
    if (i2c_write_reg(handle, FXOS8700_REG_M_CTRL_REG1, 0x1F) != 0)
        return -1;

    /* Magnetometer: auto-increment for multi-byte reads */
    if (i2c_write_reg(handle, FXOS8700_REG_M_CTRL_REG2, 0x20) != 0)
        return -1;

    /* Magnetometer full-scale = +/- 2 Gauss */
    if (i2c_write_reg(handle, FXOS8700_REG_M_DATA_CFG, 0x0E) != 0)
        return -1;

    /* Active mode: 14-bit accel, 800 Hz ODR */
    if (i2c_write_reg(handle, FXOS8700_REG_CTRL_REG1, 0x0D) != 0)
        return -1;

    return 0;
}

/* ---- Data acquisition ---- */
static int read_sensor_data(int handle,
                            int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *mx, int16_t *my, int16_t *mz)
{
    uint8_t buf[12];
    int rc;

    /* Read 6 bytes of accel data starting at OUT_X_MSB */
    rc = i2cReadI2CBlockData(handle, FXOS8700_REG_OUT_X_MSB, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Accel block read failed: %s\n",
                rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }

    /* 14-bit left-aligned accelerometer data */
    *ax = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    *ay = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    *az = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    /* Read 6 bytes of magnetometer data starting at M_OUT_X_MSB */
    rc = i2cReadI2CBlockData(handle, FXOS8700_REG_M_OUT_X_MSB, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Mag block read failed: %s\n",
                rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }

    /* 16-bit magnetometer data */
    *mx = (int16_t)((buf[0] << 8) | buf[1]);
    *my = (int16_t)((buf[2] << 8) | buf[3]);
    *mz = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* ---- Main ---- */
int main(void)
{
    int16_t ax, ay, az, mx, my, mz;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, FXOS8700_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n",
                FXOS8700_I2C_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_fxos8700(g_i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("FXOS8700 ready. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read error; retrying...\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

