#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DEVID 0x00
#define ADXL345_DEVID 0xE5
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, int16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

int adxl345_init(int fd) {
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_REG_DEVID, &devid) < 0) {
        fprintf(stderr, "Error: Failed to read DEVID register.\n");
        return -1;
    }
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "Error: ADXL345 not found (DEVID=0x%02X, expected 0x%02X).\n", devid, ADXL345_DEVID);
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: Failed to set data format.\n");
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_REG_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error: Failed to set data rate.\n");
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to enable measurement mode.\n");
        return -1;
    }
    return 0;
}

int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    if (i2c_read_reg16(fd, ADXL345_REG_DATAX0, x) < 0) return -1;
    if (i2c_read_reg16(fd, ADXL345_REG_DATAX0 + 2, y) < 0) return -1;
    if (i2c_read_reg16(fd, ADXL345_REG_DATAX0 + 4, z) < 0) return -1;
    return 0;
}

float calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 256.0;
    float y_g = (float)y / 256.0;
    float z_g = (float)z / 256.0;
    return atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0 / M_PI;
}

int log_tilt_event(float angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Tilt angle: %.2f degrees\n", timestamp, angle);
    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing ADXL345.\n");
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized. Monitoring tilt angle... (Ctrl+C to exit)\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading acceleration data.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float tilt_angle = calculate_tilt_angle(x, y, z);

        if (fabs(tilt_angle) > TILT_THRESHOLD) {
            if (log_tilt_event(tilt_angle) < 0) {
                fprintf(stderr, "Error logging tilt event.\n");
            }
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, ADXL345_REG_POWER_CTL, 0x00);
        close(i2c_fd);
    }
    return 0;
}

