#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define GPIO_PIN 17
#define WINDOW_DURATION_SEC 5
#define SAMPLE_INTERVAL_US 1000
#define PAUSE_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor(void) {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n", GPIO_PIN, value);
        return -1;
    }
    return value;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed.\n");
        return;
    }
    if (strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }
    printf("[%s] ", buffer);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold_high_readings_per_window>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    errno = 0;
    long threshold = strtol(argv[1], &endptr, 10);

    if (errno != 0 || endptr == argv[1] || *endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d. Threshold: %ld high readings per %d-second window.\n",
           GPIO_PIN, threshold, WINDOW_DURATION_SEC);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int high_count = 0;
        int valid_samples = 0;
        int error_flag = 0;

        for (int i = 0; i < WINDOW_DURATION_SEC * 1000 && running; i++) {
            int reading = read_sensor();
            if (reading < 0) {
                error_flag = 1;
                break;
            }
            if (reading == 1) {
                high_count++;
            }
            valid_samples++;
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (error_flag) {
            fprintf(stderr, "Error: GPIO read failure during window. Exiting.\n");
            break;
        }

        print_timestamp();
        if (valid_samples > 0 && high_count > threshold) {
            printf("ALERT: %d high readings (threshold %ld)\n", high_count, threshold);
        } else {
            printf("OK: %d high readings (threshold %ld)\n", high_count, threshold);
        }
        fflush(stdout);

        if (running) {
            sleep(PAUSE_SEC);
        }
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

