#define DOOR_A_PIN 17
#define DOOR_B_PIN 27
#define UNLOCK_DURATION_SEC 5
#define LOG_FILE "access_log.txt"
#define GPIO_CHIP_NAME "gpiochip4"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int generate_security_code(int *code) {
    if (code == NULL) {
        return -1;
    }
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        return -1;
    }
    srand((unsigned int)t);
    *code = 100000 + (rand() % 900000);
    return 0;
}

static int read_user_input(int *user_code) {
    char input[32];
    int result;

    printf("Enter the 6-digit security code: ");
    fflush(stdout);

    result = scanf("%31s", input);
    if (result != 1) {
        fprintf(stderr, "Error: Invalid input format.\n");
        int c;
        while ((c = getchar()) != '\n' && c != EOF) {
            /* discard remaining input */
        }
        return -1;
    }

    char *endptr;
    long val = strtol(input, &endptr, 10);
    if (*endptr != '\0' || val < 100000 || val > 999999) {
        fprintf(stderr, "Error: Security code must be a 6-digit number (100000-999999).\n");
        return -1;
    }

    *user_code = (int)val;
    return 0;
}

static int log_access(int security_code) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time to local time.\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, security_code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
