#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "light_log.txt"
#define CONVERSION_TIME_MS 180
#define SLEEP_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(int fd) {
    uint8_t cmd = 0x10; // Continuous H-Resolution Mode
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bh1750_init(fd) < 0) {
        fprintf(stderr, "Error initializing BH1750: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        usleep(CONVERSION_TIME_MS * 1000);
        float lux;
        if (bh1750_read_lux(fd, &lux) < 0) {
            fprintf(stderr, "Error reading lux value: %s\n", strerror(errno));
        } else {
            if (log_data(lux) < 0) {
                fprintf(stderr, "Error logging data: %s\n", strerror(errno));
            }
        }
        sleep(SLEEP_INTERVAL_S);
    }

    close(fd);
    return 0;
}

