#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define LSM303_MAG_ADDR 0x1E
#define LSM303_CTRL_REG1_M 0x20
#define LSM303_CTRL_REG2_M 0x21
#define LSM303_OUT_X_L_M 0x28
#define LSM303_OUT_X_H_M 0x29
#define LSM303_OUT_Y_L_M 0x2A
#define LSM303_OUT_Y_H_M 0x2B
#define LSM303_OUT_Z_L_M 0x2C
#define LSM303_OUT_Z_H_M 0x2D

#define LED_PIN        17
#define PWM_RANGE      255
#define PWM_FREQ       1000
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s (errno: %s)\n", ts, msg, strerror(errno));
    if (log_file) {
        fprintf(log_file, "[%s] ERROR: %s (errno: %s)\n", ts, msg, strerror(errno));
        fflush(log_file);
    }
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int init_lsm303(int fd) {
    if (i2c_write_reg8(fd, LSM303_CTRL_REG1_M, 0x70) < 0) {
        log_error("Failed to write CTRL_REG1_M");
        return -1;
    }
    if (i2c_write_reg8(fd, LSM303_CTRL_REG2_M, 0x00) < 0) {
        log_error("Failed to write CTRL_REG2_M");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, LSM303_OUT_X_L_M, buf, 6) < 0) {
        log_error("Failed to read magnetometer data");
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(LED_PIN, brightness);
}

static void cleanup(void) {
    gpioPWM(LED_PIN, 0);
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("Failed to set signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        log_error("Failed to acquire I2C bus access");
        cleanup();
        return 1;
