#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E

#define REG_CONFIG_A 0x00
#define REG_CONFIG_B 0x01
#define REG_MODE 0x02
#define REG_DATA_X_MSB 0x03

#define NUM_SAMPLES 100
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X\n", val, reg);
        return -1;
    }
    return 0;
}

static int read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading block from reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "Short read from reg 0x%02X: got %d, expected %u\n", reg, rc, len);
        return -1;
    }
    return 0;
}

static int init_magnetometer(void) {
    if (write_reg(REG_CONFIG_A, 0x70) < 0) return -1;
    if (write_reg(REG_CONFIG_B, 0x20) < 0) return -1;
    if (write_reg(REG_MODE, 0x00) < 0) return -1;
    return 0;
}

static int read_raw(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (read_block(REG_DATA_X_MSB, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void update_running_average(int16_t x, int16_t y, int16_t z,
                                   int64_t *sx, int64_t *sy, int64_t *sz,
                                   int *n) {
    if (*n < NUM_SAMPLES) {
        *sx += x; *sy += y; *sz += z;
        (*n)++;
    } else {
        *sx += x - (int64_t)(*sx) / NUM_SAMPLES;
        *sy += y - (int64_t)(*sy) / NUM_SAMPLES;
        *sz += z - (int64_t)(*sz) / NUM_SAMPLES;
    }
}

static void apply_offsets(int16_t x, int16_t y, int16_t z,
                          int64_t sx, int64_t sy, int64_t sz, int n,
                          int16_t *cx, int16_t *cy, int16_t *cz) {
    if (n > 0) {
        *cx = x - (int16_t)((sx + (n / 2)) / n);
        *cy = y - (int16_t)((sy + (n / 2)) / n);
        *cz = z - (int16_t)((sz + (n / 2)) / n);
    } else {
        *cx = x; *cy = y; *cz = z;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_magnetometer() < 0) {
        fprintf(stderr, "Magnetometer initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int64_t sx = 0, sy = 0, sz = 0;
    int n = 0;
    int consecutive_errors = 0;

    while (running) {
        int16_t rx, ry, rz;
        if (read_raw(&rx, &ry, &rz) < 0) {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "Too many consecutive I2C errors, aborting\n");
                break;
            }
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }
        consecutive_errors = 0;

        update_running_average(rx, ry, rz, &sx, &sy, &sz, &n);

        int16_t cx, cy, cz;
        apply_offsets(rx, ry, rz, sx, sy, sz, n, &cx, &cy, &cz);

        printf("X: %d, Y: %d, Z: %d\n", cx, cy, cz);
        fflush(stdout);

        gpioDelay(SAMPLE_DELAY_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

