code:
/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W.
 *
 * Reads tri‑axial acceleration data over I2C at ~10 ms intervals,
 * stores samples in a 64‑entry circular buffer, and dumps the
 * last ten buffered samples to stdout whenever the INT1 pin
 * (BCM GPIO 23, physical pin 16) rises.
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 *
 * Wiring:
 *   LSM303D SDA  -> Pi GPIO2  (physical pin 3)
 *   LSM303D SCL  -> Pi GPIO3  (physical pin 5)
 *   LSM303D INT1 -> Pi GPIO23 (physical pin 16)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D register addresses ---- */
#define LSM303D_ADDR_ACCEL   0x19
#define LSM303D_ADDR_MAG     0x1E

#define LSM303D_WHO_AM_I     0x0F
#define LSM303D_WHO_AM_I_VAL 0x49

#define LSM303D_CTRL_REG1_A  0x20
#define LSM303D_CTRL_REG4_A  0x23
#define LSM303D_OUT_X_L_A    0x28
#define LSM303D_INT1_CFG     0x30
#define LSM303D_INT1_SRC     0x31
#define LSM303D_INT1_THS     0x32
#define LSM303D_INT1_DUR     0x33

/* ---- GPIO / timing constants ---- */
#define I2C_BUS        "/dev/i2c-1"
#define GPIO_CHIP       "gpiochip0"
#define INT1_PIN        23
#define SAMPLE_PERIOD   10000   /* microseconds */
#define BUFFER_SIZE     64
#define DUMP_COUNT      10
#define ACCEL_SENS_MG   0.061f  /* mg per LSB at default ±2 g */

/* ---- Data structures ---- */
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t samples[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1_line = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

/* ---- LSM303D initialization ---- */
static int init_lsm303d(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, LSM303D_WHO_AM_I, &who) != 0)
        return -1;
    if (who != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1_A: 0x57 = 0101 0111 -> 50 Hz ODR, normal mode, all axes enabled */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1_A, 0x57) != 0)
        return -1;

    /* CTRL_REG4_A: 0x00 = ±2 g full‑scale, high resolution disabled */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG4_A, 0x00) != 0)
        return -1;

    /* INT1_CFG: 0x00 = active high, push‑pull, latch until read */
    if (i2c_write_reg8(fd, LSM303D_INT1_CFG, 0x00) != 0)
        return -1;

    /* INT1_THS: 2000 mg / 0.061 mg/LSB ≈ 32768 ≈ 0x80 (simplified: 0x80 = 128 LSB) */
    if (i2c_write_reg8(fd, LSM303D_INT1_THS, 0x80) != 0)
        return -1;

    /* INT1_DUR: 0x00 = trigger on first event */
    if (i2c_write_reg8(fd, LSM303D_INT1_DUR, 0x00) != 0)
        return -1;

    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_add(circular_buffer_t *buf, accel_sample_t s)
{
    buf->samples[buf->head] = s;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void buffer_dump(const circular_buffer_t *buf, int n)
{
    if (n > buf->count)
        n = buf->count;
    if (n <= 0) {
        printf("No samples available.\n");
        return;
    }

    int start = (buf->head - n + BUFFER_SIZE) % BUFFER_SIZE;
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("[%s] Last %d samples:\n", ts, n);
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%d] X=%6.2f  Y=%6.2f  Z=%6.2f  mg\n",
               i, buf->samples[idx].x * ACCEL_SENS_MG,
               buf->samples[idx].y * ACCEL_SENS_MG,
               buf->samples[idx].z * ACCEL_SENS_MG);
    }
    fflush(stdout);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer: ODR=0, power-down mode */
        (void)i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1_A, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_int1_line) {
        gpiod_line_release(g_int1_line);
        g_int1_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    circular_buffer_t accel_buf = {0};
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR_ACCEL) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303D_ADDR_ACCEL, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_lsm303d(g_i2c_fd) != 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_int1_line = gpiod_chip_get_line(g_chip, INT1_PIN);
    if (!g_int1_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                INT1_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(g_int1_line, "lsm303d-mon") != 0) {
        fprintf(stderr, "Cannot request INT1 as input: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303D monitoring started. INT1 on BCM GPIO %d. Ctrl-C to exit.\n",
           INT1_PIN);

    while (g_running) {
        int prev = gpiod_line_get_value(g_int1_line);
        if (prev < 0) {
            fprintf(stderr, "Warning: INT1 read failed: %s\n",
                    strerror(errno));
            usleep(SAMPLE_PERIOD);
            continue;
        }

        int16_t x, y, z;
        if (i2c_read_reg16(g_i2c_fd, LSM303D_OUT_X_L_A, &x) != 0 ||
            i2c_read_reg16(g_i2c_fd, LSM303D_OUT_X_L_A + 2, &y) != 0 ||
            i2c_read_reg16(g_i2c_fd, LSM303D_OUT_X_L_A + 4, &z) != 0) {
            fprintf(stderr, "Warning: accelerometer read failed; skipping sample.\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        accel_sample_t s = { x, y, z };
        buffer_add(&accel_buf, s);

        int cur = gpiod_line_get_value(g_int1_line);
        if (cur < 0) {
            fprintf(stderr, "Warning: INT1 read failed: %s\n",
                    strerror(errno));
        } else if (cur == 1 && prev == 0) {
            buffer_dump(&accel_buf, DUMP_COUNT);
        }

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

