#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS 500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin)
{
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, int level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %u (level %d)\n", pin, level);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Ensure both solenoids are de-energized before releasing resources */
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(SOLENOID_1_PIN) != 0 || safe_set_mode(SOLENOID_2_PIN) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with both solenoids de-energized */
    if (safe_write(SOLENOID_1_PIN, 0) != 0 || safe_write(SOLENOID_2_PIN, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct timespec delay;
    delay.tv_sec  = DELAY_MS / 1000;
    delay.tv_nsec = (DELAY_MS % 1000) * 1000000L;

    while (g_running) {
        if (safe_write(SOLENOID_1_PIN, 1) != 0 || safe_write(SOLENOID_2_PIN, 0) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        nanosleep(&delay, NULL);
        if (!g_running) break;

        if (safe_write(SOLENOID_1_PIN, 0) != 0 || safe_write(SOLENOID_2_PIN, 1) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        nanosleep(&delay, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

