#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define UART0_DEVICE "/dev/serial0"
#define UART1_DEVICE "/dev/serial1"
#define BAUD_RATE 9600
#define CODE_LENGTH 6
#define EXPECTED_CODE "123456"
#define RELAY_ON_TIME_SEC 2
#define READ_TIMEOUT_SEC 5
#define POLL_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LOCK2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK1_GPIO, 0) != 0 || gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise lock relays to LOW\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_uart(const char *device, int baud_rate) {
    int handle = serOpen((char *)device, baud_rate, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open UART %s: %s\n", device, strerror(errno));
        return -1;
    }
    return handle;
}

static int read_code(int uart_handle, char *code, int code_length) {
    static char buffer[256];
    static int buffer_index = 0;
    char ch;
    int bytes_read;

    bytes_read = serReadByte(uart_handle);
    if (bytes_read < 0) {
        fprintf(stderr, "UART read error: %s\n", strerror(errno));
        buffer_index = 0;
        return -1;
    }
    if (bytes_read == 0) {
        return 0;
    }
    ch = (char)bytes_read;

    if (ch >= '0' && ch <= '9') {
        if (buffer_index < code_length) {
            buffer[buffer_index++] = ch;
        }
        if (buffer_index == code_length) {
            strncpy(code, buffer, code_length);
            code[code_length] = '\0';
            buffer_index = 0;
            return 1;
        }
    } else {
        buffer_index = 0;
    }
    return 0;
}

static int compare_codes(const char *code1, const char *code2) {
    int result = 0;
    for (int i = 0; i < CODE_LENGTH; i++) {
        result |= (unsigned char)code1[i] ^ (unsigned char)code2[i];
    }
    return (result == 0) ? 0 : -1;
}

static void unlock_doors(void) {
    if (gpioWrite(LOCK1_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to activate lock 1\n");
        return;
    }
    if (gpioWrite(LOCK2_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to activate lock 2\n");
        gpioWrite(LOCK1_GPIO, 0);
        return;
    }
    printf("Unlocking doors...\n");
    time_sleep(RELAY_ON_TIME_SEC);
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to deactivate lock 1\n");
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to deactivate lock 2\n");
    }
