#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define RELAY_ON_TIME_SEC 1
#define MOTION_TIMEOUT_SEC 10
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(int priority, const char *message) {
    time_t now = time(NULL);
    char time_buf[32];
    struct tm tm_info;

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
        syslog(priority, "%s: %s", time_buf, message);
    } else {
        syslog(priority, "UNKNOWN_TIME: %s", message);
    }
}

static void log_relay_event(int priority, const char *message) {
    time_t now = time(NULL);
    char time_buf[32];
    struct tm tm_info;

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
        syslog(priority, "%s: %s", time_buf, message);
    } else {
        syslog(priority, "UNKNOWN_TIME: %s", message);
    }
}

static void activate_relay(struct gpiod_line *relay_line) {
    if (gpiod_line_set_value(relay_line, 1) < 0) {
        log_event(LOG_ERR, "Failed to activate relay (set HIGH)");
        return;
    }
    log_relay_event(LOG_INFO, "Relay activated");
}

static void deactivate_relay(struct gpiod_line *relay_line) {
    if (gpiod_line_set_value(relay_line, 0) < 0) {
        log_event(LOG_ERR, "Failed to deactivate relay (set LOW)");
        return;
    }
    log_relay_event(LOG_INFO, "Relay deactivated");
}

static void cleanup(struct gpiod_chip *chip, struct gpiod_line *relay_line) {
    if (relay_line) {
        deactivate_relay(relay_line);
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("door_access_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_event(LOG_ERR, "Failed to register SIGINT handler");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_event(LOG_ERR, "Failed to register SIGTERM handler");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_event(LOG_ERR, "Failed to open gpiochip4");
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_event(LOG_ERR, "Failed to get PIR line (GPIO4)");
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_event(LOG_ERR, "Failed to get relay line (GPIO17)");
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "door_access_system") < 0) {
        log_event(LOG_ERR, "Failed to request PIR line as input");
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "door_access_system", 0) < 0) {
        log_event(LOG_ERR, "Failed to request relay line as output");
        goto cleanup;
    }

    log_event(LOG_INFO, "Door access system started");

    time_t motion_start_time = 0;
    int relay_active = 0;

    while (program_running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            log_event(LOG_ERR, "Failed to read PIR sensor value");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (pir_value == 1) {
            if (motion_start_time == 0) {
                motion_start_time = time(NULL);
                log_event(LOG_INFO, "Motion detected");
            }

            if (motion_start_time != 0 && (time(NULL) - motion_start_time) > MOTION_TIMEOUT_SEC) {
                log_event(LOG_WARNING, "PIR sensor stuck HIGH for more than 10 seconds - potential malfunction");
                log_event(LOG_WARNING, "System shutting down");
                program_running = 0;
                break;
            }

            if (!relay_active) {
                activate_relay(relay_line);
                relay_active = 1;
                sleep(RELAY_ON_TIME_SEC);
                deactivate_relay(relay_line);
                relay_active = 0;
            }
        } else {
            motion_start_time = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event(LOG_INFO, "Door access system shutting down");
    ret = EXIT_SUCCESS;

cleanup:
    cleanup(chip, relay_line);
    return ret;
}

