#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

#define RELAY_ON_TIME_SEC 300
#define RELAY_OFF_TIME_SEC 60
#define TIMER_INTERVAL_SEC 60

#define NUM_RELAYS 4

static volatile sig_atomic_t program_running = 1;

static const int relay_gpios[NUM_RELAYS] = {
    RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO
};

static const char *relay_names[NUM_RELAYS] = {
    "Relay1", "Relay2", "Relay3", "Relay4"
};

static int current_relay_index = 0;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    char time_buf[32];
    struct tm *tm_info = localtime(&now);
    if (tm_info != NULL) {
        strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", tm_info);
        syslog(priority, "[%s] %s", time_buf, message);
    } else {
        syslog(priority, "%s", message);
    }
}

static int set_relay_state(int gpio, int state) {
    int rc = gpioWrite(gpio, state);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to set GPIO %d to %d: %s",
                 gpio, state, pigpio_error(rc));
        log_message(LOG_ERR, msg);
        return -1;
    }
    return 0;
}

static int initialize_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_gpios[i], PI_OUTPUT) < 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to set GPIO %d as output", relay_gpios[i]);
            log_message(LOG_ERR, msg);
            return -1;
        }
        if (set_relay_state(relay_gpios[i], 1) < 0) {
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay_state(relay_gpios[i], 1);
    }
}

static void timer_callback(void *user_data) {
    (void)user_data;

    if (!program_running) {
        return;
    }

    if (set_relay_state(relay_gpios[current_relay_index], 0) == 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Activating %s (GPIO %d)",
                 relay_names[current_relay_index], relay_gpios[current_relay_index]);
        log_message(LOG_INFO, msg);
    }

    current_relay_index = (current_relay_index + 1) % NUM_RELAYS;

    if (set_relay_state(relay_gpios[current_relay_index], 1) == 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Deactivating %s (GPIO %d)",
                 relay_names[current_relay_index], relay_gpios[current_relay_index]);
        log_message(LOG_INFO, msg);
    }
}

int main(void) {
