    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_message(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_relays() < 0) {
        log_message(LOG_ERR, "Relay initialization failed");
        deactivate_all_relays();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL_SEC * 1000, timer_callback, NULL) < 0) {
        log_message(LOG_ERR, "Failed to set up timer");
        deactivate_all_relays();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Irrigation system started");

    while (program_running) {
        sleep(1);
    }

    log_message(LOG_INFO, "Shutting down irrigation system");
    deactivate_all_relays();
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

