/*
 * MPU6050 100 Hz accelerometer sampler for Raspberry Pi 4 Model B.
 *
 * I2C bus : /dev/i2c-1  (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor  : MPU6050 at address 0x68 (AD0 tied to GND)
 * Output  : /sys/kernel/mpu6050_accel/latest
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mpu6050_accel mpu6050_accel.c
 *
 * Enable the driver module (must be loaded before the daemon starts):
 *   sudo modprobe mpu6050_accel
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/file.h>
#include <sys/inotify.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/timerfd.h>
#include <time.h>
#include <unistd.h>

#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

#define REG_PWR_MGMT_1 0x6B
#define REG_ACCEL_XOUT_H 0x3B

#define BUFFER_SIZE 100
#define SAMPLE_RATE 100
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE)

#define DRIVER_DIR "/sys/kernel"
#define DRIVER_NAME "mpu6050_accel"
#define DRIVER_VERSION "0.1"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_timer_fd = -1;
static int g_driver_fd = -1;
static int g_inotify_fd = -1;
static int g_buffer_fd = -1;

static int16_t g_buffer[BUFFER_SIZE][3];
static int g_buf_head = 0;
static int g_buf_count = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd)
{
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000);
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, REG_ACCEL_XOUT_H, x) < 0) return -1;
    if (i2c_read_reg16(fd, REG_ACCEL_XOUT_H + 2, y) < 0) return -1;
    if (i2c_read_reg16(fd, REG_ACCEL_XOUT_H + 4, z) < 0) return -1;
    return 0;
}

static void store_sample(int16_t x, int16_t y, int16_t z)
{
    g_buffer[g_buf_head][0] = x;
    g_buffer[g_buf_head][1] = y;
    g_buffer[g_buf_head][2] = z;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

static int write_latest_sample(void)
{
    char path[256];
    snprintf(path, sizeof(path), "%s/%s/latest", DRIVER_DIR, DRIVER_NAME);

    int16_t *sample = g_buffer[(g_buf_head - 1 + BUFFER_SIZE) % BUFFER_SIZE];
    if (sample == NULL)
        return -1;

    char data[256];
    int len = snprintf(data, sizeof(data), "%d %d %d\n",
                       sample[0], sample[1], sample[2]);
    if (len < 0 || (size_t)len >= sizeof(data))
        return -1;

    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, data, len) != len) {
        fprintf(stderr, "write(%s) failed: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int create_driver_files(void)
{
    char path[256];
    char version[64];
    snprintf(version, sizeof(version), "%s", DRIVER_VERSION);

    snprintf(path, sizeof(path), "%s/%s/version", DRIVER_DIR, DRIVER_NAME);
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) { perror("open version"); return -1; }
    if (write(fd, version, strlen(version)) != (ssize_t)strlen(version)) {
        perror("write version"); close(fd); return -1;
    }
    close(fd);

    snprintf(path, sizeof(path), "%s/%s/latest", DRIVER_DIR, DRIVER_NAME);
    fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) { perror("open latest"); return -1; }
    close(fd);

    return 0;
}

static int setup_timer(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGALRM, &sa, NULL) < 0) {
        perror("sigaction(SIGALRM)");
        return -1;
    }

    struct sigaction sa_timer;
    memset(&sa_timer, 0, sizeof(sa_timer));
    sa_timer.sa_handler = SIG_DFL;
    sigemptyset(&sa_timer.sa_mask);
    sa_timer.sa_flags = SA_RESTART;
    if (sigaction(SIGRTMIN, &sa_timer, NULL) < 0) {
        perror("sigaction(SIGRTMIN)");
        return -1;
    }

    g_timer_fd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (g_timer_fd < 0) {
        perror("timerfd_create");
        return -1;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = SAMPLE_PERIOD_NS;
    if (timerfd_settime(g_timer_fd, 0, &its, NULL) < 0) {
        perror("timerfd_settime");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_timer_fd >= 0) {
        close(g_timer_fd);
        g_timer_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_driver_fd >= 0) {
        close(g_driver_fd);
        g_driver_fd = -1;
    }
    if (g_inotify_fd >= 0) {
        close(g_inotify_fd);
        g_inotify_fd = -1;
    }
    if (g_buffer_fd >= 0) {
        close(g_buffer_fd);
        g_buffer_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_mpu6050(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed (sensor absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (create_driver_files() < 0) {
        fprintf(stderr, "Failed to create driver files.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (setup_timer() < 0) {
        fprintf(stderr, "Failed to setup timer.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU6050 sampling at %d Hz. Press Ctrl+C to exit.\n", SAMPLE_RATE);

    while (g_running) {
        uint64_t expirations;
        ssize_t n = read(g_timer_fd, &expirations, sizeof(expirations));
        if (n < 0) {
            if (errno == EINTR)
                continue;
            perror("read(timerfd)");
            break;
        }
        if (n == 0)
            continue;

        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            continue;
        }

        store_sample(x, y, z);
        if (write_latest_sample() < 0)
            fprintf(stderr, "Failed to write latest sample.\n");
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

