    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_mpu6050(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed (sensor absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (create_driver_files() < 0) {
        fprintf(stderr, "Failed to create driver files.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (setup_timer() < 0) {
        fprintf(stderr, "Failed to setup timer.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU6050 sampling at %d Hz. Press Ctrl+C to exit.\n", SAMPLE_RATE);

    while (g_running) {
        uint64_t expirations;
        ssize_t n = read(g_timer_fd, &expirations, sizeof(expirations));
        if (n < 0) {
            if (errno == EINTR)
                continue;
            perror("read(timerfd)");
            break;
        }
        if (n == 0)
            continue;

        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            continue;
        }

        store_sample(x, y, z);
        if (write_latest_sample() < 0)
            fprintf(stderr, "Failed to write latest sample.\n");
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

