#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define NUM_RELAYS 4

static const int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
static const int intervals[NUM_RELAYS]   = {2, 3, 5, 7};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int set_relay(int pin, int state)
{
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, state=%d) failed: %s\n",
                pin, state, strerror(errno));
        return -1;
    }
    return 0;
}

static void all_relays_off(void)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        (void)set_relay(relay_pins[i], 0);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(pin=%d, PI_OUTPUT) failed: %s\n",
                    relay_pins[i], strerror(errno));
            all_relays_off();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (set_relay(relay_pins[i], 0) != 0) {
            all_relays_off();
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct timespec next[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        clock_gettime(CLOCK_MONOTONIC, &next[i]);
    }

    int states[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        states[i] = 0;
    }

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        for (int i = 0; i < NUM_RELAYS; i++) {
            long diff = (now.tv_sec - next[i].tv_sec) * 1000000000L +
                        (now.tv_nsec - next[i].tv_nsec);

            if (diff >= 0) {
                states[i] = !states[i];
                if (set_relay(relay_pins[i], states[i]) != 0) {
                    all_relays_off();
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
                next[i].tv_sec  = now.tv_sec;
                next[i].tv_nsec = now.tv_nsec;
                next[i].tv_sec += intervals[i];
            }
        }

        struct timespec sleep_ts = {0, 10000000}; /* 10 ms */
        nanosleep(&sleep_ts, NULL);
    }

    all_relays_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

