#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define RELAY_DURATION_MS 3000
#define POLL_INTERVAL_US 100000
#define LOG_FILE "alarm_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_timestamp(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: Sound detected!\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (gpioInitialise() >= 0) {
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sound sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay to OFF state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sound_detected = gpioRead(SOUND_SENSOR_PIN);
        if (sound_detected < 0) {
            fprintf(stderr, "Error reading sound sensor pin\n");
            break;
        }

        if (sound_detected == 1) {
            printf("Sound detected!\n");

            if (gpioWrite(RELAY_PIN, 1) != 0) {
                fprintf(stderr, "Failed to activate relay\n");
                break;
            }

            if (log_timestamp(LOG_FILE) != 0) {
                fprintf(stderr, "Failed to log timestamp\n");
            }

            for (int i = 0; i < RELAY_DURATION_MS / 10 && program_running; i++) {
                gpioDelay(10000);
            }

            if (gpioWrite(RELAY_PIN, 0) != 0) {
                fprintf(stderr, "Failed to deactivate relay\n");
                break;
            }

            printf("Relay deactivated.\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

