#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define BUFFER_SIZE 100
#define THRESHOLD 50.0
#define I2C_DEVICE "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    int16_t x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU-6050\n");
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_gyro_data(int fd, gyro_data_t *data) {
    if (i2c_read_reg16(fd, GYRO_XOUT_H, &data->x) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_YOUT_H, &data->y) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_ZOUT_H, &data->z) < 0) return -1;
    return 0;
}

static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) buffer->count++;
}

static double calculate_angular_velocity(gyro_data_t data) {
    double x = (double)data.x / 131.0;
    double y = (double)data.y / 131.0;
    double z = (double)data.z / 131.0;
    return sqrt(x * x + y * y + z * z);
}

static void threshold_callback(gyro_data_t data) {
    double velocity = calculate_angular_velocity(data);
    if (velocity > THRESHOLD) {
        printf("Threshold exceeded! Angular velocity: %.2f deg/s\n", velocity);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed. Check wiring and sensor presence.\n");
        close(i2c_fd);
        return 1;
    }

    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    printf("MPU-6050 initialized. Reading data... (Ctrl+C to exit)\n");

    while (running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(i2c_fd, &gyro_data) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(100000);
            continue;
        }

        add_to_buffer(&gyro_buffer, gyro_data);
        threshold_callback(gyro_data);

        usleep(10000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

