#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/time.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL_SEC 5
#define RESPONSE_TIMEOUT_MS 1000
#define RESPONSE_LEN 9
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int uart_handle = -1;
static FILE *log_fp = NULL;
static FILE *error_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    if (!error_fp) return;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm;
    localtime_r(&tv.tv_sec, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(error_fp, "%s.%06ld: %s\n", ts, (long)tv.tv_usec, msg);
    fflush(error_fp);
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", UART_DEVICE, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_co2(int *ppm_out) {
    unsigned char cmd[RESPONSE_LEN] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    unsigned char resp[RESPONSE_LEN];
    int total = 0;
    int elapsed = 0;

    if (serWrite(uart_handle, (char *)cmd, RESPONSE_LEN) != RESPONSE_LEN) {
        log_error("Failed to send read command");
        return -1;
    }

    while (total < RESPONSE_LEN && elapsed < RESPONSE_TIMEOUT_MS) {
        int n = serRead(uart_handle, (char *)(resp + total), RESPONSE_LEN - total);
        if (n > 0) {
            total += n;
            elapsed = 0;
        } else if (n < 0) {
            log_error("UART read error");
            return -1;
        } else {
            gpioDelay(POLL_DELAY_US);
            elapsed += POLL_DELAY_US / 1000;
        }
    }

    if (total < RESPONSE_LEN) {
        log_error("Timeout waiting for CO2 response");
        return -1;
    }

    int checksum = 0;
    for (int i = 1; i < RESPONSE_LEN - 1; i++) {
        checksum += resp[i];
    }
    checksum = 255 - (checksum & 0xFF);
    if (checksum != resp[RESPONSE_LEN - 1]) {
        log_error("Checksum mismatch");
        return -1;
    }

    *ppm_out = (resp[2] << 8) | resp[3];
    return 0;
}

static void log_data(int ppm, int error) {
    if (!log_fp) return;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm;
    localtime_r(&tv.tv_sec, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_fp, "{\"timestamp\":\"%s.%06ld\",\"ppm\":%d,\"error\":%d}\n",
            ts, (long)tv.tv_usec, ppm, error);
    fflush(log_fp);
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (error_fp) {
        fclose(error_fp);
        error_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    error_fp = fopen(ERROR_LOG_FILE, "a");
    if (!error_fp) {
        fprintf(stderr, "Error opening error log file %s: %s\n", ERROR_LOG_FILE, strerror(errno));
        fclose(log_fp);
        gpioTerminate();
        return 1;
    }

    if (init_uart() != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CO2 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int ppm = 0;
        int rc = read_co2(&ppm);
        if (rc == 0) {
            log_data(ppm, 0);
            printf("{\"timestamp\":\"%ld.%06ld\",\"ppm\":%d,\"error\":0}\n",
                   (long)time(NULL), 0, ppm);
        } else {
            log_data(0, 1);
            printf("{\"timestamp\":\"%ld.%06ld\",\"ppm\":0,\"error\":1}\n",
                   (long)time(NULL), 0);
        }
        sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

