#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07
#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define CIRCULAR_BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

typedef struct {
    float buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_magnetometer_data(sensor_data_t *data) {
    char raw_data[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t x = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    int16_t z = (int16_t)((raw_data[2] << 8) | raw_data[3]);
    int16_t y = (int16_t)((raw_data[4] << 8) | raw_data[5]);
    data->x = (float)x;
    data->y = (float)y;
    data->z = (float)z;
    return 0;
}

static float calculate_heading(sensor_data_t data) {
    float heading = atan2f(data.y, data.x) * 180.0f / (float)M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

static void apply_hard_iron_compensation(sensor_data_t *data, float x_offset, float y_offset) {
    data->x -= x_offset;
    data->y -= y_offset;
}

static void add_to_circular_buffer(circular_buffer_t *buffer, float value) {
    buffer->buffer[buffer->head] = value;
    buffer->head = (buffer->head + 1) % CIRCULAR_BUFFER_SIZE;
    if (buffer->count < CIRCULAR_BUFFER_SIZE) {
        buffer->count++;
    }
}

static void control_gpio(float heading) {
    if (fabsf(heading - TARGET_HEADING) > HEADING_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1);
    } else {
        gpioWrite(GPIO_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_PIN, 0);
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }
    circular_buffer_t heading_buffer = {0};
    sensor_data_t sensor_data;
    float x_offset = 100.0f;
    float y_offset = -50.0f;
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (!terminate) {
        if (read_magnetometer_data(&sensor_data) == 0) {
            apply_hard_iron_compensation(&sensor_data, x_offset, y_offset);
            float heading = calculate_heading(sensor_data);
            add_to_circular_buffer(&heading_buffer, heading);
            control_gpio(heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    return 0;
}

