#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define I2C_BUS "/dev/i2c-1"

#define RED_PIN 17
#define GREEN_PIN 27
#define BLUE_PIN 22

#define LOG_FILE "lighting_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out) {
    if (i2c_fd < 0) {
        return -1;
    }
    if (write(i2c_fd, (uint8_t[]){BH1750_CONT_HIGH_RES_MODE}, 1) != 1) {
        perror("Error writing measurement command to BH1750");
        return -1;
    }
    usleep(120000);
    uint8_t buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading lux data from BH1750");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_lamps(float lux) {
    if (lux < 50.0f) {
        gpioWrite(RED_PIN, 1);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN, 0);
    } else if (lux < 150.0f) {
        gpioWrite(RED_PIN, 0);
        gpioWrite(GREEN_PIN, 1);
        gpioWrite(BLUE_PIN, 0);
    } else if (lux < 300.0f) {
        gpioWrite(RED_PIN, 0);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN, 1);
    } else {
        gpioWrite(RED_PIN, 1);
        gpioWrite(GREEN_PIN, 1);
        gpioWrite(BLUE_PIN, 1);
    }
}

static void log_data(float lux, int red, int green, int blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%d,%d,%d\n", timestamp, lux, red, green, blue);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        float lux;
        if (read_lux(&lux) == 0) {
            control_lamps(lux);
            int red = gpioRead(RED_PIN);
            int green = gpioRead(GREEN_PIN);
            int blue = gpioRead(BLUE_PIN);
            log_data(lux, red, green, blue);
        } else {
            fprintf(stderr, "Error reading lux value, retrying...\n");
        }
        sleep(1);
    }
    cleanup();
    return EXIT_SUCCESS;
}

