#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_pwm(unsigned gpio, unsigned duty) {
    if (gpioPWM(gpio, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static int motor_forward(int in1, int in2) {
    if (safe_write(in1, 1) != 0) return -1;
    if (safe_write(in2, 0) != 0) return -1;
    return 0;
}

static int motor_backward(int in3, int in4) {
    if (safe_write(in3, 0) != 0) return -1;
    if (safe_write(in4, 1) != 0) return -1;
    return 0;
}

static int motor_stop(int in1, int in2, int in3, int in4) {
    int rc = 0;
    if (safe_write(in1, 0) != 0) rc = -1;
    if (safe_write(in2, 0) != 0) rc = -1;
    if (safe_write(in3, 0) != 0) rc = -1;
    if (safe_write(in4, 0) != 0) rc = -1;
    return rc;
}

static int set_motor_speed(int in2, int in4, int distance) {
    int duty = (int)(((float)distance / 100.0f) * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (safe_pwm(in2, duty) != 0) return -1;
    if (safe_pwm(in4, duty) != 0) return -1;
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_motor_a> <distance_motor_b>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int distance_motor_a = atoi(argv[1]);
    int distance_motor_b = atoi(argv[2]);

    if (distance_motor_a < 10 || distance_motor_a > 100 ||
        distance_motor_b < 10 || distance_motor_b > 100) {
        fprintf(stderr, "Error: Distance values must be between 10 and 100 cm.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_mode(MOTOR_A_IN1, PI_OUTPUT) != 0 ||
        safe_set_mode(MOTOR_A_IN2, PI_OUTPUT) != 0 ||
        safe_set_mode(MOTOR_B_IN3, PI_OUTPUT) != 0 ||
        safe_set_mode(MOTOR_B_IN4, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int exit_code = EXIT_SUCCESS;

    while (running) {
        if (distance_motor_a < 50) {
            if (motor_forward(MOTOR_A_IN1, MOTOR_A_IN2) != 0) {
                exit_code = EXIT_FAILURE;
                break;
            }
            if (set_motor_speed(MOTOR_A_IN2, MOTOR_B_IN4, distance_motor_a) != 0) {
                exit_code = EXIT_FAILURE;
                break;
            }
        } else {
            if (motor_backward(MOTOR_B_IN3, MOTOR_B_IN4) != 0) {
                exit_code = EXIT_FAILURE;
                break;
            }
            if (set_motor_speed(MOTOR_A_IN2, MOTOR_B_IN4, distance_motor_a) != 0) {
                exit_code = EXIT_FAILURE;
                break;
            }
        }

        if (distance_motor_b < 50) {
            if (motor_forward(MOTOR_A_IN1, MOTOR_A_IN2) != 0) {
                exit_code = EXIT_FAILURE;
                break;
            }
            if (set_motor_speed(MOTOR_A_IN2, MOTOR_B_IN4, distance_motor_b) != 0) {
                exit_code = EXIT_FAILURE;
                break;
            }
        } else {
            if (motor_backward(MOTOR_B_IN3, MOTOR_B_IN4) != 0) {
                exit_code = EXIT_FAILURE;
                break;
            }
            if (set_motor_speed(MOTOR_A_IN2, MOTOR_B_IN4, distance_motor_b) != 0) {
                exit_code = EXIT_FAILURE;
                break;
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    if (motor_stop(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4) != 0) {
        exit_code = EXIT_FAILURE;
    }

    gpioTerminate();
    return exit_code;
}

