#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int mpu6050_init(int fd) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) == 0) return 0;
        retries++;
        usleep(100000 * (1 << retries));
    }
    return -1;
}

int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_reg(fd, ACCEL_XOUT_H, buf, 6) != 0) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

void calc_pitch_roll(int16_t ax, int16_t ay, int16_t az, float *pitch, float *roll) {
    float fx = (float)ax, fy = (float)ay, fz = (float)az;
    *pitch = atan2f(fx, sqrtf(fy * fy + fz * fz)) * 180.0f / M_PI;
    *roll = atan2f(fy, sqrtf(fx * fx + fz * fz)) * 180.0f / M_PI;
}

int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int duty = 100000 + (angle * 1000000 / 180);
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    fprintf(fp, "%d", duty);
    fclose(fp);
    return 0;
}

int log_data(float pitch, float roll, int pos) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return -1;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, pitch, roll, pos);
    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) { perror("ioctl"); close(fd); return 1; }

    if (mpu6050_init(fd) != 0) {
        fprintf(stderr, "MPU6050 init failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        int16_t ax, ay, az;
        if (read_accel(fd, &ax, &ay, &az) != 0) {
            fprintf(stderr, "Read error: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }
        float pitch, roll;
        calc_pitch_roll(ax, ay, az, &pitch, &roll);
        int pos = (int)(pitch + 90);
        if (set_servo_angle(pos) != 0) fprintf(stderr, "Servo set failed\n");
        if (log_data(pitch, roll, pos) != 0) fprintf(stderr, "Log failed\n");
        usleep(50000);
    }

    close(fd);
    return 0;
}

