#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION_SEC 1800
#define FADE_STEPS 1800
#define FADE_STEP_DELAY_US 1000000
#define SCHEDULE_FILE "lighting_schedule.txt"
#define MAX_SCHEDULE_ENTRIES 24

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;

typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} ScheduleEntry;

static ScheduleEntry schedule[MAX_SCHEDULE_ENTRIES];
static int schedule_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(void) {
    FILE *fp = fopen(SCHEDULE_FILE, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    schedule_count = 0;

    while (fgets(line, sizeof(line), fp) != NULL && schedule_count < MAX_SCHEDULE_ENTRIES) {
        ScheduleEntry entry;
        if (sscanf(line, "%d:%d:%d,%d,%d",
                   &entry.hour, &entry.minute, &entry.second,
                   &entry.relay_number, &entry.on_off) == 5) {
            if (entry.hour >= 0 && entry.hour < 24 &&
                entry.minute >= 0 && entry.minute < 60 &&
                entry.second >= 0 && entry.second < 60 &&
                entry.relay_number >= 1 && entry.relay_number <= NUM_RELAYS) {
                schedule[schedule_count++] = entry;
            } else {
                fprintf(stderr, "Invalid schedule entry: %s", line);
            }
        } else {
            fprintf(stderr, "Invalid format: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

static int compare_schedule(const void *a, const void *b) {
    const ScheduleEntry *e1 = (const ScheduleEntry *)a;
    const ScheduleEntry *e2 = (const ScheduleEntry *)b;
    int diff = e1->hour - e2->hour;
    if (diff == 0) diff = e1->minute - e2->minute;
    if (diff == 0) diff = e1->second - e2->second;
    return diff;
}

static int find_next_transition(void) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (!t) return -1;

    int current_time = t->tm_hour * 3600 + t->tm_min * 60 + t->tm_sec;

    for (int i = 0; i < schedule_count; i++) {
        int scheduled_time = schedule[i].hour * 3600 +
                             schedule[i].minute * 60 +
                             schedule[i].second;
        if (scheduled_time > current_time) {
            return i;
        }
    }
    return -1;
}

static void set_relay(int relay_number, int state) {
    int pin = relay_pins[relay_number - 1];
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", pin);
    }
}

static void fade_lamps(int relay_number, int target_state) {
    int pin = relay_pins[relay_number - 1];
    int current_state = gpioRead(pin);
    if (current_state < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", pin);
        return;
    }

    if (current_state == target_state) return;

    int step_delay_us = FADE_STEP_DELAY_US;
    int num_steps = FADE_DURATION_SEC * 1000 / step_delay_us;

    for (int i = 0; i <= num_steps && running; i++) {
        float progress = (float)i / (float)num_steps;
        int duty_cycle = target_state ? (int)(progress * 100.0f) : (int)((1.0f - progress) * 100.0f);

        if (gpioPWM(pin, duty_cycle) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", pin);
            return;
        }
        gpioDelay(step_delay_us);
    }

    if (running) {
        set_relay(relay_number, target_state);
    }
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(i + 1, 0);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            cleanup();
            return 1;
        }
        set_relay(i + 1, 0);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (read_schedule() != 0) {
        fprintf(stderr, "Failed to read schedule. Exiting.\n");
        cleanup();
        return 1;
    }

    qsort(schedule, schedule_count, sizeof(ScheduleEntry), compare_schedule);

    while (running) {
        int next_transition = find_next_transition();
        if (next_transition >= 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            if (!t) {
                fprintf(stderr, "Failed to get local time\n");
                break;
            }
            int current_time = t->tm_hour * 3600 + t->tm_min * 60 + t->tm_sec;
            int scheduled_time = schedule[next_transition].hour * 3600 +
                                 schedule[next_transition].minute * 60 +
                                 schedule[next_transition].second;

            if (scheduled_time - current_time <= FADE_DURATION_SEC) {
                fade_lamps(schedule[next_transition].relay_number,
                           schedule[next_transition].on_off);
            }
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

