#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_FREQUENCY  200
#define MAX_FREQUENCY  2000
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0

#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    20000
#define MEASUREMENT_GAP_US 60000
#define ECHO_TIMEOUT_US   30000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double read_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }
    gpioDelay(5);

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low after pulse\n");
        return -1.0;
    }

    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout (sensor absent?)\n");
            return -1.0;
        }
    }

    uint32_t echo_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    double distance = (double)pulse_width * 0.0343 / 2.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: distance %.2f out of range [%.1f, %.1f]\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return -1.0;
    }

    return distance;
}

static int map_distance_to_frequency(double distance) {
    if (distance < 0) return -1;
    double normalized = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
    if (normalized < 0.0) normalized = 0.0;
    if (normalized > 1.0) normalized = 1.0;
    return (int)(MIN_FREQUENCY + normalized * (MAX_FREQUENCY - MIN_FREQUENCY));
}

static int set_buzzer_frequency(int frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Error: frequency %d out of range [%d, %d]\n",
                frequency, MIN_FREQUENCY, MAX_FREQUENCY);
        return -1;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency to %d\n", frequency);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {
        fprintf(stderr, "Error: failed to start PWM on buzzer\n");
        return -1;
    }
    return 0;
}

static void silence_buzzer(void) {
    gpioPWM(BUZZER_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = read_distance();

        if (distance < 0) {
            fprintf(stderr, "Error: invalid distance reading\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int frequency = map_distance_to_frequency(distance);
        if (frequency < 0) {
            fprintf(stderr, "Error: failed to map distance to frequency\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (set_buzzer_frequency(frequency) < 0) {
            fprintf(stderr, "Error: failed to set buzzer frequency\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    silence_buzzer();
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

