#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define PWM_FREQ  1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_rgb_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN, red) < 0) {
        fprintf(stderr, "Error setting PWM on RED_PIN: %s\n", pigpio_error(gpioGetMode(RED_PIN)));
        return -1;
    }
    if (gpioPWM(GREEN_PIN, green) < 0) {
        fprintf(stderr, "Error setting PWM on GREEN_PIN: %s\n", pigpio_error(gpioGetMode(GREEN_PIN)));
        return -1;
    }
    if (gpioPWM(BLUE_PIN, blue) < 0) {
        fprintf(stderr, "Error setting PWM on BLUE_PIN: %s\n", pigpio_error(gpioGetMode(BLUE_PIN)));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    set_rgb_color(0, 0, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set RED_PIN mode: %s\n", pigpio_error(RED_PIN));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GREEN_PIN mode: %s\n", pigpio_error(GREEN_PIN));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BLUE_PIN mode: %s\n", pigpio_error(BLUE_PIN));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on RED_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GREEN_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on BLUE_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on RED_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GREEN_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on BLUE_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity-based RGB LED control started. Press Ctrl+C to exit.\n");

    while (running) {
        double proximity = 0.5 * (1.0 + sin(2.0 * M_PI * (double)clock() / (double)CLOCKS_PER_SEC));

        int red_intensity   = (int)(proximity * 255.0);
        int green_intensity = (int)((1.0 - proximity) * 255.0);
        int blue_intensity  = 0;

        if (set_rgb_color(red_intensity, green_intensity, blue_intensity) < 0) {
            fprintf(stderr, "Failed to set RGB color, exiting.\n");
            break;
        }

        usleep(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

