        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BLUE_PIN mode: %s\n", pigpio_error(BLUE_PIN));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on RED_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GREEN_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on BLUE_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on RED_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GREEN_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on BLUE_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity-based RGB LED control started. Press Ctrl+C to exit.\n");

    while (running) {
        double proximity = 0.5 * (1.0 + sin(2.0 * M_PI * (double)clock() / (double)CLOCKS_PER_SEC));

        int red_intensity   = (int)(proximity * 255.0);
        int green_intensity = (int)((1.0 - proximity) * 255.0);
        int blue_intensity  = 0;

        if (set_rgb_color(red_intensity, green_intensity, blue_intensity) < 0) {
            fprintf(stderr, "Failed to set RGB color, exiting.\n");
            break;
        }

        usleep(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

