#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_MS 50
#define PWM_DUTY 128  /* 50% of 255 */

/* Musical note frequencies (Hz) */
typedef struct {
    const char *name;
    int frequency;
} Note;

static const Note melody[] = {
    {"C4", 262}, {"D4", 294}, {"E4", 330}, {"F4", 349},
    {"G4", 392}, {"A4", 440}, {"B4", 494}, {"C5", 523}
};
static const int melody_length = sizeof(melody) / sizeof(melody[0]);

/* Timing for each note: duration in ms + pause in ms */
static const int note_durations[][2] = {
    {500, 100}, {500, 100}, {500, 100}, {500, 100},
    {500, 100}, {500, 100}, {500, 100}, {500, 100}
};

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;
static volatile uint32_t last_interrupt_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level == 0) {  /* Active low */
        uint32_t elapsed = tick - last_interrupt_tick;
        if (elapsed > (uint32_t)(DEBOUNCE_MS * 1000)) {
            button_pressed = 1;
            last_interrupt_tick = tick;
        }
    }
}

static int play_tone(int frequency, int duration_ms) {
    if (frequency <= 0) {
        gpioDelay(duration_ms * 1000);
        return 0;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for %d Hz\n", frequency);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, PWM_DUTY) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for %d Hz\n", frequency);
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM stop failed for %d Hz\n", frequency);
        return -1;
    }
    gpioDelay(50000);  /* 50 ms pause between notes */
    return 0;
}

static int play_melody(void) {
    for (int i = 0; i < melody_length; i++) {
        if (!running) return -1;
        if (play_tone(melody[i].frequency, note_durations[i][0]) < 0) return -1;
        if (button_pressed) {
            button_pressed = 0;
            return -1;  /* Interrupted by another press */
        }
        gpioDelay(note_durations[i][1] * 1000);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pin %d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pin %d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for buzzer pin %d\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM initial stop failed for buzzer pin %d\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for button pin %d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Doorbell system started. Press the button (GPIO%d) to play the melody.\n", BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            printf("Button pressed! Playing melody...\n");
            if (play_melody() < 0) {
                printf("Melody interrupted by another button press.\n");
            } else {
                printf("Melody finished.\n");
            }
        }
        gpioDelay(10000);  /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    gpioPWM(BUZZER_PIN, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("Doorbell system stopped.\n");
    return EXIT_SUCCESS;
}

