#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define LSM303_ADDRESS 0x1D
#define LSM303_REGISTER_CRA_REG_M 0x00
#define LSM303_REGISTER_MR_REG_M 0x02
#define LSM303_REGISTER_OUT_X_H_M 0x08
#define LSM303_REGISTER_OUT_X_L_M 0x09
#define LSM303_REGISTER_OUT_Y_H_M 0x0A
#define LSM303_REGISTER_OUT_Y_L 0x0B
#define LSM303_REGISTER_OUT_Z_H_M 0x0C
#define LSM303_REGISTER_OUT_Z_L_M 0x0D

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_magnetometer(int fd) {
    if (i2c_write_reg8(fd, LSM303_REGISTER_CRA_REG_M, 0x70) < 0) {
        fprintf(stderr, "Error writing to CRA_REG_M\n");
        return -1;
    }
    if (i2c_write_reg8(fd, LSM303_REGISTER_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to MR_REG_M\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    if (i2c_read_reg16(fd, LSM303_REGISTER_OUT_X_H_M, x) < 0) {
        fprintf(stderr, "Error reading X data\n");
        return -1;
    }
    if (i2c_read_reg16(fd, LSM303_REGISTER_OUT_Y_H_M, y) < 0) {
        fprintf(stderr, "Error reading Y data\n");
        return -1;
    }
    if (i2c_read_reg16(fd, LSM303_REGISTER_OUT_Z_H_M, z) < 0) {
        fprintf(stderr, "Error reading Z data\n");
        return -1;
    }
    return 0;
}

static void calibrate_data(int16_t x, int16_t y, int16_t z, int16_t *cx, int16_t *cy, int16_t *cz) {
    *cx = x - X_OFFSET;
    *cy = y - Y_OFFSET;
    *cz = z - Z_OFFSET;
}

static float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

static const char *determine_compass_direction(float heading) {
    if (heading >= 337.5f || heading < 22.5f) return "N";
    if (heading < 67.5f) return "NE";
    if (heading < 112.5f) return "E";
    if (heading < 157.5f) return "SE";
    if (heading < 202.5f) return "S";
    if (heading < 247.5f) return "SW";
    if (heading < 292.5f) return "W";
    if (heading < 337.5f) return "NW";
    return "N";
}

static int log_data(FILE *fp, int16_t cx, int16_t cy, int16_t cz, float heading) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, %d, %d, %d, %.2f\n", timestamp, cx, cy, cz, heading) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDRESS) < 0) {
        perror("Error setting I2C address");
        close(i2c_fd);
        return 1;
    }

    if (init_magnetometer(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing magnetometer\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
        fflush(log_file);
    }

    printf("Magnetometer data logging started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z, cx, cy, cz;
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading magnetometer data, skipping sample\n");
        } else {
            calibrate_data(x, y, z, &cx, &cy, &cz);
            float heading = calculate_heading(cx, cy);
            const char *direction = determine_compass_direction(heading);
            printf("Direction: %s, Heading: %.2f\n", direction, heading);
            if (log_data(log_file, cx, cy, cz, heading) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }
        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

