#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define MOISTURE_THRESHOLD 30
#define RELAY_ON_DURATION 5
#define RELAY_GAP 1
#define POLL_INTERVAL 10

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static const int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as output.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialise GPIO%d high.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_soil_moisture(void) {
    return rand() % 101;
}

static int activate_relay(int pin, int moisture_level) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: failed to activate relay on GPIO%d.\n", pin);
        return -1;
    }
    printf("Relay on GPIO%d activated (moisture: %d%%).\n", pin, moisture_level);

    for (int i = 0; i < RELAY_ON_DURATION && running; i++) {
        sleep(1);
    }

    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: failed to deactivate relay on GPIO%d.\n", pin);
        return -1;
    }
    printf("Relay on GPIO%d deactivated.\n", pin);
    return 0;
}

static int log_irrigation_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Relay %d activated, Moisture Level: %d\n", timestamp, relay_number, moisture_level) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        gpioWrite(relay_pins[i], 1);
        gpioSetMode(relay_pins[i], PI_INPUT);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open irrigation_log.txt for appending.\n");
        cleanup();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_soil_moisture();
        printf("Soil Moisture Level: %d%%\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            for (int i = 0; i < 4 && running; i++) {
                if (activate_relay(relay_pins[i], moisture_level) != 0) {
                    fprintf(stderr, "Error activating relay on GPIO%d.\n", relay_pins[i]);
                } else {
                    if (log_irrigation_event(i + 1, moisture_level) != 0) {
                        fprintf(stderr, "Error logging irrigation event for relay %d.\n", i + 1);
                    }
                }
                if (i < 3 && running) {
                    sleep(RELAY_GAP);
                }
            }
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

