#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <the_servo_library.h> /* Replace with actual servo library header */

#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_MID_PULSE_WIDTH 1500

#define VALVE_OPEN_ANGLE 90
#define VALVE_CLOSED_ANGLE 0

#define NOZZLE_ANGLES {0, 45, 90, 135, 180}
#define NOZZLE_PULSE_WIDTHS {500, 1000, 1500, 2000, 2500}

#define WATERING_DURATION 5
#define CYCLE_DELAY 5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int set_servo_angle(int pin, int angle) {
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)) / 180;
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) pulse_width = SERVO_MIN_PULSE_WIDTH;
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) pulse_width = SERVO_MAX_PULSE_WIDTH;

    for (int i = 0; i < RETRY_COUNT; i++) {
        if (servo_set_pulse_width(pin, pulse_width) == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: Failed to set servo angle on pin %d (attempt %d/%d): %s\n",
                pin, i + 1, RETRY_COUNT, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    fprintf(stderr, "Error: Failed to set servo angle on pin %d after %d retries.\n", pin, RETRY_COUNT);
    return -1;
}

static int open_valve(void) {
    if (set_servo_angle(VALVE_SERVO_PIN, VALVE_OPEN_ANGLE) != 0) {
        fprintf(stderr, "Error: Failed to open valve.\n");
        return -1;
    }
    printf("Valve opened.\n");
    return 0;
}

static int close_valve(void) {
    if (set_servo_angle(VALVE_SERVO_PIN, VALVE_CLOSED_ANGLE) != 0) {
        fprintf(stderr, "Error: Failed to close valve.\n");
        return -1;
    }
    printf("Valve closed.\n");
    return 0;
}

static int sweep_nozzle(void) {
    int angles[] = NOZZLE_ANGLES;
    int pulse_widths[] = NOZZLE_PULSE_WIDTHS;
    int num_angles = sizeof(angles) / sizeof(angles[0]);

    for (int i = 0; i < num_angles; i++) {
        if (set_servo_angle(NOZZLE_SERVO_PIN, angles[i]) != 0) {
            fprintf(stderr, "Warning: Failed to set nozzle angle %d. Skipping.\n", angles[i]);
            continue;
        }
        printf("Nozzle angle: %d degrees\n", angles[i]);
        sleep(2);
    }
    return 0;
}

static int water_plant(void) {
    if (open_valve() != 0) {
        fprintf(stderr, "Error: Valve open failed. Aborting watering cycle.\n");
        return -1;
    }

    if (sweep_nozzle() != 0) {
        fprintf(stderr, "Warning: Nozzle sweep encountered errors.\n");
    }

    printf("Watering plant for %d seconds...\n", WATERING_DURATION);
    sleep(WATERING_DURATION);

    if (close_valve() != 0) {
        fprintf(stderr, "Error: Valve close failed. Water may be leaking.\n");
        return -1;
    }

    printf("Watering cycle complete.\n");
    return 0;
}

static int read_soil_moisture(void) {
    static int moisture_values[] = {20, 40, 60, 80, 100};
    static int index = 0;
    static time_t last_change_time = 0;

    time_t current_time = time(NULL);
    if (current_time == (time_t)-1) {
        fprintf(stderr, "Error: Failed to get current time.\n");
        return -1;
    }

    if (current_time - last_change_time >= 1) {
        printf("Simulated soil moisture: %d%%\n", moisture_values[index]);
        index = (index + 1) % (sizeof(moisture_values) / sizeof(moisture_values[0]));
        last_change_time = current_time;
    }
    return moisture_values[index];
}

int main(void) {
    struct sigaction sa;
