#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define SAMPLE_RATE_HZ 10
#define SAMPLE_DELAY_US (1000000 / SAMPLE_RATE_HZ)

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    uint8_t whoami = 0;
    if (i2c_read_reg8(fd, 0x75, &whoami) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (whoami != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x68\n", whoami);
        return -1;
    }
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    if (i2c_read_reg16(fd, GYRO_XOUT_H, x) < 0) {
        fprintf(stderr, "Error reading GYRO_XOUT: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_read_reg16(fd, GYRO_YOUT_H, y) < 0) {
        fprintf(stderr, "Error reading GYRO_YOUT: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_read_reg16(fd, GYRO_ZOUT_H, z) < 0) {
        fprintf(stderr, "Error reading GYRO_ZOUT: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d,%d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening gyro_log.txt: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Logging MPU-6050 gyro data to gyro_log.txt at %d Hz. Press Ctrl+C to stop.\n", SAMPLE_RATE_HZ);

    while (running) {
        int16_t x, y, z;
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

