#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_PIN      18
#define POLL_DELAY_US  100000
#define DIST_THRESHOLD 50

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_SYSTEM_MODE_START       0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by one byte of data. */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read N bytes from a 16-bit register address. */
static int vl53l1x_read_block(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle)
{
    if (vl53l1x_write_byte(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    if (vl53l1x_write_byte(handle, VL53L1X_REG_SOFT_RESET, 0x01) != 0) {
        fprintf(stderr, "Error: failed to release soft reset.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    /* Start ranging (bit 0 = mode_start). */
    if (vl53l1x_write_byte(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    return 0;
}

static int vl53l1x_read_distance(int handle, uint8_t *distance_mm)
{
    uint8_t status;
    uint8_t data[2];

    if (vl53l1x_read_block(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 1) {
        fprintf(stderr, "Error: failed to read range status.\n");
        return -1;
    }

    if ((status & 0x1F) == 0) {
        /* Data not ready yet. */
        return 1;
    }

    if (vl53l1x_read_block(handle, VL53L1X_REG_RESULT_DISTANCE, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read distance data.\n");
        return -1;
    }

    *distance_mm = (data[0] << 8) | data[1];
    return 0;
}

static void control_relay(int distance_mm)
{
    int distance_cm = distance_mm / 10;
    if (distance_cm <= DIST_THRESHOLD) {
        gpioWrite(RELAY_PIN, 1);
        printf("Distance: %d cm, Relay: ON\n", distance_cm);
    } else {
        gpioWrite(RELAY_PIN, 0);
        printf("Distance: %d cm, Relay: OFF\n", distance_cm);
    }
}

int main(void)
{
    int i2c_handle = -1;
    int ret_code = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin mode.\n");
        goto cleanup_gpio;
    }
    gpioWrite(RELAY_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device (addr 0x%02X): %d\n",
                VL53L1X_ADDR, i2c_handle);
        goto cleanup_gpio;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        goto cleanup_i2c;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint8_t distance_mm = 0;
        int rc = vl53l1x_read_distance(i2c_handle, &distance_mm);

        if (rc == 0) {
            control_relay(distance_mm);
        } else if (rc < 0) {
            /* I2C error — keep relay off for safety. */
            gpioWrite(RELAY_PIN, 0);
        }
        /* rc == 1 means data not ready; just wait. */

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    ret_code = 0;

cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
cleanup_gpio:
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return ret_code;
}

