    if ((status & 0x1F) == 0) {
        /* Data not ready yet. */
        return 1;
    }

    if (vl53l1x_read_block(handle, VL53L1X_REG_RESULT_DISTANCE, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read distance data.\n");
        return -1;
    }

    *distance_mm = (data[0] << 8) | data[1];
    return 0;
}

static void control_relay(int distance_mm)
{
    int distance_cm = distance_mm / 10;
    if (distance_cm <= DIST_THRESHOLD) {
        gpioWrite(RELAY_PIN, 1);
        printf("Distance: %d cm, Relay: ON\n", distance_cm);
    } else {
        gpioWrite(RELAY_PIN, 0);
        printf("Distance: %d cm, Relay: OFF\n", distance_cm);
    }
}

int main(void)
{
    int i2c_handle = -1;
    int ret_code = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin mode.\n");
        goto cleanup_gpio;
    }
    gpioWrite(RELAY_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device (addr 0x%02X): %d\n",
                VL53L1X_ADDR, i2c_handle);
        goto cleanup_gpio;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        goto cleanup_i2c;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint8_t distance_mm = 0;
        int rc = vl53l1x_read_distance(i2c_handle, &distance_mm);

        if (rc == 0) {
            control_relay(distance_mm);
        } else if (rc < 0) {
            /* I2C error — keep relay off for safety. */
            gpioWrite(RELAY_PIN, 0);
        }
        /* rc == 1 means data not ready; just wait. */

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    ret_code = 0;

cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
cleanup_gpio:
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return ret_code;
}

