#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_CONFIG  0x1B

/* Sensitivity scale factor for ±250 dps (1 LSB = 8.75 mdps) */
#define GYRO_SCALE  0.00875f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd)
{
    /* Wake up the MPU-6050 (clear SLEEP bit) */
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* allow oscillator to stabilize */

    /* Set gyroscope full-scale range to ±250 dps */
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

int main(void)
{
    int fd = -1;
    int16_t gyro_x, gyro_y, gyro_z;
    float gyro_x_rate, gyro_y_rate, gyro_z_rate;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus for 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6050 */
    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050 (sensor absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Reading angular velocity...\n");

    /* Main loop */
    while (g_running) {
        if (i2c_read_reg16(fd, GYRO_XOUT_H, &gyro_x) < 0 ||
            i2c_read_reg16(fd, GYRO_XOUT_H + 2, &gyro_y) < 0 ||
            i2c_read_reg16(fd, GYRO_XOUT_H + 4, &gyro_z) < 0) {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
            usleep(100000);
            continue;
        }

        gyro_x_rate = (float)gyro_x * GYRO_SCALE;
        gyro_y_rate = (float)gyro_y * GYRO_SCALE;
        gyro_z_rate = (float)gyro_z * GYRO_SCALE;

        printf("Angular Velocity: X = %.2f dps, Y = %.2f dps, Z = %.2f dps\n",
               gyro_x_rate, gyro_y_rate, gyro_z_rate);

        usleep(100000); /* 100 ms delay */
    }

    /* Clean shutdown */
    printf("\nExiting gracefully...\n");
    if (fd >= 0)
        close(fd);

    return EXIT_SUCCESS;
}

