#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define POLL_INTERVAL_SEC 60
#define CYCLE_INTERVAL_SEC 86400
#define RELAY_ACTIVE_SEC 5
#define LOG_FILE "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_cycle_start(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s\n", ts) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_relay(int index, int duration_sec) {
    if (index < 0 || index >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay index: %d\n", index);
        return -1;
    }
    if (gpiod_line_set_value(lines[index], 0) < 0) {
        fprintf(stderr, "Failed to activate relay %d (GPIO%u): %s\n",
                index, relay_pins[index], strerror(errno));
        return -1;
    }
    printf("Relay %d (GPIO%u) activated for %d seconds\n", index, relay_pins[index], duration_sec);
    sleep(duration_sec);
    if (gpiod_line_set_value(lines[index], 1) < 0) {
        fprintf(stderr, "Failed to deactivate relay %d (GPIO%u): %s\n",
                index, relay_pins[index], strerror(errno));
        return -1;
    }
    printf("Relay %d (GPIO%u) deactivated\n", index, relay_pins[index]);
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", relay_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "plant-watering", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (log_cycle_start() < 0) {
            fprintf(stderr, "Warning: failed to log cycle start.\n");
        }
        for (int i = 0; i < NUM_RELAYS && running; i++) {
            if (activate_relay(i, RELAY_ACTIVE_SEC) < 0) {
                fprintf(stderr, "Error activating relay %d.\n", i);
            }
        }
        if (running) {
            sleep(POLL_INTERVAL_SEC);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

