#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 1800
#define STEP_DELAY_US 1000000
#define LOG_FILE "smart_lighting.log"

static const int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void log_event(const char *message) {
    if (log_file == NULL) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
