#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define MPU6050_ADDR         0x68
#define LED_GPIO             17
#define BUFFER_SIZE          100
#define SAMPLE_PERIOD_US     50000   /* 50 ms -> 20 Hz */
#define THRESHOLD            250.0f  /* deg/s */
#define MAX_REINIT_ATTEMPTS  3

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_CONFIG  0x1B

/* ---- Data structures ---- */
typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static int i2c_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t terminate = 0;

/* ---- Prototypes ---- */
static int  init_i2c(void);
static int  read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(circular_buffer_t *buf, float x, float y, float z);
static void check_threshold(float x, float y, float z);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- I2C helpers ---- */
static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, MPU6050_ADDR, i2c_handle);
        return -1;
    }

    /* Wake up: clear SLEEP bit, use internal 8 MHz oscillator */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle */

    /* Set gyro full-scale range to +/- 250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing GYRO_CONFIG\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyro data block\n");
        return -1;
    }

    raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    /* +/- 250 deg/s range => 131 LSB per deg/s */
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

/* ---- Circular buffer ---- */
static void add_to_buffer(circular_buffer_t *buf, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    buf->data[buf->head].timestamp = ts;
    buf->data[buf->head].x = x;
    buf->data[buf->head].y = y;
    buf->data[buf->head].z = z;

    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

/* ---- Threshold LED ---- */
static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > THRESHOLD || fabsf(y) > THRESHOLD || fabsf(z) > THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

/* ---- Signal handling ---- */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    float x, y, z;
    int reinit_attempts = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    /* Register signal handlers */
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPU-6050 gyroscope reader started. Sampling at 20 Hz.\n");
    printf("Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(&gyro_buffer, x, y, z);
            check_threshold(x, y, z);
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Gyro read failed. Attempting re-initialization (%d/%d)...\n",
                    reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
            if (reinit_attempts < MAX_REINIT_ATTEMPTS) {
                if (init_i2c() == 0) {
                    reinit_attempts = 0;
                } else {
                    reinit_attempts++;
                }
            } else {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

