#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_OFFSET     8
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_RETRIES     3
#define SAMPLE_DELAY_MS 10
#define LOG_FILE        "gyro_log.txt"

#define REG_PWR_MGMT_1  0x6B
#define REG_GYRO_XOUT_H 0x43
#define REG_GYRO_CONFIG 0x1B

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to de-assert CS: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(float *x_rate, float *y_rate, float *z_rate) {
    uint8_t tx[7] = {0};
    uint8_t rx[7] = {0};

    tx[0] = REG_GYRO_XOUT_H | 0x80;
    if (spi_transfer(tx, rx, 7) < 0) return -1;

    int16_t raw_x = (int16_t)((rx[1] << 8) | rx[2]);
    int16_t raw_y = (int16_t)((rx[3] << 8) | rx[4]);
    int16_t raw_z = (int16_t)((rx[5] << 8) | rx[6]);

    *x_rate = (float)raw_x / 131.0f;
    *y_rate = (float)raw_y / 131.0f;
    *z_rate = (float)raw_z / 131.0f;
    return 0;
}

static int log_data(float x_rate, float y_rate, float z_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    if (fprintf(log_fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
    if (spi_fd >= 0) { close(spi_fd); spi_fd = -1; }
    if (cs_line) { gpiod_line_release(cs_line); cs_line = NULL; }
    if (gpio_chip) { gpiod_chip_close(gpio_chip); gpio_chip = NULL; }
}

