#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Configuration */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      3900000    /* ~3.9 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define LED_PIN        17         /* BCM 17, physical pin 11 */
#define BUFFER_SIZE    64
#define THRESHOLD      200.0f     /* deg/s */
#define SAMPLE_DELAY_US 100000    /* 100 ms */

/* MPU-6050 registers (SPI command byte = 0x80 | reg) */
#define REG_SMPLRT_DIV 0x19
#define REG_GYRO_XOUT_H 0x43
#define REG_PWR_MGMT_1 0x6B
#define REG_WHO_AM_I   0x75
#define MPU6050_WHO_AM_I 0x68

/* Data structure for gyroscope readings */
typedef struct {
    float x, y, z;
    struct timespec timestamp;
} gyro_data_t;

/* Circular buffer */
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static circular_buffer_t gyro_buffer;

/* Function prototypes */
static int  init_spi(void);
static int  init_gpio(void);
static int  read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
static void check_threshold(float x, float y, float z);
static void blink_led(void);
static void print_buffer(const circular_buffer_t *buffer);
static void cleanup(void);
static void signal_handler(int sig);

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Initialize SPI */
static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n",
                SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

/* Initialize GPIO */
static int init_gpio(void) {
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_PIN);
        return -1;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", LED_PIN);
        return -1;
    }
    return 0;
}

/* Read 6 bytes of gyroscope data from MPU-6050 via SPI */
static int read_gyro_data(float *x, float *y, float *z) {
    char tx[7], rx[7];
    int16_t raw_x, raw_y, raw_z;

    /* Burst read: 0x80 | 0x43 (GYRO_XOUT_H) */
    tx[0] = 0x80 | REG_GYRO_XOUT_H;
    for (int i = 1; i < 7; i++) tx[i] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 7) != 7) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    raw_x = (int16_t)((rx[1] << 8) | rx[2]);
    raw_y = (int16_t)((rx[3] << 8) | rx[4]);
    raw_z = (int16_t)((rx[5] << 8) | rx[6]);

    /* Convert to deg/s: 131 LSB/deg/s */
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

/* Add data to circular buffer */
static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) buffer->count++;
}

/* Check if any axis exceeds threshold */
static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > THRESHOLD || fabsf(y) > THRESHOLD || fabsf(z) > THRESHOLD) {
        blink_led();
    }
}

/* Blink LED for 1 second (500 ms on, 500 ms off) */
static void blink_led(void) {
    gpioWrite(LED_PIN, 1);
    gpioDelay(500000); /* 500 ms */
    gpioWrite(LED_PIN, 0);
    gpioDelay(500000); /* 500 ms */
}

/* Print circular buffer contents as CSV */
static void print_buffer(const circular_buffer_t *buffer) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer->count; i++) {
        int idx = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&buffer->data[idx].timestamp.tv_sec, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("%s.%09ld,%.2f,%.2f,%.2f\n",
               ts, buffer->data[idx].timestamp.tv_nsec,
               buffer->data[idx].x, buffer->data[idx].y, buffer->data[idx].z);
    }
    fflush(stdout);
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (init_spi() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    /* Set up signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 Gyroscope Monitor (SPI)\n");
    printf("Press Ctrl+C to stop and print buffer.\n");

    float x, y, z;
    struct timespec ts;

    while (running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            gyro_data_t data = { .x = x, .y = y, .z = z, .timestamp = ts };
            add_to_buffer(&gyro_buffer, data);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Print buffer before exiting */
    print_buffer(&gyro_buffer);

    cleanup();
    return EXIT_SUCCESS;
}

