#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_PWR_MGMT_1   0x6B

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 21

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 45.0

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an MPU-6050 register */
static int mpu_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n",
                value, reg, rc);
    }
    return rc;
}

/* Read a block of bytes starting at an MPU-6050 register */
static int mpu_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading %u bytes from register 0x%02X (rc=%d)\n",
                len, reg, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "Short read: expected %u bytes, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

/* Initialize the MPU-6050 sensor */
static int init_mpu6050(int handle) {
    /* Wake up the device (clear SLEEP bit) */
    if (mpu_write_reg(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (mpu_write_reg(handle, MPU6050_SMPLRT_DIV, 0x07) < 0) {
        return -1;
    }

    /* Configure gyroscope: ±250 dps, no DLPF */
    if (mpu_write_reg(handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        return -1;
    }

    /* Configure accelerometer: ±2 g, no DLPF */
    if (mpu_write_reg(handle, MPU6050_ACCEL_CONFIG, 0x00) < 0) {
        return -1;
    }

    return 0;
}

/* Read accelerometer data and compute roll/pitch in degrees */
static int read_tilt_data(int handle, float *roll, float *pitch) {
    uint8_t buf[6];

    /* Burst-read 6 bytes starting at ACCEL_XOUT_H */
    if (mpu_read_block(handle, MPU6050_ACCEL_XOUT_H, buf, 6) < 0) {
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    /* Convert to g units (default range ±2 g => 16384 LSB/g) */
    float x = (float)accel_x / 16384.0f;
    float y = (float)accel_y / 16384.0f;
    float z = (float)accel_z / 16384.0f;

    /* Compute roll and pitch in degrees */
    *roll  = atan2f(y, sqrtf(x * x + z * z)) * 180.0f / (float)M_PI;
    *pitch = atan2f(-x, sqrtf(y * y + z * z)) * 180.0f / (float)M_PI;

    return 0;
}

/* Log tilt data to a CSV file */
static void log_tilt_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening tilt_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
    } else {
        fprintf(fp, "timestamp_error,%.2f,%.2f\n", roll, pitch);
    }

    fclose(fp);
}

/* Control the LED based on tilt threshold */
static void control_led(float roll, float pitch) {
    bool tilt_exceeded = (fabsf(roll) > TILT_THRESHOLD) ||
                         (fabsf(pitch) > TILT_THRESHOLD);

    if (gpioWrite(LED_PIN, tilt_exceeded ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: failed to write LED pin %d\n", LED_PIN);
    }
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X (rc=%d)\n",
                I2C_BUS, MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050(g_i2c_handle) < 0) {
        fprintf(stderr, "Error initializing MPU-6050\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float roll, pitch;

        if (read_tilt_data(g_i2c_handle, &roll, &pitch) == 0) {
            printf("Roll: %.2f deg, Pitch: %.2f deg\n", roll, pitch);
            log_tilt_data(roll, pitch);
            control_led(roll, pitch);
        } else {
            fprintf(stderr, "Error reading tilt data, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

