#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1145_ADDR 0x45
#define I2C_BUS "/dev/i2c-1"
#define LED_PIN 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x24
#define SI1145_REG_PS1_DATA1 0x25
#define SI1145_REG_COMMAND 0x18
#define SI1145_REG_RESPONSE 0x20
#define SI1145_REG_IRQ_ENABLE 0x0F
#define SI1145_REG_IRQ_STATUS 0x12
#define SI1145_REG_HOSTIN0 0x13
#define SI1145_REG_HOSTIN1 0x14
#define SI1145_REG_HOSTIN2 0x15
#define SI1145_REG_HOSTIN3 0x16
#define SI1145_REG_HOSTIN4 0x17
#define SI1145_REG_HOSTIN5 0x18
#define SI1145_REG_HOSTIN6 0x19
#define SI1145_REG_HOSTIN7 0x1A
#define SI1145_REG_HOSTIN8 0x1B
#define SI1145_REG_HOSTIN9 0x1C
#define SI1145_REG_HOSTIN10 0x1D
#define SI1145_REG_HOSTIN11 0x1E
#define SI1145_REG_HOSTIN12 0x1F
#define SI1145_REG_HOSTIN13 0x20
#define SI1145_REG_HOSTIN14 0x21
#define SI1145_REG_HOSTIN15 0x22
#define SI1145_REG_HOSTIN16 0x23
#define SI1145_REG_HOSTIN17 0x24
#define SI1145_REG_HOSTIN18 0x25
#define SI1145_REG_HOSTIN19 0x26
#define SI1145_REG_HOSTIN20 0x27
#define SI1145_REG_HOSTIN21 0x28
#define SI1145_REG_HOSTIN22 0x29
#define SI1145_REG_HOSTIN23 0x2A
#define SI1145_REG_HOSTIN24 0x2B
#define SI1145_REG_HOSTIN25 0x2C
#define SI1145_REG_HOSTIN26 0x2D
#define SI1145_REG_HOSTIN27 0x2E
#define SI1145_REG_HOSTIN28 0x2F
#define SI1145_REG_HOSTIN29 0x30
#define SI1145_REG_HOSTIN30 0x31
#define SI1145_REG_HOSTIN31 0x32

#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PSALS_FORCE 0x07
#define SI1145_CMD_PS_PAUSE 0x0B
#define SI1145_CMD_ALS_PAUSE 0x0C
#define SI1145_CMD_PSALS_PAUSE 0x0D
#define SI1145_CMD_NOP 0x00

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[1] << 8 | buf[0];
    return 0;
}

static int si1145_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing HW_KEY: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x00) < 0) {
        fprintf(stderr, "Error writing MEAS_RATE0: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Error writing MEAS_RATE1: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_IRQ_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Error writing IRQ_ENABLE: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) {
        fprintf(stderr, "Error sending reset command: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    return 0;
}

static int si1145_read_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t response;
    int retries = MAX_RETRIES;
    while (retries > 0) {
        if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_PSALS_FORCE) < 0) {
            fprintf(stderr, "Error sending force command: %s\n", strerror(errno));
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(10000);
        if (i2c_read_reg8(fd, SI1145_REG_RESPONSE, &response) < 0) {
            fprintf(stderr, "Error reading RESPONSE: %s\n", strerror(errno));
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (response != 0x00) {
            fprintf(stderr, "Unexpected RESPONSE value: 0x%02X\n", response);
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_read_reg16(fd, SI1145_REG_ALS_VIS_DATA0, ambient_light) < 0) {
            fprintf(stderr, "Error reading ALS_VIS_DATA: %s\n", strerror(errno));
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_read_reg16(fd, SI1145_REG_PS1_DATA0, proximity) < 0) {
            fprintf(stderr, "Error reading PS1_DATA: %s\n", strerror(errno));
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0;
    }
    return -1;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,AmbientLight:%u,Proximity:%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient_light, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

