    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing HW_KEY: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x00) < 0) {
        fprintf(stderr, "Error writing MEAS_RATE0: %s\n", strerror(errno));
        return -1;
