#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXRS290 register addresses (verified against datasheet) */
#define ADXRS290_REG_XGYRO_OUT 0x04
#define ADXRS290_REG_YGYRO_OUT 0x06
#define ADXRS290_REG_TEMP_OUT  0x08
#define ADXRS290_REG_DIAG_STAT 0x0A
#define ADXRS290_REG_DEVICE_ID 0x0C

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* Sampling */
#define SAMPLE_PERIOD_US 10000  /* 10 ms -> 100 Hz */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXRS290 register                              */
/* Returns 0 on success, -1 on SPI error                               */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, uint8_t *value)
{
    char tx[2];
    char rx[2];

    tx[0] = (char)(reg | 0x80);   /* OR read bit */
    tx[1] = 0x00;                 /* dummy */

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    *value = (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register (MSB first)                        */
/* Returns 0 on success, -1 on SPI error                               */
/* ------------------------------------------------------------------ */
static int read_register16(uint8_t reg, int16_t *value)
{
    uint8_t msb, lsb;

    if (read_register(reg, &msb) != 0)
        return -1;
    if (read_register(reg + 1, &lsb) != 0)
        return -1;

    *value = (int16_t)(((uint16_t)msb << 8) | (uint16_t)lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read X and Y angular rates                                          */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int16_t *x_rate, int16_t *y_rate)
{
    if (read_register16(ADXRS290_REG_XGYRO_OUT, x_rate) != 0)
        return -1;
    if (read_register16(ADXRS290_REG_YGYRO_OUT, y_rate) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to CSV                                               */
/* ------------------------------------------------------------------ */
static void log_data(int16_t x_rate, int16_t y_rate)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;

    fprintf(log_file, "%.6f,%d,%d\n", timestamp, x_rate, y_rate);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t x_rate, y_rate;
    int retry_count = 0;
    const int max_retries = 3;

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file ------------------------------------------------ */
    log_file = fopen("gyro_data.csv", "w");
    if (log_file == NULL) {
        perror("Error opening gyro_data.csv");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,x_rate,y_rate\n");
    fflush(log_file);

    /* --- Signal handling --------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main sampling loop ------------------------------------------ */
    while (!terminate) {
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            log_data(x_rate, y_rate);
            retry_count = 0;
        } else {
            fprintf(stderr, "Failed to read gyro data (attempt %d/%d)\n",
                    retry_count + 1, max_retries);
            if (retry_count < max_retries) {
                retry_count++;
                gpioDelay(100000);  /* 100 ms back-off */
                spiClose(spi_handle);
                spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
                if (spi_handle < 0) {
                    fprintf(stderr, "SPI re-initialisation failed: %d\n",
                            spi_handle);
                    break;
                }
            } else {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Clean shutdown --------------------------------------------- */
    cleanup();
    return EXIT_SUCCESS;
}

