#define SENSOR_2_PIN 24
#define ALERT_PIN    17

#define SEISMIC_THRESHOLD_MS 500
#define ALERT_DURATION_MS    2000

#define LOG_FILE "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static volatile uint32_t sensor1_high_tick = 0;
static volatile uint32_t sensor2_high_tick = 0;
static volatile int      sensor1_high     = 0;
static volatile int      sensor2_high     = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) {
        fprintf(stderr, "Error: Log file not open.\n");
        return;
    }
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s - %s\n", ts, message);
    fflush(log_file);
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        if (gpio == SENSOR_1_PIN) {
            sensor1_high_tick = tick;
            sensor1_high = 1;
        } else if (gpio == SENSOR_2_PIN) {
            sensor2_high_tick = tick;
            sensor2_high = 1;
        }
    } else if (level == 0) {
        if (gpio == SENSOR_1_PIN) {
            sensor1_high = 0;
        } else if (gpio == SENSOR_2_PIN) {
            sensor2_high = 0;
        }
    }
}

