#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (BCM GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define LED_PIN        17         /* BCM GPIO17 */
#define BUFFER_SIZE    100
#define THRESHOLD      20.0f      /* deg/s */
#define SAMPLE_PERIOD  0.1        /* seconds */

/* ADXRS290 register addresses (8-bit, MSB = 1 for read) */
#define ADXRS290_REG_XGYRO_OUT  0x02
#define ADXRS290_REG_TEMP_OUT  0x04
#define ADXRS290_REG_DIAG_STAT 0x06
#define ADXRS290_REG_DEVICE_ID 0x08

/* ---- Data structures ---- */
typedef struct {
    struct timespec timestamp;
    int16_t x_rate;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static circular_buffer_t g_buffer;
static int g_spi_handle = -1;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static int  init_pigpio(void);
static int  init_spi(void);
static int  init_led(void);
static int  read_gyro_x(int16_t *out);
static void buffer_add(circular_buffer_t *buf, gyro_data_t d);
static void check_threshold(float rate);
static void cleanup(void);

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Initialize pigpio ---- */
static int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

/* ---- Initialize SPI ---- */
static int init_spi(void) {
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d, flags=%d): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, g_spi_handle);
        return -1;
    }
    return 0;
}

/* ---- Initialize LED ---- */
static int init_led(void) {
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        return -1;
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", LED_PIN);
        return -1;
    }
    return 0;
}

/* ---- Read X-axis angular rate ----
 * Sends the read command (address | 0x80) then clocks out 2 bytes.
 * Returns 0 on success, -1 on SPI error.
 */
static int read_gyro_x(int16_t *out) {
    char tx[2] = { (char)(ADXRS290_REG_XGYRO_OUT | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 2)\n", ret);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_add(circular_buffer_t *buf, gyro_data_t d) {
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE; /* overwrite oldest */
    } else {
        buf->count++;
    }
}

/* ---- Threshold check ---- */
static void check_threshold(float rate) {
    if (rate > THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_pigpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_spi() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_led() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&g_buffer, 0, sizeof(g_buffer));

    printf("ADXRS290 X-axis reader running. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw;
        if (read_gyro_x(&raw) != 0) {
            fprintf(stderr, "Warning: gyro read failed, retrying...\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        gyro_data_t sample;
        clock_gettime(CLOCK_MONOTONIC, &sample.timestamp);
        sample.x_rate = raw;

        buffer_add(&g_buffer, sample);
        check_threshold((float)raw);

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

