#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27
#define PWM_FREQ 100
#define PWM_RANGE 255
#define NUM_LAMPS 3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_lamp_brightness(int pin, int duty) {
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d (duty %d)\n", pin, duty);
        return -1;
    }
    return 0;
}

static int fade_lamp(int pin, int duration_sec) {
    int step_delay_us = (duration_sec * 1000000) / PWM_RANGE;
    if (step_delay_us < 1000) step_delay_us = 1000;

    for (int duty = PWM_RANGE; duty >= 0 && g_running; duty--) {
        if (set_lamp_brightness(pin, duty) != 0) return -1;
        usleep(step_delay_us);
    }
    return 0;
}

static void all_lamps_off(void) {
    set_lamp_brightness(LAMP1_PIN, 0);
    set_lamp_brightness(LAMP2_PIN, 0);
    set_lamp_brightness(LAMP3_PIN, 0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int total_duration = atoi(argv[1]);
    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Error: duration must be between 1 and 3600 seconds.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
