        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LAMP1_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(LAMP2_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(LAMP3_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
