#define YELLOW_DURATION_SEC 2
#define GREEN_DURATION_SEC  10
#define BLUE_DURATION_SEC   3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_line(struct gpiod_line *line, int val, const char *label)
{
    int ret = gpiod_line_set_value(line, val);
    if (ret < 0) {
        fprintf(stderr, "Error setting %s to %d: %s\n", label, val, strerror(-ret));
        return -1;
    }
    return 0;
}

static int all_off(struct gpiod_line *r, struct gpiod_line *y,
                   struct gpiod_line *g, struct gpiod_line *b)
{
    if (set_line(r, 1, "red")   < 0) return -1;
    if (set_line(y, 1, "yellow") < 0) return -1;
    if (set_line(g, 1, "green") < 0) return -1;
    if (set_line(b, 1, "blue")  < 0) return -1;
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *r = NULL, *y = NULL, *g = NULL, *b = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    }
    if (!chip) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    r = gpiod_chip_get_line(chip, RED_PIN);
    y = gpiod_chip_get_line(chip, YELLOW_PIN);
    g = gpiod_chip_get_line(chip, GREEN_PIN);
    b = gpiod_chip_get_line(chip, BLUE_PIN);
