        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Traffic light simulation started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (set_line(r, 0, "red")   < 0) goto cleanup;
        if (set_line(y, 1, "yellow") < 0) goto cleanup;
        if (set_line(g, 1, "green") < 0) goto cleanup;
        if (set_line(b, 1, "blue")  < 0) goto cleanup;
        printf("Red + Yellow\n");
        sleep(YELLOW_DURATION_SEC);

        if (!g_running) break;

        if (set_line(r, 1, "red")   < 0) goto cleanup;
        if (set_line(y, 1, "yellow") < 0) goto cleanup;
        if (set_line(g, 0, "green") < 0) goto cleanup;
        if (set_line(b, 1, "blue")  < 0) goto cleanup;
        printf("Red\n");
