        if (!g_running) break;

        if (set_line(r, 1, "red")   < 0) goto cleanup;
        if (set_line(y, 0, "yellow") < 0) goto cleanup;
        if (set_line(g, 0, "green") < 0) goto cleanup;
        if (set_line(b, 1, "blue")  < 0) goto cleanup;
        printf("Yellow\n");
        sleep(YELLOW_DURATION_SEC);

        if (!g_running) break;

        if (set_line(r, 1, "red")   < 0) goto cleanup;
        if (set_line(y, 1, "yellow") < 0) goto cleanup;
        if (set_line(g, 1, "green") < 0) goto cleanup;
        if (set_line(b, 0, "blue")  < 0) goto cleanup;
        printf("Green\n");
        sleep(GREEN_DURATION_SEC);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (r) gpiod_line_release(r);
    if (y) gpiod_line_release(y);
    if (g) gpiod_line_release(g);
    if (b) gpiod_line_release(b);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

