#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5C
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define POLL_DELAY_US 10000
#define LOG_FILE "touch_relay.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELE0_TOUCHTH 0x41
#define MPR121_ELE0_RELEASETH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg8(fd, MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);

    if (i2c_write_reg8(fd, MPR121_ELE0_TOUCHTH, 0x0C) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELE0_RELEASETH, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ECR, 0x8F) < 0) return -1;

    return 0;
}

static int read_touch_status(int fd, uint16_t *status) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, MPR121_ECR, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioSetMode(RELAY_GPIO, PI_INPUT);
    gpioTerminate();
    if (log_file) {
        log_message("Cleanup complete.");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }
    log_message("Program started.");

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed.");
        fclose(log_file);
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_message("Failed to open I2C bus.");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        log_message("Failed to acquire I2C bus access.");
        cleanup();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        log_message("MPR121 initialisation failed.");
        cleanup();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_message("Failed to set GPIO17 as output.");
        cleanup();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    log_message("Initialization complete. Monitoring electrode 0...");

    bool relay_state = false;
    uint32_t last_touch_ms = 0;

    while (running) {
        uint16_t touch_status;
        if (read_touch_status(i2c_fd, &touch_status) < 0) {
            log_message("Failed to read touch status.");
            break;
        }

        uint32_t now_ms = gpioTick() / 1000;
        if (touch_status & 0x0001) {
            if (now_ms - last_touch_ms > DEBOUNCE_DELAY_MS) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state ? 1 : 0);
                char msg[128];
                snprintf(msg, sizeof(msg), "Electrode 0 touched. Relay toggled to %s.", relay_state ? "ON" : "OFF");
                log_message(msg);
                last_touch_ms = now_ms;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    log_message("Shutting down.");
    cleanup();
    return 0;
}

