}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    int consecutive_low = 0;
    int flame_active = 0;

    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Sensor read error, exiting\n");
            break;
        }

        if (sensor_value == 0) {
            consecutive_low++;
            if (consecutive_low >= CONSECUTIVE_READS && !flame_active) {
                if (log_flame_detection() != 0) {
                    fprintf(stderr, "Logging failed, exiting\n");
                    break;
                }
                if (activate_buzzer() != 0 || activate_led() != 0) {
                    fprintf(stderr, "Activation failed, exiting\n");
                    break;
                }
                flame_active = 1;
                printf("Flame detected!\n");
            }
        } else {
            consecutive_low = 0;
            if (flame_active) {
                if (deactivate_buzzer() != 0 || deactivate_led() != 0) {
                    fprintf(stderr, "Deactivation failed, exiting\n");
                    break;
                }
                flame_active = 0;
                printf("Flame cleared.\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Exiting gracefully.\n");
    return EXIT_SUCCESS;
}

