#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_INTERVAL_MS 1000
#define DISPENSE_LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_dispense_event(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen(DISPENSE_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", DISPENSE_LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Solenoid on GPIO%d dispensed for %d ms\n", timestamp, solenoid_pin, duration_ms) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int dispense_solenoid(int solenoid_pin, int duration_ms) {
    if (gpioWrite(solenoid_pin, 1) != 0) {
        fprintf(stderr, "Error activating solenoid on GPIO%d\n", solenoid_pin);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(solenoid_pin, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid on GPIO%d\n", solenoid_pin);
        return -1;
    }

    return 0;
}

static int dispense_sequence(void) {
    int half_duration = DISPENSE_INTERVAL_MS / 2;

    if (dispense_solenoid(SOLENOID_1_PIN, half_duration) != 0) {
        return -1;
    }

    if (log_dispense_event(SOLENOID_1_PIN, half_duration) != 0) {
        return -1;
    }

    if (dispense_solenoid(SOLENOID_2_PIN, half_duration) != 0) {
        return -1;
    }

    if (log_dispense_event(SOLENOID_2_PIN, half_duration) != 0) {
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_1_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing GPIO%d to LOW\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_2_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing GPIO%d to LOW\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (dispense_sequence() != 0) {
            fprintf(stderr, "Error during dispense sequence\n");
        }

        if (program_running) {
            gpioDelay(5000000);
        }
    }

    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();

    printf("Dispensing system stopped.\n");
    return EXIT_SUCCESS;
}

