#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25

#define KP 1.0
#define KI 0.1
#define KD 0.01

#define LOOP_DELAY_US 50000
#define OBSTACLE_THRESHOLD 20.0
#define OBSTACLE_AVOIDANCE_SPEED 128
#define MAX_SPEED 255

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float simulate_tilt_sensor(void) {
    return ((float)rand() / RAND_MAX) * 20.0f - 10.0f;
}

static float simulate_ultrasonic_sensor(void) {
    return ((float)rand() / RAND_MAX) * 398.0f + 2.0f;
}

static int set_motor_speed(int motor, int speed) {
    if (speed > MAX_SPEED) speed = MAX_SPEED;
    if (speed < -MAX_SPEED) speed = -MAX_SPEED;

    if (motor == 'A') {
        if (speed > 0) {
            gpioWrite(MOTOR_A_FORWARD, 1);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENA, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 1);
            gpioPWM(ENA, -speed);
        } else {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENA, 0);
        }
    } else if (motor == 'B') {
        if (speed > 0) {
            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENB, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
            gpioPWM(ENB, -speed);
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENB, 0);
        }
    } else {
        fprintf(stderr, "Error: Invalid motor identifier: %c\n", motor);
        return -1;
    }
    return 0;
}

static int pid_control(float error, float *integral, float *previous_error) {
    float proportional = KP * error;
    *integral += KI * error;
    if (*integral > MAX_SPEED) *integral = MAX_SPEED;
    if (*integral < -MAX_SPEED) *integral = -MAX_SPEED;
    float derivative = KD * (error - *previous_error);
    *previous_error = error;
    return (int)(proportional + *integral + derivative);
}

static void obstacle_avoidance(float distance) {
    if (distance < OBSTACLE_THRESHOLD) {
        set_motor_speed('A', -OBSTACLE_AVOIDANCE_SPEED);
        set_motor_speed('B', -OBSTACLE_AVOIDANCE_SPEED);
    } else {
        set_motor_speed('A', 0);
        set_motor_speed('B', 0);
    }
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,tilt_error,distance,motor_a_speed,motor_b_speed\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float integral = 0.0f;
    float previous_error = 0.0f;

    while (running) {
        float tilt_error = simulate_tilt_sensor();
        float distance = simulate_ultrasonic_sensor();

        int motor_a_speed = pid_control(tilt_error, &integral, &previous_error);
        int motor_b_speed = pid_control(tilt_error, &integral, &previous_error);

        obstacle_avoidance(distance);

        set_motor_speed('A', motor_a_speed);
        set_motor_speed('B', motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    set_motor_speed('A', 0);
    set_motor_speed('B', 0);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

