/*
 * mood_light.c — Raspberry Pi 3 Model B+
 *
 * Captures audio via ALSA, computes RMS amplitude, and drives a common-cathode
 * RGB LED (red=GPIO17, green=GPIO18, blue=GPIO27) with the driver library's
 * software PWM.  Falls back to a sine-wave simulator when ALSA is unavailable.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mood_light mood_light.c \
 *       -ldriver -lasound -lm
 *
 * Run:
 *   ./mood_light [sensitivity]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>

#include <driver.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define SAMPLE_RATE       8000
#define PERIOD_SIZE       1024
#define PWM_PERIOD_US     1000   /* 1 ms → 1 kHz software PWM */
#define UPDATE_INTERVAL   10000 /* 10 ms between color updates */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_us(unsigned us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

/* ---- ALSA capture (compiled only when ALSA_AVAILABLE) ---- */

#ifdef ALSA_AVAILABLE

static snd_pcm_t *g_alsa_handle = NULL;
static snd_pcm_hw_params_t *g_hw_params = NULL;

static int init_alsa(void)
{
    int err;

    err = snd_pcm_open(&g_alsa_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_open failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_malloc(&g_hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_malloc failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_any(g_alsa_handle, g_hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_any failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_access(g_alsa_handle, g_hw_params,
                                       SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_access failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_format(g_alsa_handle, g_hw_params,
                                       SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_format failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_rate_near(g_alsa_handle, g_hw_params,
                                          &SAMPLE_RATE, NULL);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_channels(g_alsa_handle, g_hw_params, 1);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_period_size_near(g_alsa_handle, g_hw_params,
                                                  &(unsigned int){PERIOD_SIZE}, NULL);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_period_size_near failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params(g_alsa_handle, g_hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_prepare(g_alsa_handle);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(err));
        goto fail;
    }

    return 0;

fail:
    if (g_hw_params) {
        snd_pcm_hw_params_free(g_hw_params);
        g_hw_params = NULL;
    }
    if (g_alsa_handle) {
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = NULL;
    }
    return -1;
}

static void cleanup_alsa(void)
{
    if (g_alsa_handle) {
        snd_pcm_drain(g_alsa_handle);
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = NULL;
    }
    if (g_hw_params) {
        snd_pcm_hw_params_free(g_hw_params);
        g_hw_params = NULL;
    }
}

static int read_audio_frame(short *buffer, int frames)
{
    int err = snd_pcm_readi(g_alsa_handle, buffer, frames);
    if (err == -EPIPE) {
        fprintf(stderr, "ALSA buffer overrun — re-preparing\n");
        snd_pcm_prepare(g_alsa_handle);
        return -1;
    } else if (err == -EINTR) {
        return -1;
    } else if (err < 0) {
        fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_strerror(err));
        return -1;
    }
    return 0;
}

#else

static void init_alsa(void) { (void)init_alsa; }
static void cleanup_alsa(void) { (void)cleanup_alsa; }
static int read_audio_frame(short *buffer, int frames)
{
    (void)buffer;
    (void)frames;
    return 0;
}

#endif

/* ---- RGB LED control via driver library ---- */

static struct driver *g_drv = NULL;
static struct gpio *g_red = NULL, *g_green = NULL, *g_blue = NULL;

static int init_gpio(void)
{
    g_drv = driver_open(NULL, 0, 0);
    if (!g_drv) {
        fprintf(stderr, "driver_open failed\n");
        return -1;
    }

    g_red   = driver_gpio(g_drv, RED_PIN);
    g_green = driver_gpio(g_drv, GREEN_PIN);
    g_blue  = driver_gpio(g_drv, BLUE_PIN);
