/*
 * mood_light.c — Raspberry Pi 3 Model B+
 *
 * Captures audio via ALSA, computes RMS amplitude, and drives a common-cathode
 * RGB LED (red=GPIO17, green=GPIO18, blue=GPIO27) with the driver library's
 * software PWM.  Falls back to a sine-wave simulator when ALSA is unavailable.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mood_light mood_light.c \
 *       -ldriver -lasound -lm
 *
 * Run:
 *   ./mood_light [sensitivity]
 */

