    if (g_hw_params) {
        snd_pcm_hw_params_free(g_hw_params);
        g_hw_params = NULL;
    }
    if (g_alsa_handle) {
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = NULL;
    }
    return -1;
}

static void cleanup_alsa(void)
{
