#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define SUNRISE_DURATION 3600
#define DAY_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHT_DURATION 51840

#define PWM_STEPS 100
#define STEP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int all_relays_off(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (set_relay_state(pins[i], 1) != 0) return -1;
    }
    return 0;
}

static int sunrise_sequence(void) {
    for (int i = 0; i < PWM_STEPS && running; i++) {
        int duty = (i * 100) / PWM_STEPS;
        int on_time = (duty * STEP_DELAY_US) / 100;
        int off_time = STEP_DELAY_US - on_time;
        if (set_relay_state(RELAY1_PIN, 0) != 0) return -1;
        if (set_relay_state(RELAY2_PIN, 0) != 0) return -1;
        if (set_relay_state(RELAY3_PIN, 0) != 0) return -1;
        if (set_relay_state(RELAY4_PIN, 0) != 0) return -1;
        gpioDelay(on_time);
        if (set_relay_state(RELAY1_PIN, 1) != 0) return -1;
        if (set_relay_state(RELAY2_PIN, 1) != 0) return -1;
        if (set_relay_state(RELAY3_PIN, 1) != 0) return -1;
        if (set_relay_state(RELAY4_PIN, 1) != 0) return -1;
        gpioDelay(off_time);
    }
    return 0;
}

static int sunset_sequence(void) {
    for (int i = PWM_STEPS - 1; i >= 0 && running; i--) {
        int duty = (i * 100) / PWM_STEPS;
        int on_time = (duty * STEP_DELAY_US) / 100;
        int off_time = STEP_DELAY_US - on_time;
        if (set_relay_state(RELAY1_PIN, 0) != 0) return -1;
        if (set_relay_state(RELAY2_PIN, 0) != 0) return -1;
        if (set_relay_state(RELAY3_PIN, 0) != 0) return -1;
        if (set_relay_state(RELAY4_PIN, 0) != 0) return -1;
        gpioDelay(on_time);
        if (set_relay_state(RELAY1_PIN, 1) != 0) return -1;
        if (set_relay_state(RELAY2_PIN, 1) != 0) return -1;
        if (set_relay_state(RELAY3_PIN, 1) != 0) return -1;
        if (set_relay_state(RELAY4_PIN, 1) != 0) return -1;
        gpioDelay(off_time);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO pin %d as output\n", pins[i]);
            gpioTerminate();
            return 1;
        }
        if (set_relay_state(pins[i], 1) != 0) {
            gpioTerminate();
            return 1;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handler\n");
        all_relays_off();
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (sunrise_sequence() != 0) break;
        if (!running) break;
        for (int i = 0; i < DAY_DURATION / 100 && running; i++) gpioDelay(100000);
        if (!running) break;
        if (sunset_sequence() != 0) break;
        if (!running) break;
        for (int i = 0; i < NIGHT_DURATION / 100 && running; i++) gpioDelay(100000);
    }

    all_relays_off();
    gpioTerminate();
    return 0;
}

