#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_US 200000
#define VIDEO_DURATION_SEC 5
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int capture_video(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[128];
    char command[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }

    if (strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.h264", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }

    if (snprintf(command, sizeof(command), "raspivid -o %s%s -t %d -w 640 -h 480 -fps 30 2>/dev/null",
                 VIDEO_DIR, filename, VIDEO_DURATION_SEC * 1000) >= (int)sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small.\n");
        return -1;
    }

    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error: system() failed to execute raspivid.\n");
        return -1;
    }
    if (WIFEXITED(result) && WEXITSTATUS(result) != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d.\n", WEXITSTATUS(result));
        return -1;
    }
    if (WIFSIGNALED(result)) {
        fprintf(stderr, "Error: raspivid killed by signal %d.\n", WTERMSIG(result));
        return -1;
    }

    printf("Video captured: %s%s\n", VIDEO_DIR, filename);
    return 0;
}

static int log_motion_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }

    if (fprintf(log_file, "%s Motion detected\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush() failed on log file.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    uint32_t last_trigger_tick = 0;

    while (running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", GPIO_PIN);
            break;
        }

        if (level == 0) {
            uint32_t now_tick = gpioTick();
            uint32_t elapsed = now_tick - last_trigger_tick;

            if (last_trigger_tick == 0 || elapsed >= DEBOUNCE_DELAY_US) {
                printf("Motion detected!\n");

                if (capture_video() != 0) {
                    fprintf(stderr, "Warning: video capture failed.\n");
                }

                if (log_motion_event() != 0) {
                    fprintf(stderr, "Warning: failed to log motion event.\n");
                }

                last_trigger_tick = now_tick;
            }
        }

        gpioDelay(10000);
    }

    cleanup();
    printf("Exiting gracefully.\n");
    return EXIT_SUCCESS;
}

