#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (SDO tied to GND) */
#define ADXL345_ADDR 0x53

/* ADXL345 registers */
#define ADXL345_REG_DEVID       0x00
#define ADXL345_REG_POWER_CTL   0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID          0xE5

/* Free-fall threshold: 0.2 g in g-force units */
#define FREEFALL_THRESHOLD_G   0.2f

/* Free-fall confirmation window: 0.5 s */
#define FREEFALL_WINDOW_SEC    0.5

/* Alarm GPIO (BCM numbering) */
#define ALARM_GPIO             27

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS                1

/* Polling interval */
#define POLL_INTERVAL_US       100000  /* 100 ms */

/* Alarm hold time */
#define ALARM_HOLD_SEC         5

/* Log file path */
#define LOG_FILE               "freefall.log"

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — clean shutdown                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register                                */
/* ------------------------------------------------------------------ */
static int adxl_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register                               */
/* ------------------------------------------------------------------ */
static int adxl_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADXL345: verify device ID, set range to +/-2 g,      */
/* enable measurement mode.                                            */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    int devid = adxl_read_reg(handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        return -1;
    }
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID);
        return -1;
    }

    /* DATA_FORMAT: 0x0B = FULL_RES bit=1 (12-bit) + range bits = +/-2 g */
    if (adxl_write_reg(handle, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) {
        return -1;
    }

    /* POWER_CTL: bit D3 = MEASURE */
    if (adxl_write_reg(handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data and convert to g-force units.     */
/* ------------------------------------------------------------------ */
static int adxl345_read_g(int handle, float *x, float *y, float *z)
{
    char raw[6];
    int rc = i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0, raw, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read failed: %s\n", pigpio_error(rc));
        return -1;
    }

    /* ADXL345 is little-endian: DATAX0 = LSB, DATAX1 = MSB */
    int16_t x_raw = (int16_t)(((uint8_t)raw[1] << 8) | (uint8_t)raw[0]);
    int16_t y_raw = (int16_t)(((uint8_t)raw[3] << 8) | (uint8_t)raw[2]);
    int16_t z_raw = (int16_t)(((uint8_t)raw[5] << 8) | (uint8_t)raw[4]);

    /*
     * Full-resolution mode: 12-bit left-justified in 16 bits.
     * Sensitivity = 3.9 mg/LSB = 0.0039 g/LSB.
     * Right-shift by 4 to get the 12-bit value, then multiply.
     */
    *x = (float)x_raw * 0.0039f;
    *y = (float)y_raw * 0.0039f;
    *z = (float)z_raw * 0.0039f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Detect free-fall: all three axes below threshold for window seconds */
/* ------------------------------------------------------------------ */
static bool detect_freefall(int handle)
{
    float x1, y1, z1;
    if (adxl345_read_g(handle, &x1, &y1, &z1) < 0) {
        return false;
    }

    if (fabsf(x1) > FREEFALL_THRESHOLD_G ||
        fabsf(y1) > FREEFALL_THRESHOLD_G ||
        fabsf(z1) > FREEFALL_THRESHOLD_G) {
        return false;
    }

    /* Wait for the confirmation window */
    time_sleep(FREEFALL_WINDOW_SEC);

    float x2, y2, z2;
    if (adxl345_read_g(handle, &x2, &y2, &z2) < 0) {
        return false;
    }

    return (fabsf(x2) <= FREEFALL_THRESHOLD_G &&
            fabsf(y2) <= FREEFALL_THRESHOLD_G &&
            fabsf(z2) <= FREEFALL_THRESHOLD_G);
}

/* ------------------------------------------------------------------ */
/* Log a free-fall event to CSV file                                    */
/* ------------------------------------------------------------------ */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z);
    } else {
        fprintf(fp, "timestamp_error,%.3f,%.3f,%.3f\n", x, y, z);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Activate alarm on GPIO27 for hold seconds                            */
/* ------------------------------------------------------------------ */
static void trigger_alarm(int gpio_pin, int hold_sec)
{
    if (gpioWrite(gpio_pin, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d high\n", gpio_pin);
        return;
    }
    time_sleep(hold_sec);
    if (gpioWrite(gpio_pin, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d low\n", gpio_pin);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(g_i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure alarm GPIO */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (detect_freefall(g_i2c_handle)) {
            float x, y, z;
            adxl345_read_g(g_i2c_handle, &x, &y, &z);
            printf("Free-fall detected! X=%.3f g, Y=%.3f g, Z=%.3f g\n", x, y, z);
            log_freefall(x, y, z);
            trigger_alarm(ALARM_GPIO, ALARM_HOLD_SEC);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

