#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18

#define TRIGGER_PULSE_US 10
#define CYCLE_DELAY_US 200000
#define ECHO_TIMEOUT_US 100000
#define MAX_PULSE_US 23200
#define MAX_DISTANCE_CM 400.0
#define SPEED_OF_SOUND_CM_PER_US 0.0343

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick = 0;
static volatile int g_echo_state = 0;
static volatile int g_echo_done = 0;
static volatile int g_running = 1;

static pthread_mutex_t g_data_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *g_log_file = NULL;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        g_start_tick = tick;
        g_echo_state = 1;
    } else if (level == 0 && g_echo_state == 1) {
        g_end_tick = tick;
        g_echo_state = 2;
        g_echo_done = 1;
    }
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void log_distance(double distance_cm, uint32_t timestamp_ns) {
    if (g_log_file == NULL) return;
    if (distance_cm < 0.0) {
        fprintf(g_log_file, "%u,-1.0\n", timestamp_ns);
    } else {
        fprintf(g_log_file, "%u,%.2f\n", timestamp_ns, distance_cm);
    }
    fflush(g_log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert function for ECHO_PIN.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("distance_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open distance_log.txt for appending.\n");
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        g_echo_done = 0;
        g_echo_state = 0;
        g_start_tick = 0;
        g_end_tick = 0;

        trigger_sensor();

        uint32_t start_wait = gpioTick();
        while (!g_echo_done && g_running) {
            if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);
        }

        uint32_t pulse_us = 0;
        double distance_cm = -1.0;
        uint32_t timestamp_ns = gpioTick();

        if (g_echo_done) {
            uint32_t start = g_start_tick;
            uint32_t end = g_end_tick;
            pulse_us = end - start;
            if (pulse_us > MAX_PULSE_US) {
                fprintf(stderr, "Warning: pulse width %u us exceeds max, discarding.\n", pulse_us);
            } else {
                distance_cm = (pulse_us * SPEED_OF_SOUND_CM_PER_US) / 2.0;
            }
        } else {
            fprintf(stderr, "Warning: echo timeout (no echo received within %d us).\n", ECHO_TIMEOUT_US);
        }

        log_distance(distance_cm, timestamp_ns);
        printf("Distance: %.2f cm (pulse: %u us)\n", distance_cm, pulse_us);

        gpioDelay(CYCLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    pthread_mutex_destroy(&g_data_mutex);
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

