    int16_t raw_x = (int16_t)((x_h << 8) | x_l);
    int16_t raw_y = (int16_t)((y_h << 8) | y_l);
    int16_t raw_z = (int16_t)((z_h << 8) | z_l);

    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;
    return 0;
}

static void activate_buzzer(int gpio, int duration_ms) {
    gpioWrite(gpio, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(gpio, 0);
}

int main(int argc, char *argv[]) {
    int i2c_bus = DEFAULT_I2C_BUS;
    int lis3dh_addr = DEFAULT_LIS3DH_ADDR;
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-b") == 0 && i + 1 < argc) {
            i2c_bus = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            lis3dh_addr = (int)strtol(argv[++i], NULL, 0);
        } else if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            freefall_threshold = (float)atof(argv[++i]);
        } else if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            impact_threshold = (float)atof(argv[++i]);
        } else if (strcmp(argv[i], "-g") == 0 && i + 1 < argc) {
            buzzer_gpio = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            DEFAULT_BUZZER_DURATION_MS = atoi(argv[++i]);
        } else {
            fprintf(stderr, "Usage: %s [-b i2c_bus] [-a lis3dh_addr] [-f freefall_threshold] [-i impact_threshold] [-g buzzer_gpio] [-d buzzer_duration_ms]\n", argv[0]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(i2c_bus, lis3dh_addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, address 0x%02X: %d\n", i2c_bus, lis3dh_addr, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh(i2c_handle) != 0) {
        fprintf(stderr, "LIS3DH initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(buzzer_gpio, PI_OUTPUT);
    gpioWrite(buzzer_gpio, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    bool in_freefall = false;

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float magnitude = sqrtf(x * x + y * y + z * z);

        if (magnitude < freefall_threshold && !in_freefall) {
            printf("Freefall detected! Magnitude: %.3f g\n", magnitude);
            in_freefall = true;
        } else if (magnitude > impact_threshold && in_freefall) {
            printf("Impact detected! Magnitude: %.3f g\n", magnitude);
            activate_buzzer(buzzer_gpio, DEFAULT_BUZZER_DURATION_MS);
            in_freefall = false;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(buzzer_gpio, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

