static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_lis3dh(int handle) {
    if (i2cWriteByteData(handle, LIS3DH_REG_CTRL1, CTRL1_VAL) < 0) {
        fprintf(stderr, "Error writing CTRL1: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(handle, LIS3DH_REG_CTRL4, CTRL4_VAL) < 0) {
        fprintf(stderr, "Error writing CTRL4: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, LIS3DH_REG_OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        *x = *y = *z = 0.0f;
        return -1;
    }
    short x_raw = (short)((buffer[1] << 8) | buffer[0]);
    short y_raw = (short)((buffer[3] << 8) | buffer[2]);
    short z_raw = (short)((buffer[5] << 8) | buffer[4]);
    *x = (float)x_raw / 16384.0f;
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;
    return 0;
}

static void log_acceleration(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.3f g, Y: %.3f g, Z: %.3f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fclose(fp);
}

static void shutdown_system(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fprintf(fp, "System shutdown initiated due to high acceleration.\n");
        fclose(fp);
    }
    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    float threshold = DEFAULT_THRESHOLD;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            i2c_address = (int)strtol(argv[++i], NULL, 16);
            if (i2c_address < 0x08 || i2c_address > 0x77) {
                fprintf(stderr, "Invalid I2C address: 0x%02X\n", i2c_address);
                return 0;
            }
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = strtof(argv[++i], NULL);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Threshold must be greater than 0.\n");
                return 0;
            }
        } else {
            fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold_g]\n", argv[0]);
            return 0;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (non-hardware environment).\n");
        return 0;
    }

    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", i2c_address, strerror(errno));
        gpioTerminate();
        return 0;
    }

    int who_am_i = i2cReadByteData(i2c_handle, LIS3DH_REG_WHO_AM_I);
    if (who_am_i != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "LIS3DH not detected (WHO_AM_I=0x%02X, expected 0x%02X).\n", who_am_i, LIS3DH_WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    if (init_lis3dh(i2c_handle) < 0) {
        fprintf(stderr, "LIS3DH initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Monitoring acceleration (threshold: %.2f g)...\n", threshold);

    while (!terminate) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_acceleration(x, y, z);
                shutdown_system();
                break;
            }
        }
        gpioDelay(SLEEP_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

