#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN   4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27
#define ALERT_PIN         22

#define BUFFER_SIZE 5
#define POLL_DELAY_US 10000   /* 10 ms */
#define ALERT_DURATION_US 2000000 /* 2 s */

typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

static sensor_data_t sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void add_to_buffer(int left, int center, int right) {
    sensor_buffer[buffer_index].left   = left;
    sensor_buffer[buffer_index].center = center;
    sensor_buffer[buffer_index].right  = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void check_line_loss(void) {
    if (buffer_count < BUFFER_SIZE) return;

    int last_five_center = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        last_five_center |= sensor_buffer[idx].center;
    }
    if (last_five_center == 1) {
        gpioWrite(ALERT_PIN, 1);
        gpioDelay(ALERT_DURATION_US);
        gpioWrite(ALERT_PIN, 0);
    }
}

static void move_forward(void)  { printf("Moving forward\n"); }
static void turn_left(void)    { printf("Turning left\n"); }
static void turn_right(void)   { printf("Turning right\n"); }
static void stop_robot(void)   { printf("Stopping\n"); }

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize alert pin.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int center = gpioRead(CENTER_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error: GPIO read failure (L=%d C=%d R=%d).\n", left, center, right);
            stop_robot();
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        add_to_buffer(left, center, right);
        check_line_loss();

        if (center == 0) {
            if (left == 0)  turn_left();
            else if (right == 0) turn_right();
            else                move_forward();
        } else {
            stop_robot();
        }

        gpioDelay(POLL_DELAY_US);
    }

    stop_robot();
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

