#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7210_ADDR 0x48
#define RELAY_GPIO 17
#define THRESHOLD 5.0f
#define LOG_FILE "magnetic_events.txt"
#define POLL_TIMEOUT_MS 5000
#define POLL_INTERVAL_US 10000
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s: %s\n", ts, message);
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_si7210(void) {
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x01, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x02, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x03, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x04, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x05, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x06, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x07, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x08, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x09, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x0A, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x0B, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x0C, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x0D, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x0E, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x0F, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x10, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x11, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x12, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x13, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x14, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x15, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x16, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x17, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x18, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x19, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x1A, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x1B, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x1C, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x1D, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x1E, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x1F, 0x00) < 0) return -1;
    return 0;
}

static int read_magnetic_field(float *field) {
    int raw = i2cReadWordData(i2c_handle, 0x00);
    if (raw < 0) return -1;
    *field = (float)raw * 0.1f;
    return 0;
}

static void control_relay(bool on) {
    gpioWrite(RELAY_GPIO, on ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed\n");
        gpioTerminate();
        return 1;
    }
    if (init_si7210() < 0) {
        fprintf(stderr, "Si7210 init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    log_event("Program started");
    bool relay_on = false;
    while (running) {
        float field;
        if (read_magnetic_field(&field) < 0) {
            log_event("Error reading magnetic field");
            gpioWrite(RELAY_GPIO, 0);
            relay_on = false;
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (field > THRESHOLD) {
            if (!relay_on) {
                control_relay(true);
                relay_on = true;
                char msg[128];
                snprintf(msg, sizeof(msg), "Relay ON (field=%.2f mT)", field);
                log_event(msg);
            }
        } else {
            if (relay_on) {
                control_relay(false);
                relay_on = false;
                log_event("Relay OFF");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    log_event("Program shutting down");
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

