                log_event(msg);
            }
        } else {
            if (relay_on) {
                control_relay(false);
                relay_on = false;
                log_event("Relay OFF");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    log_event("Program shutting down");
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

