#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int new_socket = -1;
static FILE *log_file = NULL;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static int parse_command(const char *command) {
    if (command == NULL) return -1;
    size_t len = strlen(command);
    for (size_t i = 0; i < len; i++) {
        if (command[i] == '\0') break;
        command[i] = (char)tolower((unsigned char)command[i]);
    }
    if (strcmp(command, "on") == 0) return 1;
    if (strcmp(command, "off") == 0) return 0;
    return -1;
}

static int set_relay(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (new_socket >= 0) {
        close(new_socket);
        new_socket = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        log_event("Server shutting down");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO %d to LOW\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        cleanup();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Listening on port %d...\n", PORT);
    log_event("Server started");

    while (running) {
        new_socket = accept(server_fd, NULL, NULL);
        if (new_socket < 0) {
            if (errno == EINTR && !running) break;
            perror("accept failed");
            continue;
        }

        char buffer[BUFFER_SIZE] = {0};
        ssize_t bytes = read(new_socket, buffer, BUFFER_SIZE - 1);
        if (bytes < 0) {
            perror("read failed");
            close(new_socket);
            new_socket = -1;
            continue;
        }
        if (bytes == 0) {
            close(new_socket);
            new_socket = -1;
            continue;
        }
        buffer[bytes] = '\0';

        int command = parse_command(buffer);
        if (command == 1) {
            if (set_relay(1) == 0) {
                log_event("Relay turned ON");
                printf("Relay turned ON\n");
            }
        } else if (command == 0) {
            if (set_relay(0) == 0) {
                log_event("Relay turned OFF");
                printf("Relay turned OFF\n");
            }
        } else {
            char log_msg[256];
            snprintf(log_msg, sizeof(log_msg), "Invalid command received: %s", buffer);
            fprintf(stderr, "%s\n", log_msg);
            log_event(log_msg);
        }

        close(new_socket);
        new_socket = -1;
    }

    cleanup();
    return EXIT_SUCCESS;
}

