#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x28
#define SENSOR2_ADDR 0x29
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0f
#define POLL_DELAY_US 100000
#define LOG_FILE "flow_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t cmd[2] = {0x36, 0x08};
    uint8_t buf[3];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write start-measurement command to I2C handle %d\n", handle);
        return -1;
    }

    gpioDelay(10000); /* 10 ms conversion delay */

    if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: failed to read 3 bytes from I2C handle %d\n", handle);
        return -1;
    }

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on I2C handle %d\n", handle);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / 100.0f;
    return 0;
}

static void log_flow_rate(FILE *fp, float flow1, float flow2) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld, Flow1: %.2f ml/min, Flow2: %.2f ml/min\n",
            timestamp, ts.tv_nsec / 1000000, flow1, flow2);
    fflush(fp);
}

static void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main(void) {
    int handle1 = -1, handle2 = -1;
    FILE *log_fp = NULL;
    int rc = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X (err=%d)\n", SENSOR1_ADDR, handle1);
        goto cleanup_gpio;
    }

    handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X (err=%d)\n", SENSOR2_ADDR, handle2);
        goto cleanup_i2c1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_GPIO);
        goto cleanup_i2c2;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay GPIO %d to LOW\n", RELAY_GPIO);
        goto cleanup_i2c2;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        goto cleanup_i2c2;
    }

    printf("Monitoring flow sensors. Press Ctrl+C to exit.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = (read_flow_rate(handle1, &flow1) == 0);
        int ok2 = (read_flow_rate(handle2, &flow2) == 0);

        if (ok1 && ok2) {
            log_flow_rate(log_fp, flow1, flow2);
            if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
                control_relay(RELAY_GPIO, 1);
                printf("Flow below threshold. Relay ON.\n");
            } else {
                control_relay(RELAY_GPIO, 0);
                printf("Flow above threshold. Relay OFF.\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed (s1=%d, s2=%d). Relay state unchanged.\n", ok1, ok2);
        }

        gpioDelay(POLL_DELAY_US);
    }

    rc = 0;

cleanup_i2c2:
    if (handle2 >= 0) i2cClose(handle2);
cleanup_i2c1:
    if (handle1 >= 0) i2cClose(handle1);
cleanup_log:
    if (log_fp != NULL) fclose(log_fp);
cleanup_gpio:
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return rc;
}

