#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define MOTOR_RUN_US    5000000  /* 5 seconds in microseconds */
#define POLL_US         200000   /* 200 ms between polls */
#define DRY_THRESHOLD   3        /* consecutive dry polls to re-arm */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */

static int motor_stop(void)
{
    int rc = 0;
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        syslog(LOG_WARNING, "gpioWrite(ENA,0) failed");
        rc = -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_WARNING, "gpioWrite(IN1,0) failed");
        rc = -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_WARNING, "gpioWrite(IN2,0) failed");
        rc = -1;
    }
    return rc;
}

static int motor_close(void)
{
    int rc = 0;
    if (gpioWrite(MOTOR_ENA_PIN, 1) < 0) {
        syslog(LOG_WARNING, "gpioWrite(ENA,1) failed");
        rc = -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_WARNING, "gpioWrite(IN1,1) failed");
        rc = -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_WARNING, "gpioWrite(IN2,0) failed");
        rc = -1;
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting rain-activated window controller");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(RAIN) failed");
        goto fail_init;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(RAIN) failed");
        goto fail_init;
    }

    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(ENA) failed");
        goto fail_init;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(IN1) failed");
        goto fail_init;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(IN2) failed");
        goto fail_init;
    }

    /* Ensure motor is stopped at startup */
    if (motor_stop() < 0) {
        syslog(LOG_ERR, "Initial motor_stop() failed");
        goto fail_init;
    }

    syslog(LOG_INFO, "Monitoring rain sensor on GPIO %d", RAIN_SENSOR_PIN);

    int armed = 1;          /* 1 = ready to trigger on next wet edge */
    int dry_count = 0;      /* consecutive dry polls */

    while (g_running) {
        int rain = gpioRead(RAIN_SENSOR_PIN);
        if (rain < 0) {
            syslog(LOG_WARNING, "gpioRead(RAIN) failed");
            usleep(POLL_US);
            continue;
        }

        if (rain == 0) {
            /* Sensor DO is low => rain present */
            dry_count = 0;
            if (armed) {
                syslog(LOG_INFO, "Rain detected (GPIO %d low)", RAIN_SENSOR_PIN);
                armed = 0;

                if (motor_close() < 0) {
                    syslog(LOG_ERR, "motor_close() failed; aborting run");
                    break;
                }

                syslog(LOG_INFO, "Closing window for %d us", MOTOR_RUN_US);

                /*
                 * gpioDelay is a busy-wait but keeps the process alive
                 * and responsive to signals.  Break the block into
                 * 100 ms slices so SIGINT/SIGTERM are caught promptly.
                 */
                uint32_t elapsed = 0;
                while (g_running && elapsed < MOTOR_RUN_US) {
                    uint32_t slice = (MOTOR_RUN_US - elapsed > 100000)
                                      ? 100000 : (MOTOR_RUN_US - elapsed);
                    gpioDelay(slice);
                    elapsed += slice;
                }

                if (motor_stop() < 0) {
                    syslog(LOG_ERR, "motor_stop() after run failed");
                } else {
                    syslog(LOG_INFO, "Window close sequence complete");
                }

                /* Re-arm only after the motor has stopped */
                armed = 0;
            }
        } else {
            /* Sensor DO is high => dry */
            dry_count++;
            if (dry_count >= DRY_THRESHOLD) {
                armed = 1;
                dry_count = 0;
            }
        }

        usleep(POLL_US);
    }

    /* Graceful shutdown */
    syslog(LOG_INFO, "Shutting down, stopping motor");
    if (motor_stop() < 0) {
        syslog(LOG_ERR, "motor_stop() during shutdown failed");
    }
    gpioTerminate();
    syslog(LOG_INFO, "Shutdown complete");
    closelog();
    return EXIT_SUCCESS;

fail_init:
    gpioTerminate();
    closelog();
    return EXIT_FAILURE;
}

