#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define DEBOUNCE_US    50000   /* 50 ms debounce window */
#define POLL_US        10000   /* 10 ms poll interval */
#define SERVO_STOP_US  0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_servo_pulse(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d (pulse %d us)\n",
                SERVO_PIN, pulse_us);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop the servo (no pulses) and release the pin. */
    gpioServo(SERVO_PIN, SERVO_STOP_US);
    gpioSetMode(SERVO_PIN, PI_INPUT);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set button pins as input\n");
        cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up resistors on button pins\n");
        cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure servo is stopped at start. */
    if (set_servo_pulse(SERVO_STOP_US) != 0) {
        cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");
    printf("  Lock button : GPIO %d (press to lock)\n", LOCK_BUTTON);
    printf("  Unlock button: GPIO %d (press to unlock)\n", UNLOCK_BUTTON);
    printf("  Servo pin   : GPIO %d\n", SERVO_PIN);

    while (g_running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(LOCK_BUTTON) == 0) {
                if (set_servo_pulse(LOCK_PULSE_US) == 0) {
                    printf("Locking door...\n");
                }
                /* Wait for button release to avoid re-triggering. */
                while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                    gpioDelay(POLL_US);
                }
            }
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                if (set_servo_pulse(UNLOCK_PULSE_US) == 0) {
                    printf("Unlocking door...\n");
                }
                while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                    gpioDelay(POLL_US);
                }
            }
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    gpioTerminate();
    printf("Door lock control stopped.\n");
    return EXIT_SUCCESS;
}

