    int last_pir = gpioRead(PIR_PIN);
    if (last_pir < 0) {
        fprintf(stderr, "gpioRead(PIR_PIN) failed\n");
        cleanup();
        return 1;
    }

    while (g_running) {
        int pir = gpioRead(PIR_PIN);
        if (pir < 0) {
            fprintf(stderr, "gpioRead(PIR_PIN) failed\n");
            break;
        }

        /* Rising edge: 0 -> 1 */
        if (pir == 1 && last_pir == 0) {
            printf("Motion detected!\n");

            if (log_event("Motion detected") != 0) {
                fprintf(stderr, "Logging failed; turning off floodlight.\n");
                set_floodlight(0);
                break;
            }

            if (set_floodlight(1) != 0) {
                break;
            }

