#define MPR121_ADDR 0x5C
#define RELAY_GPIO 17
#define DEBOUNCE_MS 200
#define I2C_BUS "/dev/i2c-1"

#define MHD_RISING 0x01
#define NHD_RISING 0x01
#define NCL_RISING 0x00
#define FDL_RISING 0x00
#define MHD_FALLING 0x01
#define NHD_FALLING 0x01
#define NCL_FALLING 0x00
#define FDL_FALLING 0x00
#define DEBOUNCE 3
#define FFI 6
#define SFI 4
#define CDT 0x10
#define ELE0 0x00
#define ELE11 0x0B
#define ELE12 0x0C
#define ELE13 0x0D
#define ELE14 0x0E
#define ELE15 0x0F
#define ELE16 0x10
#define ELE17 0x11
#define ELE18 0x12
#define ELE19 0x13
#define ELE20 0x14
#define ELE21 0x15
#define ELE22 0x16
#define ELE23 0x17
#define ELE24 0x18
#define ELE25 0x19
#define ELE26 0x1A
#define ELE27 0x1B
#define ELE28 0x1C
#define ELE29 0x1D
#define ELE30 0x1E
#define ELE31 0x1F

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg8(fd, 0x80, 0x63) < 0) return -1;
    gpioDelay(1000);

    if (i2c_write_reg8(fd, 0x2B, MHD_RISING) < 0) return -1;
    if (i2c_write_reg8(fd, 0x2C, NHD_RISING) < 0) return -1;
    if (i2c_write_reg8(fd, 0x2D, NCL_RISING) < 0) return -1;
    if (i2c_write_reg8(fd, 0x2E, FDL_RISING) < 0) return -1;
    if (i2c_write_reg8(fd, 0x2F, MHD_FALLING) < 0) return -1;
    if (i2c_write_reg8(fd, 0x30, NHD_FALLING) < 0) return -1;
    if (i2c_write_reg8(fd, 0x31, NCL_FALLING) < 0) return -1;
    if (i2c_write_reg8(fd, 0x32, FDL_FALLING) < 0) return -1;

    if (i2c_write_reg8(fd, 0x33, DEBOUNCE) < 0) return -1;
    if (i2c_write_reg8(fd, 0x34, FFI) < 0) return -1;
    if (i2c_write_reg8(fd, 0x35, SFI) < 0) return -1;
    if (i2c_write_reg8(fd, 0x36, CDT) < 0) return -1;

    if (i2c_write_reg8(fd, 0x5E, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x5F, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x60, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x61, 0x00) < 0) return -1;

    if (i2c_write_reg8(fd, 0x5D, 0x0C) < 0) return -1;

    if (i2c_write_reg8(fd, 0x5B, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x5C, 0x01) < 0) return -1;

    return 0;
}

static int read_touch_data(int fd, uint16_t *touch_status) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, 0x00, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, 0x01, &hi) < 0) return -1;
    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void toggle_relay(void) {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
        fprintf(stderr, "Failed to write relay GPIO: %s\n", strerror(errno));
    } else {
        printf("Relay toggled to state: %d\n", relay_state);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    uint8_t whoami = 0;
    if (i2c_read_reg8(i2c_fd, 0x5C, &whoami) < 0) {
        fprintf(stderr, "MPR121 not responding on address 0x%02X\n", MPR121_ADDR);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("MPR121 initialized. Monitoring electrode 0...\n");

    uint16_t touch_status = 0;
    bool last_touched = false;
    uint32_t last_toggle_ms = 0;

    while (running) {
        if (read_touch_data(i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch data, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        bool currently_touched = (touch_status & (1 << ELE0)) != 0;

        if (currently_touched && !last_touched) {
            uint32_t now_ms = gpioTick() / 1000;
            if (now_ms - last_toggle_ms >= DEBOUNCE_MS) {
                toggle_relay();
                last_toggle_ms = now_ms;
            }
        }

        last_touched = currently_touched;
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

