        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        log_message(LOG_ERR, "Failed to set PIR_PIN %d as input", PIR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_WARNING, "Invalid servo angle: %d", angle);
        return;
    }

    int pulse_width = SERVO_MIN_PULSE + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
