#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR             0x23
#define BH1750_CONT_HIGH_RES    0x10
#define BH1750_MEAS_DELAY_US    120000
#define GROW_LIGHT_GPIO         23
#define LUX_THRESHOLD           150.0f
#define SAMPLE_INTERVAL_US      2000000
#define LOG_FILE_PATH           "grow_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure the grow light is off before terminating pigpio */
    gpioWrite(GROW_LIGHT_GPIO, 0);
    gpioTerminate();
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                BH1750_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void)
{
    if (gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GROW_LIGHT_GPIO);
        return -1;
    }
    if (gpioWrite(GROW_LIGHT_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing GPIO %d to LOW\n", GROW_LIGHT_GPIO);
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out)
{
    int rc;

    rc = i2cWriteByte(g_i2c_handle, BH1750_CONT_HIGH_RES);
    if (rc < 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", rc);
        return -1;
    }

    gpioDelay(BH1750_MEAS_DELAY_US);

    char buf[2];
    rc = i2cReadDevice(g_i2c_handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading 2 bytes from BH1750: %d\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(g_log_file, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    } else {
        fflush(g_log_file);
    }
}

static void control_grow_light(float lux)
{
    int level = (lux < LUX_THRESHOLD) ? 1 : 0;
    if (gpioWrite(GROW_LIGHT_GPIO, level) != 0) {
        fprintf(stderr, "Error writing GPIO %d\n", GROW_LIGHT_GPIO);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0 || init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_PATH, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_PATH);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow light controller started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux;
        if (read_lux(&lux) == 0) {
            log_data(lux);
            control_grow_light(lux);
            printf("Lux: %.2f  Grow Light: %s\n",
                   lux, (lux < LUX_THRESHOLD) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

