#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER      "localhost"
#define MQTT_PORT        1883
#define MQTT_CLIENT_ID   "relay_controller_1"
#define MQTT_TOPIC       "home/lights/control"
#define MQTT_KEEPALIVE   60
#define GPIO_PIN         17
#define LOOP_DELAY_US    1000000  /* 1 second */
#define RECONNECT_DELAY  5        /* seconds */
#define MAX_PAYLOAD      256

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialise GPIO%d LOW", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    syslog(LOG_INFO, "GPIO%d initialised and set LOW", GPIO_PIN);
    return 0;
}

static void gpio_set(int pin, int state)
{
    if (gpioWrite(pin, state) < 0)
        syslog(LOG_ERR, "Failed to write %d to GPIO%d", state, pin);
}

static void gpio_cleanup(void)
{
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *m, void *ud, int rc)
{
    (void)ud;
    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker at %s:%d",
               MQTT_BROKER, MQTT_PORT);
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS)
            syslog(LOG_ERR, "Failed to subscribe to %s", MQTT_TOPIC);
        else
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC);
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s",
               mosquitto_connack_string(rc));
    }
}

static void on_disconnect(struct mosquitto *m, void *ud, int rc)
{
    (void)m; (void)ud;
    if (rc == MOSQ_ERR_SUCCESS)
        syslog(LOG_INFO, "Disconnected cleanly from MQTT broker");
    else
        syslog(LOG_ERR, "Unexpected MQTT disconnect: %s",
               mosquitto_strerror(rc));
}

static void on_message(struct mosquitto *m, void *ud,
                        const struct mosquitto_message *msg)
{
    (void)m; (void)ud;
    if (msg->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty MQTT payload on topic %s", msg->topic);
        return;
    }
    if (msg->payloadlen >= MAX_PAYLOAD) {
        syslog(LOG_ERR, "Payload too large (%d bytes) on %s",
               msg->payloadlen, msg->topic);
        return;
    }

    char payload[MAX_PAYLOAD];
    memcpy(payload, msg->payload, msg->payloadlen);
    payload[msg->payloadlen] = '\0';

    syslog(LOG_INFO, "Received '%s' on topic %s", payload, msg->topic);

    if (strcmp(payload, "ON") == 0) {
        gpio_set(GPIO_PIN, 1);
        syslog(LOG_INFO, "Relay ON (GPIO%d HIGH)", GPIO_PIN);
    } else if (strcmp(payload, "OFF") == 0) {
        gpio_set(GPIO_PIN, 0);
        syslog(LOG_INFO, "Relay OFF (GPIO%d LOW)", GPIO_PIN);
    } else {
        syslog(LOG_ERR, "Invalid payload '%s' — expected ON or OFF",
               payload);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT setup                                                          */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "mosquitto_new failed: %s", strerror(errno));
        return -1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s",
               mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }
    return 0;
}

static void mqtt_cleanup(void)
{
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s",
               strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_init() != 0) {
        gpio_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Relay controller started (GPIO%d, topic %s)",
           GPIO_PIN, MQTT_TOPIC);

    while (running) {
        int rc = mosquitto_loop(mosq, LOOP_DELAY_US, 1);
        if (rc == MOSQ_ERR_SUCCESS)
            continue;

        if (rc == MOSQ_ERR_CONN_LOST || rc == MOSQ_ERR_NO_CONN) {
            syslog(LOG_WARNING, "MQTT connection lost, attempting reconnect");
            sleep(RECONNECT_DELAY);
            if (mosquitto_reconnect(mosq) != MOSQ_ERR_SUCCESS)
                syslog(LOG_ERR, "Reconnect failed, will retry");
            continue;
        }

        if (rc != MOSQ_ERR_CONN_REFUSED) {
            syslog(LOG_ERR, "mosquitto_loop error: %s",
                   mosquitto_strerror(rc));
        }
        sleep(RECONNECT_DELAY);
    }

    syslog(LOG_INFO, "Shutting down relay controller");
    mqtt_cleanup();
    gpio_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

