#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define TARGET_PULSE_WIDTH_1 1000
#define TARGET_PULSE_WIDTH_2 1500
#define TARGET_PULSE_WIDTH_3 2000
#define TARGET_PULSE_WIDTH_4 500
#define TARGET_PULSE_WIDTH_5 2500

#define SERVO_HOLD_TIME_MS 3000

int main() {
    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int target_pulse_widths[] = {
        TARGET_PULSE_WIDTH_1,
        TARGET_PULSE_WIDTH_2,
        TARGET_PULSE_WIDTH_3,
        TARGET_PULSE_WIDTH_4,
        TARGET_PULSE_WIDTH_5
    };
    int num_servos = sizeof(pins) / sizeof(pins[0]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_servos; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_servos; i++) {
        int pulse_width = target_pulse_widths[i];
        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Error: Pulse width %d for Servo %d out of range [%d, %d].\n",
                    pulse_width, i + 1, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioServo(pins[i], pulse_width) != 0) {
            fprintf(stderr, "Error: Failed to set servo pulse on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Servos moving to target positions...\n");
    gpioDelay(SERVO_HOLD_TIME_MS * 1000);

    for (int i = 0; i < num_servos; i++) {
        gpioServo(pins[i], 0);
    }

    gpioTerminate();
    printf("Servos stopped and GPIO cleaned up.\n");
    return EXIT_SUCCESS;
}

