#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <stdatomic.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM_PIN  17  /* DRV8833 IN1  */
#define MOTOR_A_DIR_PIN  18  /* DRV8833 IN2  */
#define MOTOR_B_PWM_PIN  22  /* DRV8833 IN3  */
#define MOTOR_B_DIR_PIN  23  /* DRV8833 IN4  */

#define ENCODER_A_PHASE_A 4
#define ENCODER_A_PHASE_B 5
#define ENCODER_B_PHASE_A 6
#define ENCODER_B_PHASE_B 12

/* ---- Motor parameters ---- */
#define TICKS_PER_REVOLUTION 64
#define GEAR_RATIO           1.0f
#define TARGET_RPM           50.0f

/* ---- PI controller gains ---- */
#define KP  0.5f
#define KI  0.1f

/* ---- PWM configuration ---- */
#define PWM_FREQUENCY       10000   /* 10 kHz */
#define PWM_RANGE           255

/* ---- Control loop ---- */
#define LOOP_PERIOD_US      100000  /* 100 ms */

/* ---- Stall detection ---- */
#define STALL_TIMEOUT_S     2.0f

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;

static atomic_int g_encoder_a_ticks;
static atomic_int g_encoder_b_ticks;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void set_motor_a_speed(int speed);
static void set_motor_b_speed(int speed);
static void stop_motors(void);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure motor control pins */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure encoder input pins */
    if (gpioSetMode(ENCODER_A_PHASE_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_PHASE_B, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_PHASE_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_PHASE_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set encoder pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups on encoder pins (open-collector style) */
    gpioSetPullUpDown(ENCODER_A_PHASE_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_PHASE_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PHASE_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PHASE_B, PI_PUD_UP);

    /* Set PWM frequency and range for both motor PWM pins */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register encoder ISRs on rising edge */
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_A, RISING_EDGE, 0,
                         encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR for Encoder A.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_A, RISING_EDGE, 0,
                         encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR for Encoder B.\n");
        gpioSetISRFuncEx(ENCODER_A_PHASE_A, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize tick counters */
    atomic_store(&g_encoder_a_ticks, 0);
    atomic_store(&g_encoder_b_ticks, 0);

    /* Start with motors stopped */
    stop_motors();

    printf("Motor control started. Target RPM: %.1f\n", TARGET_RPM);
    printf("Press Ctrl+C to exit.\n");

    /* Main control loop */
    while (g_running) {
        /* Read current tick counts */
        int a_ticks = atomic_load(&g_encoder_a_ticks);
        int b_ticks = atomic_load(&g_encoder_b_ticks);

        /* Compute RPM from ticks over the 100 ms loop period */
        float a_rpm = ((float)a_ticks / TICKS_PER_REVOLUTION) *
                      (60.0f / (LOOP_PERIOD_US / 1000000.0f)) / GEAR_RATIO;
        float b_rpm = ((float)b_ticks / TICKS_PER_REVOLUTION) *
                      (60.0f / (LOOP_PERIOD_US / 1000000.0f)) / GEAR_RATIO;

        /* PI control for Motor A */
        float a_error = TARGET_RPM - a_rpm;
        static float a_integral = 0.0f;
        a_integral += a_error * (LOOP_PERIOD_US / 1000000.0f);
        float a_output = KP * a_error + KI * a_integral;
        int a_pwm = (int)(a_output * 10.0f);  /* scale to 0-255 */

        /* Anti-windup: clamp integral when saturated */
        if (a_pwm > PWM_RANGE) {
            a_pwm = PWM_RANGE;
            a_integral = (a_integral > 0) ? (PWM_RANGE / (KP * 10.0f)) : a_integral;
        } else if (a_pwm < 0) {
            a_pwm = 0;
            a_integral = (a_integral < 0) ? (-PWM_RANGE / (KP * 10.0f)) : a_integral;
        }

        /* PI control for Motor B */
        float b_error = TARGET_RPM - b_rpm;
        static float b_integral = 0.0f;
        b_integral += b_error * (LOOP_PERIOD_US / 1000000.0f);
        float b_output = KP * b_error + KI * b_integral;
        int b_pwm = (int)(b_output * 10.0f);

        if (b_pwm > PWM_RANGE) {
            b_pwm = PWM_RANGE;
            b_integral = (b_integral > 0) ? (PWM_RANGE / (KP * 10.0f)) : b_integral;
        } else if (b_pwm < 0) {
            b_pwm = 0;
            b_integral = (b_integral < 0) ? (-PWM_RANGE / (KP * 10.0f)) : b_integral;
        }

        /* Drive motors (forward: IN2=1, PWM on IN1) */
        set_motor_a_speed(a_pwm);
        set_motor_b_speed(b_pwm);

        /* Stall detection: if no ticks in 2 seconds, warn */
        if (a_ticks == 0 && b_ticks == 0) {
            static uint32_t stall_start = 0;
            if (stall_start == 0) {
                stall_start = gpioTick();
            } else if ((float)(gpioTick() - stall_start) / 1000000.0f > STALL_TIMEOUT_S) {
                fprintf(stderr, "Warning: potential stall detected (no encoder ticks for %.1f s).\n",
                        STALL_TIMEOUT_S);
                stall_start = 0;  /* reset to avoid repeated spam */
            }
        } else {
            stall_start = 0;
        }

        /* Print status */
        printf("Motor A: RPM=%.1f, PWM=%d | Motor B: RPM=%.1f, PWM=%d\n",
               a_rpm, a_pwm, b_rpm, b_pwm);

        /* Sleep for the remainder of the loop period */
        gpioDelay(LOOP_PERIOD_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    stop_motors();
    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    atomic_fetch_add(&g_encoder_a_ticks, 1);
}

/* ------------------------------------------------------------------ */
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    atomic_fetch_add(&g_encoder_b_ticks, 1);
}

/* ------------------------------------------------------------------ */
static void set_motor_a_speed(int speed)
{
    if (speed > 0) {
        gpioWrite(MOTOR_A_DIR_PIN, 1);   /* forward */
        gpioPWM(MOTOR_A_PWM_PIN, speed);
    } else if (speed < 0) {
        gpioWrite(MOTOR_A_DIR_PIN, 0);   /* reverse */
        gpioPWM(MOTOR_A_PWM_PIN, -speed);
    } else {
        gpioWrite(MOTOR_A_DIR_PIN, 0);
        gpioPWM(MOTOR_A_PWM_PIN, 0);
    }
}

/* ------------------------------------------------------------------ */
static void set_motor_b_speed(int speed)
{
    if (speed > 0) {
        gpioWrite(MOTOR_B_DIR_PIN, 1);   /* forward */
        gpioPWM(MOTOR_B_PWM_PIN, speed);
    } else if (speed < 0) {
        gpioWrite(MOTOR_B_DIR_PIN, 0);   /* reverse */
        gpioPWM(MOTOR_B_PWM_PIN, -speed);
    } else {
        gpioWrite(MOTOR_B_DIR_PIN, 0);
        gpioPWM(MOTOR_B_PWM_PIN, 0);
    }
}

/* ------------------------------------------------------------------ */
static void stop_motors(void)
{
    gpioWrite(MOTOR_A_DIR_PIN, 0);
    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioWrite(MOTOR_B_DIR_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, 0);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable ISRs */
    gpioSetISRFuncEx(ENCODER_A_PHASE_A, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENCODER_B_PHASE_A, RISING_EDGE, 0, NULL, NULL);

    /* Stop motors */
    stop_motors();

    /* Release pigpio */
    gpioTerminate();
}

