#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define BH1750_CMD_CONT_HIGH_RES 0x10
#define GPIO_RELAY 17
#define LUX_THRESHOLD_DUSK 50.0
#define LUX_THRESHOLD_DAWN 200.0
#define POLL_INTERVAL_SEC 5
#define BH1750_MEAS_DELAY_US 180000
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int read_bh1750(float *lux_out) {
    if (i2cWriteByte(i2c_handle, BH1750_CMD_CONT_HIGH_RES) < 0) {
        log_event("Error: failed to write measurement command to BH1750");
        return -1;
    }
    gpioDelay(BH1750_MEAS_DELAY_US);
    int raw = i2cReadWordData(i2c_handle, 0);
    if (raw < 0) {
        log_event("Error: failed to read data from BH1750");
        return -1;
    }
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_RELAY);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_RELAY, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    int relay_state = 0;
    while (running) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux = %.2f, Relay = %s", lux, relay_state ? "ON" : "OFF");
            log_event(msg);

            if (!relay_state && lux < LUX_THRESHOLD_DUSK) {
                if (gpioWrite(GPIO_RELAY, 1) == 0) {
                    relay_state = 1;
                    log_event("Relay activated");
                } else {
                    log_event("Error: failed to activate relay");
                }
            } else if (relay_state && lux > LUX_THRESHOLD_DAWN) {
                if (gpioWrite(GPIO_RELAY, 0) == 0) {
                    relay_state = 0;
                    log_event("Relay deactivated");
                } else {
                    log_event("Error: failed to deactivate relay");
                }
            }
        } else {
            log_event("Error: BH1750 read failed, turning off relay for safety");
            if (relay_state) {
                gpioWrite(GPIO_RELAY, 0);
                relay_state = 0;
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

