#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    printf("[%s] Relay is now: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void) {
    int relay_state = 0;
    int last_touch_state = 0;
    int current_touch_state = 0;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set touch sensor pin %d as input (code %d)\n", TOUCH_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set relay pin %d as output (code %d)\n", RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to initialise relay pin %d to LOW (code %d)\n", RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    relay_state = 0;
    log_relay_state(relay_state);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler\n");
    }

    while (running) {
        last_touch_state = current_touch_state;
        current_touch_state = gpioRead(TOUCH_SENSOR_PIN);

        if (current_touch_state < 0) {
            fprintf(stderr, "Error: failed to read touch sensor pin %d (code %d)\n", TOUCH_SENSOR_PIN, current_touch_state);
            break;
        }

        if (current_touch_state == 1 && last_touch_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);

            int debounced_state = gpioRead(TOUCH_SENSOR_PIN);
            if (debounced_state < 0) {
                fprintf(stderr, "Error: failed to read touch sensor pin %d during debounce (code %d)\n", TOUCH_SENSOR_PIN, debounced_state);
                break;
            }

            if (debounced_state == 1) {
                relay_state = !relay_state;
                ret = gpioWrite(RELAY_PIN, relay_state);
                if (ret != 0) {
                    fprintf(stderr, "Error: failed to write relay pin %d (code %d)\n", RELAY_PIN, ret);
                    break;
                }
                log_relay_state(relay_state);

                while (running) {
                    int sensor_val = gpioRead(TOUCH_SENSOR_PIN);
                    if (sensor_val < 0) {
                        fprintf(stderr, "Error: failed to read touch sensor pin %d (code %d)\n", TOUCH_SENSOR_PIN, sensor_val);
                        running = 0;
                        break;
                    }
                    if (sensor_val == 0) {
                        break;
                    }
                    gpioDelay(LOOP_DELAY_US);
                }
            }
        }

        if (running) {
            gpioDelay(LOOP_DELAY_US);
        }
    }

    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Warning: failed to turn off relay pin %d during shutdown (code %d)\n", RELAY_PIN, ret);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

