#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO    27
#define FLOW_THRESHOLD_HIGH 5.0
#define FLOW_THRESHOLD_LOW  4.5
#define PULSE_TO_LITER      7.5
#define DEBOUNCE_US         1000000
#define SAMPLE_INTERVAL_US  1000000
#define LOG_FILE_NAME       "water_flow.log"

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *g_log_file = NULL;

static void log_message(const char *message) {
    if (g_log_file == NULL) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(g_log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;
    if (diff > DEBOUNCE_US) {
        pthread_mutex_lock(&g_mutex);
        g_pulse_count++;
        pthread_mutex_unlock(&g_mutex);
        last_tick = tick;
    }
}

static int control_solenoid(int state) {
    if (gpioWrite(SOLENOID_GPIO, state) != 0) {
        log_message("Error: Failed to write solenoid GPIO");
        return -1;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Solenoid set to %s", state ? "OPEN" : "CLOSED");
    log_message(msg);
    return 0;
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        log_message("Shutting down water flow monitor");
        fclose(g_log_file);
        g_log_file = NULL;
    }
    control_solenoid(1);
    gpioTerminate();
    pthread_mutex_destroy(&g_mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set flow sensor GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set solenoid GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on flow sensor GPIO\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR for flow sensor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (control_solenoid(1) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Water flow monitor started");

    while (g_running) {
        uint32_t local_count = 0;
        pthread_mutex_lock(&g_mutex);
        local_count = g_pulse_count;
        g_pulse_count = 0;
        pthread_mutex_unlock(&g_mutex);

        double liters = (double)local_count / PULSE_TO_LITER;
        double lpm = liters * 60.0;
        char msg[128];
        snprintf(msg, sizeof(msg), "Flow: %.2f LPM (pulses: %u)", lpm, local_count);
        log_message(msg);

        if (lpm > FLOW_THRESHOLD_HIGH) {
            control_solenoid(0);
        } else if (lpm < FLOW_THRESHOLD_LOW) {
            control_solenoid(1);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

