#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN  24
#define SERVO_PIN      18
#define DEFAULT_PORT   12345
#define DEFAULT_IP     "127.0.0.1"
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_KNOWN_WEIGHT 100.0
#define DEFAULT_TARGET_WEIGHT 50.0
#define DEFAULT_ACTUAL_WEIGHT 50.0
#define DEFAULT_ERROR_MSG "No error"
#define DEFAULT_LOG_FILE "dispensing_log.json"
#define DEFAULT_CONFIG_FILE "config.ini"
#define HX711_TIMEOUT_ATTEMPTS 1000
#define HX711_SETTLE_DELAY_US 1000000
#define SERVO_MIN_PULSE_US 1000
#define SERVO_MAX_PULSE_US 2000
#define SERVO_SETTLE_DELAY_US 500000
#define API_SETTLE_DELAY_US 1000000
#define API_MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, double *calibration_factor, double *known_weight) {
    *calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    *known_weight = DEFAULT_KNOWN_WEIGHT;
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s. Using defaults.\n", filename, strerror(errno));
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char key[128], value[128];
        if (sscanf(line, " %127[^=]=%127s", key, value) == 2) {
            if (strcmp(key, "calibration_factor") == 0) {
                *calibration_factor = atof(value);
            } else if (strcmp(key, "known_weight") == 0) {
                *known_weight = atof(value);
            }
        }
    }
    fclose(fp);
    return 0;
}

static int read_hx711(int *value) {
    int data = 0;
    int attempts = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (++attempts >= HX711_TIMEOUT_ATTEMPTS) {
            fprintf(stderr, "Error: HX711 timeout waiting for DATA pin to go LOW.\n");
            return -1;
        }
        gpioDelay(100);
    }
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data = (data << 1) | (gpioRead(HX711_DATA_PIN) & 1);
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }
    *value = data;
    return 0;
}

static double calibrate_weight(int raw_value, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

static int set_servo_pulse(int pulse_width_us) {
    if (pulse_width_us < SERVO_MIN_PULSE_US || pulse_width_us > SERVO_MAX_PULSE_US) {
        fprintf(stderr, "Error: Invalid servo pulse width: %d us\n", pulse_width_us);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_width_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed: %s\n", pigpio_error(gpioGetMode(SERVO_PIN)));
        return -1;
    }
    return 0;
}

static int api_dispense(double target_weight) {
    int pulse_width_us = (int)(SERVO_MIN_PULSE_US + (target_weight / 100.0) * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));
    if (pulse_width_us < SERVO_MIN_PULSE_US) pulse_width_us = SERVO_MIN_PULSE_US;
    if (pulse_width_us > SERVO_MAX_PULSE_US) pulse_width_us = SERVO_MAX_PULSE_US;
    if (set_servo_pulse(pulse_width_us) != 0) return -1;
    gpioDelay(API_SETTLE_DELAY_US);
    return 0;
}

static int log_event(const char *timestamp, double target_weight, double actual_weight, const char *error_msg) {
    if (!log_file) {
        fprintf(stderr, "Error: Log file not open.\n");
        return -1;
    }
    fprintf(log_file, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_msg\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_msg);
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (client_fd >= 0) { close(client_fd); client_fd = -1; }
    if (server_fd >= 0) { close(server_fd); server_fd = -1; }
    if (log_file) { fclose(log_file); log_file = NULL; }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);

    double calibration_factor, known_weight;
    read_config(DEFAULT_CONFIG_FILE, &calibration_factor, &known_weight);
    printf("Calibration factor: %.4f, Known weight: %.2f g\n", calibration_factor, known_weight);

    log_file = fopen(DEFAULT_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", DEFAULT_LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Error: socket creation failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "Warning: setsockopt failed: %s\n", strerror(errno));
    }
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = inet_addr(DEFAULT_IP);
    address.sin_port = htons(DEFAULT_PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Error: bind failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Error: listen failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    printf("Listening on %s:%d...\n", DEFAULT_IP, DEFAULT_PORT);

    while (running) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (running && errno != EINTR) fprintf(stderr, "Error: accept failed: %s\n", strerror(errno));
            continue;
        }
        char buffer[1024];
        memset(buffer, 0, sizeof(buffer));
        ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            fprintf(stderr, "Error: recv failed: %s\n", strerror(errno));
            close(client_fd);
            client_fd = -1;
            continue;
        }
        if (bytes_received == 0) {
            printf("Client disconnected.\n");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        buffer[bytes_received] = '\0';
        double target_weight = DEFAULT_TARGET_WEIGHT;
        if (sscanf(buffer, "%lf", &target_weight) != 1) {
            fprintf(stderr, "Error: Invalid target weight received: %s\n", buffer);
            target_weight = DEFAULT_TARGET_WEIGHT;
        }
        printf("Target weight: %.2f g\n", target_weight);

        int raw_value = 0;
        if (read_hx711(&raw_value) != 0) {
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            log_event(timestamp, target_weight, DEFAULT_ACTUAL_WEIGHT, "HX711 read timeout");
            const char *err_msg = "HX711 read timeout";
            char response[256];
            snprintf(response, sizeof(response), "Error: %s\n", err_msg);
            send(client_fd, response, strlen(response), 0);
            close(client_fd);
            client_fd = -1;
            continue;
        }
        double actual_weight = calibrate_weight(raw_value, calibration_factor);
        printf("Raw value: %d, Actual weight: %.2f g\n", raw_value, actual_weight);

        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        int api_result = -1;
        for (int attempt = 0; attempt < API_MAX_RETRIES; attempt++) {
            if (api_dispense(target_weight) == 0) {
                api_result = 0;
                break;
            }
            fprintf(stderr, "API dispense attempt %d failed.\n", attempt + 1);
            gpioDelay(100000);
        }
        if (api_result != 0) {
            log_event(timestamp, target_weight, actual_weight, "API dispense failed");
            const char *err_msg = "API dispense failed";
            char response[256];
            snprintf(response, sizeof(response), "Error: %s\n", err_msg);
            send(client_fd, response, strlen(response), 0);
            close(client_fd);
            client_fd = -1;
            continue;
        }

        gpioDelay(SERVO_SETTLE_DELAY_US);
        if (read_hx711(&raw_value) != 0) {
            fprintf(stderr, "Error: HX711 read timeout after dispensing.\n");
            log_event(timestamp, target_weight, DEFAULT_ACTUAL_WEIGHT, "HX711 read timeout after dispensing");
            const char *err_msg = "HX711 read timeout after dispensing";
            char response[256];
            snprintf(response, sizeof(response), "Error: %s\n", err_msg);
            send(client_fd, response, strlen(response), 0);
            close(client_fd);
            client_fd = -1;
            continue;
        }
        actual_weight = calibrate_weight(raw_value, calibration_factor);
        printf("Post-dispense raw value: %d, Actual weight: %.2f g\n", raw_value, actual_weight);

        log_event(timestamp, target_weight, actual_weight, DEFAULT_ERROR_MSG);
        char response[256];
        snprintf(response, sizeof(response), "Actual weight: %.2f g\n", actual_weight);
        send(client_fd, response, strlen(response), 0);

        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

