#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEFAULT_DEBOUNCE_MS;
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_ms = atoi(optarg);
                if (debounce_ms <= 0) {
                    fprintf(stderr, "Error: debounce interval must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set touch sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_touch_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_touch_state < 0) {
        fprintf(stderr, "Error: failed to read initial touch sensor state\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;

    while (running) {
        int current_touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_touch_state < 0) {
            fprintf(stderr, "Error: failed to read touch sensor\n");
            break;
        }

        if (current_touch_state == 1 && last_touch_state == 0) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                fprintf(stderr, "Error: failed to write relay pin\n");
                break;
            }
            log_relay_state(relay_state);
            gpioDelay(debounce_ms * 1000);
        }

        last_touch_state = current_touch_state;
        gpioDelay(10000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

