#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18          /* BCM 18, physical pin 12 */
#define SERVO_MIN_PULSE 500        /* microseconds  */
#define SERVO_MAX_PULSE 2500       /* microseconds  */
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define SERVO_CENTER_ANGLE 90
#define SERVO_CENTER_PULSE 1500    /* 1500 us at 50 Hz -> 90 degrees */
#define ANGLE_STEP       10
#define PWM_FREQ         50         /* Hz -> 20 ms period */
#define POLL_DELAY_US    10000      /* 10 ms */

static volatile sig_atomic_t g_running = 1;
static struct termios g_orig_termios;

/* ------------------------------------------------------------------ */
/* Restore terminal settings to their original state.                 */
/* ------------------------------------------------------------------ */
static void restore_terminal(void)
{
    if (tcsetattr(STDIN_FILENO, TCSANOW, &g_orig_termios) == -1)
        perror("tcsetattr");
}

/* ------------------------------------------------------------------ */
/* Signal handler for SIGINT / SIGTERM — set flag so main loop exits.  */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Compute pulse width in microseconds for a given angle.             */
/* Returns -1 if the angle is out of range.                            */
/* ------------------------------------------------------------------ */
static int angle_to_pulse(int angle)
{
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE)
        return -1;

    /* Linear interpolation: 0 deg -> 500 us, 180 deg -> 2500 us */
    return SERVO_MIN_PULSE +
           (int)((long)(angle - SERVO_MIN_ANGLE) *
                 (SERVO_MAX_PULSE - SERVO_MIN_PULSE) /
                 (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE));
}

/* ------------------------------------------------------------------ */
/* Set servo pulse width and print any error.                          */
/* ------------------------------------------------------------------ */
static int set_servo_pulse(int pulse_us)
{
    int rc = gpioServo(SERVO_PIN, pulse_us);
    if (rc < 0) {
        fprintf(stderr, "gpioServo failed (rc=%d): %s\n",
                rc, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single raw keypress (blocking, no echo, no buffering).       */
/* Returns the ASCII code, or -1 on EOF / error.                       */
/* ------------------------------------------------------------------ */
static int read_key(void)
{
    int c = getchar();
    if (c == EOF)
        return -1;
    return c;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int angle = SERVO_CENTER_ANGLE;
    int pulse_us;
    int c;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Save and switch terminal to raw mode ---- */
    if (tcgetattr(STDIN_FILENO, &g_orig_termios) == -1) {
        perror("tcgetattr");
        return EXIT_FAILURE;
    }

    struct termios raw = g_orig_termios;
    raw.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL);
    raw.c_cc[VMIN]  = 1;
    raw.c_cc[VTIME] = 0;

    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) == -1) {
        perror("tcsetattr");
        restore_terminal();
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        restore_terminal();
        return EXIT_FAILURE;
    }

    /* ---- Center the servo at startup ---- */
    pulse_us = angle_to_pulse(angle);
    if (pulse_us < 0) {
        fprintf(stderr, "Initial angle %d out of range\n", angle);
        gpioServo(SERVO_PIN, 0);   /* stop pulses */
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_pulse(pulse_us) != 0) {
        gpioServo(SERVO_PIN, 0);
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo control started.  Pin %d, freq %d Hz.\n", SERVO_PIN, PWM_FREQ);
    printf("Press '+' to increase angle by %d degrees, '-' to decrease.\n", ANGLE_STEP);
    printf("Press 'q' to quit.\n");
    fflush(stdout);

    /* ---- Main input loop ---- */
    while (g_running) {
        c = read_key();

        if (c == '+') {
            angle += ANGLE_STEP;
            if (angle > SERVO_MAX_ANGLE)
                angle = SERVO_MAX_ANGLE;
        } else if (c == '-') {
            angle -= ANGLE_STEP;
            if (angle < SERVO_MIN_ANGLE)
                angle = SERVO_MIN_ANGLE;
        } else if (c == 'q') {
            break;
        } else if (c == EOF) {
            /* EOF (Ctrl-D) — treat as quit */
            break;
        } else {
            /* Ignore any other key */
            continue;
        }

        pulse_us = angle_to_pulse(angle);
        if (pulse_us < 0) {
            fprintf(stderr, "Angle %d out of range\n", angle);
            continue;
        }

        if (set_servo_pulse(pulse_us) != 0) {
            break;
        }

        printf("Angle: %d degrees\n", angle);
        fflush(stdout);
    }

    /* ---- Cleanup ---- */
    gpioServo(SERVO_PIN, 0);   /* stop PWM pulses */
    restore_terminal();
    gpioTerminate();

    printf("\nServo stopped. Goodbye.\n");
    return EXIT_SUCCESS;
}

