    struct termios raw = g_orig_termios;
    raw.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL);
    raw.c_cc[VMIN]  = 1;
    raw.c_cc[VTIME] = 0;

    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) == -1) {
        perror("tcsetattr");
        restore_terminal();
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        restore_terminal();
        return EXIT_FAILURE;
    }

    /* ---- Center the servo at startup ---- */
    pulse_us = angle_to_pulse(angle);
    if (pulse_us < 0) {
        fprintf(stderr, "Initial angle %d out of range\n", angle);
        gpioServo(SERVO_PIN, 0);   /* stop pulses */
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_pulse(pulse_us) != 0) {
        gpioServo(SERVO_PIN, 0);
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo control started.  Pin %d, freq %d Hz.\n", SERVO_PIN, PWM_FREQ);
    printf("Press '+' to increase angle by %d degrees, '-' to decrease.\n", ANGLE_STEP);
    printf("Press 'q' to quit.\n");
    fflush(stdout);

    /* ---- Main input loop ---- */
    while (g_running) {
        c = read_key();

        if (c == '+') {
            angle += ANGLE_STEP;
            if (angle > SERVO_MAX_ANGLE)
                angle = SERVO_MAX_ANGLE;
        } else if (c == '-') {
            angle -= ANGLE_STEP;
            if (angle < SERVO_MIN_ANGLE)
                angle = SERVO_MIN_ANGLE;
        } else if (c == 'q') {
            break;
        } else if (c == EOF) {
            /* EOF (Ctrl-D) — treat as quit */
            break;
        } else {
            /* Ignore any other key */
            continue;
        }

        pulse_us = angle_to_pulse(angle);
        if (pulse_us < 0) {
            fprintf(stderr, "Angle %d out of range\n", angle);
            continue;
        }

        if (set_servo_pulse(pulse_us) != 0) {
            break;
        }

        printf("Angle: %d degrees\n", angle);
        fflush(stdout);
    }

    /* ---- Cleanup ---- */
    gpioServo(SERVO_PIN, 0);   /* stop PWM pulses */
    restore_terminal();
    gpioTerminate();

    printf("\nServo stopped. Goodbye.\n");
    return EXIT_SUCCESS;
}

