#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN        17
#define DEBOUNCE_US     2000   /* 2 ms debounce window */
#define SAMPLE_PERIOD_S 5      /* RPM sampling interval */
#define LOG_FILE        "motor_rpm.log"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — called on every edge of GPIO_PIN            */
/* ------------------------------------------------------------------ */
static void hall_sensor_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    static uint32_t last_tick = 0;
    static int      have_last = 0;

    if (level != 1)            /* only rising edges */
        return;

    uint32_t diff;
    if (have_last) {
        diff = tick - last_tick;   /* pigpio tick wraps every ~72 min */
    } else {
        diff = DEBOUNCE_US + 1;   /* force first pulse to be ignored */
        have_last = 1;
    }

    if (diff < DEBOUNCE_US)     /* within debounce window — ignore */
        return;

    last_tick = tick;
}

/* ------------------------------------------------------------------ */
/* Compute RPM from a monotonic timestamp and a pulse count           */
/* ------------------------------------------------------------------ */
static double calculate_rpm(const struct timespec *now,
                            const struct timespec *last,
                            unsigned long pulses)
{
    double dt = (double)(now->tv_sec - last->tv_sec)
              + (double)(now->tv_nsec - last->tv_nsec) / 1e9;
    if (dt <= 0.0)
        return 0.0;

    /* Two-pole magnet: one pulse per revolution */
    return (double)pulses / dt * 60.0;
}

/* ------------------------------------------------------------------ */
/* Write one CSV line: timestamp,RPM\n                                */
/* ------------------------------------------------------------------ */
static int log_rpm(double rpm)
{
    if (g_log_fp == NULL)
        return -1;

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (tm_info == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO 17 as input with pull-up ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", GPIO_PIN);
        goto cleanup_gpio;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", GPIO_PIN);
        goto cleanup_gpio;
    }

    /* ---- Register alert callback for rising-edge detection ---- */
    if (gpioSetAlertFunc(GPIO_PIN, hall_sensor_callback) != 0) {
        fprintf(stderr, "gpioSetAlertFunc(%d) failed\n", GPIO_PIN);
        goto cleanup_gpio;
    }

    printf("Monitoring motor RPM on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_PIN);

    /* ---- Main sampling loop ---- */
    struct timespec last_ts;
    clock_gettime(CLOCK_MONOTONIC, &last_ts);

    unsigned long pulse_count = 0;

    while (g_running) {
        struct timespec now_ts;
        clock_gettime(CLOCK_MONOTONIC, &now_ts);

        double rpm = calculate_rpm(&now_ts, &last_ts, pulse_count);

        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Logging failed — continuing.\n");
        }

        printf("RPM: %.2f\n", rpm);

        /* Reset counters for the next interval */
        pulse_count = 0;
        last_ts = now_ts;

        /* Sleep for the sampling period, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++)
            gpioDelay(1000000);   /* 1 s */
    }

    printf("\nShutting down...\n");

    /* ---- Cleanup ---- */
    gpioSetAlertFunc(GPIO_PIN, NULL);   /* unregister callback */
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_OFF);
    gpioSetMode(GPIO_PIN, PI_INPUT);

cleanup_gpio:
    gpioTerminate();

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    return EXIT_SUCCESS;
}

