#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_DELAY_US 50000   /* 50 ms */
#define STUCK_TIMEOUT_S 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin %d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay pin %d to OFF\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort: ensure relay is OFF before terminating */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_touch = 0;
    time_t touch_start = 0;
    int stuck_active = 0;

    while (g_running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            fprintf(stderr, "gpioRead failed on pin %d (PI_BAD_GPIO)\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch == 1 && last_touch == 0) {
            /* Rising edge: toggle relay */
            relay_state = !relay_state;
            if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                fprintf(stderr, "gpioWrite failed on pin %d\n", RELAY_PIN);
                break;
            }
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        if (touch == 1) {
            if (touch_start == 0) {
                touch_start = time(NULL);
            } else if (!stuck_active && (time(NULL) - touch_start) > STUCK_TIMEOUT_S) {
                /* Sensor stuck HIGH for >10 s: force relay OFF */
                if (relay_state != 0) {
                    relay_state = 0;
                    if (gpioWrite(RELAY_PIN, 0) != 0) {
                        fprintf(stderr, "gpioWrite failed on pin %d\n", RELAY_PIN);
                        break;
                    }
                    printf("Sensor stuck HIGH for >%d s; relay forced OFF\n", STUCK_TIMEOUT_S);
                }
                stuck_active = 1;
            }
        } else {
            /* Sensor released: reset timers */
            touch_start = 0;
            stuck_active = 0;
        }

        last_touch = touch;
        gpioDelay(POLL_DELAY_US);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

