#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_RANGE          255
#define SAMPLE_PERIOD_US   100000  /* 100 ms */
#define KP                 1.0f

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static FILE                 *g_log_file = NULL;
static float                 g_target_flow = 0.0f;

/* ------------------------------------------------------------------ */
/* ISR: increment pulse count on each rising edge from the flow sensor */
/* ------------------------------------------------------------------ */
static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_pulse_count++;
}

/* ------------------------------------------------------------------ */
/* Signal handler: request graceful shutdown                           */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup: release all resources                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM and disable valve */
    if (gpioInitialise() >= 0) {
        gpioPWM(VALVE_PWM_PIN, 0);
        gpioWrite(VALVE_ENABLE_PIN, 0);
    }

    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Compute proportional control output (0-255)                         */
/* ------------------------------------------------------------------ */
static int compute_pwm(float flow_rate)
{
    float error = g_target_flow - flow_rate;
    float pwm = KP * error;

    if (pwm < 0.0f)   pwm = 0.0f;
    if (pwm > (float)PWM_RANGE) pwm = (float)PWM_RANGE;

    return (int)(pwm + 0.5f);
}

/* ------------------------------------------------------------------ */
/* Log one CSV row                                                     */
/* ------------------------------------------------------------------ */
static void log_data(float flow_rate, int valve_position)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long long timestamp_ms = (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;

