#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_1_PIN      17
#define LOCK_2_PIN      27
#define BUTTON_PIN      22
#define LOG_FILE        "/var/log/door_access.log"
#define DEBOUNCE_US     50000   /* 50 ms */
#define UNLOCK_DURATION 5       /* seconds */
#define POLL_DELAY_US   100000  /* 100 ms */
#define MAX_SPI_RETRIES 4

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging helper                                                      */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    if (!g_log)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(g_log, "%s - %s\n", ts, event);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Lock helpers                                                        */
/* ------------------------------------------------------------------ */
static void lock_engage(int pin)
{
    if (gpioWrite(pin, 1) < 0)
        log_event("ERROR: gpioWrite(engage) failed");
}

static void lock_disengage(int pin)
{
    if (gpioWrite(pin, 0) < 0)
        log_event("ERROR: gpioWrite(disengage) failed");
}

static void all_locks_engaged(void)
{
    lock_engage(LOCK_1_PIN);
    lock_engage(LOCK_2_PIN);
}

/* ------------------------------------------------------------------ */
/* Button press detection with debounce                                */
/* ------------------------------------------------------------------ */
static int button_pressed(void)
{
    static uint32_t last_press_tick = 0;
    static int      last_state      = 1;   /* HIGH = released */

    int level = gpioRead(BUTTON_PIN);
    if (level < 0) {
        log_event("ERROR: gpioRead(button) failed");
        return 0;
    }

    if (level == 0 && last_state == 1) {
        uint32_t now = gpioTick();
        if (now - last_press_tick > DEBOUNCE_US) {
            last_press_tick = now;
            return 1;
        }
    }
    last_state = level;
    return 0;
}

/* ------------------------------------------------------------------ */
/* RFID reader — non-blocking poll                                     */
/* ------------------------------------------------------------------ */
static int rfid_read(unsigned char *tag)
{
    int  bytes_read = 0;
    int  attempt;
    int  rc;

    for (attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        rc = spiRead(0, (char *)tag, 10);
        if (rc == 10) {
            bytes_read = 10;
            break;
        }
        if (rc < 0) {
            log_event("ERROR: SPI read failed");
            gpioDelay(1000);
            continue;
        }
        /* rc == 0 means no tag present — not an error */
        bytes_read = 0;
        break;
    }
    return bytes_read;
}

/* ------------------------------------------------------------------ */
/* Tag validation                                                      */
/* ------------------------------------------------------------------ */
static int validate_tag(const unsigned char *tag)
{
    static const unsigned char valid_tag[10] = {
        0x01, 0x02, 0x03, 0x04, 0x05,
        0x06, 0x07, 0x08, 0x09, 0x0A
    };
    return (memcmp(tag, valid_tag, 10) == 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    unsigned char tag[10];
    int            tag_bytes;
    int            button;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(LOCK_1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK_2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BUTTON_PIN, PI_INPUT)  < 0)
    {
        fprintf(stderr, "GPIO mode configuration failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    /* Engage locks at startup */
    all_locks_engaged();

    /* ---- SPI init (channel 0, 100 kHz) ---- */
    if (spiOpen(0, 100000, 0) < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        all_locks_engaged();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen log");
        spiClose(0);
        all_locks_engaged();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Door access control started");

    /* ---- Main loop ---- */
    while (g_running) {
        tag_bytes = rfid_read(tag);

        if (tag_bytes == 10) {
            if (validate_tag(tag)) {
                log_event("Valid RFID tag detected");

                button = button_pressed();
                if (button) {
                    log_event("Button pressed — unlocking");

                    lock_disengage(LOCK_1_PIN);
                    lock_disengage(LOCK_2_PIN);

                    /* Hold unlocked for 5 s, checking for shutdown */
                    for (int i = 0; i < UNLOCK_DURATION * 10 && g_running; i++)
                        gpioDelay(100000);

                    all_locks_engaged();
                    log_event("Locks re-engaged");
                } else {
                    log_event("Button press required after valid tag");
                }
            } else {
                log_event("Invalid RFID tag");
            }
        } else if (tag_bytes == 0) {
            /* No tag present — normal, just poll again */
        } else {
            /* tag_bytes < 0 already logged in rfid_read */
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    log_event("Shutting down — forcing locks engaged");
    all_locks_engaged();

    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    spiClose(0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

