                }
            } else {
                log_event("Invalid RFID tag");
            }
        } else if (tag_bytes == 0) {
            /* No tag present — normal, just poll again */
        } else {
            /* tag_bytes < 0 already logged in rfid_read */
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    log_event("Shutting down — forcing locks engaged");
    all_locks_engaged();

    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    spiClose(0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

