#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define ENC1_A 5
#define ENC1_B 6
#define ENC2_A 26
#define ENC2_B 19

/* ---- PID parameters ---- */
#define KP 1.0
#define KI 0.01
#define KD 0.1
#define TARGET_SPEED 60.0
#define PWM_PERIOD_US 10000   /* 100 Hz */
#define PWM_DUTY_MAX 1000
#define SAMPLE_TIME_US 100000 /* 100 ms */

/* ---- Globals ---- */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t enc1_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t enc2_mutex = PTHREAD_MUTEX_INITIALIZER;

static volatile int enc1_count = 0;
static volatile int enc2_count = 0;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void motor1_forward(int duty);
static void motor1_backward(int duty);
static void motor1_stop(void);
static void motor2_forward(int duty);
static void motor2_backward(int duty);
static void motor2_stop(void);
static int  read_encoder1(void);
static int  read_encoder2(void);
static double pid_control(double target, double actual, double *integral, double *prev_error);
static void log_data(double m1, double m2, double p, double i, double d, double out);
static void *encoder_thread1(void *arg);
static void *encoder_thread2(void *arg);

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* ---- Motor primitives ---- */
static void motor1_forward(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    gpioWrite(MOTOR1_IN1, 1);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, duty);
}

static void motor1_backward(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 1);
    gpioPWM(MOTOR1_ENA, duty);
}

static void motor1_stop(void) {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, 0);
}

static void motor2_forward(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    gpioWrite(MOTOR2_IN3, 1);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, duty);
}

static void motor2_backward(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 1);
    gpioPWM(MOTOR2_ENB, duty);
}

static void motor2_stop(void) {
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, 0);
}

/* ---- Encoder reads ---- */
static int read_encoder1(void) {
    int a, b;
    int cur, prev;

    a = gpioRead(ENC1_A);
    b = gpioRead(ENC1_B);
    if (a < 0 || b < 0) return 0;

    prev = gpioRead(ENC1_A);
    if (prev < 0) return 0;

    if (a != prev) {
        if (a == b) {
            pthread_mutex_lock(&enc1_mutex);
            enc1_count++;
            pthread_mutex_unlock(&enc1_mutex);
        } else {
            pthread_mutex_lock(&enc1_mutex);
            enc1_count--;
            pthread_mutex_unlock(&enc1_mutex);
        }
    }
    return 0;
}

static int read_encoder2(void) {
    int a, b;
    int cur, prev;

    a = gpioRead(ENC2_A);
    b = gpioRead(ENC2_B);
    if (a < 0 || b < 0) return 0;

    prev = gpioRead(ENC2_A);
    if (prev < 0) return 0;

    if (a != prev) {
        if (a == b) {
            pthread_mutex_lock(&enc2_mutex);
            enc2_count++;
            pthread_mutex_unlock(&enc2_mutex);
        } else {
            pthread_mutex_lock(&enc2_mutex);
            enc2_count--;
            pthread_mutex_unlock(&enc2_mutex);
        }
    }
    return 0;
}

/* ---- PID ---- */
static double pid_control(double target, double actual, double *integral, double *prev_error) {
    double error = target - actual;
    *integral += error;
    double derivative = error - *prev_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    return output;
}

/* ---- Logging ---- */
static void log_data(double m1, double m2, double p, double i, double d, double out) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            m1, m2, p, i, d, out);
    fflush(log_file);
}

/* ---- Encoder threads ---- */
static void *encoder_thread1(void *arg) {
    (void)arg;
    while (running) {
        read_encoder1();
        gpioDelay(1000);
    }
    return NULL;
}

static void *encoder_thread2(void *arg) {
    (void)arg;
    while (running) {
        read_encoder2();
        gpioDelay(1000);
    }
    return NULL;
}

/* ---- Main ---- */
int main(void) {
    pthread_t tid1, tid2;
    double integral1 = 0.0, prev_err1 = 0.0;
    double integral2 = 0.0, prev_err2 = 0.0;
    int prev_enc1 = 0, prev_enc2 = 0;
    int duty1 = 0, duty2 = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("motor_log.csv", "a");
    if (!log_file) {
        perror("fopen motor_log.csv");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,P,I,D,Output\n");
    fflush(log_file);

    /* Configure motor pins */
    if (gpioSetMode(MOTOR1_ENA, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_ENB, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure encoder pins */
    if (gpioSetMode(ENC1_A, PI_INPUT) < 0 ||
        gpioSetMode(ENC1_B, PI_INPUT) < 0 ||
        gpioSetMode(ENC2_A, PI_INPUT) < 0 ||
        gpioSetMode(ENC2_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set encoder pin modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Request edge events on encoder A pins */
    if (gpioSetAlertFunc(ENC1_A, NULL) < 0 ||
        gpioSetAlertFunc(ENC2_A, NULL) < 0) {
        fprintf(stderr, "Failed to request edge events\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Start encoder threads */
    if (pthread_create(&tid1, NULL, encoder_thread1, NULL) != 0 ||
        pthread_create(&tid2, NULL, encoder_thread2, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder threads\n");
        motor1_stop();
        motor2_stop();
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main control loop */
    while (running) {
        int cur_enc1, cur_enc2;

        pthread_mutex_lock(&enc1_mutex);
        cur_enc1 = enc1_count;
        pthread_mutex_unlock(&enc1_mutex);

        pthread_mutex_lock(&enc2_mutex);
        cur_enc2 = enc2_count;
        pthread_mutex_unlock(&enc2_mutex);

        int delta1 = cur_enc1 - prev_enc1;
        int delta2 = cur_enc2 - prev_enc2;
        prev_enc1 = cur_enc1;
        prev_enc2 = cur_enc2;

        /* Convert encoder ticks to RPM (assuming 20 ticks per revolution) */
        double speed1 = (double)delta1 * 60.0 / 20.0 / (SAMPLE_TIME_US / 1000000.0);
        double speed2 = (double)delta2 * 60.0 / 20.0 / (SAMPLE_TIME_US / 1000000.0);

        /* PID */
        double pid_out1 = pid_control(TARGET_SPEED, speed1, &integral1, &prev_err1);
        double pid_out2 = pid_control(TARGET_SPEED, speed2, &integral2, &prev_err2);

        /* Compute duty cycle */
        duty1 = (int)(pid_out1 * 10.0);
        duty2 = (int)(pid_out2 * 10.0);
        if (duty1 < 0) duty1 = 0;
        if (duty1 > PWM_DUTY_MAX) duty1 = PWM_DUTY_MAX;
        if (duty2 < 0) duty2 = 0;
        if (duty2 > PWM_DUTY_MAX) duty2 = PWM_DUTY_MAX;

        /* Drive motors */
        if (pid_out1 > 0) motor1_forward(duty1);
        else if (pid_out1 < 0) motor1_backward(-duty1);
        else motor1_stop();

        if (pid_out2 > 0) motor2_forward(duty2);
        else if (pid_out2 < 0) motor2_backward(-duty2);
        else motor2_stop();

        /* Log */
        log_data(speed1, speed2, KP * (TARGET_SPEED - speed1),
                 KI * integral1, KD * (TARGET_SPEED - speed1 - prev_err1),
                 pid_out1);

        gpioDelay(SAMPLE_TIME_US);
    }

    /* ---- Cleanup ---- */
    motor1_stop();
    motor2_stop();
    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);
    gpioSetAlertFunc(ENC1_A, NULL);
    gpioSetAlertFunc(ENC2_A, NULL);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

