#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define VALVE1_PAUSE_MS 5000
#define VALVE2_PAUSE_MS 10000
#define LOG_FILE "valve_log.txt"
#define GPIO_CHIP_NAME "gpiochip4"

static volatile sig_atomic_t program_running = 1;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(int valve_num, int duration_ms) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s - Valve %d activated for %d ms\n", timestamp, valve_num, duration_ms) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        }
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void activate_valve(struct gpiod_line *line, int valve_num, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d HIGH for Valve %d: %s\n", 
                (valve_num == 1) ? VALVE1_GPIO : VALVE2_GPIO, valve_num, strerror(errno));
        return;
    }

    struct timespec ts;
    ts.tv_sec = duration_ms / 1000;
    ts.tv_nsec = (duration_ms % 1000) * 1000000L;
    nanosleep(&ts, NULL);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d LOW for Valve %d: %s\n", 
                (valve_num == 1) ? VALVE1_GPIO : VALVE2_GPIO, valve_num, strerror(errno));
    }

    log_event(valve_num, duration_ms);
}

static void cleanup(void) {
    if (valve1_line != NULL) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line != NULL) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (valve1_line == NULL) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", VALVE1_GPIO, strerror(errno));
        goto cleanup;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (valve2_line == NULL) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", VALVE2_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(valve1_line, "water_valve", 0) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO %d as output: %s\n", VALVE1_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(valve2_line, "water_valve", 0) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO %d as output: %s\n", VALVE2_GPIO, strerror(errno));
        goto cleanup;
    }

    printf("Water distribution system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        activate_valve(valve1_line, 1, VALVE1_DURATION_MS);
        if (!program_running) break;
        struct timespec pause1;
        pause1.tv_sec = VALVE1_PAUSE_MS / 1000;
        pause1.tv_nsec = (VALVE1_PAUSE_MS % 1000) * 1000000L;
        nanosleep(&pause1, NULL);

        activate_valve(valve2_line, 2, VALVE2_DURATION_MS);
        if (!program_running) break;
        struct timespec pause2;
        pause2.tv_sec = VALVE2_PAUSE_MS / 1000;
        pause2.tv_nsec = (VALVE2_PAUSE_MS % 1000) * 1000000L;
        nanosleep(&pause2, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    cleanup();
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

