    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    bool relay_state = false;

    while (running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (touch_status > 0) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_GPIO, relay_state ? 1 : 0) < 0) {
                fprintf(stderr, "Error writing to GPIO %d\n", RELAY_GPIO);
            } else {
                printf("Relay toggled to: %s\n", relay_state ? "ON" : "OFF");
            }
        }

        gpioDelay(100000);
    }

    gpioWrite(RELAY_GPIO, 0);
    cleanup();
    return EXIT_SUCCESS;
}

