#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define MIN_PATTERN_LENGTH 5
#define MAX_PATTERN_LENGTH 15
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200

typedef struct {
    int motor1_duty_cycle;
    int motor2_duty_cycle;
    int duration_ms;
} PatternStep;

typedef struct {
    PatternStep *steps;
    int length;
} HapticPattern;

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int generate_random_pattern(HapticPattern *pattern) {
    pattern->length = (rand() % (MAX_PATTERN_LENGTH - MIN_PATTERN_LENGTH + 1)) + MIN_PATTERN_LENGTH;
    pattern->steps = (PatternStep *)malloc(pattern->length * sizeof(PatternStep));
    if (pattern->steps == NULL) {
        fprintf(stderr, "Error: memory allocation failed for pattern steps.\n");
        return -1;
    }

    for (int i = 0; i < pattern->length; i++) {
        pattern->steps[i].motor1_duty_cycle = (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
        pattern->steps[i].motor2_duty_cycle = (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
        pattern->steps[i].duration_ms = (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1)) + MIN_DURATION_MS;
    }

    return 0;
}

static void play_pattern(const HapticPattern *pattern) {
    for (int i = 0; i < pattern->length; i++) {
        if (shutdown_flag) {
            break;
        }

        if (gpioPWM(MOTOR1_GPIO, pattern->steps[i].motor1_duty_cycle) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed for motor 1 at step %d.\n", i);
        }
        if (gpioPWM(MOTOR2_GPIO, pattern->steps[i].motor2_duty_cycle) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed for motor 2 at step %d.\n", i);
        }

        gpioDelay(pattern->steps[i].duration_ms * 1000);
    }
}

static void cleanup(HapticPattern *pattern) {
    if (pattern->steps != NULL) {
        free(pattern->steps);
        pattern->steps = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    srand((unsigned int)time(NULL));

    HapticPattern pattern;
    pattern.steps = NULL;
    pattern.length = 0;

    while (!shutdown_flag) {
        if (generate_random_pattern(&pattern) != 0) {
            fprintf(stderr, "Error: failed to generate random pattern. Exiting.\n");
            break;
        }

        play_pattern(&pattern);
        cleanup(&pattern);
    }

    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);
    gpioTerminate();

    return 0;
}

