#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"

#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET 0.0
#define WEIGHT_THRESHOLD 10.0
#define STARTUP_CALIBRATION_SAMPLES 100
#define HX711_TIMEOUT_US 500000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static double scale_factor = DEFAULT_SCALE_FACTOR;
static double offset = DEFAULT_OFFSET;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int data = 0;
    int timeout = HX711_TIMEOUT_US;

    if (gpioSetMode(data_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(clock_pin, PI_OUTPUT) < 0) return -1;

    while (gpioRead(data_pin) == 1) {
        if (timeout <= 0) return -1;
        gpioDelay(100);
        timeout -= 100;
    }

    for (int i = 0; i < 24; i++) {
        if (gpioWrite(clock_pin, 1) < 0) return -1;
        gpioDelay(1);
        data = (data << 1) | (gpioRead(data_pin) & 1);
        if (gpioWrite(clock_pin, 0) < 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(clock_pin, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(clock_pin, 0) < 0) return -1;
    gpioDelay(1);

    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }

    return data;
}

static double calculate_weight(int raw_value, double scale, double offset) {
    return ((double)raw_value - offset) / scale;
}

static int load_calibration_data(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open %s. Using defaults.\n", filename);
        return -1;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: Invalid calibration data. Using defaults.\n");
        scale_factor = DEFAULT_SCALE_FACTOR;
        offset = DEFAULT_OFFSET;
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Calibration loaded: scale=%.2f, offset=%.2f\n", scale_factor, offset);
    return 0;
}

static int save_calibration_data(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error: Could not open %s for writing.\n", filename);
        return -1;
    }
    fprintf(fp, "%lf %lf\n", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved to %s\n", filename);
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin) {
    double sum = 0.0;
    int valid_samples = 0;

    printf("Starting startup calibration. Ensure no weight is on the load cell.\n");
    for (int i = 0; i < STARTUP_CALIBRATION_SAMPLES; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw == -1) {
            fprintf(stderr, "Warning: Timeout during calibration sample %d.\n", i + 1);
            continue;
        }
        sum += (double)raw;
        valid_samples++;
        gpioDelay(10000);
    }

    if (valid_samples == 0) {
        fprintf(stderr, "Error: No valid calibration samples. Using default offset.\n");
        return -1;
    }

    offset = sum / valid_samples;
    printf("Calibration complete. Offset: %.2f\n", offset);
    return 0;
}

static void log_data(double weight, int lock_engaged) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Weight: %.2f kg, Lock: %s\n", timestamp, weight, lock_engaged ? "Engaged" : "Disengaged");
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: Could not register SIGINT handler.\n");
    }

    if (load_calibration_data(CALIBRATION_FILE) != 0) {
        fprintf(stderr, "Using default calibration values.\n");
    }

    if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN) != 0) {
        fprintf(stderr, "Warning: Startup calibration failed. Using default offset.\n");
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Could not set solenoid pin mode.\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    printf("Monitoring weight. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw_value == -1) {
            fprintf(stderr, "Warning: HX711 read timeout. Skipping iteration.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double weight = calculate_weight(raw_value, scale_factor, offset);
        int lock_engaged = (weight > WEIGHT_THRESHOLD) ? 1 : 0;

        if (gpioWrite(SOLENOID_PIN, lock_engaged) < 0) {
            fprintf(stderr, "Warning: Failed to write solenoid pin.\n");
        }

        log_data(weight, lock_engaged);
        printf("Weight: %.2f kg, Lock: %s\n", weight, lock_engaged ? "Engaged" : "Disengaged");

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return 0;
}

