            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }
    return (low_count >= RAIN_THRESHOLD) ? 1 : 0;
}

static int control_motor(int close_window) {
    if (close_window) {
        syslog(LOG_INFO, "Closing window...");
        if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
            syslog(LOG_ERR, "Failed to set IN1 high");
            return -1;
        }
        if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to set IN2 low");
            return -1;
        }
        if (gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_PWM_FREQ) < 0) {
            syslog(LOG_ERR, "Failed to set PWM frequency");
            return -1;
        }
        if (gpioSetPWMrange(MOTOR_PWM_PIN, MOTOR_PWM_RANGE) < 0) {
            syslog(LOG_ERR, "Failed to set PWM range");
            return -1;
        }
        if (gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTY) < 0) {
            syslog(LOG_ERR, "Failed to start PWM");
            return -1;
        }
        gpioDelay(MOTOR_RUN_TIME_US);
        if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to stop PWM");
            return -1;
        }
        if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to set IN1 low");
            return -1;
        }
        if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to set IN2 low");
            return -1;
        }
        syslog(LOG_INFO, "Window closed.");
        return 0;
    } else {
        syslog(LOG_INFO, "Stopping motor...");
        if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to stop PWM");
            return -1;
        }
        if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to set IN1 low");
            return -1;
        }
        if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to set IN2 low");
            return -1;
        }
        syslog(LOG_INFO, "Motor stopped.");
        return 0;
    }
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pull-up");
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 pin mode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 pin mode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor PWM pin mode");
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialize motor IN1 low");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialize motor IN2 low");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialize motor PWM to 0");
        gpioTerminate();
        closelog();
        return 1;
    }

    log_event("Window control system started.");

    while (program_running) {
        int rain = read_rain_sensor();
        if (rain) {
            log_event("Rain detected.");
            if (control_motor(1) == 0) {
                log_event("Window closed due to rain.");
            } else {
                log_event("Error closing window.");
            }
            gpioDelay(POST_CLOSE_DELAY_US);
        } else {
            gpioDelay(POLL_INTERVAL_US);
        }
    }

    control_motor(0);
    gpioTerminate();
    log_event("Window control system stopped.");
    closelog();
    return 0;
}

