#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17

#define WEIGHT_THRESHOLD 100.0
#define LOCK_DURATION_SEC 5
#define SAMPLE_INTERVAL_SEC 1
#define HX711_TIMEOUT_US 1000000
#define HX711_SETTLE_US 1000
#define HX711_MAX_READS 100

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static int read_hx711(long *raw_value) {
    if (gpioSetMode(HX711_DT_PIN, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DT_PIN) == 1) {
        if (gpioTick() - start > HX711_TIMEOUT_US) {
            return -2;
        }
        gpioDelay(100);
    }

    long value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(HX711_DT_PIN)) value |= 1;
        if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
    gpioDelay(1);

    if (value & 0x800000) value |= 0xFF000000;
    *raw_value = value;
    return 0;
}

static double raw_to_grams(long raw) {
    return (double)raw / 1000.0;
}

static int control_solenoid(int activate) {
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(SOLENOID_PIN, activate ? 1 : 0) < 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen("stock_events.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    while (running) {
        long raw;
        int rc = read_hx711(&raw);

        if (rc == 0) {
            double weight = raw_to_grams(raw);
            char msg[128];
            snprintf(msg, sizeof(msg), "Weight: %.2f g", weight);
            log_event(msg);

            if (weight < WEIGHT_THRESHOLD) {
                log_event("Weight below threshold, activating solenoid");
                if (control_solenoid(1) == 0) {
                    for (int i = 0; i < LOCK_DURATION_SEC && running; i++) {
                        sleep(1);
                    }
                    control_solenoid(0);
                    log_event("Solenoid deactivated");
                } else {
                    log_event("Error: Failed to activate solenoid");
                }
            }
        } else if (rc == -2) {
            log_event("Error: HX711 timeout (data line stuck high)");
        } else {
            log_event("Error: HX711 read failure");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    control_solenoid(0);
    log_event("System shutting down");
    fclose(log_file);
    gpioTerminate();
    return 0;
}

