#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"

#define WEIGHT_THRESHOLD 5.0
#define SOLENOID_LOCK_TIME 5
#define HX711_TIMEOUT_US 100000
#define HX711_SETTLE_US 1
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int *out_value) {
    int value = 0;
    int timeout = 0;

    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
    gpioDelay(HX711_SETTLE_US);

    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(HX711_SETTLE_US);
        timeout += HX711_SETTLE_US;
        if (timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 timeout waiting for data line low.\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
        gpioDelay(HX711_SETTLE_US);
        value = (value << 1) | (gpioRead(HX711_DATA_PIN) & 1);
        if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
        gpioDelay(HX711_SETTLE_US);
    }

    if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
    gpioDelay(HX711_SETTLE_US);
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
    gpioDelay(HX711_SETTLE_US);

    if (value & 0x800000) {
        value |= ~0xFFFFFF;
    }

    *out_value = value;
    return 0;
}

static double calibrate_hx711(void) {
    int raw_value;
    double known_weight;
    double new_calibration_factor;

    printf("Place a known weight on the load cell and enter the weight in kg: ");
    fflush(stdout);
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Error: Invalid weight entered.\n");
        while (getchar() != '\n');
        return calibration_factor;
    }
    while (getchar() != '\n');

    if (read_hx711(&raw_value) != 0) {
        fprintf(stderr, "Error: Failed to read HX711 during calibration.\n");
        return calibration_factor;
    }

    new_calibration_factor = (double)raw_value / known_weight;

    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return calibration_factor;
    }
    fprintf(fp, "%lf\n", new_calibration_factor);
    fclose(fp);

    calibration_factor = new_calibration_factor;
    printf("Calibration factor updated to: %lf\n", calibration_factor);
    return calibration_factor;
}

static double get_weight_kg(int raw_value) {
    return (double)raw_value / calibration_factor;
}

static void log_security_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        log_file = fopen(SECURITY_LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Could not open security log file.\n");
            return;
        }
    }

    if (fprintf(log_file, "%s - Weight exceeded threshold: %.2f kg\n", timestamp, weight) < 0) {
        fprintf(stderr, "Error: Failed to write to security log file.\n");
    }
    fflush(log_file);
}

static void unlock_solenoid(void) {
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to activate solenoid.\n");
        return;
    }
    printf("Solenoid activated for %d seconds.\n", SOLENOID_LOCK_TIME);
    gpioDelay(SOLENOID_LOCK_TIME * 1000000);
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to deactivate solenoid.\n");
    }
    printf("Solenoid deactivated.\n");
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0 ||
        gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialize solenoid pin.\n");
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp != NULL) {
        if (fscanf(fp, "%lf", &calibration_factor) == 1) {
            printf("Calibration factor loaded from file: %lf\n", calibration_factor);
        } else {
            fprintf(stderr, "Warning: Could not read calibration factor from file. Using default value.\n");
        }
        fclose(fp);
    } else {
        printf("No calibration file found. Using default calibration factor: %lf\n", calibration_factor);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set SIGINT handler.\n");
        gpioTerminate();
        return 1;
    }

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value;
        if (read_hx711(&raw_value) != 0) {
            fprintf(stderr, "Error: Failed to read HX711. Retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double weight = get_weight_kg(raw_value);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight exceeded threshold: %.2f kg\n", weight);
            log_security_event(weight);
            unlock_solenoid();
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

