        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int toggle_relay(void) {
    int current_state = gpioRead(RELAY_PIN);
    if (current_state < 0) {
        fprintf(stderr, "Error reading relay state on GPIO%d: %s\n", RELAY_PIN, pigpio_error(current_state));
        return -1;
    }

    int new_state = !current_state;
    if (gpioWrite(RELAY_PIN, new_state) != 0) {
        fprintf(stderr, "Error writing to relay on GPIO%d: %s\n", RELAY_PIN, pigpio_error(new_state));
        return -1;
    }

    return new_state;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay to OFF state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-022 sensor on GPIO%d, relay on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN, RELAY_PIN);

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor on GPIO%d: %s\n", SENSOR_PIN, pigpio_error(sensor_value));
            log_event("Error reading sensor");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (sensor_value == 0) {
            int new_relay_state = toggle_relay();
            if (new_relay_state < 0) {
                log_event("Error toggling relay");
            } else {
                const char *state_str = new_relay_state ? "ON" : "OFF";
                char message[64];
                snprintf(message, sizeof(message), "Relay toggled to %s", state_str);
                log_event(message);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

