            if (gpioWrite(BUZZER_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to activate buzzer\n");
                break;
            }

            if (log_motion() != 0) {
                fprintf(stderr, "Warning: failed to log motion event\n");
            }

            /* Keep buzzer on for 2 seconds, checking for shutdown signal */
            for (int i = 0; i < 20 && running; i++) {
                usleep(100000); /* 100 ms slices */
            }

            if (gpioWrite(BUZZER_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to deactivate buzzer\n");
                break;
            }
        }

        if (running) {
            usleep(POLL_DELAY_US);
        }
    }

    /* Graceful cleanup */
    cleanup();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

