#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define CONFIG_FILE "watering.conf"
#define GPIO_PIN 18
#define MIN_DURATION 1
#define MAX_DURATION 3600
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_duration_from_config(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        if (feof(fp)) {
            fprintf(stderr, "Config file '%s' is empty\n", filename);
        } else {
            fprintf(stderr, "Error reading config file '%s': %s\n", filename, strerror(errno));
        }
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *key = strtok(line, "=\n\r");
    char *value = strtok(NULL, "=\n\r");

    if (key == NULL || value == NULL) {
        fprintf(stderr, "Config file format error: expected 'duration=<seconds>'\n");
        return -1;
    }

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Config file format error: expected key 'duration', got '%s'\n", key);
        return -1;
    }

    char *endptr;
    errno = 0;
    long val = strtol(value, &endptr, 10);
    if (errno != 0 || endptr == value || *endptr != '\0') {
        fprintf(stderr, "Config file format error: duration must be an integer\n");
        return -1;
    }

    if (val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Config file error: duration %ld out of range [%d, %d]\n",
                val, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)val;
    return 0;
}

static int set_gpio_output(int pin, int level)
{
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", pin);
        return -1;
    }
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error writing %d to GPIO %d\n", level, pin);
        return -1;
    }
    return 0;
}

static void cleanup_gpio(int pin)
{
    gpioWrite(pin, 0);
    gpioSetMode(pin, PI_INPUT);
