#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define SENSOR_LEFT_PIN   4
#define SENSOR_MIDDLE_PIN 17
#define SENSOR_RIGHT_PIN  27

#define MOTOR_LEFT_PWM_PIN  22
#define MOTOR_LEFT_IN1_PIN  23
#define MOTOR_RIGHT_PWM_PIN 24
#define MOTOR_RIGHT_IN1_PIN 25

/* ---- Control parameters ---- */
#define PWM_FREQUENCY_HZ   1000
#define PWM_RANGE          255
#define BASE_SPEED         150
#define TURN_SPEED         (BASE_SPEED / 2)
#define LOOP_DELAY_US      10000   /* 10 ms */

/* ---- Globals for cleanup ---- */
static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor line (active-low: 0 = line detected, 1 = no line)    */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    return (v == 0) ? 1 : 0;   /* 1 = line present, 0 = no line */
}

/* ------------------------------------------------------------------ */
/* Drive both motors at the given speeds (0-255)                      */
/* ------------------------------------------------------------------ */
static int drive_motors(int left_speed, int right_speed)
{
    if (left_speed < 0 || left_speed > PWM_RANGE ||
        right_speed < 0 || right_speed > PWM_RANGE) {
        fprintf(stderr, "Invalid motor speed: left=%d right=%d\n",
                left_speed, right_speed);
        return -1;
    }

    /* Left motor: forward */
    if (gpioWrite(MOTOR_LEFT_IN1_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", MOTOR_LEFT_IN1_PIN);
        return -1;
    }
    if (gpioPWM(MOTOR_LEFT_PWM_PIN, left_speed) < 0) {
        fprintf(stderr, "gpioPWM failed on pin %d\n", MOTOR_LEFT_PWM_PIN);
        return -1;
    }

    /* Right motor: forward */
    if (gpioWrite(MOTOR_RIGHT_IN1_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", MOTOR_RIGHT_IN1_PIN);
        return -1;
    }
    if (gpioPWM(MOTOR_RIGHT_PWM_PIN, right_speed) < 0) {
        fprintf(stderr, "gpioPWM failed on pin %d\n", MOTOR_RIGHT_PWM_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Stop both motors                                                 */
/* ------------------------------------------------------------------ */
static void stop_motors(void)
{
    gpioPWM(MOTOR_LEFT_PWM_PIN, 0);
    gpioPWM(MOTOR_RIGHT_PWM_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Log one control cycle to the trace file                           */
/* ------------------------------------------------------------------ */
static void log_data(int left, int middle, int right,
                     int left_speed, int right_speed)
{
    if (g_log_file == NULL)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(g_log_file, "%s,%d,%d,%d,%d,%d\n",
            ts, left, middle, right, left_speed, right_speed);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Line‑following control logic                                      */
/* ------------------------------------------------------------------ */
static void line_follow(int left, int middle, int right)
{
    int left_speed, right_speed;

    if (middle == 1) {
        /* Line under middle sensor — drive straight */
        left_speed  = BASE_SPEED;
        right_speed = BASE_SPEED;
    } else if (left == 1) {
        /* Line on left — turn right (reduce left motor) */
        left_speed  = TURN_SPEED;
        right_speed = BASE_SPEED;
    } else if (right == 1) {
        /* Line on right — turn left (reduce right motor) */
        left_speed  = BASE_SPEED;
        right_speed = TURN_SPEED;
    } else {
        /* No line detected — stop */
        left_speed  = 0;
        right_speed = 0;
    }

    if (drive_motors(left_speed, right_speed) < 0) {
        fprintf(stderr, "Motor drive failed — stopping\n");
        stop_motors();
        g_running = 0;
    }

    log_data(left, middle, right, left_speed, right_speed);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    stop_motors();
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                              */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(SENSOR_LEFT_PIN,   PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_MIDDLE_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_RIGHT_PIN,  PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure motor control pins ---- */
    if (gpioSetMode(MOTOR_LEFT_PWM_PIN,  PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_LEFT_IN1_PIN,  PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_IN1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency and range ---- */
    if (gpioSetPWMfrequency(MOTOR_LEFT_PWM_PIN, PWM_FREQUENCY_HZ) < 0 ||
        gpioSetPWMfrequency(MOTOR_RIGHT_PWM_PIN, PWM_FREQUENCY_HZ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_LEFT_PWM_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_RIGHT_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("trace_log.txt", "a");
    if (g_log_file == NULL) {
        perror("fopen trace_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line-following robot started. Press Ctrl+C to stop.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        int left   = read_sensor(SENSOR_LEFT_PIN);
        int middle = read_sensor(SENSOR_MIDDLE_PIN);
        int right  = read_sensor(SENSOR_RIGHT_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error — stopping\n");
            g_running = 0;
        } else {
            line_follow(left, middle, right);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

