#define LUX_THRESHOLD 150.0f
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fclose(fp);
}

static int read_bh1750(float *lux_out) {
    if (i2cWriteByte(i2c_handle, BH1750_CONT_HIGH_RES_MODE) < 0) {
        log_event("Error writing measurement command to BH1750");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000);
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        log_event("Error reading data from BH1750");
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GROW_LAMP_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetMode(GROW_LAMP_GPIO, PI_OUTPUT);
    gpioWrite(GROW_LAMP_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    log_event("Program started");
    int relay_state = 0;
    while (running) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_event(msg);
            if (lux < LUX_THRESHOLD) {
                if (!relay_state) {
                    gpioWrite(GROW_LAMP_GPIO, 1);
                    relay_state = 1;
                    log_event("Grow lamp turned ON");
                }
            } else {
                if (relay_state) {
                    gpioWrite(GROW_LAMP_GPIO, 0);
                    relay_state = 0;
                    log_event("Grow lamp turned OFF");
                }
            }
        }
        gpioDelay(1000000);
    }
    log_event("Program exiting");
    cleanup();
    return EXIT_SUCCESS;
}

