#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_LOCK_PULSE_WIDTH 1000
#define SERVO_UNLOCK_PULSE_WIDTH 2000

#define DEBOUNCE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse_width(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width %d out of range [%d, %d]\n",
                pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int lock_door(void) {
    printf("Locking door...\n");
    if (set_servo_pulse_width(SERVO_PIN, SERVO_LOCK_PULSE_WIDTH) != 0) {
        return -1;
    }
    gpioDelay(500000);
    printf("Door locked.\n");
    return 0;
}

static int unlock_door(void) {
    printf("Unlocking door...\n");
    if (set_servo_pulse_width(SERVO_PIN, SERVO_UNLOCK_PULSE_WIDTH) != 0) {
        return -1;
    }
    gpioDelay(500000);
    printf("Door unlocked.\n");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set button pins as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(LOCK_BUTTON_PIN) == 0) {
                lock_door();
                while (running && gpioRead(LOCK_BUTTON_PIN) == 0) {
                    gpioDelay(10000);
                }
            }
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                unlock_door();
                while (running && gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                    gpioDelay(10000);
                }
            }
        }

        gpioDelay(10000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Exiting gracefully.\n");
    return EXIT_SUCCESS;
}

