#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MOTOR1_PULSE_US 200000  /* 200 ms in microseconds */
#define MOTOR2_PULSE_US 300000  /* 300 ms in microseconds */
#define LOOP_DELAY_US 100000    /* 100 ms delay between pulses */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned pin, unsigned value) {
    if (gpioWrite(pin, value) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %u (value %u)\n", pin, value);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %u (mode %u)\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned pin, unsigned pud) {
    if (gpioSetPullUpDown(pin, pud) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed on pin %u (pud %u)\n", pin, pud);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (safe_set_mode(MOTOR1_PIN, PI_OUTPUT) != 0) return -1;
    if (safe_set_mode(MOTOR2_PIN, PI_OUTPUT) != 0) return -1;
    if (safe_set_pull(MOTOR1_PIN, PI_PUD_OFF) != 0) return -1;
    if (safe_set_pull(MOTOR2_PIN, PI_PUD_OFF) != 0) return -1;

    /* Ensure motors are off at startup */
    if (safe_write(MOTOR1_PIN, 0) != 0) return -1;
    if (safe_write(MOTOR2_PIN, 0) != 0) return -1;

    return 0;
}

static void cleanup_gpio(void) {
    /* Turn off motors before releasing lines */
    gpioWrite(MOTOR1_PIN, 0);
    gpioWrite(MOTOR2_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (safe_write(MOTOR1_PIN, 1) != 0) break;
        gpioDelay(MOTOR1_PULSE_US);
        if (safe_write(MOTOR1_PIN, 0) != 0) break;
        gpioDelay(LOOP_DELAY_US);

        if (safe_write(MOTOR2_PIN, 1) != 0) break;
        gpioDelay(MOTOR2_PULSE_US);
        if (safe_write(MOTOR2_PIN, 0) != 0) break;
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup_gpio();
    printf("\nHaptic feedback system stopped.\n");
    return EXIT_SUCCESS;
}

