#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <fcntl.h>
#include <sys/file.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <zmq.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN    27
#define ZMQ_PORT         5555
#define POLL_INTERVAL_MS 10
#define ALARM_DURATION_S 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int gpio_export(int pin) {
    char buf[4];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(/sys/class/gpio/export): %s\n", strerror(errno));
        return -1;
    }
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "write export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    char buf[4];
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(/sys/class/gpio/unexport): %s\n", strerror(errno));
        return -1;
    }
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "write unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) != (ssize_t)strlen(dir)) {
        fprintf(stderr, "write direction: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
