#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_TOLERANCE 200
#define MAX_PULSE_GAP 5000

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static int pulse_count = 0;
static uint32_t pulses[MAX_PULSES];
static uint32_t last_tick = 0;
static bool frame_ready = false;
static uint32_t decoded_command = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static bool in_range(uint32_t val, uint32_t target, uint32_t tol) {
    return (val >= target - tol) && (val <= target + tol);
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != 0) return;

    uint32_t diff = tick - last_tick;
    last_tick = tick;

    if (diff > MAX_PULSE_GAP) {
        if (pulse_count > 0) {
            frame_ready = true;
        }
        pulse_count = 0;
        return;
    }

    if (pulse_count < MAX_PULSES) {
        pulses[pulse_count++] = diff;
    } else {
        syslog(LOG_WARNING, "IR pulse buffer overflow");
        pulse_count = 0;
        frame_ready = true;
        return;
    }
}

static bool decode_nec(uint32_t *cmd) {
    if (pulse_count < 68) return false;

    if (!in_range(pulses[0], NEC_HEADER_MARK, NEC_TOLERANCE) ||
        !in_range(pulses[1], NEC_HEADER_SPACE, NEC_TOLERANCE)) {
        return false;
    }

    uint32_t address = 0, command = 0, inv_addr = 0, inv_cmd = 0;

    for (int i = 0; i < 16; i++) {
        uint32_t idx = 2 + i * 2;
        if (!in_range(pulses[idx], NEC_BIT_MARK, NEC_TOLERANCE)) return false;
        if (in_range(pulses[idx + 1], NEC_ONE_SPACE, NEC_TOLERANCE)) {
            address |= (1u << i);
        } else if (in_range(pulses[idx + 1], NEC_ZERO_SPACE, NEC_TOLERANCE)) {
            address &= ~(1u << i);
        } else {
            return false;
        }
    }

    for (int i = 0; i < 16; i++) {
        uint32_t idx = 34 + i * 2;
        if (!in_range(pulses[idx], NEC_BIT_MARK, NEC_TOLERANCE)) return false;
        if (in_range(pulses[idx + 1], NEC_ONE_SPACE, NEC_TOLERANCE)) {
            command |= (1u << i);
        } else if (in_range(pulses[idx + 1], NEC_ZERO_SPACE, NEC_TOLERANCE)) {
            command &= ~(1u << i);
        } else {
            return false;
        }
    }

    for (int i = 0; i < 16; i++) {
        uint32_t idx = 66 + i * 2;
        if (!in_range(pulses[idx], NEC_BIT_MARK, NEC_TOLERANCE)) return false;
        if (in_range(pulses[idx + 1], NEC_ONE_SPACE, NEC_TOLERANCE)) {
            inv_addr |= (1u << i);
        } else if (in_range(pulses[idx + 1], NEC_ZERO_SPACE, NEC_TOLERANCE)) {
            inv_addr &= ~(1u << i);
        } else {
            return false;
        }
    }

    for (int i = 0; i < 16; i++) {
        uint32_t idx = 98 + i * 2;
        if (!in_range(pulses[idx], NEC_BIT_MARK, NEC_TOLERANCE)) return false;
        if (in_range(pulses[idx + 1], NEC_ONE_SPACE, NEC_TOLERANCE)) {
            inv_cmd |= (1u << i);
        } else if (in_range(pulses[idx + 1], NEC_ZERO_SPACE, NEC_TOLERANCE)) {
            inv_cmd &= ~(1u << i);
        } else {
            return false;
        }
    }

    if ((address != ((uint16_t)~inv_addr & 0xFFFF)) ||
        (command != ((uint16_t)~inv_cmd & 0xFFFF))) {
        return false;
    }

    *cmd = ((uint32_t)command << 16) | address;
    return true;
}

static void publish_command(uint32_t cmd) {
    char payload[64];
    int len = snprintf(payload, sizeof(payload), "{\"command\": %u}", cmd);
    if (len > 0) {
        int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, (size_t)len, payload, 0, false);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
        }
    }
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register signal handler");
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "Failed to set pull-up on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetAlertFunc(IR_GPIO, ir_callback) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", mosquitto_strerror(MOSQ_ERR_NOMEM));
        gpioTerminate();
        closelog();
        return 1;
    }

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT loop start failed: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO %d, MQTT %s:%d/%s", IR_GPIO, MQTT_HOST, MQTT_PORT, MQTT_TOPIC);

    while (running) {
        if (frame_ready) {
            frame_ready = false;
            if (pulse_count > 0) {
                if (decode_nec(&decoded_command)) {
                    syslog(LOG_INFO, "Decoded command: 0x%08X", decoded_command);
                    publish_command(decoded_command);
                } else {
                    syslog(LOG_WARNING, "Invalid NEC frame");
                }
            }
            pulse_count = 0;
        }
        gpioDelay(10000);
    }

    syslog(LOG_INFO, "Shutting down...");
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    return 0;
}

