#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define BH1750_CONV_TIME_MS 180
#define LOOP_DELAY_MS 1000

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_bh1750(int fd, float *lux_out) {
    unsigned char cmd = BH1750_CONT_HIGH_RES_MODE;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "BH1750 write failed (addr %d): %s\n", fd, strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_TIME_MS * 1000);

    unsigned char buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "BH1750 read failed (addr %d): %s\n", fd, strerror(errno));
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_udp_packet(const char *data) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }
    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt failed");
        close(sockfd);
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }
    close(sockfd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    int fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        fds[i] = open(I2C_BUS, O_RDWR);
        if (fds[i] < 0) {
            fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
            for (int j = 0; j < i; j++) close(fds[j]);
            return 1;
        }
    }

    int addrs[NUM_SENSORS] = {0x23, 0x5C, 0x1D, 0x76};
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (ioctl(fds[i], I2C_SLAVE, addrs[i]) < 0) {
            fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", addrs[i], strerror(errno));
            for (int j = 0; j <= i; j++) close(fds[j]);
            return 1;
        }
    }

    while (!terminate) {
        char lux_string[256];
        int idx = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            float lux;
            if (read_bh1750(fds[i], &lux) == 0) {
                idx += snprintf(lux_string + idx, sizeof(lux_string) - idx, "%d,%.2f;", i + 1, lux);
            } else {
                idx += snprintf(lux_string + idx, sizeof(lux_string) - idx, "%d,NaN;", i + 1);
            }
        }
        lux_string[idx - 1] = '\0';
        if (send_udp_packet(lux_string) != 0) {
            fprintf(stderr, "Failed to send UDP packet\n");
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        close(fds[i]);
    }
    return 0;
}

