#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x40
#define LOG_FILE       "airflow_log.txt"
#define READ_RETRIES   3
#define RETRY_DELAY_MS 100
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    for (int attempt = 0; attempt < READ_RETRIES; attempt++) {
        ssize_t n = read(fd, buf, len);
        if (n == (ssize_t)len)
            return 0;
        if (n < 0) {
            if (errno == EIO)
                fprintf(stderr, "I2C bus error (attempt %d/%d): %s\n",
                        attempt + 1, READ_RETRIES, strerror(errno));
            else if (errno == ENXIO)
                fprintf(stderr, "No I2C device found at address 0x%02X (attempt %d/%d)\n",
                        AWM7300V_ADDR, attempt + 1, READ_RETRIES);
            else
                fprintf(stderr, "I2C read error (attempt %d/%d): %s\n",
                        attempt + 1, READ_RETRIES, strerror(errno));
        } else {
            fprintf(stderr, "Short read: got %zd of %zu bytes (attempt %d/%d)\n",
                    n, len, attempt + 1, READ_RETRIES);
        }
        if (attempt < READ_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static float convert_to_slpm(const uint8_t *raw)
{
    /*
     * AWM7300V: 14-bit flow data is left-justified in the first two bytes.
     * Byte 0: bits 7..2 = flow MSBs, bits 1..0 = status flags
     * Byte 1: bits 7..0 = flow LSBs
     * Mask 0x7F to clear status bits, then assemble the 14-bit value.
     */
    uint16_t flow_raw = ((uint16_t)(raw[0] & 0x7F) << 8) | (uint16_t)raw[1];
    return (float)flow_raw / 100.0f;
}

static int log_flow_rate(float flow_rate)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, %.2f SLPM\n", ts, flow_rate) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AWM7300V_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        /*
         * Issue a zero-length write to generate a start condition,
         * then read two bytes from the sensor.
         */
        if (write(g_i2c_fd, NULL, 0) < 0) {
            if (errno == EIO)
                fprintf(stderr, "I2C bus error during start-condition write: %s\n",
                        strerror(errno));
            else if (errno == ENXIO)
                fprintf(stderr, "No I2C device found at address 0x%02X\n",
                        AWM7300V_ADDR);
            else
                fprintf(stderr, "I2C write error: %s\n", strerror(errno));
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        uint8_t raw[2];
        if (i2c_read_bytes(g_i2c_fd, raw, sizeof(raw)) != 0) {
            fprintf(stderr, "Failed to read flow data after %d retries.\n",
                    READ_RETRIES);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float flow_rate = convert_to_slpm(raw);
        if (log_flow_rate(flow_rate) != 0) {
            fprintf(stderr, "Failed to log flow rate.\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

