#define I2C_BUS "/dev/i2c-1"
#define AS7341_ADDR 0x49
#define LOG_FILE "spectral_log.csv"

#define AS7341_ENABLE 0x80
#define AS7341_ATIME 0x81
#define AS7341_WTIME 0x83
#define AS7341_CFG6 0x8A
#define AS7341_ID 0x92
#define AS7341_STATUS 0x93
#define AS7341_DATA0 0x94
#define AS7341_DATA1 0x95
#define AS7341_DATA2 0x96
#define AS7341_DATA3 0x97
#define AS7341_DATA4 0x98
#define AS7341_DATA5 0x99
#define AS7341_DATA6 0x9A
#define AS7341_DATA7 0x9B
#define AS7341_DATA8 0x9C
#define AS7341_DATA9 0x9D

#define AS7341_ID_VALUE 0x7341
#define AS7341_ENABLE_PON 0x01
#define AS7341_ENABLE_SP_EN 0x20

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int as7341_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, AS7341_ID, &id) < 0) {
        fprintf(stderr, "Error: Failed to read ID register.\n");
        return -1;
    }
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "Error: Invalid ID 0x%04X (expected 0x%04X).\n", id, AS7341_ID_VALUE);
        return -1;
    }

    if (i2c_write_reg8(fd, AS7341_ENABLE, AS7341_ENABLE_PON) < 0) {
        fprintf(stderr, "Error: Failed to power on sensor.\n");
        return -1;
    }
    usleep(10000);

    if (i2c_write_reg8(fd, AS7341_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_WTIME, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG6, 0x00) < 0) return -1;

    if (i2c_write_reg8(fd, AS7341_ENABLE, AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) < 0) {
        fprintf(stderr, "Error: Failed to enable spectral measurement.\n");
        return -1;
    }
    usleep(10000);

    return 0;
}

static int as7341_read_data(int fd, uint16_t *data) {
    uint8_t buf[20];
    uint8_t reg = AS7341_DATA0;

    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 20) != 20) {
        return -1;
    }

    for (int i = 0; i < 10; i++) {
        data[i] = (uint16_t)buf[i * 2] | ((uint16_t)buf[i * 2 + 1] << 8);
    }
    return 0;
}

static float as7341_compute_lux(const uint16_t *data) {
    float clear = (float)data[0];
    float ir = (float)data[1];
    float lux = (clear > 0.0f) ? (clear * 0.5f) : 0.0f;
    return lux;
}

static void log_data(FILE *fp, const uint16_t *data, float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec);
    for (int i = 0; i < 10; i++) {
        fprintf(fp, ",%u", data[i]);
    }
    fprintf(fp, ",%.2f\n", lux);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (as7341_init(i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Ch0,Ch1,Ch2,Ch3,Ch4,Ch5,Ch6,Ch7,Ch8,Ch9,Lux\n");
    }

    uint16_t data[10];
    while (running) {
        if (as7341_read_data(i2c_fd, data) < 0) {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        } else {
            float lux = as7341_compute_lux(data);
            log_data(log_file, data, lux);
            printf("Lux: %.2f\n", lux);
        }
        sleep(5);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

