#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <getopt.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x53
#define DEFAULT_SAMPLE_INTERVAL 1
#define DEFAULT_OUTPUT_FILE "seismic_data.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define READ_DELAY_MS 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static FILE *error_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (error_log_file) {
        fprintf(error_log_file, "%s: %s\n", timestamp, message);
        fflush(error_log_file);
    }
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_sensor_data(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(fd, 0x00, &raw_x) < 0) return -1;
    if (i2c_read_reg16(fd, 0x02, &raw_y) < 0) return -1;
    if (i2c_read_reg16(fd, 0x04, &raw_z) < 0) return -1;

    *x = (float)raw_x / 100.0f;
    *y = (float)raw_y / 100.0f;
    *z = (float)raw_z / 100.0f;
    return 0;
}

static int log_data(FILE *file, float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z) < 0) {
        return -1;
    }
    fflush(file);
    return 0;
}

static void cleanup(void) {
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    if (error_log_file) {
        fclose(error_log_file);
        error_log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int sample_interval = DEFAULT_SAMPLE_INTERVAL;
    char output_file[256] = DEFAULT_OUTPUT_FILE;

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 'i':
                sample_interval = (int)strtol(optarg, NULL, 0);
                if (sample_interval <= 0) {
                    fprintf(stderr, "Invalid sample interval. Using default.\n");
                    sample_interval = DEFAULT_SAMPLE_INTERVAL;
                }
                break;
            case 'f':
                strncpy(output_file, optarg, sizeof(output_file) - 1);
                output_file[sizeof(output_file) - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sample_interval] [-f output_file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    error_log_file = fopen("seismic_error.log", "a");
    if (!error_log_file) {
        perror("Failed to open error log file");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to acquire I2C bus access");
        cleanup();
        return EXIT_FAILURE;
    }

    csv_file = fopen(output_file, "a");
    if (!csv_file) {
        log_error("Failed to open CSV file");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");
        fflush(csv_file);
    }

    float x, y, z;
    int retries;

    while (running) {
        retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
