#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CONT_H  0x10
#define BH1750_RES     0x20
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL  1
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_sockfd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int bh1750_init(int fd) {
    uint8_t cmd[2] = { BH1750_CONT_H, BH1750_RES };
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "Error writing config to BH1750: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error reading from BH1750: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux) {
    char buffer[32];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "Error formatting lux value\n");
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    if (sendto(g_sockfd, buffer, (size_t)len, 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending multicast: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }
    if (bh1750_init(g_i2c_fd) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    g_sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_sockfd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }
    int ttl = MULTICAST_TTL;
    if (setsockopt(g_sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting multicast TTL: %s\n", strerror(errno));
        close(g_sockfd);
        g_sockfd = -1;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    while (g_running) {
        float lux;
        if (bh1750_read_lux(g_i2c_fd, &lux) == 0) {
            if (send_multicast(lux) != 0) {
                fprintf(stderr, "Failed to send multicast data\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    if (g_sockfd >= 0) close(g_sockfd);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

