#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define READ_BUF_SIZE 4096
#define MAX_OBJECTS 100

/* TI mmWave SDK magic word (8 bytes, little-endian) */
static const uint8_t MAGIC_WORD[8] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

/* TI mmWave SDK TLV types */
#define TLV_TYPE_DETECTED_OBJECTS 1

/* TI mmWave SDK TLV header (8 bytes) */
typedef struct __attribute__((packed)) {
    uint32_t type;
    uint32_t length;
} tlv_header_t;

/* TI mmWave SDK detected object (8 bytes) */
typedef struct __attribute__((packed)) {
    uint16_t rangeIdx;
    uint16_t dopplerIdx;
    uint16_t peakVal;
    uint16_t x;
    uint16_t y;
    uint16_t z;
} detected_obj_t;

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_uart_handle = -1;
static FILE *g_csv_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Read exactly n bytes from UART, retrying on short reads */
static int read_exact(int handle, uint8_t *buf, size_t n) {
    size_t total = 0;
    while (total < n) {
        int r = serRead(handle, (char *)(buf + total), n - total);
        if (r < 0) {
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "UART read returned 0 (EOF)\n");
            return -1;
        }
        total += (size_t)r;
    }
    return 0;
}

/* Find the 8-byte magic word in buf[0..len-1] */
static int find_magic_word(const uint8_t *buf, size_t len) {
    if (len < 8) return -1;
    for (size_t i = 0; i <= len - 8; i++) {
        if (memcmp(buf + i, MAGIC_WORD, 8) == 0) return (int)i;
    }
    return -1;
}

/* Parse a complete frame starting at frame_start, extract objects */
static int parse_frame(const uint8_t *frame, size_t frame_len,
                       float *ranges, float *velocities, int *num_objects) {
    *num_objects = 0;

    /* Frame header is 40 bytes after magic word */
    if (frame_len < 40) {
        fprintf(stderr, "Frame too short for header\n");
        return -1;
    }

    /* Skip 32 bytes of frame header, then 4 bytes of version, then 4 bytes of packet length */
    size_t offset = 32 + 4 + 4;
    if (offset >= frame_len) {
        fprintf(stderr, "Frame header missing TLV list\n");
        return -1;
    }

    /* Walk TLV list */
    while (offset + sizeof(tlv_header_t) <= frame_len) {
        tlv_header_t hdr;
        memcpy(&hdr, frame + offset, sizeof(tlv_header_t));
        offset += sizeof(tlv_header_t);

        if (offset + hdr.length > frame_len) {
            fprintf(stderr, "TLV payload exceeds frame\n");
            return -1;
        }

        if (hdr.type == TLV_TYPE_DETECTED_OBJECTS) {
            size_t obj_size = sizeof(detected_obj_t);
            if (hdr.length % obj_size != 0) {
                fprintf(stderr, "Detected objects TLV length not multiple of object size\n");
                offset += hdr.length;
                continue;
            }
            size_t num = hdr.length / obj_size;
            if (num > MAX_OBJECTS) num = MAX_OBJECTS;

            for (size_t i = 0; i < num; i++) {
                const detected_obj_t *obj = (const detected_obj_t *)(frame + offset + i * obj_size);
                /* Convert raw indices to physical units (requires calibration constants) */
                /* For this example we use placeholder conversions */
                ranges[i] = (float)obj->rangeIdx * 0.0436f;   /* ~0.0436 m per range index */
                velocities[i] = (float)obj->dopplerIdx * 0.0436f; /* ~0.0436 m/s per doppler index */
            }
            *num_objects = (int)num;
            return 0;
        }

        offset += hdr.length;
    }

    return -1;
}

/* Append one object row to CSV */
static int log_object(FILE *fp, float range, float velocity) {
    time_t rawtime;
    struct tm *timeinfo;
    char ts[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,0,%.3f,%.3f\n", ts, range, velocity) < 0) {
        fprintf(stderr, "CSV write error: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    uint8_t read_buf[READ_BUF_SIZE];
    uint8_t frame_buf[READ_BUF_SIZE];
    size_t frame_len = 0;
    float ranges[MAX_OBJECTS];
    float velocities[MAX_OBJECTS];
    int num_objects;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open UART */
    g_uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_handle < 0) {
        fprintf(stderr, "Failed to open UART %s: %s\n", UART_DEVICE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file */
    g_csv_file = fopen(CSV_FILE, "a");
    if (!g_csv_file) {
        fprintf(stderr, "Failed to open CSV file %s: %s\n", CSV_FILE, strerror(errno));
        serClose(g_uart_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_csv_file, 0, SEEK_END);
    if (ftell(g_csv_file) == 0) {
        fprintf(g_csv_file, "timestamp,object_index,range_m,velocity_mps\n");
        fflush(g_csv_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "Radar data acquisition started on %s @ %d baud. Press Ctrl+C to stop.\n",
            UART_DEVICE, BAUD_RATE);

    /* Main acquisition loop */
    while (g_running) {
        int bytes_read = serRead(g_uart_handle, (char *)read_buf, sizeof(read_buf));
        if (bytes_read < 0) {
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            break;
        }
        if (bytes_read == 0) {
            gpioDelay(1000); /* 1 ms idle delay */
            continue;
        }

        /* Append to frame buffer */
        if (frame_len + bytes_read > sizeof(frame_buf)) {
            /* Buffer overflow: discard everything except last 7 bytes (partial magic) */
            size_t keep = sizeof(frame_buf) - 7;
            if (keep > 0) {
                memmove(frame_buf, frame_buf + frame_len - keep, keep);
