#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define READ_TIMEOUT_SEC 2
#define LINE_BUF_SIZE 512
#define TIMESTAMP_BUF_SIZE 32

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag = 0;
    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 second inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NONBLOCK: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void format_timestamp(double timestamp, char *buf, size_t buf_size) {
    time_t rawtime = (time_t)timestamp;
    struct tm timeinfo;
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, buf_size, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_uart_fd = init_uart(UART_PORT);
    if (g_uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char timestamp_str[TIMESTAMP_BUF_SIZE];

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = READ_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int select_result = select(g_uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error during select(): %s\n", strerror(errno));
            break;
        }

        if (select_result == 0) {
            continue;
        }

        if (FD_ISSET(g_uart_fd, &readfds)) {
            char read_buf[256];
            ssize_t bytes_read = read(g_uart_fd, read_buf, sizeof(read_buf) - 1);

            if (bytes_read < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    continue;
                }
                fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
                break;
            }

            if (bytes_read == 0) {
                fprintf(stderr, "UART closed by peer\n");
                break;
            }

            read_buf[bytes_read] = '\0';

            for (ssize_t i = 0; i < bytes_read; i++) {
                char c = read_buf[i];

                if (c == '\n') {
                    line_buf[line_len] = '\0';

                    if (line_len > 0) {
                        char *endptr = NULL;
                        double timestamp = strtod(line_buf, &endptr);

                        if (endptr != line_buf && *endptr == ',') {
                            char *range_str = endptr + 1;
                            char *range_endptr = NULL;
                            double range = strtod(range_str, &range_endptr);

                            if (range_endptr != range_str && *range_endptr == '\0') {
                                format_timestamp(timestamp, timestamp_str, sizeof(timestamp_str));
                                printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
                                fflush(stdout);
                            } else {
                                fprintf(stderr, "Invalid range value: %s\n", range_str);
                            }
                        } else {
                            fprintf(stderr, "Invalid timestamp format: %s\n", line_buf);
                        }
                    }
                    line_len = 0;
                } else if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line buffer overflow, discarding\n");
                    line_len = 0;
                }
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }

    return 0;
}

